unsigned int __stdcall ProjectLoadProgramImageThreadFn(void *pParam)
{
	CAOIProject *ProjectPtr = (CAOIProject*)(pParam);
	if ( NULL == ProjectPtr ) { return -1; }
	if ( ProjectPtr->IsKindOf(RUNTIME_CLASS(CAOIProject)) == FALSE ) { return -1; }
	
	size_t       i=0, j=0;
	size_t       FrameCount = 0;
	CAOIField   *FieldPtr = NULL;
	CAOIFrame   *FramePtr = NULL;
	TCHAR        Str[MAX_JET_PATH]=_T("");	
	FRAME_MERGE_STATE FrameState = FRAME_MERGE_NONE;
	THREAD_COMMAND_MODE  ThreadCmd = THREAD_COMMAND_TO_NONE;
	const size_t FieldCount = ProjectPtr->GetProjectProgramFieldCount();

	for ( i=0; i<FieldCount; i++ )
	{
		ThreadCmd = ProjectPtr->GetProjectPreLoadFrameImageThreadCmd();
		if ( THREAD_COMMAND_TO_EXIT == ThreadCmd ) 
		{	break; }

		FieldPtr = ProjectPtr->GetProjectProgramFieldPtr(i, false);
		if ( NULL == FieldPtr ) { continue; }

		FrameCount = FieldPtr->GetFieldFramePtrCount();
		for ( j=0; j<FrameCount; j++ )
		{
			ThreadCmd = ProjectPtr->GetProjectPreLoadFrameImageThreadCmd();
			if ( THREAD_COMMAND_TO_EXIT == ThreadCmd ) 
			{	break; }

			FramePtr = FieldPtr->GetFieldFramePtr(j, false);
			if ( NULL == FramePtr ) { continue; }
			FrameState = FramePtr->GetFrameMergeState();
			if ( FRAME_MERGE_DONE == FrameState ) { continue; }
			if ( FRAME_MERGE_DOING == FrameState ) { continue; }			
			//if ( FRAME_MERGE_CLEAR == FrameState ) { continue; }
			//同步化
			CAOIFrame::LockFrame();
			FrameState = FramePtr->GetFrameMergeState();//重新取得狀態, 因為在鎖住前可能別的執行緒又進去算了
			if ( FRAME_MERGE_DOING==FrameState || FRAME_MERGE_DONE==FrameState )
			{
				CAOIFrame::UnlockFrame();
				continue;
			}
			FramePtr->SetFrameMergeState(FRAME_MERGE_DOING);
			CAOIFrame::UnlockFrame();
			if ( FramePtr->ExecFrameLoad() == false )
			{					
				::_stprintf(Str, _T("Error Load Frame Fault (Field_%d, Frame_%d"), i+1, j+1);				
				ProjectPtr->SetErrorString(Str);
				return -1;
			}			
			FramePtr->SetFrameMergeState(FRAME_MERGE_DONE);
			ProjectPtr->IncrementProjectPreLoadFrameImageCount();
		}		

		FieldPtr->SetFieldMergeState(FIELD_MERGE_NONE);
		if ( FieldPtr->CheckFieldFramesMergeFinish() == true )
		{	FieldPtr->SetFieldMergeState(FIELD_MERGE_DONE);	}
	}
	return 0;
}
