//-------------------------------------------------------------------------------------//
void CAOIProject::CloneProjectObjList(const CAOIProject &project)
{
	this->ClearProjectAllObjects();
	
	size_t         i=0, j=0, k=0;
	size_t         OldIndex=0, NewIndex=0;
	size_t         FdCount = 0;
	size_t         MarkCount = 0;
	size_t         BarcodeCount = 0;
	size_t         SubRgnCount = 0;
	size_t         PanelCount = 0;
	size_t         BoardCount = 0;	
	size_t         FieldCount = 0;	
	size_t         FrameCount = 0;	
	size_t         WindowCount = 0;	
	size_t         ComponentCount = 0;
	CAOIRgn       *SubRgnPtr = NULL;	
	CAOIFd        *OldFdPtr=NULL, *NewFdPtr=NULL;
	CAOIMark      *OldMarkPtr=NULL, *NewMarkPtr=NULL;
	CAOIBarcode   *OldBarcodePtr=NULL, *NewBarcodePtr=NULL;
	CAOIPanel     *OldPanelPtr=NULL, *NewPanelPtr=NULL;
	CAOIBoard     *OldBoardPtr=NULL, *NewBoardPtr=NULL;
	CAOIField     *OldFieldPtr=NULL, *NewFieldPtr=NULL;
	CAOIFrame     *OldFramePtr=NULL, *NewFramePtr=NULL;
	CAOIModel     *OldModelPtr=NULL, *NewModelPtr=NULL;
	CAOIWindow    *WindowPtr = NULL;
	CAOIComponent *OldComponentPtr=NULL, *NewComponentPtr=NULL;
	//m_ProjectModelPtrList

	const size_t ProjectFdCount = project.GetProjectFdCount();	
	const size_t ProjectMarkCount = project.GetProjectMarkCount();	
	const size_t ProjectPanelCount = project.GetProjectPanelCount();
	const size_t ProjectBoardCount = project.GetProjectBoardCount();	
	const size_t ProjectBarcodeCount = project.GetProjectBarcodeCount();
	const size_t ProjectProgramFieldCount = project.GetProjectProgramFieldCount();	
	const size_t ProjectInspectionFieldCount = project.GetProjectInspectionFieldCount();
	const size_t ProjectComponentCount = project.GetProjectComponentCount();	
	const size_t ProjectModelCount = project.GetProjectModelCount();
	
	//Clone Fd List
	for ( i=0; i<ProjectFdCount; i++ )
	{
		OldFdPtr = project.GetProjectFdPtr(i, false);
		if ( NULL == OldFdPtr ) { continue; }
		NewFdPtr = OldFdPtr->CloneFdObj();
		if ( NULL == NewFdPtr ) { continue; }
		NewFdPtr->SetFdFieldPtr(NULL);
		this->AddProjectFdPtr(NewFdPtr, false);
	}

	//Clone Mark List
	for ( i=0; i<ProjectMarkCount; i++ )
	{
		OldMarkPtr = project.GetProjectMarkPtr(i, false);
		if ( NULL == OldMarkPtr ) { continue; }
		NewMarkPtr = OldMarkPtr->CloneMarkObj();
		if ( NULL == NewMarkPtr ) { continue; }
		AddProjectMarkPtr(NewMarkPtr, false);

		//清除Field指標
		NewMarkPtr->SetMarkFieldPtr(NULL);
		SubRgnCount = NewMarkPtr->GetMarkSubRgnCount();
		for ( k=0; k<SubRgnCount; k++ )
		{
			SubRgnPtr = NewMarkPtr->GetMarkSubRgnPtr(k, false);
			if ( NULL == SubRgnPtr ) { continue; }
			SubRgnPtr->SetRgnFieldPtr(NULL);
		}
	}

	//Clone Barcode List
	for ( i=0; i<ProjectBarcodeCount; i++ )
	{
		OldBarcodePtr = project.GetProjectBarcodePtr(i, false);
		if ( NULL == OldBarcodePtr ) { continue; }
		NewBarcodePtr = OldBarcodePtr->CloneBarcodeObj();
		if ( NULL == NewBarcodePtr ) { continue; }
		this->AddProjectBarcodePtr(NewBarcodePtr, false);

		//清除Field指標
		NewBarcodePtr->SetBarcodeFieldPtr(NULL);
		SubRgnCount = NewBarcodePtr->GetBarcodeSubRgnCount();
		for ( k=0; k<SubRgnCount; k++ )
		{
			SubRgnPtr = NewBarcodePtr->GetBarcodeSubRgnPtr(k, false);
			if ( NULL == SubRgnPtr ) { continue; }
			SubRgnPtr->SetRgnFieldPtr(NULL);
		}
	}
	//Clone Model List
	for ( i=0; i<ProjectModelCount; i++ )
	{
		OldModelPtr = project.GetProjectModelPtr(i, false);
		if ( NULL == OldModelPtr ) { continue; }
		NewModelPtr = OldModelPtr->CloneModelObj();
		if ( NULL == NewModelPtr ) { continue; }
		this->AddProjectModelPtr(NewModelPtr, false);
	}

	//Clone Component List
	for ( i=0; i<ProjectComponentCount; i++ )
	{
		OldComponentPtr = project.GetProjectComponentPtr(i, false);
		if ( NULL == OldComponentPtr ) { continue; }
		NewComponentPtr = OldComponentPtr->CloneComponentObj();
		if ( NULL == NewComponentPtr ) { continue; }
		this->AddProjectComponentPtr(NewComponentPtr, false);

		//清除Field指標
		NewComponentPtr->SetComponentFieldPtr(NULL);
		SubRgnCount = NewComponentPtr->GetComponentSubRgnCount();
		for ( k=0; k<SubRgnCount; k++ )
		{
			SubRgnPtr = NewComponentPtr->GetComponentSubRgnPtr(k, false);
			if ( NULL == SubRgnPtr ) { continue; }
			SubRgnPtr->SetRgnFieldPtr(NULL);
		}
		
		WindowCount = NewComponentPtr->GetComponentWindowCount();
		for ( j=0; j<WindowCount; j++ )
		{
			WindowPtr = NewComponentPtr->GetComponentWindowPtr(j, false);
			if ( NULL == WindowPtr ) { continue; }
			
			WindowPtr->SetWindowFieldPtr(NULL);
			SubRgnCount = WindowPtr->GetWindowSubRgnCount();
			for ( k=0; k<SubRgnCount; k++ )
			{
				SubRgnPtr = WindowPtr->GetWindowSubRgnPtr(k, false);
				if ( NULL == SubRgnPtr ) { continue; }
				SubRgnPtr->SetRgnFieldPtr(NULL);
			}			
		}		
	}
	//Clone Board List
	for ( i=0; i<ProjectBoardCount; i++ )
	{
		OldBoardPtr = project.GetProjectBoardPtr(i, false);
		if ( NULL == OldBoardPtr ) { continue; }
		NewBoardPtr = OldBoardPtr->CloneBoardObj();
		if ( NULL == NewBoardPtr ) { continue; }
		this->AddProjectBoardPtr(NewBoardPtr, false);
	}
	//Clone Panel List
	for ( i=0; i<ProjectPanelCount; i++ )
	{
		OldPanelPtr = project.GetProjectPanelPtr(i, false);
		if ( NULL == OldPanelPtr ) { continue; }
		NewPanelPtr = OldPanelPtr->ClonePanelObj();
		if ( NULL == NewPanelPtr ) { continue; }
		this->AddProjectPanelPtr(NewPanelPtr, false);
	}
	//Clone Field List Matrix
	//CAOIFrame     *OldFramePtr=NULL, *NewFramePtr=NULL;
	for ( i=0; i<ProjectProgramFieldCount; i++ )
	{
		OldFieldPtr = project.GetProjectProgramFieldPtr(i, false);
		if ( NULL == OldFieldPtr ) { continue; }
		NewFieldPtr = OldFieldPtr->CloneFieldObj();
		if ( NULL == NewFieldPtr ) { continue; }
		this->AddProjectProgramFieldPtr(NewFieldPtr, false);
		
		//NewFieldPtr->ClearFieldAllFrames();		
		NewFieldPtr->RemoveFieldAllFrames();//來自於Field的複製, 所以僅能移除vector, 而非物件
		FrameCount = OldFieldPtr->GetFieldFramePtrCount();
		for ( j=0; j<FrameCount; j++ )
		{
			OldFramePtr = OldFieldPtr->GetFieldFramePtr(j, false);
			if ( NULL == OldFramePtr ) { continue; }
			NewFramePtr = OldFramePtr->CloneFrameObj();
			if ( NULL == NewFramePtr ) { continue; }
			NewFieldPtr->AddFieldFramePtr(NewFramePtr);
		}
	}

	//Clone Field List Random
	for ( i=0; i<ProjectInspectionFieldCount; i++ )
	{
		OldFieldPtr = project.GetProjectInspectionFieldPtr(i, false);
		if ( NULL == OldFieldPtr ) { continue; }
		NewFieldPtr = OldFieldPtr->CloneFieldObj();
		if ( NULL == NewFieldPtr ) { continue; }
		this->AddProjectInspectionFieldPtr(NewFieldPtr, false);		

		//NewFieldPtr->ClearFieldAllFrames();		
		NewFieldPtr->RemoveFieldAllFrames();//來自於Field的複製, 所以僅能移除vector, 而非物件
		FrameCount = OldFieldPtr->GetFieldFramePtrCount();
		for ( j=0; j<FrameCount; j++ )
		{
			OldFramePtr = OldFieldPtr->GetFieldFramePtr(j, false);
			if ( NULL == OldFramePtr ) { continue; }
			NewFramePtr = OldFramePtr->CloneFrameObj();
			if ( NULL == NewFramePtr ) { continue; }
			NewFieldPtr->AddFieldFramePtr(NewFramePtr);
		}
	}	

	const size_t NewProjectFdCount = GetProjectFdCount();	
	const size_t NewProjectMarkCount = GetProjectMarkCount();		
	const size_t NewProjectPanelCount = GetProjectPanelCount();
	const size_t NewProjectBoardCount = GetProjectBoardCount();
	const size_t NewProjectBarcodeCount = GetProjectBarcodeCount();
	const size_t NewProjectProgramFieldCount = GetProjectProgramFieldCount();
	const size_t NewProjectInspectionFieldCount = GetProjectInspectionFieldCount();
	const size_t NewProjectComponentCount = GetProjectComponentCount();
	const size_t NewProjectModelCount = GetProjectModelCount();

	//確認總數相同
	if ( (NewProjectFdCount != ProjectFdCount) ||
		 (NewProjectMarkCount != ProjectMarkCount) ||
		 (NewProjectBarcodeCount != ProjectBarcodeCount) ||
		 (NewProjectModelCount != ProjectModelCount) ||
		 (NewProjectComponentCount != ProjectComponentCount) ||
		 (NewProjectProgramFieldCount != ProjectProgramFieldCount) || 
		 (NewProjectInspectionFieldCount != ProjectInspectionFieldCount) || 
		 (NewProjectBoardCount != ProjectBoardCount) || 
		 (NewProjectPanelCount != ProjectPanelCount) )
	{
		this->ClearProjectAllObjects();
		return;
	}
	
	//Clone Component Agent List
	for ( i=0; i<ProjectComponentCount; i++ )
	{		
		OldComponentPtr = project.GetProjectComponentPtr(i, false);
		if ( NULL == OldComponentPtr ) { continue; }
		if ( OldComponentPtr->CheckComponentIsMaster() == false ) { continue; }
		NewComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == NewComponentPtr ) { continue; }
		if ( NewComponentPtr->CheckComponentIsMaster() == false ) { continue; }

		CAOIComponent *OldMasterPtr=OldComponentPtr;
		CAOIComponent *NewMasterPtr=NewComponentPtr;
		const size_t AgentCount=OldMasterPtr->GetComponentAgentCount();

		NewMasterPtr->ClearComponentAgentList();
		for ( j=0; j<AgentCount; j++ )
		{
			OldComponentPtr = OldMasterPtr->GetComponentAgentPtr(j, false);
			if ( NULL == OldComponentPtr ) { continue; }
			OldIndex = OldComponentPtr->GetComponentIndex_Project();
			if ( OldIndex >= NewProjectComponentCount ) { continue; }
			NewComponentPtr = GetProjectComponentPtr(OldIndex, false);
			if ( NULL == NewComponentPtr ) { continue; }
			NewMasterPtr->AddComponentAgentPtr(NewComponentPtr);
		}
	}	

	//Clone Board List
	for ( i=0; i<ProjectBoardCount; i++ )
	{
		OldBoardPtr = project.GetProjectBoardPtr(i, false);
		if ( NULL == OldBoardPtr ) { continue; }
		NewBoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == NewBoardPtr ) { continue; }
		
		NewBoardPtr->RemoveBoardAllFds();
		NewBoardPtr->RemoveBoardAllMarks();
		NewBoardPtr->RemoveBoardAllFields();
		NewBoardPtr->RemoveBoardAllBarcodes();
		NewBoardPtr->RemoveBoardAllComponents();

		//Combine Fd Ptr List		
		FdCount = OldBoardPtr->GetBoardFdCount();
		for ( j=0; j<FdCount; j++ )
		{
			OldFdPtr = OldBoardPtr->GetBoardFdPtr(j, false);
			if ( NULL == OldFdPtr ) { continue; }
			OldIndex = OldFdPtr->GetFdIndex_Project();
			if ( OldIndex >= NewProjectFdCount ) { continue; }
			NewFdPtr = GetProjectFdPtr(OldIndex, false);
			NewBoardPtr->AddBoardFdPtr(NewFdPtr);
		}

		//Combine Mark Ptr List		
		MarkCount = OldBoardPtr->GetBoardMarkCount();
		for ( j=0; j<MarkCount; j++ )
		{
			OldMarkPtr = OldBoardPtr->GetBoardMarkPtr(j, false);
			if ( NULL == OldMarkPtr ) { continue; }
			OldIndex = OldMarkPtr->GetMarkIndex_Project();
			if ( OldIndex >= NewProjectMarkCount ) { continue; }
			NewMarkPtr = GetProjectMarkPtr(OldIndex, false);
			NewBoardPtr->AddBoardMarkPtr(NewMarkPtr);
		}

		//Combine Barcode Ptr List		
		BarcodeCount = OldBoardPtr->GetBoardBarcodeCount();
		for ( j=0; j<BarcodeCount; j++ )
		{
			OldBarcodePtr = OldBoardPtr->GetBoardBarcodePtr(j, false);
			if ( NULL == OldBarcodePtr ) { continue; }
			OldIndex = OldBarcodePtr->GetBarcodeIndex_Project();
			if ( OldIndex >= NewProjectBarcodeCount ) { continue; }
			NewBarcodePtr = GetProjectBarcodePtr(OldIndex, false);
			NewBoardPtr->AddBoardBarcodePtr(NewBarcodePtr);
		}

		//Combine Component Ptr List		
		ComponentCount = OldBoardPtr->GetBoardComponentCount();
		for ( j=0; j<ComponentCount; j++ )
		{
			OldComponentPtr = OldBoardPtr->GetBoardComponentPtr(j, false);
			if ( NULL == OldComponentPtr ) { continue; }
			OldIndex = OldComponentPtr->GetComponentIndex_Project();
			if ( OldIndex >= NewProjectComponentCount ) { continue; }
			NewComponentPtr = GetProjectComponentPtr(OldIndex, false);
			NewBoardPtr->AddBoardComponentPtr(NewComponentPtr);
		}
	}	

	//Clone Panel List
	for ( i=0; i<ProjectPanelCount; i++ )
	{
		OldPanelPtr = project.GetProjectPanelPtr(i, false);
		if ( NULL == OldPanelPtr ) { continue; }
		NewPanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == NewPanelPtr ) { continue; }		

		NewPanelPtr->RemovePanelAllFds();
		NewPanelPtr->RemovePanelAllMarks();
		NewPanelPtr->RemovePanelAllBarcodes();
		NewPanelPtr->RemovePanelAllBoards();
		NewPanelPtr->RemovePanelAllFields();
		NewPanelPtr->RemovePanelAllComponents();

		//Combine Fd Ptr List	
		FdCount = OldPanelPtr->GetPanelFdCount();
		for ( j=0; j<FdCount; j++ )
		{
			OldFdPtr = OldPanelPtr->GetPanelFdPtr(j, false);
			if ( NULL == OldFdPtr ) { continue; }
			OldIndex = OldFdPtr->GetFdIndex_Project();
			if ( OldIndex >= NewProjectFdCount ) { continue; }
			NewFdPtr = GetProjectFdPtr(OldIndex, false);
			NewPanelPtr->AddPanelFdPtr(NewFdPtr);
		}

		//Combine Mark Ptr List
		MarkCount = OldPanelPtr->GetPanelMarkCount();
		for ( j=0; j<MarkCount; j++ )
		{
			OldMarkPtr = OldPanelPtr->GetPanelMarkPtr(j, false);
			if ( NULL == OldMarkPtr ) { continue; }
			OldIndex = OldMarkPtr->GetMarkIndex_Project();
			if ( OldIndex >= NewProjectMarkCount ) { continue; }
			NewMarkPtr = GetProjectMarkPtr(OldIndex, false);
			NewPanelPtr->AddPanelMarkPtr(NewMarkPtr);
		}

		//Combine Barcode Ptr List
		BarcodeCount = OldPanelPtr->GetPanelBarcodeCount();
		for ( j=0; j<BarcodeCount; j++ )
		{
			OldBarcodePtr = OldPanelPtr->GetPanelBarcodePtr(j, false);
			if ( NULL == OldBarcodePtr ) { continue; }
			OldIndex = OldBarcodePtr->GetBarcodeIndex_Project();
			if ( OldIndex >= NewProjectBarcodeCount ) { continue; }
			NewBarcodePtr = GetProjectBarcodePtr(OldIndex, false);
			NewPanelPtr->AddPanelBarcodePtr(NewBarcodePtr);
		}

		//Combine Component Ptr List	
		ComponentCount = OldPanelPtr->GetPanelComponentCount();
		for ( j=0; j<ComponentCount; j++ )
		{
			OldComponentPtr = OldPanelPtr->GetPanelComponentPtr(j, false);
			if ( NULL == OldComponentPtr ) { continue; }
			OldIndex = OldComponentPtr->GetComponentIndex_Project();
			if ( OldIndex >= NewProjectComponentCount ) { continue; }
			NewComponentPtr = GetProjectComponentPtr(OldIndex, false);
			NewPanelPtr->AddPanelComponentPtr(NewComponentPtr);
		}

		//Combine Board Ptr List	
		BoardCount = OldPanelPtr->GetPanelBoardCount();
		for ( j=0; j<BoardCount; j++ )
		{
			OldBoardPtr = OldPanelPtr->GetPanelBoardPtr(j, false);
			if ( NULL == OldBoardPtr ) { continue; }
			OldIndex = OldBoardPtr->GetBoardIndex_Project();
			if ( OldIndex >= NewProjectBoardCount ) { continue; }
			NewBoardPtr = GetProjectBoardPtr(OldIndex, false);
			NewPanelPtr->AddPanelBoardPtr(NewBoardPtr);
		}

		//RemovePanelAllFields
		//Combine Field Ptr List
		FieldCount = OldPanelPtr->GetPanelFieldCount();
		for ( j=0; j<FieldCount; j++ )
		{
			OldFieldPtr = OldPanelPtr->GetPanelFieldPtr(j, false);
			if ( NULL == OldFieldPtr ) { continue; }
			OldIndex = OldFieldPtr->GetFieldIndex();
			if ( OldIndex >= NewProjectInspectionFieldCount ) { continue; }
			NewFieldPtr = GetProjectInspectionFieldPtr(OldIndex, false);
			NewPanelPtr->AddPanelFieldPtr(NewFieldPtr);
		}
	}		
	return ;
}
