//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectIniFileFn(LPCTSTR filename, CJetIniFile *pIniFile)
{	
	if ( NULL == pIniFile ) { return true; }	
	if ( NULL == filename )
	{ 
		m_ErrorString.Format(_T("Error, Filename Exception"));
		return false; 
	}
	if ( pIniFile->SaveIniFile(filename, TXT_FILE_UTF8) == false)
	{
		m_ErrorString = pIniFile->GetErrorString();
		return false;
	}
	return true;
}
