//-------------------------------------------------------------------------------------//
bool CAOIProject::CheckProjectOthersUsing3D() const//確認專案其餘有使用3D
{
	size_t i=0;
	bool bUse2D=false;
	bool bUse3D=false;
	int  FrameIndex_3D=-1;
	const int FrameUniqueID_3D=FRAME_UNIQUE_ID_DLP;
	const TProjectParameter &ProgParam=GetProjectParameter();
	const std::vector<TFrameParam> &FrameParamList=m_ProjectFrameParamList;	
	const size_t FrameParamCount=FrameParamList.size();

	//Check Use3D Image
	for ( i=0; i<FrameParamCount; i++ )
	{
		const TFrameParam &FrameParamRef=FrameParamList[i];
		//if ( FRAME_SPACE != FrameParamRef.FrameType )
		if ( FrameUniqueID_3D != FrameParamRef.FrameUniqueID )
		{	bUse2D = true; }
		else
		{	
			bUse3D = true; 
			FrameIndex_3D = (int)(i);
		}
	}
	//沒有2D影像(純3D)或者沒有3D影像, 就是之前模式
	if ( false==bUse2D || false==bUse3D || -1==FrameIndex_3D ) 
	{	return true; }

	//確認存整版底圖是否儲存3D圖
	int SaveProjectTestMap_3D=FN_DISABLE;
	if ( SAVE_TEST_MAP_DISABLE != ProgParam.m_SaveProjectTestMap )
	{
		switch ( FrameIndex_3D )
		{
		case 0: SaveProjectTestMap_3D=ProgParam.m_SaveProjectTestMap_01; break;
		case 1: SaveProjectTestMap_3D=ProgParam.m_SaveProjectTestMap_02; break;
		case 2: SaveProjectTestMap_3D=ProgParam.m_SaveProjectTestMap_03; break;
		case 3: SaveProjectTestMap_3D=ProgParam.m_SaveProjectTestMap_04; break;
		case 4: SaveProjectTestMap_3D=ProgParam.m_SaveProjectTestMap_05; break;
		case 5: SaveProjectTestMap_3D=ProgParam.m_SaveProjectTestMap_06; break;
		case 6: SaveProjectTestMap_3D=ProgParam.m_SaveProjectTestMap_07; break;
		case 7: SaveProjectTestMap_3D=ProgParam.m_SaveProjectTestMap_08; break;
		default:
			break;
		}
	}
	if ( FN_ENABLE == SaveProjectTestMap_3D )
	{	return true; }	

	//確認特殊檢測是否使用3D圖
	if ( FN_ENABLE == ProgParam.m_DropOutPartEnable )
	{
		if ( FrameUniqueID_3D == ProgParam.m_DropOutPartFrameUniqueID )
		{	return true; }
	}

	if ( FN_ENABLE == ProgParam.m_ScratchPartEnable )
	{
		if ( FrameUniqueID_3D == ProgParam.m_ScratchPartFrameUniqueID )
		{	return true; }
	}	
	return false;
}
