//-------------------------------------------------------------------------------------//
bool CAOIProject::CopyProjectSpcPartImageSelected()//複製選取到零件的Spc零件圖檔
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }
	SAVE_SPC_PART_IMAGE_MODE  SaveSpcPartImageMode=GetProjectSaveSpcPartImageMode();
	if ( SAVE_SPC_PART_IMAGE_SELECTED_COPY != SaveSpcPartImageMode ) { return true; }

	CAOIComponent *ComponentPtr = NULL;
	std::vector<CAOIComponent*> SelPartList, UnSelPartList;
	const size_t ComponentCount = ProjectPtr->GetProjectComponentCount();
	for ( size_t i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentBypassed() == true ) { continue; }

		ComponentPtr->SetComponentTempInt(FN_DISABLE);
		if ( ComponentPtr->GetComponentSelected() )
		{	SelPartList.push_back(ComponentPtr);	}
		else
		{	UnSelPartList.push_back(ComponentPtr);	}
	}

	const size_t SelCount=SelPartList.size();
	const size_t UnSelCount=UnSelPartList.size();
	if ( 0 == SelCount || 0 == UnSelCount )
	{	return true; }

	//Sort By ComponentName;
	CSortObj SortObj;
	std::vector<CSortObj> SortList(UnSelCount);
	for ( size_t i=0; i<UnSelCount; i++ )
	{
		ComponentPtr = UnSelPartList[i];
		if ( NULL == ComponentPtr ) { continue; }

		CSortObj &SrotObjRef=SortList[i];
		SrotObjRef.SetID(i);
		SrotObjRef.SetPtr(ComponentPtr);
		SrotObjRef.SetSortMode(SORT_BY_TXT);
		SrotObjRef.SetValueStr(ComponentPtr->GetComponentName());
	}
	std::sort(SortList.begin(), SortList.end());
	const size_t SortCount=SortList.size();
	if ( SortCount != UnSelCount )
	{	return false; }
	
	for ( size_t i=0; i<SortCount; i++)
	{
		ComponentPtr = (CAOIComponent*)(SortList[i].GetPtr());
		UnSelPartList[i] = ComponentPtr;
	}
	
	CAOIComponent *ComponentPtr_Sel = NULL;			
	CString UnSelName, SelName, LastSelName, LastUnSelName;	
	for ( size_t i=0; i<UnSelCount; i++ )
	{
		ComponentPtr = UnSelPartList[i];
		if ( NULL == ComponentPtr ) { continue; }
		UnSelName = ComponentPtr->GetComponentName();
		if ( UnSelName.CompareNoCase(LastUnSelName) == 0 )		
		{			
			if ( LastSelName.GetLength() == 0 ) { continue; }
			CopyProjectSpcPartImage(ComponentPtr_Sel, ComponentPtr);
			continue; 
		}

		LastSelName = _T("");
		LastUnSelName = UnSelName;
		for ( size_t j=0; j<SelCount; j++ )
		{
			ComponentPtr_Sel = SelPartList[j];
			if ( NULL == ComponentPtr_Sel ) { continue; }
			if ( FN_ENABLE == ComponentPtr_Sel->GetComponentTempInt() ) { continue; }

			SelName = ComponentPtr_Sel->GetComponentName();
			if ( UnSelName.CollateNoCase(SelName) != 0 ) { continue; }
			LastSelName = SelName;
			ComponentPtr_Sel->SetComponentTempInt(FN_ENABLE);			
			break;
		}
		if ( LastSelName.GetLength() == 0 ) { continue; }
		CopyProjectSpcPartImage(ComponentPtr_Sel, ComponentPtr);		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CopyProjectSpcPartImage(const CAOIComponent *SrcPtr, const CAOIComponent *DstPtr)//複製選取到零件的Spc零件圖檔
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }
	if ( NULL==SrcPtr || NULL==DstPtr ) { return false ;}	
	CString SrcFile, DstFile;
	CString SrcFullName=SrcPtr->GetComponentFullName();
	CString DstFullName=DstPtr->GetComponentFullName();
	CString PartImageFolder = ProjectPtr->GetProjectSpcPartImageFolder();
	const bool bSave3D = ProjectPtr->GetProjectSaveModelImage3DFile_AI();
	const std::vector<TFrameParam> &FrameParamList=ProjectPtr->m_ProjectFrameParamList;
	for ( size_t i=0; i<FrameParamList.size(); i++ )
	{
		const TFrameParam &FrameRef=FrameParamList[i];

		SrcFile.Format(_T("%s\\%s#%d.%s"), PartImageFolder, SrcFullName, i+1, _T("PNG"));
		DstFile.Format(_T("%s\\%s#%d.%s"), PartImageFolder, DstFullName, i+1, _T("PNG"));
		::CopyFile(SrcFile, DstFile, FALSE);

		if ( true==bSave3D && FRAME_SPACE==FrameRef.FrameType )
		{	//Z3D
			SrcFile.Format(_T("%s\\%s#%d.%s"), PartImageFolder, SrcFullName, i+1, _T("Z3D"));
			DstFile.Format(_T("%s\\%s#%d.%s"), PartImageFolder, DstFullName, i+1, _T("Z3D"));
			::CopyFile(SrcFile, DstFile, FALSE);
		}			
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::DeleteProjectSpcPartImageSelected(LPCTSTR Folder)//刪除選取到零件的Spc零件圖檔
{
	size_t i=0;	
	CString MainName;
	CString ComponentName;	
	std::vector<CString> FileList;
	CAOIComponent *ComponentPtr = NULL;
	const size_t ComponentCount=GetProjectComponentCount();	
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentSelected() == false ) { continue; }

		ComponentName = ComponentPtr->GetComponentFullName();
		MainName.Format(_T("%s*"), ComponentName);		
		JetAPI::ListFilesInFolder(Folder, MainName, NULL, FileList);
	}
	JetAPI::DeleteFileList(Folder, FileList);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::DeleteProjectSpcPartImageSelectedWithTheSameName(LPCTSTR Folder)//刪除選取到零件的Spc零件圖檔-與相同名稱零件
{
	size_t i=0;	
	CString MainName;
	CString ComponentName;	
	std::vector<CString> FileList;
	CAOIComponent *ComponentPtr = NULL;
	std::vector<CAOIComponent*> SelList, UnSelList;
	const size_t ComponentCount=GetProjectComponentCount();	
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->SetComponentTempInt(FN_DISABLE);
		if ( ComponentPtr->GetComponentSelected() == true )
		{	SelList.push_back(ComponentPtr);	}
		else
		{	UnSelList.push_back(ComponentPtr);	}
	}
	
	const size_t SelCount=SelList.size();
	const size_t UnSelCount=UnSelList.size();
	if ( 0==SelCount || 0==UnSelCount )
	{	return DeleteProjectSpcPartImageSelected(Folder);	}

	//Sort By Component Name
	CSortObj SortObj;
	std::vector<CSortObj> SelSortList, UnSelSortList;
	SortObj.SetSortMode(SORT_BY_TXT);
	for ( i=0; i<SelCount; i++ )
	{
		ComponentPtr = SelList[i];
		if ( NULL == ComponentPtr ) { continue; }
		SortObj.SetID(i);
		SortObj.SetPtr(ComponentPtr);
		SortObj.SetValueStr(ComponentPtr->GetComponentName());
		SelSortList.push_back(SortObj);
	}
	std::sort(SelSortList.begin(), SelSortList.end());

	for ( i=0; i<UnSelCount; i++ )
	{
		ComponentPtr = UnSelList[i];
		if ( NULL == ComponentPtr ) { continue; }
		SortObj.SetID(i);
		SortObj.SetPtr(ComponentPtr);
		SortObj.SetValueStr(ComponentPtr->GetComponentName());
		UnSelSortList.push_back(SortObj);
	}
	std::sort(UnSelSortList.begin(), UnSelSortList.end());

	const size_t SelSortCount=SelSortList.size();
	const size_t UnSelSortCount=UnSelSortList.size();
	if ( SelSortCount!=SelCount || UnSelSortCount!=UnSelCount )
	{	return DeleteProjectSpcPartImageSelected(Folder);; }

	for ( size_t i=0; i<SelSortCount; i++)
	{	SelList[i] = (CAOIComponent*)(SelSortList[i].GetPtr());	}
	for ( size_t i=0; i<UnSelSortCount; i++)
	{	UnSelList[i] = (CAOIComponent*)(UnSelSortList[i].GetPtr());	}	
	
	CString UnSelName, SelName, LastSelName, LastUnSelName;	
	for ( size_t i=0; i<UnSelCount; i++ )
	{
		ComponentPtr = UnSelList[i];
		if ( NULL == ComponentPtr ) { continue; }
		UnSelName = ComponentPtr->GetComponentName();
		if ( UnSelName.CompareNoCase(LastUnSelName) == 0 )		
		{			
			if ( LastSelName.GetLength() == 0 ) { continue; }
			ComponentPtr->SetComponentSelected(true);
			continue; 
		}

		LastSelName = _T("");
		LastUnSelName = UnSelName;
		for ( size_t j=0; j<SelCount; j++ )
		{
			CAOIComponent *ComponentPtr_Sel = SelList[j];
			if ( NULL == ComponentPtr_Sel ) { continue; }
			if ( FN_ENABLE == ComponentPtr_Sel->GetComponentTempInt() ) { continue; }

			SelName = ComponentPtr_Sel->GetComponentName();
			if ( UnSelName.CollateNoCase(SelName) != 0 ) { continue; }
			LastSelName = SelName;
			ComponentPtr_Sel->SetComponentTempInt(FN_ENABLE);			
			break;
		}
		if ( LastSelName.GetLength() == 0 ) { continue; }
		ComponentPtr->SetComponentSelected(true);
	}	

	const bool bSucc = DeleteProjectSpcPartImageSelected(Folder);
	for ( size_t i=0; i<UnSelCount; i++ )
	{
		ComponentPtr = UnSelList[i];
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->SetComponentSelected(false);
	}
	return bSucc;
}
