//-------------------------------------------------------------------------------------//
bool CAOIProject::ApplyProjectParameter()//套用專案參數
{
	CString        str;
	size_t         i=0, j=0, k=0;
	CAOIFd        *FdPtr=NULL;
	CAOIMark      *MarkPtr=NULL;
	CAOIPanel     *PanelPtr = NULL;
	CAOIBoard     *BoardPtr = NULL;
	CAOIBarcode   *BarcodePtr = NULL;
	CAOIComponent *ComponentPtr = NULL;	
	double StagePosX=0, StagePosY=0, StagePosZ=0;
	const int    nRatio = m_ProjectParameter.m_SpaceToGrayRatioMode;
	const size_t VersionCodeIdx=m_ProjectParameter.m_VersionCodeActiveIndex;
	const double FocusPos = GetProjectFocusPos();
	const size_t FdCount = GetProjectFdCount();
	const size_t MarkCount = GetProjectMarkCount();
	const size_t PanelCount = GetProjectPanelCount();
	const size_t BoardCount = GetProjectBoardCount();
	const size_t BarcodeCount = GetProjectBarcodeCount();
	const size_t ComponentCount = GetProjectComponentCount();

	CreateProjectServerLibraryFolder();

	m_ProjectSpaceToGrayRatio = AOIDataCollect.GetSpaceToGrayRatio(nRatio);

	m_ProjectMarkStagePos.z = FocusPos;
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		FdPtr->SetFdStagePosZ(FocusPos);
		FdPtr->SetFdTeachStagePosZ(FocusPos);		
	}

	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
	}

	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
	}

	for ( i=0; i<MarkCount; i++ )
	{
		MarkPtr = GetProjectMarkPtr(i, false);
		if ( NULL == MarkPtr ) { continue; }
		MarkPtr->SetMarkStagePosZ(FocusPos);
	}

	for ( i=0; i<BarcodeCount; i++ )
	{
		BarcodePtr = GetProjectBarcodePtr(i, false);
		if ( NULL == BarcodePtr ) { continue; }
		BarcodePtr->SetBarcodeStagePosZ(FocusPos);
	}

	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->SetComponentStagePosZ(FocusPos);		
	}
	
	ChangeProjectVersionCode(VersionCodeIdx);
	LayoutProjectVersionCodeList();	
	m_ProjectVersionCodeListBackup = m_ProjectVersionCodeList;

	if ( m_ProjectInspectionFieldBuildMode != m_ProjectParameter.m_InspectionFieldBuildMode ||
		 m_ProjectInspectionFieldBuildAreaMode != m_ProjectParameter.m_InspectionFieldBuildAreaMode )
	{
		str = _T("Project field build mode is chaned, Do you want to apply new field build mode?");
		str = LoadMultiLanguageString(str, str);
		if ( JetAPI::ShowMessageBox(str, MB_YESNO) == IDNO )
		{	
			m_ProjectParameter.m_InspectionFieldBuildMode = m_ProjectInspectionFieldBuildMode;	
			m_ProjectParameter.m_InspectionFieldBuildAreaMode = m_ProjectInspectionFieldBuildAreaMode;	
		}
		else
		{
			m_ProjectInspectionFieldBuildMode = m_ProjectParameter.m_InspectionFieldBuildMode;
			m_ProjectInspectionFieldBuildAreaMode = m_ProjectParameter.m_InspectionFieldBuildAreaMode;
			if ( ClearProjectAllInspectionField() == false )
			{	
				str = GetErrorString();
				JetAPI::ShowMessageBox(str);
			}
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ApplySystemParameter(LANE_ID LaneID)//套用系統參數
{
	CString      str;
	size_t       i=0, j=0, k=0;	
	CAOIFd      *FdPtr=NULL;	
	const size_t FdCount = GetProjectFdCount();

	LaneID = AOIDataCollect.GetActiveLaneID();

	CreateProjectServerLibraryFolder();

	//SetProjectActLaneID(LaneID);
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		FdPtr->SetFdLaneID(LaneID);		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::BackupProjectParameter()//備份專案參數
{
	size_t         i=0;
	const TProjectParameter &ProParam=GetProjectParameter();
	const size_t VersionCodeIdx=ProParam.m_VersionCodeActiveIndex;
	
	m_ProjectVersionCodeListBackup = m_ProjectVersionCodeList;

	CAOIComponent *ComponentPtr = NULL;
	const size_t   ComponentCount = GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->UpdateToComponentVersionParam(VersionCodeIdx);
		ComponentPtr->BackupComponentParamByVersion();
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::RestoreProjectParameter()//還原專案參數
{
	size_t         i=0;
	m_ProjectVersionCodeList = m_ProjectVersionCodeListBackup;

	CAOIComponent *ComponentPtr = NULL;
	const size_t   ComponentCount = GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->RestoreComponentParamByVersion();
	}	
	return true;
}
