//-------------------------------------------------------------------------------------//
bool CAOIProject::FlushProjectOperLogFile()//傾寫專案的操作訊息檔案
{
	if ( CheckProjectOperLogIndexValid() == false ) { return true; }
	unsigned int LogIndex=GetProjectOperLogIndex();
	if ( LogManager.FlushLogNodeMsgToFile(LogIndex) == false )
	{	
		m_ErrorString = LogManager.GetErrorString(); 
		return false;
	}	
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::RevokeProjectOperLogFile()//撤銷專案的操作訊息檔案
{
	if ( CheckProjectOperLogIndexValid() == false ) { return true; }
	unsigned int LogIndex=GetProjectOperLogIndex();
	LogManager.RemoveLogNode(LogIndex);
	m_ProjectOperLogIndex = -1;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::RegisterProjectOperLogFile()//註冊專案的操作訊息檔案
{
	RevokeProjectOperLogFile();	
	//if ( GetProjectUseOperLog() == true ) { return true; }
	//訊息操作
	const bool bSaveHeader=false;		
	CString LogBackup = _T("");
	CString LogExtName = _T("TXT");	
	CString LogFilename = _T("LogOper");
	CString ProjectFolder= _T("");
	CString ProjectLogFolder = _T("");	
	CString ProjectName = GetProjectFileName();	
	JetAPI::ExtractMainFileName(ProjectName, ProjectFolder);
	ProjectLogFolder=AOIDataDefine.GetProjectOperLogFolderName(ProjectFolder);
	::CreateDirectory(ProjectLogFolder, NULL);
	//m_ProjectOperLogIndex = LogManager.AddLogFile(ProjectLogFolder, LogFilename, LogExtName, LogBackup, CLogNode::LOG_FILENAME_BY_DATE, bSaveHeader);
	m_ProjectOperLogIndex = LogManager.AddLogFileOnRuning(ProjectLogFolder, LogFilename, LogExtName, LogBackup, CLogNode::LOG_FILENAME_BY_DATE, bSaveHeader);	
	return true;
}
