//-------------------------------------------------------------------------------------//
bool CAOIProject::SwtichProjectOfflineFileMode(OFFLINE_FILE_MODE OfflineFileMode, bool DistrictChange, bool LoadFrame)
{
	bool    IsOK = true;
	CString OfflineFolder;
	CString OfflineFdName;	
	CString OfflineFilename;
	bool    OfflineMode = AOIDataCollect.GetOfflineMode();
	bool    ProjectMapMode = AOIDataCollect.GetProjectMapMode();
	OFFLINE_FILE_MODE BeforeOfflineFileMode = GetProjectOfflineFileMode();

	//釋放之前的Offline圖檔
	if ( BeforeOfflineFileMode!=OfflineFileMode || true==DistrictChange )
	{
	#ifdef OFFLINE_VERSION
		switch ( BeforeOfflineFileMode )
		{
		case OFFLINE_FILE_PROGRAM:
			ReleaseProjectProgramFieldFrameImageBuffer();
			break;
		case OFFLINE_FILE_INSPECTION://由於檢測時沒有儲存所有圖片, 所以不建議釋放掉
			ReleaseProjectInspectionFieldFrameImageBuffer();
			break;
		}
	#endif//OFFLINE_VERSION
	}

	LANE_ID LaneID = GetProjectActLaneID();
	DISTRICT_ID DistrictID = GetProjectActDistrictID();		
	OFFLINE_IMAGE_SCOPE OfflineImageScope=GetProjectOfflineImageScope();
	switch ( OfflineFileMode )
	{
	case OFFLINE_FILE_PROGRAM:
		OfflineMode = true;//離線模式
		OfflineFolder = GetProjectProgramOfflineFolder();	
		OfflineFilename = AOIDataDefine.GetProjectOfflineFileName(OfflineFolder, DistrictID);		
		SetProjectOfflineFolder(OfflineFolder);			
		if ( true == DistrictChange ) 
		{
			if ( LoadProjectProgramOfflineFile(OfflineFilename) == false ) 
			{	return false; }
		}
		m_ProjectFieldPtrList = m_ProjectProgramFieldPtrList;
		break;
	case OFFLINE_FILE_INSPECTION:
		ProjectMapMode = false;//底圖模式
		OfflineFolder = GetProjectInspectionOfflineFolder();	
		OfflineFilename = AOIDataDefine.GetProjectOfflineFileName(OfflineFolder, DistrictID);
		SetProjectOfflineFolder(OfflineFolder);	
		if ( true == DistrictChange ) 
		{
			if ( LoadProjectInspectionOfflineFile(OfflineFilename) == false ) 
			{	return false; }
		}
		OfflineImageScope=GetProjectOfflineImageScope();
		if ( OFFLINE_IMAGE_PART == OfflineImageScope )
		{	m_ProjectFieldPtrList = m_ProjectInspectionPartFieldPtrList;	}
		else
		{	m_ProjectFieldPtrList = m_ProjectInspectionFieldPtrList;	}	
		break;
	}
	SetProjectOfflineFileMode(OfflineFileMode);	
	OfflineFdName = AOIDataDefine.GetProjectOfflineFdName(OfflineFolder, DistrictID);	
	AOIDataCollect.SetOfflineMode(OfflineMode);
	AOIDataCollect.SetProjectMapMode(ProjectMapMode);
	AOIDataCollect.SetIsNeedGrabFiducial(true, LaneID);	
	if ( LoadProjectOfflineFdFile(OfflineFdName) == false )
	{	return false; }
	
	const bool PreLoadOffline = AOIDataCollect.GetPreLoadProjectProgramImage();
	if ( true == PreLoadOffline && true==LoadFrame )
	{
		if ( OFFLINE_FILE_PROGRAM == OfflineFileMode )
		{
			const bool ProjectProgramFieldBufferReleased = GetProjectProgramFieldBufferReleased();
			if ( true == ProjectProgramFieldBufferReleased )
			{
				HCURSOR hCursor = ::AfxGetApp()->LoadStandardCursor(IDC_WAIT);
				HCURSOR hOldCursor = ::SetCursor(hCursor);
				IsOK = ExecProjectPreLoadProgramImage();
				::SetCursor(hOldCursor);
				if ( false == IsOK )
				{	return false;	}
			}
		}
		if ( OFFLINE_FILE_INSPECTION == OfflineFileMode && OFFLINE_IMAGE_FOV==OfflineImageScope )
		{
			const bool ProjectInspectionFieldBufferReleased = GetProjectInspectionFieldBufferReleased();
			if ( true == ProjectInspectionFieldBufferReleased )
			{
				HCURSOR hCursor = ::AfxGetApp()->LoadStandardCursor(IDC_WAIT);
				HCURSOR hOldCursor = ::SetCursor(hCursor);
				IsOK = ExecProjectPreLoadInspectionImage();
				::SetCursor(hOldCursor);
				if ( false == IsOK )
				{	return false;	}
			}
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CombineProjectAllObjects(CAOIFileIO &FileIO)//連結所有物件-使用引數
{
	size_t         i=0, j=0;	
	size_t         BoardIdx=0;	
	size_t         PanelIdx=0;	
	size_t         FieldIdx=0;
	size_t         ModelIndx=0;
	size_t         ComponentIdx=0;
	size_t         ModelWndCount=0;
	unsigned int   BoardIndex = 0;
	unsigned int   FrameIndex = 0;
	unsigned int   FrameUniqueID = 0;
	MODEL_TYPE     ModelType;
	CString        ModelNameC, ModelNameM;
	CAOIFd        *FdPtr = NULL;
	CAOIMark      *MarkPtr = NULL;
	CAOIPartGroup *PartGroupPtr = NULL;
	CAOIBarcode   *BarcodePtr = NULL;
	CAOIWnd       *WndPtr = NULL;
	CAOIPanel     *PanelPtr = NULL;
	CAOIBoard     *BoardPtr = NULL;
	CAOIField     *FieldPtr = NULL;
	CAOIModel     *ModelPtr = NULL;	
	CAlgParam     *AlgParamPtr = NULL;
	CAlgBinaryParam *BinParamPtr = NULL;
	CAOIComponent *ComponentPtr = NULL;	
	
	const size_t   FdCount = GetProjectFdCount();
	const size_t   MarkCount = GetProjectMarkCount();
	const size_t   PartGroupCount = GetProjectPartGroupCount();
	const size_t   BarcodeCount = GetProjectBarcodeCount();
	const size_t   PanelCount = GetProjectPanelCount();
	const size_t   BoardCount = GetProjectBoardCount();
	const size_t   ProgramFieldCount = GetProjectProgramFieldCount();
	const size_t   InspectionFieldCount = GetProjectInspectionFieldCount();
	const size_t   ComponentCount = GetProjectComponentCount();
	const size_t   ModelCount = GetProjectModelCount();
	const double   PosZ = GetProjectFocusPos();

	unsigned int   DefaultFrameIndex=0;
	unsigned int   DefaultFrameUniqueID = 0;	
	std::vector<unsigned int> FrameIndexMapList;
	AOIObjManager.LayoutRecycleObjList();
	BuildProjectFrameIndexMapParam(FrameIndexMapList, DefaultFrameIndex, DefaultFrameUniqueID);	

	//專案底圖引數-3D
	m_ProjectMapIndex3D = -1;
	const size_t FrameUniqueIDCount = GetProjectFrameUniqueIDCount();
	for ( i=0; i<FrameUniqueIDCount; i++ )
	{
		FrameUniqueID = GetProjectFrameUniqueID(i, false);//取得專案的影像參數唯一碼
		if ( FRAME_UNIQUE_ID_DLP != FrameUniqueID ) { continue; }
		m_ProjectMapIndex3D = (unsigned int)(i);
		break;
	}

	//專案抽色
	CColorGroup *ColorGroupPtr = NULL;
	const size_t ColorGroupCount = GetProjectColorGroupCount();
	for ( i=0; i<ColorGroupCount; i++ )
	{
		ColorGroupPtr = GetProjectColorGroupPtr(i, false);
		if ( NULL == ColorGroupPtr ) { continue; }		
		ColorGroupPtr->UpdateColorGroupFrameUniqueID(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);		
	}

	const std::vector<CColorGroup> &ColorGroupList=m_ProjectColorGroupList;	

	//拋件的基準面參數	
	TBasePlaneParam &DropBasePlaneParamRef=GetProjectParameter().m_DropOutPartSpaceNoiseFilter.BasePlaneParam;	
	UpdateProjectBasePlaneColorGroupLinkIndex(ColorGroupList, DropBasePlaneParamRef);	
	UpdateProjectBasePlaneFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList, DropBasePlaneParamRef);

	//模組資料
	for ( i=0; i<ModelCount; i++ )
	{
		ModelPtr = GetProjectModelPtr(i, false);
		if ( NULL == ModelPtr ) { continue; }		
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);
		ModelPtr->UpdateModelFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);		
	}

	//避免重複combine因此先移除原有的連結
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		PanelPtr->RemovePanelAllObjects();		
		PanelPtr->RemovePanelAllFields();
		PanelPtr->SetPanelProjectPtr(this);
	}
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
		BoardPtr->RemoveBoardAllObjects();
		BoardPtr->RemoveBoardAllFields();
	}

	for ( i=0; i<InspectionFieldCount; i++ )
	{
		FieldPtr = GetProjectInspectionFieldPtr(i, false);
		if ( NULL == FieldPtr ) { continue; }
		FieldPtr->SetFieldStagePosZ(PosZ);

		PanelIdx = FieldPtr->GetFieldPanelIndex();
		PanelPtr = GetProjectPanelPtr(PanelIdx, true);
		if ( NULL != PanelPtr )
		{	PanelPtr->AddPanelFieldPtr(FieldPtr);	}

		BoardIdx = FieldPtr->GetFieldBoardIndex();
		BoardPtr = GetProjectBoardPtr(BoardIdx, true);
		if ( NULL != BoardPtr )
		{	BoardPtr->AddBoardFieldPtr(FieldPtr);	}

		ComponentIdx = FieldPtr->GetFieldComponentIndex();
		ComponentPtr = GetProjectComponentPtr(ComponentIdx, true);
		if ( NULL != ComponentPtr )
		{	ComponentPtr->SetComponentSelfFieldPtr(FieldPtr);	}		
	}

	//定位點
	int FdUniqueID = 0;
	m_ProjectFdMaxUniqueID = -1;
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		FdPtr->SetFdProjectPtr(this);
		ModelPtr = FdPtr->GetFdModelPtr();		
		ModelType = ModelPtr->GetModelType();
		if ( ModelPtr->CheckModelTypeEnabled() == false ) { continue; }

		//BoardPtr = FdPtr->GetFdBoardPtr();//尚未匹配至單板內
		//if ( NULL == BoardPtr ) { continue; }
		//BoardIndex = FdPtr->GetFdBoardIndex_Project();
		//if ( -1 == BoardIndex ) { continue; }

		//確認專案定位點的Frame
		FdPtr->UpdateFdFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);

		//Fd Model		
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);
		ModelPtr->UpdateModelFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);		

		FdPtr->SetFdStagePosZ(PosZ);
		FdPtr->SetFdTeachStagePosZ(PosZ);		

		FdPtr->SetFdFieldPtr(NULL);
		FdPtr->SetFdFieldIndex(-1);

		//FieldIdx = FdPtr->GetFdFieldIndex();
		//FieldPtr = CAOIProject::GetProjectInspectionFieldPtr(FieldIdx, true);
		//FdPtr->SetFdFieldPtr(FieldPtr);

		FdUniqueID = FdPtr->GetFdUniqueID();
		if ( m_ProjectFdMaxUniqueID < FdUniqueID )
		{	m_ProjectFdMaxUniqueID = FdUniqueID; }
	}
	m_ProjectFdMaxUniqueID = m_ProjectFdMaxUniqueID+1;

	//特徵點
	int MarkUniqueID = 0;
	m_ProjectMarkMaxUniqueID = -1;
	for ( i=0; i<MarkCount; i++ )
	{
		MarkPtr = GetProjectMarkPtr(i, false);
		if ( NULL == MarkPtr ) { continue; }	
		MarkPtr->SetMarkProjectPtr(this);
		MarkPtr->SetMarkStagePosZ(PosZ);

		//確認專案特徵點的Frame		
		MarkPtr->UpdateMarkFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);

		//Barcode Model
		ModelPtr = MarkPtr->GetMarkModelPtr();		
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);
		ModelPtr->UpdateModelFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);				

		FieldIdx = MarkPtr->GetMarkFieldIndex();
		FieldPtr = GetProjectInspectionFieldPtr(FieldIdx, true);
		MarkPtr->SetMarkFieldPtr(FieldPtr);

		MarkUniqueID = MarkPtr->GetMarkUniqueID();
		if ( m_ProjectMarkMaxUniqueID < MarkUniqueID )
		{	m_ProjectMarkMaxUniqueID = MarkUniqueID; }
	}
	m_ProjectMarkMaxUniqueID = m_ProjectMarkMaxUniqueID+1;

	//零件群組
	int GroupUniqueID = 0;
	size_t GorupNodeCount=0;
	TPartGroupNode *GroupNodePtr=NULL;
	m_ProjectGroupMaxUniqueID = -1;
	for ( i=0; i<PartGroupCount; i++ )
	{
		PartGroupPtr = GetProjectPartGroupPtr(i, false);
		if ( NULL == PartGroupPtr ) { continue; }	
		PartGroupPtr->SetPartGroupProjectPtr(this);

		GroupNodePtr = PartGroupPtr->GetPartGroupNodePtr1();
		if ( NULL != GroupNodePtr )
		{	GroupNodePtr->ComponentPtr = GetProjectComponentPtr(GroupNodePtr->ComponentIndex, true);	}

		GroupNodePtr = PartGroupPtr->GetPartGroupNodePtr2();
		if ( NULL != GroupNodePtr )
		{	GroupNodePtr->ComponentPtr = GetProjectComponentPtr(GroupNodePtr->ComponentIndex, true);	}

		GroupNodePtr = PartGroupPtr->GetPartGroupNodePtr3();
		if ( NULL != GroupNodePtr )
		{	GroupNodePtr->ComponentPtr = GetProjectComponentPtr(GroupNodePtr->ComponentIndex, true);	}

		GroupNodePtr = PartGroupPtr->GetPartGroupNodePtr4();
		if ( NULL != GroupNodePtr )
		{	GroupNodePtr->ComponentPtr = GetProjectComponentPtr(GroupNodePtr->ComponentIndex, true);	}

		GorupNodeCount = PartGroupPtr->GetPartGroupNodeCount();
		for ( j=0; j<GorupNodeCount; j++ )
		{
			GroupNodePtr = PartGroupPtr->GetPartGroupNodePtr(j, false);
			if ( NULL == GroupNodePtr ) { continue; }			
			GroupNodePtr->ComponentPtr = GetProjectComponentPtr(GroupNodePtr->ComponentIndex, true);
		}
		
		GroupUniqueID = PartGroupPtr->GetPartGroupUniqueID();
		if ( m_ProjectGroupMaxUniqueID < GroupUniqueID )
		{	m_ProjectGroupMaxUniqueID = GroupUniqueID; }
	}
	m_ProjectGroupMaxUniqueID = m_ProjectGroupMaxUniqueID+1;

	//軟體條碼
	int BarcodeUniqueID = 0;
	m_ProjectBarcodeMaxUniqueID = -1;
	for ( i=0; i<BarcodeCount; i++ )
	{
		BarcodePtr = GetProjectBarcodePtr(i, false);
		if ( NULL == BarcodePtr ) { continue; }	
		BarcodePtr->SetBarcodeProjectPtr(this);
		BarcodePtr->SetBarcodeStagePosZ(PosZ);

		//確認專案條碼的Frame		
		BarcodePtr->UpdateBarcodeFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);

		//Barcode Model
		ModelPtr = BarcodePtr->GetBarcodeModelPtr();		
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);
		ModelPtr->UpdateModelFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);				

		FieldIdx = BarcodePtr->GetBarcodeFieldIndex();
		FieldPtr = CAOIProject::GetProjectInspectionFieldPtr(FieldIdx, true);
		BarcodePtr->SetBarcodeFieldPtr(FieldPtr);

		BarcodeUniqueID = BarcodePtr->GetBarcodeUniqueID();
		if ( m_ProjectBarcodeMaxUniqueID < BarcodeUniqueID )
		{	m_ProjectBarcodeMaxUniqueID = BarcodeUniqueID; }
	}
	m_ProjectBarcodeMaxUniqueID = m_ProjectBarcodeMaxUniqueID+1;

	//放入Board
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
		BoardPtr->SetBoardProjectPtr(this);
		PanelPtr = GetProjectPanelPtr(BoardPtr->GetBoardPanelIndex_Project(), true);
		if ( NULL != PanelPtr )
		{	PanelPtr->AddPanelBoardPtr(BoardPtr);	}		
	}

	//放入定位點
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }		
		PanelPtr = GetProjectPanelPtr(FdPtr->GetFdPanelIndex_Project(), true);
		if ( NULL != PanelPtr )
		{	PanelPtr->AddPanelFdPtr(FdPtr);	}		

		BoardPtr = GetProjectBoardPtr(FdPtr->GetFdBoardIndex_Project(), true);
		if ( NULL != BoardPtr )
		{	BoardPtr->AddBoardFdPtr(FdPtr);	}		
	}

	//放入特徵點
	for ( i=0; i<MarkCount; i++ )
	{
		MarkPtr = GetProjectMarkPtr(i, false);
		if ( NULL == MarkPtr ) { continue; }	
		
		PanelPtr = GetProjectPanelPtr(MarkPtr->GetMarkPanelIndex_Project(), true);
		if ( NULL != PanelPtr )
		{	PanelPtr->AddPanelMarkPtr(MarkPtr);	}		

		BoardPtr = GetProjectBoardPtr(MarkPtr->GetMarkBoardIndex_Project(), true);
		if ( NULL != BoardPtr )
		{	BoardPtr->AddBoardMarkPtr(MarkPtr);	}
	}

	//放入軟體條碼
	for ( i=0; i<BarcodeCount; i++ )
	{
		BarcodePtr = GetProjectBarcodePtr(i, false);
		if ( NULL == BarcodePtr ) { continue; }	
		
		PanelPtr = GetProjectPanelPtr(BarcodePtr->GetBarcodePanelIndex_Project(), true);
		if ( NULL != PanelPtr )
		{	PanelPtr->AddPanelBarcodePtr(BarcodePtr);	}		

		BoardPtr = GetProjectBoardPtr(BarcodePtr->GetBarcodeBoardIndex_Project(), true);
		if ( NULL != BoardPtr )
		{	BoardPtr->AddBoardBarcodePtr(BarcodePtr);	}
	}

	//放入Component
	bool    bFindModel = false;
	double  ComponentAngle=0.0;
	bool    IsExceptionAngle=false;
	int     ComponentUniqueID = 0;
	CString ModelFolder;
	CString FullComponentName;
	CString PartLibraryFolder = FileIO.GetPartLibraryFolder();
	m_ProjectComponentMaxUniqueID = -1;
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }		
		ComponentPtr->SetComponentProjectPtr(this);		
		ComponentPtr->SetComponentStagePosZ(PosZ);

		//確認專案零件的Frame
		ComponentPtr->UpdateComponentFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);

		ComponentUniqueID = ComponentPtr->GetComponentUniqueID();
		if ( m_ProjectComponentMaxUniqueID < ComponentUniqueID )
		{	m_ProjectComponentMaxUniqueID = ComponentUniqueID; }

		FieldIdx = ComponentPtr->GetComponentFieldIndex();
		FieldPtr = GetProjectInspectionFieldPtr(FieldIdx, true);
		ComponentPtr->SetComponentFieldPtr(FieldPtr);

		PanelPtr = GetProjectPanelPtr(ComponentPtr->GetComponentPanelIndex_Project(), true);
		if ( NULL != PanelPtr )
		{	PanelPtr->AddPanelComponentPtr(ComponentPtr);	}		

		BoardPtr = GetProjectBoardPtr(ComponentPtr->GetComponentBoardIndex_Project(), true);
		if ( NULL != BoardPtr )
		{	BoardPtr->AddBoardComponentPtr(ComponentPtr);	}				
		
		if ( ComponentPtr->GetComponentModelIsolated() == false )
		{
			bFindModel = false;
			ModelIndx = ComponentPtr->GetComponentModelIndex();			
			ModelPtr = GetProjectModelPtr(ModelIndx, true);
			ModelNameC = ComponentPtr->GetComponentModelName();			
			if ( NULL != ModelPtr )
			{
				//Double Check Model Name
				ModelNameM = ModelPtr->GetModelName();				
				if ( ModelNameC.CompareNoCase(ModelNameM) == 0 )
				{
					bFindModel = true;
					ComponentPtr->UpdateComponentModelFromLibrary(ModelPtr); 
				}
			}
			if ( false == bFindModel )
			{
				ModelPtr = GetProjectModelPtrByModelName(ModelNameC);
				if ( NULL != ModelPtr )
				{
					bFindModel = true;
					ComponentPtr->UpdateComponentModelFromLibrary(ModelPtr); 
				}
			}
		}
		else
		{	
			ModelPtr = ComponentPtr->GetComponentModelPtr();			
			ComponentAngle = ComponentPtr->GetComponentAngle();
			IsExceptionAngle = JetAPI::CheckIsExceptionAngle(ComponentAngle);
			if ( true == IsExceptionAngle )
			{	ModelPtr->UpdateModelBodyToComponent(); }			
			FullComponentName = ComponentPtr->GetComponentFullName();								
			ModelFolder.Format(_T("%s\\%s"), PartLibraryFolder, FullComponentName);										
			ModelPtr->SetModelIsolated(true);
			ModelPtr->SetModelFolderComponent(ModelFolder);
			ModelPtr->AssignModelFolder();

			ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);
			ModelPtr->UpdateModelFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);			
		}
	}

	//Match Master & Agent
	CString      MasterName;
	CString      ComponentName;
	unsigned int MasterIndex=-1;
	CAOIComponent *MasterPtr=NULL;
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }		
		if ( ComponentPtr->CheckComponentIsAgent() == false ) { continue; }		
		ComponentName = ComponentPtr->GetComponentName();
		MasterIndex = ComponentPtr->GetComponentMasterIndex();		
		MasterPtr = GetProjectComponentPtr(MasterIndex, true);
		if ( NULL != MasterPtr )
		{				
			//Check Master Name
			MasterName = MasterPtr->GetComponentName();
			if ( ComponentName.CompareNoCase(MasterName) != 0 )
			{	MasterPtr = NULL;	}
		}

		if ( NULL == MasterPtr )
		{	ComponentPtr->ResetComponentMaster();	}
		else
		{	MasterPtr->AddComponentAgentPtr(ComponentPtr);	}
	}
	m_ProjectComponentMaxUniqueID = m_ProjectComponentMaxUniqueID+1;	

	SetProjectFdModified(false);

	const bool bCalcFov=true;
	const bool bMultiDistrictID = GetProjectMultiDistrictMode();
	if ( false == bMultiDistrictID )
	{
		CalcProjectStagePosition_Panel();
		CalcProjectStagePosition_Board(bCalcFov);
	}
	else
	{
		CalcProjectStagePosition_Panel(DISTRICT_ID_A);
		CalcProjectStagePosition_Panel(DISTRICT_ID_B);
		CalcProjectStagePosition_Board(DISTRICT_ID_A, bCalcFov);
		CalcProjectStagePosition_Board(DISTRICT_ID_B, bCalcFov);
	}	

	//計算邊界
	LayoutProjectRegion();
	//BuildProjectDefectComponentList();
	return true;
}
//-------------------------------------------------------------------------------------//
void CAOIProject::DumpProjectFile(FILE *pfile)//偵錯匯出
{
	if ( NULL == pfile ) { return; }

	int           i = 0;
	CAOIFd        *FdPtr = NULL;
	CAOIMark      *MarkPtr = NULL;
	CAOIBarcode   *BarcodePtr = NULL;
	CAOIPanel     *PanelPtr = NULL;
	CAOIBoard     *BoardPtr = NULL;
	CAOIComponent *ComponentPtr = NULL;
	const int   FdCount = (int)(GetProjectFdCount());
	const int   MarkCount = (int)(GetProjectMarkCount());
	const int   BarcodeCount = (int)(GetProjectBarcodeCount());
	const int   PanelCount = (int)(GetProjectPanelCount());
	const int   BoardCount = (int)(GetProjectBoardCount());
	const int   ComponentCount = (int)(GetProjectComponentCount());

	//Proect Component List
	::_ftprintf(pfile, _T("Project Component List (%d)\n"), ComponentCount);
	::_ftprintf(pfile, _T("Idx, Panel, Board, ComponentIdProject, ComponentIdPanel, ComponentIdBoard\n"));
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }

		
		::_ftprintf(pfile, _T("%d, %d, %d, %d, %d, %d\n"),
				i+1, 
				ComponentPtr->GetComponentPanelIndex_Project()+1,
				ComponentPtr->GetComponentBoardIndex_Project()+1,
				ComponentPtr->GetComponentIndex_Project()+1,
				ComponentPtr->GetComponentIndex_Panel()+1,
				ComponentPtr->GetComponentIndex_Board()+1			                  
			);
	}
	::_ftprintf(pfile, _T("\n"));

	//Proect Mark List
	::_ftprintf(pfile, _T("Project Mark List (%d)\n"), MarkCount);
	::_ftprintf(pfile, _T("Idx, Panel, Board, MarkId_Project, MarkId_Panel, MarkId_Board\n"));
	for ( i=0; i<MarkCount; i++ )
	{
		MarkPtr = GetProjectMarkPtr(i, false);
		if ( NULL == MarkPtr ) { continue; }
		
		::_ftprintf(pfile, _T("%d, %d, %d, %d, %d, %d\n"),
				i+1, 
				MarkPtr->GetMarkPanelIndex_Project()+1,
				MarkPtr->GetMarkBoardIndex_Project()+1,
				MarkPtr->GetMarkIndex_Project()+1,
				MarkPtr->GetMarkIndex_Panel()+1,
				MarkPtr->GetMarkIndex_Board()+1			                  
			);
	}
	::_ftprintf(pfile, _T("\n"));


	//Proect Barcode List
	::_ftprintf(pfile, _T("Project Barcode List (%d)\n"), BarcodeCount);
	::_ftprintf(pfile, _T("Idx, Panel, Board, BarcodeId_Project, BarcodeId_Panel, BarcodeId_Board\n"));
	for ( i=0; i<BarcodeCount; i++ )
	{
		BarcodePtr = GetProjectBarcodePtr(i, false);
		if ( NULL == BarcodePtr ) { continue; }
		
		::_ftprintf(pfile, _T("%d, %d, %d, %d, %d, %d\n"),
				i+1, 
				BarcodePtr->GetBarcodePanelIndex_Project()+1,
				BarcodePtr->GetBarcodeBoardIndex_Project()+1,
				BarcodePtr->GetBarcodeIndex_Project()+1,
				BarcodePtr->GetBarcodeIndex_Panel()+1,
				BarcodePtr->GetBarcodeIndex_Board()+1			                  
			);
	}
	::_ftprintf(pfile, _T("\n"));

	//Proect Fd List
	::_ftprintf(pfile, _T("Project Fd List (%d)\n"), FdCount);
	::_ftprintf(pfile, _T("Idx, Panel, Board, FdIdProject, FdIdPanel, FdIdBoard\n"));
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		
		::_ftprintf(pfile, _T("%d, %d, %d, %d, %d, %d\n"),
				i+1, 
				FdPtr->GetFdPanelIndex_Project()+1,
				FdPtr->GetFdBoardIndex_Project()+1,
				FdPtr->GetFdIndex_Project()+1,
				FdPtr->GetFdIndex_Panel()+1,
				FdPtr->GetFdIndex_Board()+1			                  
			);
	}
	::_ftprintf(pfile, _T("\n"));

	//Proect Board List
	::_ftprintf(pfile, _T("Project Board List (%d)\n"), BoardCount);
	::_ftprintf(pfile, _T("Idx, Panel, BoardIdProject, BoardIdPanel, NComponents, NFds\n"));
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }

		
		::_ftprintf(pfile, _T("%d, %d, %d, %d, %d, %d\n"),
				i+1, 
				BoardPtr->GetBoardPanelIndex_Project()+1,
				BoardPtr->GetBoardIndex_Project()+1,
				BoardPtr->GetBoardIndex_Panel()+1,
				BoardPtr->GetBoardComponentCount(),
				BoardPtr->GetBoardFdCount()			                  
			);
	}
	::_ftprintf(pfile, _T("\n"));

	//Proect Panel List
	::_ftprintf(pfile, _T("Project Panel List (%d)\n"), PanelCount);
	::_ftprintf(pfile, _T("Idx, PanelIdProject, NBoards, NComponents, NFds\n"));
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		
		::_ftprintf(pfile, _T("%d, %d, %d, %d, %d\n"),
				i+1, 
				PanelPtr->GetPanelIndex_Project()+1,
				PanelPtr->GetPanelBoardCount(),
				PanelPtr->GetPanelComponentCount(),
				PanelPtr->GetPanelFdCount()				
			);
	}
	::_ftprintf(pfile, _T("\n"));
	return;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::DumpProjectRgnList(LPCTSTR pfilename, const std::vector<CAOIRgn*> &RgnList)
{
	size_t       i=0;
	FILE        *pfile = NULL;
	int          nIsSub=0;
	unsigned int RgnIdx=0;
	unsigned int PanelIdx=0;
	unsigned int BoardIdx=0;	
	CString      strTypeText;
	CAOIRgn     *RgnPtr1  = NULL;	
	CAOIRgn     *RgnPtr2  = NULL;	
	CAOIPanel   *PanelPtr = NULL;
	CAOIBoard   *BoardPtr = NULL;

	AOI_OBJ_TYPE ObjType;
	char         TypeName[32]="";
	const size_t RgnCount = RgnList.size();
	TCHAR        TMode[32] = _T("");

	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	pfile = _tfopen(pfilename, TMode);
	if ( NULL == pfile ) 
	{
		m_ErrorString.Format(_T("Error, Open file fault (%s)"), pfilename);
		return false;
	}

	::_ftprintf(pfile, _T("index, Type, Sub, SubIdx, Panel, Board\n"));
	for ( i=0; i<RgnCount; i++ )
	{
		RgnPtr1 = RgnList[i];
		if ( NULL == RgnPtr1 ) { continue; }

		PanelIdx = -1;
		BoardIdx = -1;
		RgnPtr2 = RgnPtr1->GetRgnParent();
		RgnIdx = RgnPtr1->GetRgnIndex();
		if ( NULL != RgnPtr2 )
		{	
			nIsSub=1;
			ObjType = RgnPtr2->GetObjType();	
			PanelIdx = RgnPtr2->GetRgnPanelIndex_Project();
			BoardIdx = RgnPtr2->GetRgnBoardIndex_Project();
			strTypeText = RgnPtr2->GetRgnDerivedName();
		}
		else
		{	
			nIsSub=0;
			ObjType = RgnPtr1->GetObjType();	
			PanelIdx = RgnPtr1->GetRgnPanelIndex_Project();
			BoardIdx = RgnPtr1->GetRgnBoardIndex_Project();
			strTypeText = RgnPtr1->GetRgnDerivedName();
		}
		//strTypeText = CAOIObj::ObtainAOITypeText(ObjType);
		::_ftprintf(pfile, _T("%d, %s, %d, %d, %d, %d\n"), i+1, (LPCTSTR)strTypeText, nIsSub, RgnIdx, PanelIdx, BoardIdx);
	}
	::fclose(pfile); pfile = NULL;
	return true;
}
