//-------------------------------------------------------------------------------------//
bool CAOIProject::DumpProjectFieldFrameList(LPCTSTR pfilename, const std::vector<CAOIField*> &FieldList)
{
	size_t       i=0, j=0;	
	size_t       RgnCount=0;	
	size_t       FrameCount=0;
	CString      strYesNo;
	CString      FrameName;
	SPACE_PTR    SpacePtr=NULL;
	IMAGE_PTR    ImagePtr=NULL;
	IMAGE_SIZE   FrameImageW=0;
	IMAGE_SIZE   FrameImageH=0;
	IMAGE_SIZE   FrameImaeSize=0;
	FILE        *pfile = NULL;
	CAOIField   *FieldPtr = NULL;	
	CAOIFrame   *FramePtr = NULL;	
	FRAME_CALC_STATE FrameCalcState;
	FRAME_MERGE_STATE FrameMergeState;	
	
	char         TypeName[32]="";
	const size_t FieldCount = FieldList.size();
	TCHAR        TMode[32] = _T("");

	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	pfile = _tfopen(pfilename, TMode);
	if ( NULL == pfile ) 
	{
		m_ErrorString.Format(_T("Error, Open file fault (%s)"), pfilename);
		return false;
	}

	::_ftprintf(pfile, _T("index, index, Size, N_Rgns, Calc, Merge, Memory, File\n"));
	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = FieldList[i];
		if ( NULL == FieldPtr ) { continue; }			
		FrameCount = FieldPtr->GetFieldFramePtrCount();
		for ( j=0; j<FrameCount; j++ )
		{
			FramePtr = FieldPtr->GetFieldFramePtr(j, false);
			if ( NULL == FramePtr ) { continue; }

			RgnCount = FramePtr->GetFrameRgnCount();
			ImagePtr = FramePtr->GetFrameImagePtr();
			SpacePtr = FramePtr->GetFrameSpacePtr();
			FrameImageW = FramePtr->GetFrameImageW();
			FrameImageH = FramePtr->GetFrameImageH();
			FrameName = FramePtr->GetFrameFileNameOffline();		
			FrameName = FramePtr->GetFrameFileFolderOffline();		
			FrameCalcState = FramePtr->GetFrameCalcState();		
			FrameMergeState = FramePtr->GetFrameMergeState();
			FrameImaeSize = FrameImageW*FrameImageH;
			if ( NULL!=ImagePtr || NULL!=SpacePtr ) 
			{	strYesNo = _T("Yes");	}
			else
			{	strYesNo = _T("No");	}
			::_ftprintf(pfile, _T("%d, %d, %d, %d, %d, %d, %s, %s\n"), i+1, j+1, FrameImaeSize, RgnCount, FrameCalcState, FrameMergeState, (LPCTSTR)strYesNo, (LPCTSTR)FrameName);
		}
	}
	::fclose(pfile); pfile = NULL;	
	return true;
}
