void CAOIProject::ClearProjectAllObjects()
{
	//注意順序
	const bool bWaitThread=true;
	IdleProjectSaveFieldThread(bWaitThread);
	IdleProjectCopyFileThread(bWaitThread);

	ClearProjectAllTempObjects();
	
	ClearProjectAllFds();
	ClearProjectAllMarks();
	ClearProjectAllPartGroups();
	ClearProjectAllMapRgns();
	ClearProjectAllBarcodes();
	ClearProjectAllComponents();		
	ClearProjectAllDropOutParts();
	ClearProjectAllScratchParts();	
	ClearProjectAllBoards();
	ClearProjectAllPanels();
	ClearProjectAllModels();	
	ClearProjectAllProgramField();
	ClearProjectAllInspectionField();
	ClearProjectAllDefectComponents();
	ClearProjectAllInspectionPartField();
	AOIObjManager.LayoutRecycleObjList();
}
//-------------------------------------------------------------------------------------//
void CAOIProject::ClearProjectAllTempObjects()//刪除所有暫時用的物件
{
	bool IsSystemException = AOIDataCollect.GetIsSystemException();
	if ( true == IsSystemException ) 
	{	IsSystemException = true; }
	LockProject();
	ClearProjectAllTempRgns();//刪除整個檢測區域指標
	ClearProjectAllTempFovs();//刪除整個視野指標
	ClearProjectAllTempSlices();//刪除整個相機圖指標	
	ClearProjectAllTempFields();//刪除整個相機區域指標	
	ClearProjectAllTempFrames();//刪除整個畫面指標	
	UnlockProject();
	return;
}
