//-------------------------------------------------------------------------------------//
void CAOIProject::LayoutProjectAllObjectsIndex()//更新專案所有物件的引數
{
	unsigned int   i=0, j=0, k=0;
	size_t         NFds = 0;
	size_t         NMarks = 0;
	size_t         NBarcodes = 0;
	size_t         NPanels = 0;
	size_t         NBoards = 0;
	size_t         NComponents = 0;
	CAOIFd        *FdPtr = NULL;
	CAOIMark      *MarkPtr = NULL;
	CAOIBarcode   *BarcodePtr = NULL;
	CAOIPanel     *PanelPtr = NULL;
	CAOIBoard     *BoardPtr = NULL;
	CAOIComponent *ComponentPtr = NULL;

	const size_t FdCount = GetProjectFdCount();
	const size_t MarkCount = GetProjectMarkCount();
	const size_t BarcodeCount = GetProjectBarcodeCount();
	const size_t PanelCount = GetProjectPanelCount();
	const size_t BoardCount =  GetProjectBoardCount();
	const size_t ComponentCount = GetProjectComponentCount();

	//About Panel
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		PanelPtr->SetPanelIndex_Project(i);

		NFds = PanelPtr->GetPanelFdCount();
		for ( j=0; j<NFds; j++ )
		{
			FdPtr = PanelPtr->GetPanelFdPtr(j, false);
			if ( NULL == FdPtr ) { continue; }
			FdPtr->SetFdPanelIndex_Project(i);
			FdPtr->SetFdIndex_Panel(j);
		}

		NMarks = PanelPtr->GetPanelMarkCount();
		for ( j=0; j<NMarks; j++ )
		{
			MarkPtr = PanelPtr->GetPanelMarkPtr(j, false);
			if ( NULL == MarkPtr ) { continue; }
			MarkPtr->SetMarkPanelIndex_Project(i);
			MarkPtr->SetMarkIndex_Panel(j);
		}

		NBarcodes = PanelPtr->GetPanelBarcodeCount();
		for ( j=0; j<NBarcodes; j++ )
		{
			BarcodePtr = PanelPtr->GetPanelBarcodePtr(j, false);
			if ( NULL == BarcodePtr ) { continue; }
			BarcodePtr->SetBarcodePanelIndex_Project(i);
			BarcodePtr->SetBarcodeIndex_Panel(j);
		}

		NComponents = PanelPtr->GetPanelComponentCount();
		for ( j=0; j<NComponents; j++ )
		{
			ComponentPtr = PanelPtr->GetPanelComponentPtr(j, false);
			if ( NULL == ComponentPtr ) { continue; }
			ComponentPtr->SetComponentPanelIndex_Project(i);
			ComponentPtr->SetComponentIndex_Panel(j);
		}

		NBoards = PanelPtr->GetPanelBoardCount();
		for ( j=0; j<NBoards; j++ )
		{
			BoardPtr = PanelPtr->GetPanelBoardPtr(j, false);
			if ( NULL == BoardPtr ) { continue; }
			BoardPtr->SetBoardPanelIndex_Project(i);
			BoardPtr->SetBoardIndex_Panel(j);
		}
	}

	//About Board
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
		BoardPtr->SetBoardIndex_Project(i);
		
		NFds = BoardPtr->GetBoardFdCount();
		for ( j=0; j<NFds; j++ )
		{
			FdPtr = BoardPtr->GetBoardFdPtr(j, false);
			if ( NULL == FdPtr ) { continue; }
			FdPtr->SetFdBoardIndex_Project(i);
			FdPtr->SetFdBoardIndex_Panel(BoardPtr->GetBoardIndex_Panel());
			FdPtr->SetFdIndex_Board(j);
		}		

		NMarks = BoardPtr->GetBoardMarkCount();
		for ( j=0; j<NMarks; j++ )
		{
			MarkPtr = BoardPtr->GetBoardMarkPtr(j, false);
			if ( NULL == MarkPtr ) { continue; }
			MarkPtr->SetMarkBoardIndex_Project(i);
			MarkPtr->SetMarkBoardIndex_Panel(BoardPtr->GetBoardIndex_Panel());
			MarkPtr->SetMarkIndex_Board(j);
		}

		NBarcodes = BoardPtr->GetBoardBarcodeCount();
		for ( j=0; j<NBarcodes; j++ )
		{
			BarcodePtr = BoardPtr->GetBoardBarcodePtr(j, false);
			if ( NULL == BarcodePtr ) { continue; }
			BarcodePtr->SetBarcodeBoardIndex_Project(i);
			BarcodePtr->SetBarcodeBoardIndex_Panel(BoardPtr->GetBoardIndex_Panel());
			BarcodePtr->SetBarcodeIndex_Board(j);
		}

		NComponents = BoardPtr->GetBoardComponentCount();
		for ( j=0; j<NComponents; j++ )
		{
			ComponentPtr = BoardPtr->GetBoardComponentPtr(j, false);
			if ( NULL == ComponentPtr ) { continue; }
			ComponentPtr->SetComponentBoardIndex_Project(i);
			ComponentPtr->SetComponentBoardIndex_Panel(BoardPtr->GetBoardIndex_Panel());
			ComponentPtr->SetComponentIndex_Board(j);
		}
	}

	//About Fd
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		FdPtr->SetFdIndex_Project(i);
	}

	//About Mark
	for ( i=0; i<MarkCount; i++ )
	{
		MarkPtr = GetProjectMarkPtr(i, false);
		if ( NULL == MarkPtr ) { continue; }
		MarkPtr->SetMarkIndex_Project(i);
	}

	//About Barcode
	for ( i=0; i<BarcodeCount; i++ )
	{
		BarcodePtr = GetProjectBarcodePtr(i, false);
		if ( NULL == BarcodePtr ) { continue; }
		BarcodePtr->SetBarcodeIndex_Project(i);
	}

	//About Component
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->SetComponentIndex_Project(i);
	}
}
