{
	return m_ProjectResultListAOI.size();
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ShiftProjectResultListAOI()//偏移專案檢測列表-AOI
{
	size_t i=0;
	size_t KeepCount = 100;
	TTestResult    TestResult;
	CAOIComponent *ComponentPtr = NULL;	
	CString strStartTime, strEndTime, strTime;
	const size_t MaxResultCount = 10000;//最多紀錄10000筆資料
	std::vector<TTestResult>  &ResultList=m_ProjectResultListAOI;	
	const size_t ResultCount = ResultList.size();
	const size_t ComponentCount = GetProjectComponentCount();	
	const TProjectParameter &Param  = GetProjectParameter();
	STATISTIC_BY_MODE StatisticByMode = Param.m_StatisticByMode;

	SetProjectResultYieldOnAOI(false);
	if ( DEFECT_FROM_AOI != Param.m_StatisticDefectFromMode ) 
	{	return true; }
	if ( STATISTIC_BY_NONE == StatisticByMode )
	{	return true; }

	if ( STATISTIC_BY_TIME == StatisticByMode )
	{
		int TimeValue = Param.m_StatisticByTimeValue;
		if ( 0 == TimeValue )
		{	return true;	}
		else if ( ResultCount > 0 ) 
		{			
			int  nDays=0;
			int  nHours=0;
			int  nMins=0;
			int  nSecs=0;						
			CTime StartTime, EndTime;			
			TestResult = ResultList[ResultCount-1];		
			EndTime = TestResult.sDateTimeE;
		#ifdef _DEBUG
			JetAPI::GetTime(strEndTime, EndTime);
		#endif//_DEBUG
			JetAPI::GetTimeSpan(TimeValue, nDays, nHours, nMins);
			CTimeSpan TimeSpan(nDays, nHours, nMins, nSecs);
			StartTime = EndTime-TimeSpan;
		#ifdef _DEBUG
			JetAPI::GetTime(strStartTime, StartTime);
		#endif//_DEBUG

		#ifdef _DEBUG
			JetAPI::GetTime(strTime, ResultList[0].sDateTimeE);
		#endif//_DEBUG
			if ( ResultList[0].sDateTimeE > StartTime ) //第1筆時間大於時間起點
			{	return true; }

			KeepCount = ResultCount;
			for ( i=0; i<ResultCount; i++ )
			{
			#ifdef _DEBUG
				JetAPI::GetTime(strTime, ResultList[i].sDateTimeE);
			#endif//_DEBUG
				if ( ResultList[i].sDateTimeE > StartTime ) 
				{
					KeepCount = ResultCount-i;//-1+1
					break; 
				}
			}
		}		
	}
	if ( STATISTIC_BY_COUNT == StatisticByMode )
	{	
		KeepCount = Param.m_StatisticByCountValue;			
		if ( 0 == KeepCount ) 
		{	return true;	}
	}	
	KeepCount = MIN(KeepCount, MaxResultCount);
	if ( 0 == KeepCount ) { return true; }
	if ( ResultCount <= KeepCount ) { return true; }
	
	SetProjectResultYieldOnAOI(true);//比數滿足才開始統計計算
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->ShiftComponentResultToStatisticAOI(KeepCount);
	}
	
	const size_t EraseCount = ResultCount-KeepCount;
	ResultList.erase(ResultList.begin(), ResultList.begin()+EraseCount);
	const size_t ResultCount2 = ResultList.size();

#ifdef _DEBUG
	if ( ResultCount2 > 0 ) 
	{		
		JetAPI::GetTime(strStartTime, ResultList[0].sDateTimeE);
		JetAPI::GetTime(strEndTime, ResultList[ResultCount2-1].sDateTimeE);
	}	
#endif//_DEBUG
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CalcProjectResultYieldingAOI(double &rtTest, double &rtPanel, double &rtBoard, double &rtComponent)//計算專案結果良率-AOI
{
	size_t         i=0;	
	TTestResult    TestResult;	
	TTestResult   *TestResultPtr=NULL;	
	std::vector<TTestResult>  &ResultList=m_ProjectResultListAOI;	
	const size_t ResultCount = ResultList.size();

	size_t szNGTest=0, szTotalTest=0;
	size_t szNGPanel=0, szTotalPanel=0;
	size_t szNGBoard=0, szTotalBoard=0;
	size_t szNGComponent=0, szTotalComponent=0;

	for ( i=0; i<ResultCount; i++ )
	{
		TestResultPtr = &(ResultList[i]);
		
		szNGTest += TestResultPtr->sTest.NG;
		szTotalTest += TestResultPtr->sTest.Total;

		szNGPanel += TestResultPtr->sPanel.NG;
		szTotalPanel += TestResultPtr->sPanel.Total;

		szNGBoard += TestResultPtr->sBoard.NG;
		szTotalBoard += TestResultPtr->sBoard.Total;

		szNGComponent += TestResultPtr->sComponent.NG;
		szTotalComponent += TestResultPtr->sComponent.Total;

	}

	if ( 0 == szTotalTest ) 
	{	rtTest = 100.0; }
	else
	{	rtTest = (szTotalTest-szNGTest)*100.0/szTotalTest;	}

	if ( 0 == szTotalPanel ) 
	{	rtPanel = 100.0; }
	else
	{	rtPanel = (szTotalPanel-szNGPanel)*100.0/szTotalPanel;	}

	if ( 0 == szTotalBoard ) 
	{	rtBoard = 100.0; }
	else
	{	rtBoard = (szTotalBoard-szNGBoard)*100.0/szTotalBoard;	}

	if ( 0 == szTotalComponent ) 
	{	rtComponent = 100.0; }
	else
	{	rtComponent = (szTotalComponent-szNGComponent)*100.0/szTotalComponent;	}
	return true;
}
//-------------------------------------------------------------------------------------//
void CAOIProject::CalcProjectResultLatest_ARS(LANE_ID LaneID, RESULT_ID TestResultID, CTime &cTime)//計算專案最新結果-ARS
{
	size_t          i=0, j=0;	
	unsigned int    Index=0;
	size_t          PanelBoardCount=0;
	size_t          BoardComponentCount=0;		
	bool            IsBadBoard=false;	
	bool            IsBadPanel=false;	
	TTestResult     TestResult; 	
	RESULT_ID       ResultID = RESULT_ID_NONE;	
	CAOIPanel      *PanelPtr = NULL;
	CAOIBoard      *BoardPtr = NULL;
	CAOIComponent  *ComponentPtr = NULL;
	const size_t    PanelCount = GetProjectPanelCount();
	const size_t    BoardCount = GetProjectBoardCount();		
	const size_t    ComponentCount = GetProjectComponentCount();	

	TestResult.sDateTimeS = cTime;
	TestResult.sDateTimeE = cTime;
	//CTime       sDateTime;//檢測開始日期	
	
	//Component		
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }		
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
		TestResult.sComponent.Total ++;		
		ResultID = ComponentPtr->GetComponentResultID_ARS();		
		if ( RESULT_ID_NONE == ResultID )
		{ 
			TestResult.sComponent.Bypass ++;
			continue; 
		}
		if ( RESULT_ID_OK == ResultID ) 
		{
			TestResult.sComponent.OK ++;			
			continue; 
		}
		if ( RESULT_ID_BYPASS==ResultID ||RESULT_ID_SKIP==ResultID) 
		{ 
			TestResult.sComponent.Bypass ++;			
			continue; 
		}
		if ( ComponentPtr->CheckComponentModelEnabled() == false )
		{
			TestResult.sComponent.Bypass ++;			
			continue; 
		}
		TestResult.sComponent.NG ++;				
	}

	//Board Bypass
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
		if ( BoardPtr->GetBoardDeleted() == true ) { continue; }
		TestResult.sBoard.Total ++;		
		if ( BoardPtr->GetBoardBypassed() == true )
		{
			TestResult.sBoard.Bypass ++;
			BoardPtr->SetBoardResultID_ARS(RESULT_ID_BYPASS);//RESULT_ID_SKIP
			BoardPtr->UpdateBoardResultID_ARS_Lane(LaneID);
			continue;
		}

		IsBadBoard = false;		
		BoardPtr->SetBoardResultID_ARS(RESULT_ID_OK);
		BoardComponentCount = BoardPtr->GetBoardComponentCount();
		for ( j=0; j<BoardComponentCount; j++ )
		{
			ComponentPtr = BoardPtr->GetBoardComponentPtr(j, false);
			if ( NULL == ComponentPtr ) { continue; }
			if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
			ResultID = ComponentPtr->GetComponentResultID_ARS();			
			if ( RESULT_ID_NONE == ResultID ) { continue; }
			if ( RESULT_ID_OK == ResultID ) { continue; }			
			if ( RESULT_ID_SKIP == ResultID ) { continue; }
			if ( RESULT_ID_BYPASS == ResultID ) { continue; }
			if ( ComponentPtr->CheckComponentModelEnabled() == false )	{ continue; }
			IsBadBoard = true;
		}
		if ( true == IsBadBoard )
		{
			TestResult.sBoard.NG ++;
			BoardPtr->SetBoardResultID_ARS(RESULT_ID_NG);
		}
		else
		{	TestResult.sBoard.OK ++;	}
		BoardPtr->UpdateBoardResultID_ARS_Lane(LaneID);
	}

	//Panel Bypass
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		if ( PanelPtr->GetPanelDeleted() == true ) { continue; }
		TestResult.sPanel.Total ++;		
		if ( PanelPtr->GetPanelBypassed() == true )
		{
			TestResult.sPanel.Bypass ++;			
			PanelPtr->SetPanelResultID_ARS(RESULT_ID_BYPASS);//RESULT_ID_SKIP
			PanelPtr->UpdatePanelResultID_ARS_Lane(LaneID);
			continue;
		}

		IsBadPanel = false;		
		PanelPtr->SetPanelResultID_ARS(RESULT_ID_OK);		
		PanelBoardCount = PanelPtr->GetPanelBoardCount();
		for ( j=0; j<PanelBoardCount; j++ )
		{
			BoardPtr = PanelPtr->GetPanelBoardPtr(j, false);
			if ( NULL == BoardPtr ) { continue; }
			if ( BoardPtr->GetBoardDeleted() == true ) { continue; }
			ResultID = BoardPtr->GetBoardResultID_ARS();			
			if ( RESULT_ID_NONE == ResultID ) { continue; }
			if ( RESULT_ID_OK == ResultID ) { continue; }
			if ( RESULT_ID_SKIP == ResultID ) { continue; }
			if ( RESULT_ID_BYPASS == ResultID ) { continue; }
			IsBadPanel = true;
		}
		if ( true == IsBadPanel )
		{
			TestResult.sPanel.NG ++;
			PanelPtr->SetPanelResultID_ARS(RESULT_ID_NG);			
		}
		else
		{	TestResult.sPanel.OK ++;	}
		PanelPtr->UpdatePanelResultID_ARS_Lane(LaneID);
	}	

	TestResult.sTest.Total ++;	
	if ( TEST_RESULT_OK == TestResultID )//需考慮到定位點異常
	{
		TestResult.sTest.OK ++;
		TestResult.sResultID = TEST_RESULT_OK;
	}
	else
	{
		TestResult.sTest.NG ++;
		TestResult.sResultID = TEST_RESULT_NG;
	}
	TestResult.sLaneID = LaneID;
	SetProjectResultLatest_ARS(TestResult);
	SetProjectResultLatest_ARS_Lane(LaneID, TestResult);
	return ;
}
//-------------------------------------------------------------------------------------//
void CAOIProject::InitialProjectResultARS(LANE_ID LaneID)//初始化專案檢測結果-ARS
{
	size_t         i=0;
	RESULT_ID      ResultID=RESULT_ID_OK;
	CAOIPanel     *PanelPtr = NULL;
	CAOIBoard     *BoardPtr = NULL;
	CAOIComponent *ComponentPtr = NULL;
	const size_t   PanelCount = GetProjectPanelCount();
	const size_t   BoardCount = GetProjectBoardCount();
	const size_t   ComponentCount = GetProjectComponentCount();

	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		if ( PanelPtr->GetPanelBypassed() == true ) 
		{	
			PanelPtr->SetPanelResultID_ARS(RESULT_ID_BYPASS);//RESULT_ID_SKIP
			PanelPtr->UpdatePanelResultID_ARS_Lane(LaneID);
			continue;
		}
		PanelPtr->SetPanelResultID_ARS(RESULT_ID_NONE);
		PanelPtr->UpdatePanelResultID_ARS_Lane(LaneID);
	}
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
		if ( BoardPtr->GetBoardBypassed() == true ) 
		{	
			BoardPtr->SetBoardResultID_ARS(RESULT_ID_BYPASS);//RESULT_ID_SKIP
			BoardPtr->UpdateBoardResultID_ARS_Lane(LaneID);
			continue;
		}
		BoardPtr->SetBoardResultID_ARS(RESULT_ID_NONE);
		BoardPtr->UpdateBoardResultID_ARS_Lane(LaneID);
	}

	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentBypassed() == true ) 
		{	
			ComponentPtr->SetComponentResultID_ARS(RESULT_ID_BYPASS);
			ComponentPtr->UpdateComponentResultID_ARS_Lane(LaneID);
			continue;
		}
		ComponentPtr->SetComponentResultID_ARS(ResultID);
		ComponentPtr->UpdateComponentResultID_ARS_Lane(LaneID);
	}
	return ;
}
