int CAOIProject::GetProjectFdFreeGroupID()//取得專案定位點可用的群組編號
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return -1; }
	
	size_t       i=0;	
	int          GroupID=0;
	int          MaxGroupID=0;
	CAOIFd      *FdPtr = NULL;
	const size_t FdCount = ProjectPtr->GetProjectFdCount();

	MaxGroupID = GroupID = -1;
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = ProjectPtr->GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		if ( FdPtr->GetFdDeleted() == true ) { continue; }
		GroupID = FdPtr->GetFdGroupID();
		if ( GroupID > MaxGroupID ) 
		{	MaxGroupID = GroupID; }
	}
	GroupID = MaxGroupID+1;
	return GroupID;
}
