//-------------------------------------------------------------------------------------//
bool CAOIProject::CloseProjectActiveComponent(CAOIComponent *ComponentPtr, bool UpdateToeOthers)
{
	CAOIProject *ProjectPtr=this;	
	if ( NULL == ComponentPtr ) { return true; }	
	if ( ComponentPtr->CheckComponentType_ModelTest() == false )	
	{	return true; }
	if ( ComponentPtr->CheckComponentModelEnabled() == false )
	{	return true; }
	if ( ProjectPtr->CheckProjectComponentValid(ComponentPtr) == false )
	{	return false;	}	
	
	ProjectPtr->SetProjectActiveModelWnd(NULL);	

	bool IsOK = false;
	CAOIModel *ModelPtr = ComponentPtr->GetComponentModelPtr();
	const bool bModelModified = ModelPtr->CheckModelModified();		
	const bool ModelIsolated = ComponentPtr->GetComponentModelIsolated();	
	if ( true == bModelModified )
	{	ModelPtr->SetupkModelModifiedDateTime();	}	
	if ( false == ModelIsolated )
	{	
		if ( ModelPtr->GetModelModifiedCount() == true ) 
		{	IsOK = ProjectPtr->ApplyProjectCompnentModelToLibraryModel(ComponentPtr, UpdateToeOthers); }
		else
		{	IsOK = ProjectPtr->SyncProjectCompnentModelToLibraryModel(ComponentPtr, true, UpdateToeOthers); }
	}	
	//ComponentPtr->SetComponentSelected(false);
	return IsOK;	
}
