bool CAOIProject::SaveProjectFile(LPCTSTR filename)//儲存專案檔案
{
	if ( SaveProjectFileFn(filename) == false )
	{
		SetProjectExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectFileFn(LPCTSTR filename)//儲存專案檔案
{
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false )
	{	return false; }

	CString       str;	
	double        fnTime=0;
	bool          IsOK=false;
	LARGE_INTEGER fnEnd;
	LARGE_INTEGER fnStart;
	CAOIFileIO    FileIO;
	CString FileFolderDst;
	CString OfflineFolderDst;
	CString FiducialFolderDst;
	CString LibraryFolderDst;
	CString PartLibraryFolderDst;
	CString FileNameDst = filename;

	JetAPI::ExtractMainFileName(FileNameDst, FileFolderDst);
	OfflineFolderDst = AOIDataDefine.GetProjectOfflineFolderName(FileFolderDst);
	FiducialFolderDst = AOIDataDefine.GetProjectFdFolderName(FileFolderDst);
	LibraryFolderDst  = AOIDataDefine.GetProjectLibraryFolderName(FileFolderDst);
	PartLibraryFolderDst = AOIDataDefine.GetProjectPartLibraryFolderName(FileFolderDst);	

	FileIO.CreateProgressWnd();

	FileIO.SetFileName(FileNameDst);
	FileIO.SetFdFolder(FiducialFolderDst);
	FileIO.SetFileFolder(FileFolderDst);
	FileIO.SetLibraryFolder(LibraryFolderDst);
	FileIO.SetPartLibraryFolder(PartLibraryFolderDst);
	FileIO.SetTotalNodes(0);
	FileIO.SetTotalModelObjs(0);
	FileIO.SetTotalComponents(0);
	FileIO.SetNNodeCount(0);
	FileIO.SetFileTarget(FILE_TARGET_PROJECT);

	JetAPI::SetFuncTimeStart(fnStart);
	IsOK = UpdateToProjectVersionCode();
	JetAPI::SetFuncTimeStart(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CAOIProject::UpdateToProjectVersionCode Time=%.3f ms"), fnTime);
	AOIDataCollect.SaveMovingTimeMsg(str);
	if ( false == IsOK )//Kai-20180528
	{	
		FileIO.DestroyProgressWnd();		
		return false;
	}
	
	JetAPI::SetFuncTimeStart(fnStart);
	IsOK = FileIO.OpenSaveFile(filename);
	JetAPI::SetFuncTimeStart(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CAOIFileIO::OpenSaveFile Time=%.3f ms"), fnTime);
	AOIDataCollect.SaveMovingTimeMsg(str);
	if ( false == IsOK )//Kai-20180528
	{
		str = FileIO.GetErrorString();
		m_ErrorString.Format(_T("%s [%s]"), str, filename);
		FileIO.DestroyProgressWnd();		
		return false;
	}

	JetAPI::SetFuncTimeStart(fnStart);
	IsOK = WriteProjectFile(FileIO);
	JetAPI::SetFuncTimeStart(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CAOIProject::WriteProjectFile Time=%.3f ms"), fnTime);
	AOIDataCollect.SaveMovingTimeMsg(str);
	if ( false == IsOK )
	{
		str = FileIO.GetErrorString();
		m_ErrorString.Format(_T("%s [%s]"), str, filename);
		FileIO.CloseFile();
		FileIO.DestroyProgressWnd();		
		return false;
	}
	FileIO.CloseFile();
	FileIO.DestroyProgressWnd();
	ProjectPtr->SetupProjectSavedDateTime();
	return true;
}
