bool CAOIProject::ChangeProjectObjUUID()//變更專案的物件UUID-另存專案時使用
{
	UUID uuid;
	::UuidCreate(&uuid);
	CAOIProject::SetObjUuid(uuid);
	return true;
}
//-------------------------------------------------------------------------------------//
void CAOIProject::MoveProjectPos(double dX, double dY)//移動專案
{
	size_t       i=0;
	CAOIPanel   *PanelPtr = NULL;	
	const size_t PanelCount = GetProjectPanelCount();
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		PanelPtr->MovePanelPos(dX, dY);
	}
}
//-------------------------------------------------------------------------------------//
void CAOIProject::MoveProjectStagePos(double dX, double dY)//移動專案
{
	size_t       i=0;
	CAOIPanel   *PanelPtr = NULL;
	DISTRICT_ID  DistrictID = GetProjectActDistrictID();
	const size_t PanelCount = GetProjectPanelCount();
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		PanelPtr->MovePanelStagePos(dX, dY, DistrictID);
	}
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::InitialProjectBasePlaneParam(TBasePlaneParam &Param)//初始化基準面參數
{
	Param.BasePlane2DMaskEnabled = false;
	Param.BasePlane2DMaskFrameIndex = 0;
	Param.BasePlane2DMaskFrameUniqueID = FRAME_UNIQUE_ID_DEFAULT;
	Param.BasePlane2DMaskGroupLinkIndex = PROJECT_COLOR_ID_BOARD_BEGIN;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::RotateProjectBasePlaneParam(double Angle, TBasePlaneParam &Param)//旋轉基準面參數
{
	Param.UseSideMode=JetAPI::RotateSideMode(Angle, Param.UseSideMode);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::UpdateProjectBasePlaneColorGroupLinkIndex(const std::vector<CColorGroup> &ColorGroupList, TBasePlaneParam &Param)//更新基準面抽色參數
{
	const size_t ColorGroupCount=ColorGroupList.size();	
	const int ColorGroupIndex = Param.BasePlane2DMaskGroupLinkIndex;
	if ( ColorGroupIndex>=0 && ColorGroupIndex<ColorGroupCount )
	{
		const CColorGroup &ColorGroupRef=ColorGroupList[ColorGroupIndex];
		Param.BasePlane2DMaskFrameIndex = ColorGroupRef.GetColorGroupFrameIndex();
		Param.BasePlane2DMaskFrameUniqueID = ColorGroupRef.GetColorGroupFrameUniqueID();		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::UpdateProjectBasePlaneFrameIndex(unsigned int DefaultIndex, unsigned int DefaultUniqueID, const std::vector<unsigned int> &FrameIndexMapList, TBasePlaneParam &Param)//更新基準面的畫面引數
{
	unsigned int FrameIndex = Param.BasePlane2DMaskFrameIndex;		
	unsigned int FrameUniqueID = Param.BasePlane2DMaskFrameUniqueID;		
	const size_t FrameIndexMapSize = FrameIndexMapList.size();
	if ( FrameUniqueID<0 || FrameUniqueID>=FrameIndexMapSize )
	{	
		FrameIndex = DefaultIndex;	
		FrameUniqueID = DefaultUniqueID;
	}
	else
	{	
		FrameIndex = (FrameIndexMapList[FrameUniqueID]);
		if ( -1 == FrameIndex )
		{ 
			FrameIndex = DefaultIndex;	
			FrameUniqueID = DefaultUniqueID;
		}
	}	
	Param.BasePlane2DMaskFrameIndex = FrameIndex;
	Param.BasePlane2DMaskFrameUniqueID = FrameUniqueID;
	return true;
}
//-------------------------------------------------------------------------------------//
BOARD_FD_GRAB_MODE CAOIProject::CheckProjectBoardFdGragMode()//確認專案單板定位點取像模式
{
	m_ProjectBoardFdGrabMode = m_ProjectParameter.m_BoardFdGrabMode;	
	if ( BOARD_FD_GRAB_AFTER_PANEL == m_ProjectBoardFdGrabMode ) { return m_ProjectBoardFdGrabMode; }
	//if ( BOARD_FD_GRAB_AFTER_PANEL == m_ProjectBoardFdGrabMode ) { return m_ProjectBoardFdGrabMode; }

	size_t       i=0;
	CAOIFd      *FdPtr = NULL;
	CAOIBoard   *BoardPtr = NULL;
	const size_t FdCount = GetProjectFdCount();
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		if ( FdPtr->GetFdDeleted() == true ) { continue; }

		BoardPtr = FdPtr->GetFdBoardPtr();
		if ( NULL == BoardPtr ) { continue; }
		if ( BoardPtr->GetBoardBypassed() == true ) { continue; }
		if ( BoardPtr->GetBoardMapEnable() == false ) { continue; }
		if ( FdPtr->GetFdNeedToCalculate() == false ) { continue; }
		m_ProjectBoardFdGrabMode = BOARD_FD_GRAB_INSPECTING;
		return m_ProjectBoardFdGrabMode;
	}
	m_ProjectBoardFdGrabMode = BOARD_FD_GRAB_AFTER_PANEL;
	return m_ProjectBoardFdGrabMode;
}
//---------------------------------------------------------------------------------//
size_t CAOIProject::GetProjectMapRgnCount() const//取得專案底圖區域數量
{
	return GetProjectMapRgnCount_Inline();
}
//---------------------------------------------------------------------------------//
CAOIRgn* CAOIProject::GetProjectMapRgnPtr(size_t index, bool check) const//取得專案底圖區域指標
{
	if ( true == check )
	{
		const size_t count = GetProjectMapRgnCount_Inline();
		if ( index >= count )
		{	return NULL; }
	}
	return GetProjectMapRgnPtr_Inline(index);
}
//---------------------------------------------------------------------------------//
CAOIRgn* CAOIProject::AddProjectMapRgnPtr(CAOIRgn *MapRgnPtr, bool clone)//增加專案底圖區域
{
	if ( NULL == MapRgnPtr )
	{
		this->m_ErrorString.Format(_T("Error, AddProjectMapRgnPtr Fault"));
		return NULL;
	}

	CAOIRgn *NewMapRgnPtr = MapRgnPtr;
	const int MapRgnIndex = (int)(GetProjectMapRgnCount_Inline());
	if ( true == clone )
	{		
		NewMapRgnPtr = MapRgnPtr->CloneRgnObj();
		if ( NULL == NewMapRgnPtr ) { return NULL; }		
	}
	
	NewMapRgnPtr->SetRgnProjectPtr(this);
	NewMapRgnPtr->SetRgnIndex(MapRgnIndex);
	AddProjectMapRgnPtr_Inline(NewMapRgnPtr);	
	return NewMapRgnPtr;
}
//---------------------------------------------------------------------------------//
bool CAOIProject::ClearProjectAllMapRgns()//刪除專案底圖區域
{
	size_t i = 0;
	CAOIRgn *MapRgnPtr = NULL;
	const size_t MapRgnCount = GetProjectMapRgnCount_Inline();
	for ( i=0; i<MapRgnCount; i++ )
	{
		MapRgnPtr = GetProjectMapRgnPtr_Inline(i);
		if ( NULL == MapRgnPtr ) { continue; }		
		AOIObjManager.DestroyRgnObj(m_ProjectMapRgnPtrList[i]);			
		MapRgnPtr = NULL;		
	}		
	m_ProjectMapRgnPtrList.clear();
	return true;
}
//---------------------------------------------------------------------------------//
bool CAOIProject::UpdateProjectSpaceBasePlaneParam(const TBasePlaneParam &Param)//更新專案空間基準面參數
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }
	if ( -1 == Param.BasePlaneIndex ) { return true; }

	size_t    i=0, j=0;
	int       ParamIndex=0;	
	const int RefParamIndex=Param.BasePlaneIndex;	
	TProjectParameter &ProgParam = GetProjectParameter();	

	//For Drop Out Part-3D
	TNoiseFilterParam &DropSpaceNoiseFilter=ProgParam.m_DropOutPartSpaceNoiseFilter;//空間雜訊過濾處理
	ParamIndex = DropSpaceNoiseFilter.BasePlaneParam.BasePlaneIndex;
	if ( ParamIndex == RefParamIndex )
	{	DropSpaceNoiseFilter.BasePlaneParam = Param; }

	//For Part-Dimension 3D
	TNoiseFilterParam &DimensionSpaceNoiseFilter=ProgParam.m_PartDimensionSpaceNoiseFilter;//空間雜訊過濾處理
	ParamIndex = DimensionSpaceNoiseFilter.BasePlaneParam.BasePlaneIndex;
	if ( ParamIndex == RefParamIndex )
	{	DimensionSpaceNoiseFilter.BasePlaneParam = Param; }

	//Fd	
	CAOIFd      *FdPtr = NULL;
	const size_t FdCount = ProjectPtr->GetProjectFdCount();
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = ProjectPtr->GetProjectFdPtr(i, false);
		if ( NULL == FdPtr )	{	continue; }
		ParamIndex = FdPtr->GetFdSpaceBasePlaneParam().BasePlaneIndex;
		if ( RefParamIndex != ParamIndex ) { continue; }		
		FdPtr->SetFdSpaceBasePlaneParam(Param);
	}	

	//Mark
	CAOIMark    *MarkPtr = NULL;
	const size_t MarkCount = ProjectPtr->GetProjectMarkCount();
	for ( i=0; i<MarkCount; i++ )
	{
		MarkPtr = ProjectPtr->GetProjectMarkPtr(i, false);
		if ( NULL == MarkPtr )	{	continue; }
		ParamIndex = MarkPtr->GetMarkSpaceBasePlaneParam().BasePlaneIndex;
		if ( RefParamIndex != ParamIndex ) { continue; }		
		MarkPtr->SetMarkSpaceBasePlaneParam(Param);
	}

	//Barcode
	CAOIBarcode *BarcodePtr = NULL;
	const size_t BarcodeCount = ProjectPtr->GetProjectBarcodeCount();
	for ( i=0; i<BarcodeCount; i++ )
	{
		BarcodePtr = ProjectPtr->GetProjectBarcodePtr(i, false);
		if ( NULL == BarcodePtr )	{	continue; }
		ParamIndex = BarcodePtr->GetBarcodeSpaceBasePlaneParam().BasePlaneIndex;
		if ( RefParamIndex != ParamIndex ) { continue; }		
		BarcodePtr->SetBarcodeSpaceBasePlaneParam(Param);
	}

	//Component
	CAOIComponent *ComponentPtr = NULL;
	const size_t   ComponentCount = ProjectPtr->GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr )	{	continue; }
		ParamIndex = ComponentPtr->GetComponentSpaceBasePlaneParam().BasePlaneIndex;
		if ( RefParamIndex != ParamIndex ) { continue; }		
		ComponentPtr->SetComponentSpaceBasePlaneParam(Param);
	}
	return true;	
}
