bool CAOIProject::ClearProjectAllTempRgns()//刪除整個檢測區域指標
{
	size_t i = 0;
	CAOIRgn *RgnPtr = NULL;
	const size_t RgnCount = this->m_ProjectTempRgnPtrList.size();
	for ( i=0; i<RgnCount; i++ )
	{
		RgnPtr = m_ProjectTempRgnPtrList[i];
		if ( NULL == RgnPtr ) { continue; }
		if ( RgnPtr->GetRgnLinkPointer() == true ) { continue; }
		AOIObjManager.DestroyRgnObj(m_ProjectTempRgnPtrList[i]);
	}
	m_ProjectTempRgnPtrList.clear();
	return true;
}
//---------------------------------------------------------------------------------//
bool CAOIProject::AddProjectTempRgnPtr(CAOIRgn *Ptr, bool clone)//新增加檢測區域指標
{
	CAOIRgn *NewPtr = Ptr;
	if ( true == clone )
	{
		NewPtr = Ptr->CloneRgnObj();
		if ( NULL == NewPtr )
		{	return false; }
	}
	const unsigned int Count = (unsigned int)(this->m_ProjectTempRgnPtrList.size());
	NewPtr->SetRgnIndex(Count);
	this->m_ProjectTempRgnPtrList.push_back(NewPtr);
	return true;
}
