//-------------------------------------------------------------------------------------//
bool  CAOIProject::UpdateProjectColorGroupListInfo(std::vector<CColorGroup>  &ColorGroupList)//更新專案色彩資料
{
	size_t       i=0;
	CString      ColorName;
	CColorGroup *ColorGroupPtr=NULL;	
	unsigned int FrameIndex = 0;
	unsigned int FrameUniqueID = 0;
	unsigned int DefaultFrameIndex = 0;
	unsigned int DefaultFrameUniqueID = 0;
	const size_t ColorGroupCount = ColorGroupList.size();
	
	DefaultFrameIndex = 0;
	DefaultFrameUniqueID = GetProjectFrameUniqueID(DefaultFrameIndex, true);

	for ( i=0; i<ColorGroupCount; i++ )
	{
		ColorGroupPtr = &(ColorGroupList[i]);
		if ( NULL == ColorGroupPtr ) { continue; }

		FrameUniqueID = ColorGroupPtr->GetColorGroupFrameUniqueID();
		FrameIndex = GetProjectFrameIndexByUniqueID(FrameUniqueID);
		if ( -1 == FrameIndex )
		{
			FrameIndex = DefaultFrameIndex;
			FrameUniqueID = DefaultFrameUniqueID;
		}
		//ColorGroupPtr->SetColorGroupIndex(i);	
		//ColorGroupPtr->SetColorGroupName(ColorName);
		ColorGroupPtr->SetColorGroupFrameIndex(FrameIndex);
		ColorGroupPtr->SetColorGroupFrameUniqueID(FrameUniqueID);
	}
	return true;
}
