bool CAOIProject::UpdateProjectColorGroup(CAlgBinaryParam *BinaryParamPtr)//更新專案色彩
{
	if ( NULL == BinaryParamPtr ) { return true; }
	if ( UpdateProjectColorGroup(*BinaryParamPtr) == false ) { return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::UpdateProjectColorGroup(const CAlgBinaryParam &BinaryParam)//更新專案色彩
{
	BINARY_MODE BinaryMode = BinaryParam.GetBinaryMode();
	if ( BINARY_COLOR_FILTER != BinaryMode ) { return true; }

	const int LinkIndex = BinaryParam.GetBinaryColorGroupLinkIndex();
	const CColorGroup &ColorGroup = BinaryParam.GetBinaryColorGroup();
	const int ColorGroupCount = GetProjectColorGroupCount();
	if ( LinkIndex < 0 || LinkIndex>=ColorGroupCount )
	{	return true; }
	
	SetProjectColorGroup(LinkIndex, ColorGroup);
	UpdateProjectColorGroupToModel(LinkIndex, ColorGroup);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SetProjectColorGroup(size_t idx, const CColorGroup &ColorGroup)//設定專案色彩
{
	const size_t Count = m_ProjectColorGroupList.size();
	if ( idx >= Count ) { return false; }
	const size_t Index = m_ProjectColorGroupList[idx].GetColorGroupIndex();
	CString ColorName = m_ProjectColorGroupList[idx].GetColorGroupName();
	m_ProjectColorGroupList[idx] = ColorGroup;
	m_ProjectColorGroupList[idx].SetColorGroupIndex(Index);
	m_ProjectColorGroupList[idx].SetColorGroupName(ColorName);
	return true;
}
