//-------------------------------------------------------------------------------------//
bool CAOIProject::UpdateProjectColorGroupListToModel()//將專案色彩更新至模組
{
	size_t         i=0;				
	const std::vector<CColorGroup>  &ColorGroupList=m_ProjectColorGroupList;

	TBasePlaneParam &DropBasePlaneParamRef=GetProjectParameter().m_DropOutPartSpaceNoiseFilter.BasePlaneParam;	
	UpdateProjectBasePlaneColorGroupLinkIndex(ColorGroupList, DropBasePlaneParamRef);

	CAOIModel     *ModelPtr = NULL;	
	const size_t   ModelCount = GetProjectModelCount();	
	for ( i=0; i<ModelCount; i++ )
	{
		ModelPtr = GetProjectModelPtr(i, false);
		if ( NULL == ModelPtr ) { continue; }		
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);		
	}

	CAOIFd        *FdPtr = NULL;
	const size_t   FdCount = GetProjectFdCount();
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		ModelPtr = FdPtr->GetFdModelPtr();
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);		
	}

	CAOIMark    *MarkPtr = NULL;
	const size_t MarkCount = GetProjectMarkCount();
	for ( i=0; i<MarkCount; i++ )
	{
		MarkPtr = GetProjectMarkPtr(i, false);
		if ( NULL == MarkPtr ) { continue; }
		ModelPtr = MarkPtr->GetMarkModelPtr();
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);		
	}

	CAOIBarcode   *BarcodePtr = NULL;
	const size_t   BarcodeCount = GetProjectBarcodeCount();
	for ( i=0; i<BarcodeCount; i++ )
	{
		BarcodePtr = GetProjectBarcodePtr(i, false);
		if ( NULL == BarcodePtr ) { continue; }
		ModelPtr = BarcodePtr->GetBarcodeModelPtr();
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);		
	}

	CAOIComponent *ComponentPtr = NULL;
	const size_t   ComponentCount = GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->UpdateComponentColorGroupLinkIndex(ColorGroupList);

		ModelPtr = ComponentPtr->GetComponentModelPtr();
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::UpdateProjectColorGroupToModel(int LinkIndex, const CColorGroup &ColorGroup)//更新專案色彩更新
{
	size_t         i=0;				
	
	CAOIModel     *ModelPtr = NULL;	
	const size_t   ModelCount = GetProjectModelCount();	
	for ( i=0; i<ModelCount; i++ )
	{
		ModelPtr = GetProjectModelPtr(i, false);
		if ( NULL == ModelPtr ) { continue; }		
		ModelPtr->UpdateModelColorGroupLinkIndex(LinkIndex, ColorGroup);
	}

	CAOIFd        *FdPtr = NULL;
	const size_t   FdCount = GetProjectFdCount();
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		ModelPtr = FdPtr->GetFdModelPtr();
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->UpdateModelColorGroupLinkIndex(LinkIndex, ColorGroup);
	}

	CAOIMark    *MarkPtr = NULL;
	const size_t MarkCount = GetProjectMarkCount();
	for ( i=0; i<MarkCount; i++ )
	{
		MarkPtr = GetProjectMarkPtr(i, false);
		if ( NULL == MarkPtr ) { continue; }
		ModelPtr = MarkPtr->GetMarkModelPtr();
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->UpdateModelColorGroupLinkIndex(LinkIndex, ColorGroup);
	}

	CAOIBarcode   *BarcodePtr = NULL;
	const size_t   BarcodeCount = GetProjectBarcodeCount();
	for ( i=0; i<BarcodeCount; i++ )
	{
		BarcodePtr = GetProjectBarcodePtr(i, false);
		if ( NULL == BarcodePtr ) { continue; }
		ModelPtr = BarcodePtr->GetBarcodeModelPtr();
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->UpdateModelColorGroupLinkIndex(LinkIndex, ColorGroup);
	}

	CAOIComponent *ComponentPtr = NULL;
	const size_t   ComponentCount = GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ModelPtr = ComponentPtr->GetComponentModelPtr();
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->UpdateModelColorGroupLinkIndex(LinkIndex, ColorGroup);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ReadProjectColorGroup(CAOIFileIO &FileIO)//載入專案色彩
{
	#ifdef _DEBUG
	if ( FileIO.CheckFileMode() == FALSE ) { return false; }
	if ( FileIO.CheckFileOpened() == FALSE ) { return false; }
#endif//_DEBUG
	
	UUID           uuid;
	int            index=0;
	int            nValue=0;	
	//----------------------------------------------------------------------------------------//	
	CAOIProject   *Project = this;
	CColorGroup    ColorGroup;
	FileIO.SetFnName(_T("CAOIProject::ReadProjectColorGroup"));
	//----------------------------------------------------------------------------------------//
	while ( FileIO.CheckFileEnd()==false )
	{ 	
		if ( FileIO.LoadChunk(index) == false )		
		{	continue; }
		
		switch ( index )
		{
		case FILE_IO_SYSTEM_SECTION_START://系統參數區間-起點
			Project->InitialLoadProjectFile();
			Project->ClearProjectAllObjects();			
			break;
		case FILE_IO_SYSTEM_SECTION_END://系統參數區間-終點
			break;		
		case FILE_IO_PROJECT_SECTION_START://專案參數區間-起點
			break;		
		case FILE_IO_PROJECT_COLOR_GROUP_NODE://專案參數-專案色彩群組
			nValue = FileIO.GetData_INT();
			if ( ColorGroup.ReadColorGroupFile(FileIO) == false )
			{	return false; }
			ColorGroup.SetColorGroupIndex(nValue);
			ColorGroup.SetColorGroupName(AOIDataDefine.GetProjectColorGroupText(nValue));			
			SetProjectColorGroup(nValue, ColorGroup);
			break;		
		case FILE_IO_PROJECT_SECTION_END://專案參數區間-終點	
			return true;
			break;		
		case FILE_IO_END://寫檔結束						
			return true;
			break;
		}
	};
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectColorGroup(LPCTSTR filename, std::vector<CColorGroup>  &ColorGroupList)//載入專案色彩
{
	if ( LoadProjectColorGroupFn(filename, ColorGroupList) == false )
	{
		SetProjectExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectColorGroupFn(LPCTSTR filename, std::vector<CColorGroup>  &ColorGroupList)//載入專案色彩		
{	
	CAOIFileIO FileIO;	
	FileIO.SetFileName(filename);
	FileIO.SetTotalNodes(0);
	FileIO.SetNNodeCount(0);
	FileIO.SetTotalModelObjs(0);
	FileIO.SetTotalComponents(0);
	FileIO.SetFileTarget(FILE_TARGET_OTHERS);

	if ( FileIO.OpenLoadFile(filename) == false )//Kai-20180528
	{
		this->m_ErrorString = FileIO.GetErrorString();
		FileIO.DestroyProgressWnd();		
		return false;
	}		
	if ( ReadProjectColorGroup(FileIO) == false )
	{
		this->m_ErrorString = FileIO.GetErrorString();
		FileIO.CloseFile();
		FileIO.DestroyProgressWnd();		
		return false;
	}	
	FileIO.CloseFile();
	FileIO.DestroyProgressWnd();

	CloneProjectColorGroupList(ColorGroupList);	
	return true;
}
