void CAOIProject::ClearProjectMapBuffer()//清除專案底圖指標
{
	unsigned int i=0;		
	SetProjectMapIndex(0);//專案底圖的引數	
	ClearProjectMapShowBuffer();	
	for ( i=0; i<FRAME_MAX_COUNT; i++ )
	{
		if ( NULL != m_ProjectMapPtr[i] )
		{	JetMemory.free_func(m_ProjectMapPtr[i]); }

		m_ProjectMapW[i] = 0;//專案底圖寬度
		m_ProjectMapH[i] = 0;//專案底圖長度
		m_ProjectMapStep[i] = 0;//專案底圖步長
		m_ProjectBitCount[i] = 0;//專案底圖位元數	
		m_ProjectMapPtr[i] = NULL;//專案底圖指標
		m_ProjectMapFilename[i] = _T("");
		m_ProjectMapFilenameSmall[i] = _T("");
	}	
}
