//-------------------------------------------------------------------------------------//
bool CAOIProject::CalcProjectMapBufferFn(const TPOINT3D &StagePos1, const TPOINT3D &StagePos2)//計算專案影像資料	
{
	ClearProjectMapBuffer();
	ClearProjectAllTempObjects();	

	char  vaName[256]="";
	const char fnName[] = "CAOIProject::CalcProjectMapBuffer";
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;	
	TREGION4D  ProjectRegion;
	TSIZE2D    ProjectSize, ProjectImageSize;
	DISTRICT_ID DistrictID = GetProjectActDistrictID();
	ProjectRegion.minX = MIN(StagePos1.x, StagePos2.x);
	ProjectRegion.maxX = MAX(StagePos1.x, StagePos2.x);
	ProjectRegion.minY = MIN(StagePos1.y, StagePos2.y);
	ProjectRegion.maxY = MAX(StagePos1.y, StagePos2.y);
	ProjectSize.cx = ProjectRegion.GetWidth();
	ProjectSize.cy = ProjectRegion.GetHeight();

	unsigned int i=0, j=0;
	IMAGE_SIZE ImageW=0, ImageH=0;
	double ImageResX=0.0, ImageResY=0.0;
	int    ScaleMode=1, ScaleModeX=1, ScaleModeY=1;		
	double ProjectImageResX=1.0, ProjectImageResY=1.0;		
	const TImageParameter &ImageParam = AOIDataCollect.GetImageParameter();
	const double ImageWMax = ImageParam.m_ProjectImageMaxWidth;
	const double ImageHMax = ImageParam.m_ProjectImageMaxHeight;
	AOIDataCollect.GetCameraImageInfo(CameraID, ImageW, ImageH, ImageResX, ImageResY);

	ProjectImageSize.cx = ProjectSize.cx/ImageResX;
	ProjectImageSize.cy = ProjectSize.cy/ImageResY;
	ScaleModeX = (int)(ProjectImageSize.cx/ImageWMax);
	if ( ScaleModeX < 1 ) { ScaleModeX = 1; }
	ScaleModeY = (int)(ProjectImageSize.cy/ImageHMax);
	if ( ScaleModeY < 1 ) { ScaleModeY = 1; }
	ScaleMode = MAX(ScaleModeX, ScaleModeY);

	m_ProjectMapIndex3D = -1;
	ScaleMode = GetProjectMapScaleMode();//使用專案指定比例
	ScaleModeX = ScaleModeY = ScaleMode;
	ProjectImageResX = ScaleModeX*ImageResX;
	ProjectImageResY = ScaleModeY*ImageResY;

	IMAGE_PTR ProjectMapPtr[FRAME_MAX_COUNT]= {NULL};
	IMAGE_SIZE ProjectMapW[FRAME_MAX_COUNT] = {0};
	IMAGE_SIZE ProjectMapH[FRAME_MAX_COUNT] = {0};
	IMAGE_SIZE ProjectBitCount[FRAME_MAX_COUNT] = {0};
	IMAGE_SIZE ProjectMapStep[FRAME_MAX_COUNT] = {0};	

	IMAGE_SIZE    BitCount = 0;
	TFrameParam  *FrameParamPtr = NULL;	
	const size_t ProjectFrameImageCount = (m_ProjectFrameUniqueIDList.size());
	if ( ProjectFrameImageCount<1 || ProjectFrameImageCount>FRAME_MAX_COUNT )
	{
		m_ErrorString.Format(_T("Error, Project frame image count exception (%d)"), ProjectFrameImageCount);
		m_ErrorString = LoadMultiLanguageString(m_ErrorString, m_ErrorString);
		return false;
	}

	RECT  MapRect={0,0,0,0};
	const IMAGE_SIZE MapW = JetAPI::Ceil(ProjectSize.cx/ProjectImageResX);
	const IMAGE_SIZE MapH = JetAPI::Ceil(ProjectSize.cy/ProjectImageResY);
	if ( MapW<2 || MapH<2 )
	{
		m_ErrorString.Format(_T("Error, Project map size exception (%d, %d)"), MapW, MapH);
		m_ErrorString = LoadMultiLanguageString(m_ErrorString, m_ErrorString);
		return false;
	}

	JetAPI::SizeToRect(MapW, MapH, MapRect);
	for ( i=0; i<ProjectFrameImageCount; i++ )
	{
		FrameParamPtr = &(m_ProjectFrameParamList[i]);
		switch ( FrameParamPtr->FrameType )
		{
		case FRAME_GRAY:	 BitCount =  8;	break;
		case FRAME_BAYER:	 BitCount = 24;	break;
		case FRAME_COLOR:	 BitCount = 24;	break;
		case FRAME_SPACE:	 BitCount =  8;	break;
		default:	BitCount = 0; break;
		}
		if ( 0 == BitCount ) { continue; }
		if ( FRAME_SPACE == FrameParamPtr->FrameType )
		{	m_ProjectMapIndex3D = i; }
		::sprintf(vaName, "ProjectMapPtr#%d", i+1);
		ProjectMapW[i] = MapW;
		ProjectMapH[i] = MapH;
		ProjectBitCount[i] =  BitCount;
		ProjectMapStep[i] = JetAPI::GetBMPImagePixelsPerLine(ProjectMapW[i], ProjectBitCount[i], 4);
		
		const size_t BufferSize = ImageAPI.CalcBufferSize(ProjectMapStep[i], ProjectMapH[i]);
		if ( 0 == BufferSize )
		{
			m_ErrorString=_T("Error, Map Size is zero, check map region first");
			return false;
		}
		if ( JetMemory.alloc_func(BufferSize, ProjectMapPtr[i], fnName, vaName) == false )
		{
			for ( j=0; j<i; j++ )
			{	JetMemory.free_func(ProjectMapPtr[j]);	}
			this->m_ErrorString = JetMemory.GetErrorString();
			return false;
		}
		::memset(ProjectMapPtr[i], 0x00, sizeof(IMAGE_DATA)*BufferSize);		
	}
	for ( i=0; i<ProjectFrameImageCount; i++ )
	{
		m_ProjectMapW[i] = ProjectMapW[i];//專案底圖寬度
		m_ProjectMapH[i] = ProjectMapH[i];//專案底圖長度
		m_ProjectMapStep[i] = ProjectMapStep[i];//專案底圖步長
		m_ProjectBitCount[i] = ProjectBitCount[i];//專案底圖位元數
		m_ProjectMapPtr[i] = ProjectMapPtr[i];//專案底圖指標
		m_ProjectMapFilename[i] = _T("");
		m_ProjectMapFilenameSmall[i] = _T("");
	}
	
	m_ProjectMapIndex = 0;
	m_ProjectMapShowIndex = FRAME_MAX_COUNT;
	m_ProjectMapResX = ProjectImageResX;//專案底圖解析度-X
	m_ProjectMapResY = ProjectImageResY;//專案底圖解析度-Y
	m_ProjectMapScaleMode = ScaleMode;//專案底圖縮小模式

	m_ProjectParameter.m_TestSizeWidth = JetAPI::Unit_UmtoMM(ProjectSize.cx);
	m_ProjectParameter.m_TestSizeHeight = JetAPI::Unit_UmtoMM(ProjectSize.cy);
	
	SetProjectMapLocRect(MapRect);	
	SetProjectMapLocSize(ProjectSize);
	ResetProjectMapTeachRgn(ProjectRegion);		
	SetProjectMapLocStageRgn(ProjectRegion);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SetProjectMapPtr(unsigned int MapIndex, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, IMAGE_PTR Ptr)//設定專案影像	
{
	if ( MapIndex >= FRAME_MAX_COUNT ) 
	{
		m_ErrorString.Format(_T("Error, MapIndex out of range [%d/%d]"), MapIndex, FRAME_MAX_COUNT);
		SetProjectExceptionCode(AOI_EXCEPTION_PROJECT_MAP_VALID);
		return false; 
	}
	if ( NULL == Ptr )
	{
		m_ErrorString.Format(_T("Error, Map Ptr is NULL [%d/%d]"), MapIndex, FRAME_MAX_COUNT);
		SetProjectExceptionCode(AOI_EXCEPTION_PROJECT_MAP_VALID);
		return false; 
	}	
	m_ProjectMapPtr[MapIndex] = Ptr;
	m_ProjectMapW[MapIndex] = ImageW;
	m_ProjectMapH[MapIndex] = ImageH;
	m_ProjectMapStep[MapIndex] = ImageStep;
	m_ProjectBitCount[MapIndex] = BitCount;
	m_ProjectMapFilename[MapIndex] = _T("");
	m_ProjectMapFilenameSmall[MapIndex] = _T("");
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::GetProjectMapPtr(unsigned int MapIndex, IMAGE_SIZE &ImageW, IMAGE_SIZE &ImageH, IMAGE_SIZE &ImageStep, IMAGE_SIZE &BitCount, IMAGE_PTR &Ptr)//取得專案影像
{
	if ( MapIndex >= FRAME_MAX_COUNT ) 
	{
		m_ErrorString.Format(_T("Error, MapIndex out of range [%d/%d]"), MapIndex, FRAME_MAX_COUNT);
		SetProjectExceptionCode(AOI_EXCEPTION_PROJECT_MAP_VALID);	
		return false; 
	}
	if ( NULL == m_ProjectMapPtr[MapIndex] )
	{
		m_ErrorString.Format(_T("Error, Map Ptr is NULL [%d/%d]"), MapIndex, FRAME_MAX_COUNT);
		//SetProjectExceptionCode(AOI_EXCEPTION_PROJECT_MAP_VALID);	
		return false; 
	}

	Ptr       = m_ProjectMapPtr[MapIndex];
	ImageW    = m_ProjectMapW[MapIndex];
	ImageH    = m_ProjectMapH[MapIndex];
	ImageStep = m_ProjectMapStep[MapIndex];
	BitCount  = m_ProjectBitCount[MapIndex];
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::MapProjectCadToMapPos(double PosX, double PosY, double &rPosX, double &rPosY, DISTRICT_ID DistrictID)//將專案Cad座標轉成底圖座標
{
	rPosX = rPosY = 0.0;
	if ( NULL == m_ProjectMapPtr[0] ) { return false; }	
	const int MapIndex = 0;	
	TREGION4D MapCadRgn;
	IMAGE_SIZE ImageW=m_ProjectMapW[MapIndex];
	IMAGE_SIZE ImageH=m_ProjectMapH[MapIndex];
	switch ( DistrictID )
	{
	case DISTRICT_ID_A:	GetProjectMapCadRgn_DA(MapCadRgn);	break;
	case DISTRICT_ID_B:	GetProjectMapCadRgn_DB(MapCadRgn);	break;
	}
	const double CadRgnCpX = MapCadRgn.GetCpX();
	const double CadRgnCpY = MapCadRgn.GetCpY();
	const double CadOffsetX = PosX-CadRgnCpX;
	const double CadOffsetY = PosY-CadRgnCpY;
	const double ImageOffsetX = CadOffsetX/m_ProjectMapResX;
	const double ImageOffsetY = CadOffsetY/m_ProjectMapResY;	
	double ImagePosX = ImageOffsetX+(ImageW*0.5);
	double ImagePosY = ImageOffsetY+(ImageH*0.5);
	rPosX = ImagePosX;
	rPosY = ImageH-ImagePosY;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::MapProjectStageToMapPos(double PosX, double PosY, double &rPosX, double &rPosY, LANE_ID LaneID, DISTRICT_ID DistrictID)//將專案機台座標轉成底圖座標
{	//return MapProjectTeachToMapPos(PosX, PosY, rPosX, rPosY, LaneID, DistrictID);
	rPosX = rPosY = 0.0;
	if ( NULL == m_ProjectMapPtr[0] ) { return false; }	
	const int MapIndex = 0;	
	TREGION4D MapStageRgn;
	IMAGE_SIZE ImageW=m_ProjectMapW[MapIndex];
	IMAGE_SIZE ImageH=m_ProjectMapH[MapIndex];
	switch ( DistrictID )
	{
	case DISTRICT_ID_A:	GetProjectMapStageRgn_DA(MapStageRgn);	break;
	case DISTRICT_ID_B:	GetProjectMapStageRgn_DB(MapStageRgn);	break;
	}	
	const bool SignX = AOIDataCollect.GetStageSignPositiveX();
	const bool SignY = AOIDataCollect.GetStageSignPositiveY();
	const double StageRgnCpX = MapStageRgn.GetCpX();
	const double StageRgnCpY = MapStageRgn.GetCpY();
	const double StageOffsetX = PosX-StageRgnCpX;
	const double StageOffsetY = PosY-StageRgnCpY;
	double ImageOffsetX = StageOffsetX/m_ProjectMapResX;
	double ImageOffsetY = StageOffsetY/m_ProjectMapResY;	

	if ( false ==SignX )
	{	ImageOffsetX = -ImageOffsetX;	}
	double ImagePosX = ImageOffsetX+(ImageW*0.5);
	double ImagePosY = ImageOffsetY+(ImageH*0.5);	
	rPosX = ImagePosX;	
	if ( true ==SignY )
	{	rPosY = ImageH-ImagePosY;	}	
	else
	{	rPosY = ImagePosY;	}	
	return true;
}
