//-------------------------------------------------------------------------------------//
bool CAOIProject::CreateProjectMapShowPtr(unsigned int MapIndex, IMAGE_PTR &ShowPtr, bool bForce, bool bTestMap)
{
	if ( false==bForce && MapIndex==m_ProjectMapShowIndex )
	{
		ShowPtr = m_ProjectMapShowPtr;
		return true;
	}
	ShowPtr = NULL;
	ClearProjectMapShowBuffer();	
	
	IMAGE_SIZE ImageW=0;
	IMAGE_SIZE ImageH=0;
	IMAGE_SIZE ImageStep=0;
	IMAGE_SIZE BitCount=0;
	IMAGE_PTR  Ptr=NULL;
	IMAGE_PTR NewPtr=NULL;
	if ( true==bTestMap && GetProjectMapScaleMode()==GetProjectTestMapScaleMode() )
	{	
		GetProjectTestMapPtr(MapIndex, ImageW, ImageH, ImageStep, BitCount, Ptr);	
		if ( NULL != Ptr )
		{
			IMAGE_SIZE TmpW=0;
			IMAGE_SIZE TmpH=0;
			IMAGE_SIZE TmpStep=0;
			IMAGE_SIZE TmpBitCnt=0;
			IMAGE_PTR  TmpPtr=NULL;
			GetProjectMapPtr(MapIndex, TmpW, TmpH, TmpStep, TmpBitCnt, TmpPtr);
			if ( NULL != TmpPtr )
			{
				if ( TmpBitCnt != BitCount )
				{	Ptr = NULL;	}
				else if ( ImageW!=TmpW || ImageH!=TmpH || ImageStep!=TmpStep )
				{					
					const size_t TmpBufSize = ImageAPI.CalcBufferSize(TmpStep, TmpH);
					if ( JetMemory.alloc_func(TmpBufSize, NewPtr, "CAOIProject::CreateProjectMapShowPtr", "NewPtr") == false )
					{	Ptr = NULL; }
					else
					{	
						const size_t nUsedW=(size_t)(MIN(ImageW, TmpW));
						const size_t nUsedH=(size_t)(MIN(ImageH, TmpH));
						for ( size_t i=0; i<nUsedH; i++ )
						{							
							for ( size_t j=0; j<nUsedW; j++ )
							{									
								if ( 24 == BitCount )
								{
									const size_t DstIdx=(i*TmpStep)+(j*3);
									const size_t SrcIdx=(i*ImageStep)+(j*3);

									NewPtr[DstIdx] = Ptr[SrcIdx];
									NewPtr[DstIdx+1] = Ptr[SrcIdx+1];
									NewPtr[DstIdx+2] = Ptr[SrcIdx+2];
								}
								else
								{
									const size_t DstIdx=(i*TmpStep)+(j);
									const size_t SrcIdx=(i*ImageStep)+(j);
									NewPtr[DstIdx] = Ptr[SrcIdx];
								}
							}
						}

						Ptr = NewPtr;
						ImageW = TmpW;
						ImageH = TmpH;
						ImageStep = TmpStep;
						BitCount = TmpBitCnt;
					}
				}				
			}
		}
	}

	bool bTestMapUsed=false;	
	if ( NULL != Ptr )
	{	bTestMapUsed = true;	}
	else
	{
		if ( GetProjectMapPtr(MapIndex, ImageW, ImageH, ImageStep, BitCount, Ptr) == false )
		{
			if ( NULL != NewPtr )
			{	JetMemory.free_func(NewPtr); }
			return false; 
		}
	}
	

	IMAGE_PTR TempPtr=NULL;
	const size_t ShowBuffferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(ShowBuffferSize, TempPtr, "CAOIProject::CreateProjectMapShowPtr", "MapShowPtr") == false )
	{
		if ( NULL != NewPtr )
		{	JetMemory.free_func(NewPtr); }
		return false; 
	}

	if ( true == bTestMapUsed )
	{	::memcpy(TempPtr, Ptr, sizeof(IMAGE_DATA)*ShowBuffferSize);	}
	else
	{	AOIDataCollect.ExecEnhanceDisplayImage(ImageW, ImageH, ImageStep, BitCount, Ptr, TempPtr);	}	
	SetProjectMapShowBuffer(MapIndex, ShowBuffferSize, TempPtr);
	ShowPtr = TempPtr;
	if ( NULL != NewPtr )
	{	JetMemory.free_func(NewPtr); }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::UpdateProjectMapShowPtr()
{
	if ( FRAME_MAX_COUNT == m_ProjectMapShowIndex ) { return false; }
	if ( NULL == m_ProjectMapShowPtr ) { return false; }
	if ( 0 == m_ProjectMapShowSize ) { return false; }

	IMAGE_SIZE ImageW=0;
	IMAGE_SIZE ImageH=0;
	IMAGE_SIZE ImageStep=0;
	IMAGE_SIZE BitCount=0;
	IMAGE_PTR  Ptr=NULL;
	if ( GetProjectMapPtr(m_ProjectMapShowIndex, ImageW, ImageH, ImageStep, BitCount, Ptr) == false )
	{	return false; }	
	const size_t MapBufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);
	if ( m_ProjectMapShowSize < MapBufferSize )
	{	return false; }
	AOIDataCollect.ExecEnhanceDisplayImage(ImageW, ImageH, ImageStep, BitCount, Ptr, m_ProjectMapShowPtr);	
	return true;
}
