{
	DISTRICT_ID DistrictID = GetProjectActDistrictID();
	switch ( DistrictID )
	{
	case DISTRICT_ID_A:	GetProjectMapLocRect_DA(Rect);	break;
	case DISTRICT_ID_B:	GetProjectMapLocRect_DB(Rect);	break;
	default:
		break;
	}
}
