{
	DISTRICT_ID DistrictID = GetProjectActDistrictID();
	switch ( DistrictID )
	{
	case DISTRICT_ID_A:	SetProjectMapLocRect_DA(Rect);	break;
	case DISTRICT_ID_B:	SetProjectMapLocRect_DB(Rect);	break;
	default:
		break;
	}
}
//-------------------------------------------------------------------------------------//
void CAOIProject::GetProjectMapLocRectOff(RECT &Rect, RECT &Rect2) const//專案底圖局部不檢測區域
{
	RECT        RectDA;
	RECT        RectDB;
	const int   DivideLine=GetProjectMapDividePos();
	DISTRICT_ID DistrictID = GetProjectActDistrictID();

	GetProjectMapLocRect_DA(RectDA);
	GetProjectMapLocRect_DB(RectDB);
	switch ( DistrictID )
	{
	case DISTRICT_ID_A:	
		Rect2 = Rect = RectDB;
		if ( RectDB.right < RectDA.right )
		{	
			Rect.right = RectDA.left;	
			Rect2.left = Rect.right;
			Rect2.right = DivideLine;
		}
		else
		{	
			Rect.left = RectDA.right;	
			Rect2.right = Rect.left;
			Rect2.left = DivideLine;
		}
		break;
	case DISTRICT_ID_B:	
		Rect2 = Rect = RectDA;
		if ( RectDB.right < RectDA.right )
		{	
			Rect.left = RectDB.right;	
			Rect2.right = Rect.left;
			Rect2.left = DivideLine;
		}
		else
		{	
			Rect.right = RectDA.left;	
			Rect2.left = Rect.right;
			Rect2.right = DivideLine;
		}
		break;	
	}
	return;
}
