//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectMapImage(LPCTSTR filename)//儲存專案底圖檔案
{
	bool  bIsOK = true;
	bool  bOpenMP = false;
	const int   OpenMPCount = AOIDataCollect.GetOpenMPCount_General();
#ifdef OPEN_MP_USE	
	if ( 0 == OpenMPCount ) 
	{	bOpenMP = false; }
	else
	{	bOpenMP = true; }
#else
	bOpenMP = false;
#endif//OPEN_MP_USE
	if ( true == bOpenMP ) 
	{	bIsOK = SaveProjectMapImage_MP(filename); }
	else
	{	bIsOK = SaveProjectMapImage_SP(filename); }
	if ( false == bIsOK )
	{	SetProjectExceptionCode_FileWrite();	}
	return bIsOK;	
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectMapImage_SP(LPCTSTR filename)//儲存專案底圖檔案
{
	//寫入圖檔
	bool UsingSave=true;	
	size_t      i=0;
	size_t      SmallSize=0;	
	size_t      BufferSize=0;
	CString     MapNameSrc;
	CString     MapNameDst;
	CString     MainFilename=filename;
	IMAGE_SIZE  SmallW=0;
	IMAGE_SIZE  SmallH=0;
	IMAGE_SIZE  SmallStep=0;
	IMAGE_SIZE  SmallBitCount=0;	
	IMAGE_PTR   SmallPtr = NULL;
	for ( i=0; i<FRAME_MAX_COUNT; i++ )
	{
		if ( m_ProjectMapPtr[i] == NULL ) { continue; }		
		const IMAGE_SIZE  MapW = m_ProjectMapW[i];//專案底圖寬度
		const IMAGE_SIZE  MapH = m_ProjectMapH[i];//專案底圖長度
		const IMAGE_SIZE  MapStep = m_ProjectMapStep[i];//專案底圖步長
		const IMAGE_SIZE  BitCount = m_ProjectBitCount[i];//專案底圖位元數
		IMAGE_PTR     MapPtr = m_ProjectMapPtr[i];//專案底圖指標
		
		UsingSave = true;
		if ( 0 == i )
		{	MapNameDst.Format(_T("%s.JPG"), MainFilename);	}
		else
		{	MapNameDst.Format(_T("%s#%d.JPG"), MainFilename, i+1);	}		
		MapNameSrc = m_ProjectMapFilename[i];
		if ( JetAPI::IsFileExist(MapNameSrc) == true )			
		{				
			if ( MapNameDst.CompareNoCase(MapNameSrc) == 0 )
			{	UsingSave = false; }
			else
			{
				if ( ::CopyFile(MapNameSrc, MapNameDst, FALSE) == TRUE )
				{	UsingSave = false; }				
			}
		}
		if ( true == UsingSave )
		{
			if ( ImageAPI.SaveImage(MapNameDst, MapW, MapH, MapStep, BitCount, MapPtr, true) == false )
			{
				JetMemory.free_func(SmallPtr);	
				this->m_ErrorString = ImageAPI.GetImageApiErrorString();
				return false;
			}			
		}
		m_ProjectMapFilename[i] = MapNameDst;

		//小圖----1/4
		UsingSave = true;
		if ( 0 == i )
		{	MapNameDst.Format(_T("%sSmall.JPG"), MainFilename);	}
		else
		{	MapNameDst.Format(_T("%sSmall#%d.JPG"), MainFilename, i+1);		}		
		MapNameSrc = m_ProjectMapFilenameSmall[i];
		if ( JetAPI::IsFileExist(MapNameSrc) == true )			
		{				
			if ( MapNameDst.CompareNoCase(MapNameSrc) == 0 )
			{	UsingSave = false; }
			else
			{
				if ( ::CopyFile(MapNameSrc, MapNameDst, FALSE) == TRUE )
				{	UsingSave = false; }				
			}
		}
		if ( true == UsingSave )
		{
			SmallW = MapW/4;
			SmallH = MapH/4;
			SmallStep = JetAPI::GetBMPImagePixelsPerLine(SmallW, BitCount, 4);
			SmallBitCount = BitCount;		
			SmallSize = SmallStep*SmallH;
			if ( BufferSize < SmallSize )
			{	if ( 0 == BufferSize )
				{
					IMAGE_SIZE BufferW = MapW;
					IMAGE_SIZE BufferH = MapH;
					IMAGE_SIZE BufferBitCount = 24;
					IMAGE_SIZE BufferStep = JetAPI::GetBMPImagePixelsPerLine(BufferW, BufferBitCount, 4);
					BufferSize = ImageAPI.CalcBufferSize(BufferStep, BufferH)+1024;
				}				
				if ( BufferSize < SmallSize )
				{	BufferSize = SmallSize+1024;	}	
				if ( NULL != SmallPtr )
				{	JetMemory.free_func(SmallPtr); }
				if ( JetMemory.alloc_func(BufferSize, SmallPtr, "CAOIProject::SaveProjectMapImage_SP", "SmallPtr") == false )
				{
					this->m_ErrorString = JetMemory.GetErrorString();
					JetMemory.free_func(SmallPtr);	
					return false;
				}
				::memset(SmallPtr, 0x00, sizeof(unsigned char)*BufferSize);
			}
			if ( ImageAPI.FastScaleImage3(MapW, MapH, MapStep, BitCount, MapPtr, 4, SmallW, SmallH, SmallStep, SmallPtr) == false ) 
			{
				JetMemory.free_func(SmallPtr);	
				this->m_ErrorString = ImageAPI.GetImageApiErrorString();				
				return false;
			}
			if ( ImageAPI.SaveImage(MapNameDst, SmallW, SmallH, SmallStep, BitCount, SmallPtr, true) == false )
			{
				JetMemory.free_func(SmallPtr);	
				this->m_ErrorString = ImageAPI.GetImageApiErrorString();				
				return false;
			}			
		}
		m_ProjectMapFilenameSmall[i] = MapNameDst;
	}	
	JetMemory.free_func(SmallPtr);	
	return true;
}
