//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectMapImage(LPCTSTR filename)//載入專案底圖檔案		
{
	bool  bIsOK = true;
	bool  bOpenMP = false;
	const int   OpenMPCount = AOIDataCollect.GetOpenMPCount_General();
#ifdef OPEN_MP_USE	
	if ( 0 == OpenMPCount ) 
	{	bOpenMP = false; }
	else
	{	bOpenMP = true; }
#else
	bOpenMP = false;
#endif//OPEN_MP_USE
	if ( true == bOpenMP ) 
	{	bIsOK = LoadProjectMapImage_MP(filename); }
	else
	{	bIsOK = LoadProjectMapImage_SP(filename); }
	if ( false == bIsOK )
	{
		SetProjectExceptionCode_FileRead();
		return bIsOK; 
	}
	return bIsOK;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectMapImage_SP(LPCTSTR filename)//載入專案底圖檔案		
{
	//載入圖檔
	size_t      i=0;
	CString     MapName;
	CString     MapNameSmall;
	CString     MainFilename=filename;
	IMAGE_SIZE  MapW = 0;//專案底圖寬度
	IMAGE_SIZE  MapH = 0;//專案底圖長度
	IMAGE_SIZE  MapStep = 0;//專案底圖步長
	IMAGE_SIZE  BitCount = 0;//專案底圖位元數
	IMAGE_PTR   MapPtr = 0;//專案底圖指標	

	for ( i=0; i<FRAME_MAX_COUNT; i++ )
	{
		if ( 0 == i )
		{	
			MapName.Format(_T("%s.JPG"), MainFilename); 
			MapNameSmall.Format(_T("%sSmall.JPG"), MainFilename); 
		}
		else
		{	
			MapName.Format(_T("%s#%d.JPG"), MainFilename, i+1); 
			MapNameSmall.Format(_T("%sSmall#%d.JPG"), MainFilename, i+1); 
		}
		if ( JetAPI::IsFileExist(MapName) == false ) { continue; }

		if ( ImageAPI.LoadImage(MapName, MapW, MapH, MapStep, BitCount, MapPtr, 4, true) == false )
		{
			this->m_ErrorString = ImageAPI.GetImageApiErrorString();
			return false;
		}
		m_ProjectMapW[i] = MapW;//專案底圖寬度
		m_ProjectMapH[i] = MapH;//專案底圖長度
		m_ProjectMapStep[i] = MapStep;//專案底圖步長
		m_ProjectBitCount[i] = BitCount;//專案底圖位元數
		m_ProjectMapPtr[i] = MapPtr;//專案底圖指標
		m_ProjectMapFilename[i] = MapName;

		if ( JetAPI::IsFileExist(MapNameSmall) == true )
		{	m_ProjectMapFilenameSmall[i] = MapNameSmall;	}		

		//復歸參數
		MapW = 0;
		MapH = 0;
		MapStep = 0;
		BitCount = 0;
		MapPtr = NULL;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectMapImage_MP(LPCTSTR filename)//載入專案底圖檔案	
{
	//載入圖檔		
	CString     MainFilename=filename;
	const int   CPUCoreNumber = AOIDataCollect.GetComputerCPUCoreNumber();
	const int   OpenMPCount = AOIDataCollect.GetOpenMPCount_General();
	const int   OpenMPCountUsed=MIN(FRAME_MAX_COUNT, OpenMPCount);
#ifdef OPEN_MP_USE	
	bool        OK[FRAME_MAX_COUNT]={true};
	CString     ErrorString[FRAME_MAX_COUNT];	
#pragma omp parallel for num_threads(OpenMPCountUsed)
	for ( int i=0; i<FRAME_MAX_COUNT; i++ )
	{	
		CString     MapName;		
		CString     MapNameSmall;
		IMAGE_SIZE  MapW = 0;//專案底圖寬度
		IMAGE_SIZE  MapH = 0;//專案底圖長度
		IMAGE_SIZE  MapStep = 0;//專案底圖步長
		IMAGE_SIZE  BitCount = 0;//專案底圖位元數
		IMAGE_PTR   MapPtr = 0;//專案底圖指標

		OK[i] = true;
		ErrorString[i]=_T("");
		if ( 0 == i )
		{	
			MapName.Format(_T("%s.JPG"), MainFilename); 
			MapNameSmall.Format(_T("%sSmall.JPG"), MainFilename); 
		}
		else
		{	
			MapName.Format(_T("%s#%d.JPG"), MainFilename, i+1); 
			MapNameSmall.Format(_T("%sSmall#%d.JPG"), MainFilename, i+1); 
		}
		if ( JetAPI::IsFileExist(MapName) == false ) { continue; }

		if ( ImageAPI.LoadImage(MapName, MapW, MapH, MapStep, BitCount, MapPtr, 4, true) == false )
		{
			OK[i] = false;
			ErrorString[i] = ImageAPI.GetImageApiErrorString();			
			break;
		}
		m_ProjectMapW[i] = MapW;//專案底圖寬度
		m_ProjectMapH[i] = MapH;//專案底圖長度
		m_ProjectMapStep[i] = MapStep;//專案底圖步長
		m_ProjectBitCount[i] = BitCount;//專案底圖位元數
		m_ProjectMapPtr[i] = MapPtr;//專案底圖指標
		m_ProjectMapFilename[i] = MapName;

		if ( JetAPI::IsFileExist(MapNameSmall) == true )
		{	m_ProjectMapFilenameSmall[i] = MapNameSmall;	}		

		//復歸參數
		MapW = 0;
		MapH = 0;
		MapStep = 0;
		BitCount = 0;
		MapPtr = NULL;
	}	

	bool bIsOK=true;
	for ( int i=0; i<FRAME_MAX_COUNT; i++ )
	{	
		if ( true == OK[i] ) { continue; }
		bIsOK = false;
		m_ErrorString = ErrorString[i];
		break;
	}	
	if ( false == bIsOK ) 
	{	return false; }
#endif//OPEN_MP_USE	
	return true;
}
//-------------------------------------------------------------------------------------//
void CAOIProject::ClearProjectMapMaskBuffer()//清除專案底圖遮罩指標	
{
	if ( NULL != m_ProjectMapMaskPtr )
	{	
		JetMemory.free_func(m_ProjectMapMaskPtr); 
		m_ProjectMapMaskPtr = NULL;
	}
	m_ProjectMapMaskW = 1024;//專案底圖遮罩寬度
	m_ProjectMapMaskH = 1024;//專案底圖遮罩長度
	m_ProjectMapMaskStep = 1024;//專案底圖遮罩步長
	m_ProjectMapMaskBitCount = 8;//專案底圖遮罩位元數	
	return ;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectMapMaskFile(LPCTSTR filename)//儲存專案底圖遮罩檔案
{
	if ( SaveProjectMapMaskFileFn(filename) == false )
	{
		SetProjectExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectMapMaskFileFn(LPCTSTR filename)//儲存專案底圖遮罩檔案
{
	if ( NULL == filename ) { return false; }
	if ( NULL == m_ProjectMapMaskPtr ) { return true; }
	if ( ImageAPI.SaveImage(filename, m_ProjectMapMaskW, m_ProjectMapMaskH, m_ProjectMapMaskStep, m_ProjectMapMaskBitCount, m_ProjectMapMaskPtr, true) == false )
	{	
		m_ErrorString = ImageAPI.GetImageApiErrorString();
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectMapMaskFile(LPCTSTR filename)//載入專案底圖遮罩檔案
{
	if ( LoadProjectMapMaskFileFn(filename) == false )
	{
		SetProjectExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectMapMaskFileFn(LPCTSTR filename)//載入專案底圖遮罩檔案			
{
	ClearProjectMapMaskBuffer();
	if ( NULL == filename ) { return false; }
	if ( JetAPI::IsFileExist(filename) == false ) { return true; }

	IMAGE_SIZE ImageW=0;
	IMAGE_SIZE ImageH=0;
	IMAGE_SIZE ImageStep=0;
	IMAGE_SIZE BitCount=0;
	IMAGE_PTR  ImagePtr=NULL;
	const int nAlign = 4;	
	const bool bRevers = true;
	if ( ImageAPI.LoadImage(filename, ImageW, ImageH, ImageStep, BitCount, ImagePtr, nAlign, bRevers) == false )
	{	
		m_ErrorString = ImageAPI.GetImageApiErrorString();
		return false;
	}
	if ( 8 != BitCount )
	{
		JetMemory.free_func(ImagePtr);
		return true;
	}
	m_ProjectMapMaskW = ImageW;
	m_ProjectMapMaskH = ImageH;
	m_ProjectMapMaskStep = ImageStep;
	m_ProjectMapMaskBitCount = BitCount;
	m_ProjectMapMaskPtr = ImagePtr;
	return true;
}
//-------------------------------------------------------------------------------------//
IMAGE_PTR CAOIProject::GetProjectMapMaskImage(IMAGE_SIZE &MaskW, IMAGE_SIZE &MaskH, IMAGE_SIZE &MaskStep, IMAGE_SIZE &BitCount)//取得專案底圖遮罩影像
{
	MaskW = m_ProjectMapMaskW;
	MaskH = m_ProjectMapMaskH;
	MaskStep = m_ProjectMapMaskStep;
	BitCount = m_ProjectMapMaskBitCount;	
	return m_ProjectMapMaskPtr;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SetProjectMapMaskImage(IMAGE_SIZE MaskW, IMAGE_SIZE MaskH, IMAGE_SIZE MaskStep, IMAGE_SIZE BitCount, IMAGE_PTR MaskPtr, bool bClone)//設定專案底圖遮罩影像
{
	if ( 8 != BitCount )
	{
		m_ErrorString = _T("Error, Project Map Mask should be 8-bit Image");
		return false;
	}
	ClearProjectMapMaskBuffer();

	IMAGE_PTR  ImagePtr=MaskPtr;
	IMAGE_SIZE ImageW=MaskW;
	IMAGE_SIZE ImageH=MaskH;
	IMAGE_SIZE ImageStep=MaskStep;	
	const int nAlign = 4;
	if ( true == bClone )
	{
		ImagePtr = NULL;
		ImageStep = JetAPI::GetBMPImagePixelsPerLine(MaskW, BitCount, nAlign);
		if ( ImageAPI.AlignImageBuffer(MaskW, MaskH, MaskStep, BitCount, MaskPtr, ImageStep, ImagePtr, false) == false )
		{
			m_ErrorString = ImageAPI.GetImageApiErrorString();
			return false;
		}
	}
	m_ProjectMapMaskW = ImageW;
	m_ProjectMapMaskH = ImageH;
	m_ProjectMapMaskStep = ImageStep;
	m_ProjectMapMaskBitCount = BitCount;
	m_ProjectMapMaskPtr = ImagePtr;
	return true;
}
