bool CAOIProject::FilterProjectFrameParamList_No3D(const std::vector<TFrameParam> &SrcList, std::vector<TFrameParam> &DstList) const//過濾專案影像參數-無3D
{	
	DstList.clear();
	const size_t FrameParamCount = SrcList.size();	
	for (size_t i=0; i<FrameParamCount; i++ )
	{
		if ( FRAME_UNIQUE_ID_DLP == SrcList[i].FrameUniqueID ) { continue; }
		DstList.push_back(SrcList[i]);
	}
	return true;
}
