//-------------------------------------------------------------------------------------//
bool CAOIProject::CreateProjectCaptureMapObjFn()//建立專案底圖取像的物件
{		
	CAOIProject *ProjectPtr = this;
	m_ProjectFieldPtrList.clear();	
	ClearProjectAllTempObjects();

	ClearProjectAllMapRgns();
	ClearProjectAllProgramField();
	
	RECT          FieldRect={0};	
	TPOINT3D      StartPos, FovPos;		
	size_t        i=0, j=0, k=0, s=0;	
	size_t        FovSlices = 0;
	size_t        FrameSliceCount=0;
	unsigned int  CameraFrameIdx = 0;
	double        FovWReal=0, FovHReal=0;
	double        FovWInner = 0, FovHInner = 0;
	double        FovWOuter = 0, FovHOuter = 0;
	CAOIRgn*      RgnPtr = NULL;//檢測區域指標
	CAOIFov*      FovPtr = NULL;//視野指標	
	CAOISlice*    SlicePtr = NULL;//相機區域圖指標	
	CAOIFrame*    FramePtr = NULL;//影像指標
	CAOIField*    FieldPtr = NULL;//區域指標
	AOIDataCollect.GetFovSizeReal(FovWReal, FovHReal);
	AOIDataCollect.GetFovSizeInner(FovWInner, FovHInner);
	AOIDataCollect.GetFovSizeOuter(FovWOuter, FovHOuter);	
	//ProjectPtr->ModifyProjectFieldSize(FovWInner, FovHInner);
	const double FOVW2 = FovWInner*0.5;
	const double FOVH2 = FovHInner*0.5;

	TSIZE2D   ProjectSize;	
	TREGION4D ProjectRegion;	
	GetProjectMapTeachRgn(ProjectRegion);
	ProjectSize.cx = ProjectRegion.maxX-ProjectRegion.minX;
	ProjectSize.cy = ProjectRegion.maxY-ProjectRegion.minY;		
	const DISTRICT_ID DistrictID = GetProjectActDistrictID();
	const size_t FovRows = JetAPI::Ceil(ProjectSize.cy/FovHInner);
	const size_t FovCols = JetAPI::Ceil(ProjectSize.cx/FovWInner);
	const size_t FovFields = AOIDataCollect.AnalsysFovFieldCount();		
	const double FocusPos = ProjectPtr->GetProjectFocusPos();
	const bool bSignX = AOIDataCollect.GetStageSignPositiveX();
	const bool bSignY = AOIDataCollect.GetStageSignPositiveY();
	const bool bPCBRightIn = PlcCtrlPtr->GetIsPCBRightInDirection();	
	const bool bRightSide = AOIDataCollect.CheckPCBStopAtRightSide(bPCBRightIn, DistrictID);
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;		

	IMAGE_DISPLAY_MODE ImageMode = AOIDataCollect.GetSystemParameter().m_ImageDisplayMode;

	TFrameParam *FrameParamPtr = NULL;
	std::vector<CAOISlice*>  FrameSlicePtrList;
	std::vector<TSliceParam>  SliceParamList;	
	std::vector<TFrameParam>  FrameParamList;	
	SliceParamList = m_ProjectSliceParamList;
	FrameParamList = m_ProjectFrameParamList;
	const size_t FrameParamCount = FrameParamList.size();		

	//從最內側往外長	
	if ( false == bRightSide )//右進料, 以左側停板塊為主
	{	
		if ( true == bSignX )
		{	StartPos.x = ProjectRegion.minX+(FovWInner*0.5);	}
		else
		{	StartPos.x = ProjectRegion.maxX-(FovWInner*0.5)-((FovCols-1)*FovWInner);	}
	}
	else//左進料, 以右側停板塊為主
	{	
		if ( true == bSignX )
		{	StartPos.x = ProjectRegion.maxX-(FovWInner*0.5)-((FovCols-1)*FovWInner);	}
		else
		{	StartPos.x = ProjectRegion.minX+(FovWInner*0.5);	}
	}	
	if ( true == bSignY )
	{	StartPos.y = ProjectRegion.minY+(FovHInner*0.5); }
	else
	{	StartPos.y = ProjectRegion.maxY-(FovHInner*0.5)-((FovRows-1)*FovHInner); }
	//StartPos.x = ProjectRegion.minX+(FovWInner*0.5);
	//StartPos.y = ProjectRegion.minY+(FovHInner*0.5);
	StartPos.z = FocusPos;
	FovPos.z = StartPos.z;	
	
	//最佳化路徑
	double        PathStartPosX=0;
	double        PathStartPosY=0;
	size_t        FieldIdx=0;
	size_t        JetFieldIdx=0;
	TJetField     JetField;
	TJetField    *JetPathPtr=NULL;
	TJetField    *JetFieldPtr=NULL;
	TJetFieldList JetPathList;
	TJetFieldList JetFieldList;	
	k = 0;
	for (i=0; i<FovRows; i++ )
	{
		FovPos.y = StartPos.y+(i*FovHInner);
		if ( MotionCtrlPtr->CheckStagePosValidY(FovPos.y) == false )
		{
			m_ErrorString = MotionCtrlPtr->GetErrorString();
			return false;
		}
		for ( j=0; j<FovCols; j++ )
		{
			FovPos.x = StartPos.x+(j*FovWInner);
			if ( 0 == i )//只確認第一條的X座標
			{
				if ( MotionCtrlPtr->CheckStagePosValidX(FovPos.x) == false )
				{
					m_ErrorString = MotionCtrlPtr->GetErrorString();
					return false;
				}
			}
			JetField.FieldID = k;
			JetField.minX = FovPos.x-FOVW2;
			JetField.maxX = FovPos.x+FOVW2;
			JetField.minY = FovPos.y-FOVH2;
			JetField.maxY = FovPos.y+FOVH2;
			JetFieldList.push_back(JetField);
			k ++;
		}
	}	
	CJetFieldDivider FieldDivider;
	FieldDivider.SetSectionFactor(0.5);
	FieldDivider.SetFieldMaxW(FovWInner);
	FieldDivider.SetFieldMaxH(FovHInner);
	FieldDivider.SetPathStartPosX(ProjectRegion.minX);
	FieldDivider.SetPathStartPosY(ProjectRegion.minY);
	if ( FieldDivider.ExecFieldPath(JetFieldList) == false )
	{
		this->m_ErrorString.Format(_T("Error, FieldDivider.ExecFieldPath Fault"));
		return false; 
	}
	FieldDivider.CloneJetPathList(JetPathList);
	const size_t JetFieldCount = JetFieldList.size();
	const size_t JetPathCount = JetPathList.size();
	if ( JetPathCount != JetFieldCount )
	{
		this->m_ErrorString.Format(_T("Error, FieldDivider.ExecFieldPath Fault"));
		return false; 
	}
	
	CameraFrameIdx = 0;
	FieldRect.left = 0;
	FieldRect.top  = 0;
	FieldRect.right = AOIDataCollect.GetCameraImageW(CameraID);
	FieldRect.bottom = AOIDataCollect.GetCameraImageH(CameraID);	
	
	for (i=0; i<JetPathCount; i++ )
	{
		FieldIdx = i;
		JetPathPtr = &(JetPathList[i]);
		JetFieldIdx = JetPathPtr->FieldID;
		if ( JetFieldIdx >= JetFieldCount ) { continue; }
		JetFieldPtr = &(JetFieldList[JetFieldIdx]);

		FovPos.x = (JetFieldPtr->minX+JetFieldPtr->maxX)*0.5;
		FovPos.y = (JetFieldPtr->minY+JetFieldPtr->maxY)*0.5;
		FovPos.z = FocusPos;
		FovPtr = AOIObjManager.CreateFovObj();
		if ( NULL == FovPtr )
		{
			ClearProjectAllTempObjects();				
			this->m_ErrorString = _T("Error, Create AOI Fov Obj Fault");
			return false;
		}
		this->AddProjectTempFovPtr(FovPtr, false);				
		FovPtr->SetFovFrameParamList(FrameParamList);
		FovPtr->SetFovSliceParamList(SliceParamList);
		FovPtr->SetFovStagePos(FovPos);		
		
		//機台區分的區塊
		FieldPtr = AOIObjManager.CreateFieldObj();
		if ( NULL == FieldPtr )
		{
			ClearProjectAllTempObjects();
			this->m_ErrorString = _T("Error, Create AOI Field Obj Fault");
			return false;
		}
		this->AddProjectTempFieldPtr(FieldPtr, false);
		this->AddProjectProgramFieldPtr(FieldPtr, false);
		FieldPtr->SetFieldLinkPointer(true);
		
		FieldPtr->SetFieldStagePos(FovPos);
		FieldPtr->SetFieldDistrictID(DistrictID);
		FieldPtr->SetFieldSize_Real(FovWReal, FovHReal);
		FieldPtr->SetFieldSize_Inner(FovWInner, FovHInner);
		FieldPtr->SetFieldSize_Outer(FovWOuter, FovHOuter);
		
		//檢測區域的指標
		RgnPtr = AOIObjManager.CreateRgnObj();
		if ( NULL == RgnPtr )
		{
			ClearProjectAllTempObjects();	
			this->m_ErrorString = _T("Error, Create AOI Region Obj Fault");
			return false;
		}
		this->AddProjectTempRgnPtr(RgnPtr, false);
		AddProjectMapRgnPtr(RgnPtr, false);
		RgnPtr->SetRgnLinkPointer(true);
		FieldPtr->AddFieldRgnPtr(RgnPtr);
		
		for ( j=0; j<FrameParamCount; j++ )
		{
			FrameParamPtr = &(FrameParamList[j]);
			if ( NULL == FrameParamPtr ) { continue; }						
			//FramePtr = CAOIProject::CreateProjectFramePtrByFrameParam(FieldPtr, FrameParamPtr, CameraFrameIdx);			
			FrameSlicePtrList.clear();
			if ( AOIDataCollect.CreateFramePtrByFrameParam(FieldPtr, FrameParamPtr, CameraFrameIdx, FramePtr, FrameSlicePtrList) == false )
			{
				AOIObjManager.DestroyFrameObj(FramePtr);
				FrameSliceCount = FrameSlicePtrList.size();
				for ( k=0; k<FrameSliceCount; k++ )
				{	AOIObjManager.DestroySliceObj(FrameSlicePtrList[k]);	}	
				ClearProjectAllTempObjects();
				return false;
			}
			FrameSliceCount = FrameSlicePtrList.size();
			for ( k=0; k<FrameSliceCount; k++ )
			{	AddProjectTempSlicePtr(FrameSlicePtrList[k], false);	}
			this->AddProjectTempFramePtr(FramePtr, false);			
			FieldPtr->AddFieldFramePtr(FramePtr);
			//FramePtr->SetFrameLinkPointer(false);
			FramePtr->SetFrameLinkPointer(true);
			FramePtr->SetFrameImageIndex((unsigned int)j);
		}
	}	
	
	m_ProjectOfflineFileMode = OFFLINE_FILE_PROGRAM;
	SetProjectFieldBuildMode(FIELD_BUILD_MATRIX);
	SetProjectFieldBuildAreaMode(FIELD_BUILD_AREA_COMPONENT);
	SetProjectProgramOfflineFolder(m_ProjectOfflineFolder);
	m_ProjectFieldPtrList = m_ProjectTempFieldPtrList;
	return true;
}
