//-------------------------------------------------------------------------------------//
bool CAOIProject::CreateProjectBoardAlignObjFn(bool MultiFdLight)//建立專案單板對位的物件	
{
	CAOIProject *ProjectPtr = this;
	ProjectPtr->ClearProjectAllTempObjects();
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;			
	double     ImageResX=0.0, ImageResY=0.0;	
	IMAGE_SIZE ImageW=0, ImageH=0;
	AOIDataCollect.GetCameraImageInfo(CameraID, ImageW, ImageH, ImageResX, ImageResY);

	RECT          FieldRect={0};	
	TPOINT3D      FovPos;		
	size_t        i=0, j=0, k=0, s=0;	
	size_t        FovSlices = 0;
	LANE_ID       LaneID;
	TSIZE2D       FovSizeReal;
	TSIZE2D       FovSizeInner;
	TSIZE2D       FovSizeOuter;
	DISTRICT_ID   DistrictID;
	unsigned int  CameraFrameIdx = 0;
	double        FovWInner = 0, FovHInner = 0;
	double        FovWOuter = 0, FovHOuter = 0;
	CAOIPanel*    PanelPtr = NULL;//整板指標
	CAOIBoard*    BoardPtr = NULL;//單板指標
	CAOIFd*       FdPtr = NULL;//定位點指標	
	CAOIRgn*      RgnPtr = NULL;//檢測區域指標
	CAOIFov*      FovPtr = NULL;//視野指標	
	CAOISlice*    SlicePtr = NULL;//相機區域圖指標	
	CAOIFrame*    FramePtr = NULL;//影像指標
	CAOIField*    FieldPtr = NULL;//區域指標
	//CAOIBlock*    BlockPtr = NULL;//區塊指標		
	AOIDataCollect.GetFovSizeInner(FovWInner, FovHInner);
	AOIDataCollect.GetFovSizeOuter(FovWOuter, FovHOuter);		
	//ProjectPtr->ModifyProjectFieldSize(FovWInner, FovHInner);
	const double FocusPos = ProjectPtr->GetProjectFocusPos();
	const size_t FdCount = ProjectPtr->GetProjectFdSortedCount();	
	const DISTRICT_ID ProjectDistrictID = ProjectPtr->GetProjectActDistrictID();

	size_t       FrameSliceCount=0;
	TFrameParam *FrameParamPtr = NULL;
	TSliceParam *SliceParamPtr = NULL;
	std::vector<TSliceParam>  SliceParamList;
	std::vector<TFrameParam>  FrameParamList;
	std::vector<CAOISlice*> FrameSlicePtrList;

	if ( false == MultiFdLight )
	{
		unsigned int FrameUniqueID = GetProjectFrameUniqueID_Fd();
		if ( AOIDataCollect.AddFrameSliceParamListByFrameUniqueID(FrameUniqueID, FrameParamList, SliceParamList) == false )
		{	return false; }
	}
	else
	{
		if ( CloneProjectSliceParamList_BoardFd(SliceParamList) == false )
		{	return false; }
		if ( CloneProjectFrameParamList_BoardFd(FrameParamList) == false )
		{	return false; }
	}
	const size_t FrameParamCount = FrameParamList.size();

	CameraFrameIdx = 0;
	FieldRect.left = 0;
	FieldRect.top  = 0;
	FieldRect.right = ImageW;
	FieldRect.bottom = ImageH;
	AOIDataCollect.GetFovSizeReal(FovSizeReal.cx, FovSizeReal.cy);
	AOIDataCollect.GetFovSizeInner(FovSizeInner.cx, FovSizeInner.cy);
	AOIDataCollect.GetFovSizeOuter(FovSizeOuter.cx, FovSizeOuter.cy);	
	//ProjectPtr->ModifyProjectFieldSize(FovSizeInner.cx, FovSizeInner.cy);
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = ProjectPtr->GetProjectFdSortedPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		PanelPtr = FdPtr->GetFdPanelPtr();
		if ( NULL == PanelPtr ) { continue; }
		BoardPtr = FdPtr->GetFdBoardPtr();
		if ( NULL == BoardPtr ) { continue; }
		DistrictID = FdPtr->GetFdDistrictID();
		if ( DistrictID != ProjectDistrictID ) { continue; }
		if ( PanelPtr->CheckPanelBypassedSkipped() == true ) { continue; }
		if ( BoardPtr->GetBoardBypassed() == true ) { continue; }
		if ( BoardPtr->GetBoardMapEnable() == false ) { continue; }		
	
		LaneID = FdPtr->GetFdLaneID();
		FovPos = FdPtr->GetFdTeachStagePos();
		AOIDataCollect.MapStagePosLaneByLaneID(FovPos.x, FovPos.y, LaneID);
		FdPtr->SetFdFovStagePosX(FovPos.x);
		FdPtr->SetFdFovStagePosY(FovPos.y);
		FovPos.z = FocusPos;		
		FovPtr = AOIObjManager.CreateFovObj();
		if ( NULL == FovPtr )
		{
			ClearProjectAllTempObjects();
			this->m_ErrorString = _T("Error, Create AOI Fov Obj Fault");
			return false;
		}
		this->AddProjectTempFovPtr(FovPtr, false);
		
		FovPtr->SetFovFrameParamList(FrameParamList);
		FovPtr->SetFovSliceParamList(SliceParamList);
		FovPtr->SetFovStagePos(FovPos);		

		//機台區分的區塊
		FieldPtr = AOIObjManager.CreateFieldObj();
		if ( NULL == FieldPtr )
		{
			ClearProjectAllTempObjects();
			this->m_ErrorString = _T("Error, Create AOI Field Obj Fault");
			return false;
		}
		this->AddProjectTempFieldPtr(FieldPtr, false);
		FieldPtr->SetFieldStagePos(FovPos);
		FieldPtr->SetFieldDistrictID(DistrictID);
		FieldPtr->SetFieldSize_Real(FovSizeReal);
		FieldPtr->SetFieldSize_Inner(FovSizeInner);
		FieldPtr->SetFieldSize_Outer(FovSizeOuter);

		//檢測區域的指標		
		RgnPtr = FdPtr;		
		RgnPtr->SetRgnLinkPointer(true);
		RgnPtr->SetRgnCalculated(false);
		RgnPtr->SetRgnCalcState(REGION_CALC_NONE);
		this->AddProjectTempRgnPtr(RgnPtr, false);
		FieldPtr->AddFieldRgnPtr(RgnPtr);			
		
		for ( j=0; j<FrameParamCount; j++ )
		{
			FrameParamPtr = &(FrameParamList[j]);
			if ( NULL == FrameParamPtr ) { continue; }
			//FramePtr = CAOIProject::CreateProjectFramePtrByFrameParam(FieldPtr, FrameParamPtr, CameraFrameIdx);			
			FrameSlicePtrList.clear();
			if ( AOIDataCollect.CreateFramePtrByFrameParam(FieldPtr, FrameParamPtr, CameraFrameIdx, FramePtr, FrameSlicePtrList) == false )
			{
				AOIObjManager.DestroyFrameObj(FramePtr);
				FrameSliceCount = FrameSlicePtrList.size();
				for ( k=0; k<FrameSliceCount; k++ )
				{	AOIObjManager.DestroySliceObj(FrameSlicePtrList[k]);	}	
				ClearProjectAllTempObjects();
				return false;
			}
			FrameSliceCount = FrameSlicePtrList.size();
			for ( k=0; k<FrameSliceCount; k++ )
			{	AddProjectTempSlicePtr(FrameSlicePtrList[k], false);	}
			this->AddProjectTempFramePtr(FramePtr, false);
			FieldPtr->AddFieldFramePtr(FramePtr);
		}	
	}	

	//提前移動至前一個位置
	FovPtr = GetProjectTempFovPtr(0, true);
	if ( NULL != FovPtr )
	{
		FovPos = FovPtr->GetFovStagePos();
		MotionCtrlPtr->XYZMoveTo(FovPos.x, FovPos.y, FovPos.z);
	}
	return true;
}
