//-------------------------------------------------------------------------------------//
bool CAOIProject::CreateProjectInspectionObjFn(bool AutoReleaseFieldFrame)//建立專案檢測的物件		
{
	CAOIProject *ProjectPtr = this;
	ProjectPtr->ClearProjectAllTempObjects();
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;			
	double     ImageResX=0.0, ImageResY=0.0;	
	IMAGE_SIZE ImageW=0, ImageH=0;
	AOIDataCollect.GetCameraImageInfo(CameraID, ImageW, ImageH, ImageResX, ImageResY);

	CString        str;
	RECT           FieldRect={0};	
	TPOINT3D       FovPos;		
	size_t         i=0, j=0, k=0, s=0;	
	size_t         FovSlices = 0;
	size_t         RgnCount = 0;
	size_t         FrameCount = 0;
	DISTRICT_ID    DistrictID;
	bool           RebuildFrame = false;
	bool           ProgramOfflineMode = false;
	unsigned int   CameraFrameIdx = 0;
	double         fnTime=0;
	double         FovWInner = 0, FovHInner = 0;
	double         FovWOuter = 0, FovHOuter = 0;
	LARGE_INTEGER  fnStart, fnEnd;
	CAOIMark*      MarkPtr = NULL;//特徵點指標
	CAOIPanel*     PanelPtr = NULL;//整板指標
	CAOIBoard*     BoardPtr = NULL;//單板指標	
	CAOIBoard*     BoardPtr_Last = NULL;//單板指標	
	CAOIBarcode*   BarcodePtr = NULL;//軟體條碼指標
	CAOIRgn*       RgnPtr = NULL;//檢測區域指標
	CAOIFov*       FovPtr = NULL;//視野指標	
	CAOISlice*     SlicePtr = NULL;//相機區域圖指標	
	CAOIFrame*     FramePtr = NULL;//影像指標
	CAOIField*     FieldPtr = NULL;//區域指標
	CAOIComponent* ComponentPtr = NULL;//零件指標
	AOIDataCollect.GetFovSizeInner(FovWInner, FovHInner);
	AOIDataCollect.GetFovSizeOuter(FovWOuter, FovHOuter);		
	ProjectPtr->ModifyProjectFieldSize(FovWInner, FovHInner);
	BOARD_FD_GRAB_MODE BoardFdGrabMode = GetProjectBoardFdGrabMode();
	//ONLINE_STATE_MODE OnlineStateMode = AOIDataCollect.GetOnlineStateMode();
	FIELD_BUILD_MODE FieldBuildMode = GetProjectInspectionFieldBuildMode();	
	const bool   bOthersUsing3D = CheckProjectOthersUsing3D();
	const size_t MarkCount = GetProjectMarkCount();
	const size_t BarcodeCount = GetProjectBarcodeCount();
	const size_t FieldCount = GetProjectFieldCount();
	const size_t BoardCount = GetProjectBoardCount();
	const size_t ComponentCount = GetProjectComponentCount();	
	const double FOVW2 = FovWInner/2;
	const double FOVH2 = FovHInner/2;
	const bool   OfflineMode = AOIDataCollect.GetOfflineMode();	
	const bool   bBypassGrab3D = AOIDataCollect.GetAutoBypassGrab3DFrame();
	OFFLINE_FILE_MODE OfflineFileMode = GetProjectOfflineFileMode();
	TFrameParam *FrameParamPtr = NULL;
	TSliceParam *SliceParamPtr = NULL;
	std::vector<TSliceParam>  SliceParamList;
	std::vector<TFrameParam>  FrameParamList;
	std::vector<TSliceParam>  SliceParamList_No3D;
	std::vector<TFrameParam>  FrameParamList_No3D;	
	CloneProjectSliceParamList(SliceParamList);
	CloneProjectFrameParamList(FrameParamList);
	CloneProjectSliceParamList_No3D(SliceParamList_No3D);
	CloneProjectFrameParamList_No3D(FrameParamList_No3D);

	size_t       FrameParamCount = 0;
	const size_t FrameParamCount_Full = FrameParamList.size();	
	const size_t FrameParamCount_No3D = FrameParamList_No3D.size();		
	const double   FocusPos = ProjectPtr->GetProjectFocusPos();
	const int      DefNotSet  = 0;
	const int      DefByBoard = 1;
	const int      DefByPanel = 2;

	CameraFrameIdx = 0;
	FieldRect.left = 0;
	FieldRect.top  = 0;
	FieldRect.right = ImageW;
	FieldRect.bottom = ImageH;

	ProgramOfflineMode = false;
	if ( true==OfflineMode && OFFLINE_FILE_PROGRAM==OfflineFileMode  )
	{	ProgramOfflineMode = true;	}	

	//最佳化路徑
	size_t        RgnCountValid=0;
	size_t        FieldCountValid=0;
	double        PathStartPosX=0;
	double        PathStartPosY=0;	
	size_t        FieldIdx=0;
	size_t        JetFieldIdx=0;
	TJetField     JetField;
	TJetField    *JetPathPtr=NULL;
	TJetField    *JetFieldPtr=NULL;
	TJetFieldList JetPathList;
	TJetFieldList JetFieldList;	
	FIELD_PATH_MODE FieldPathMode = ProjectPtr->GetProjectParameter().m_FieldPathMode;
	const double  SectionFactor = ProjectPtr->GetProjectParameter().m_FieldSectionFactor;
	const DISTRICT_ID ProjectDistrictID = ProjectPtr->GetProjectActDistrictID();

	str.Format(_T("CAOIProject::CreateProjectInspectionObj#ExecFieldPath Start"));
	AOIDataCollect.SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	JetAPI::SetFuncTimeStart(fnStart);

	MotionCtrlPtr->GetCurrentPos(PathStartPosX, PathStartPosY);

	TPOINT2D TestStartPos(PathStartPosX, PathStartPosY);
	if ( false == OfflineMode ) 
	{			
		if ( OFFLINE_FILE_PROGRAM==OfflineFileMode )
		{	ProjectPtr->SetProjectProgramOfflineStartPos(TestStartPos);  }
		else
		{	ProjectPtr->SetProjectInspectionOfflineStartPos(TestStartPos);  }
	}
	else
	{
		if ( OFFLINE_FILE_PROGRAM==OfflineFileMode )
		{	ProjectPtr->GetProjectProgramOfflineStartPos(TestStartPos);  }
		else
		{	ProjectPtr->GetProjectInspectionOfflineStartPos(TestStartPos);  }		
	}
	
	CJetFieldDivider FieldDivider;
	FieldDivider.SetPathMode(FieldPathMode);
	FieldDivider.SetSectionFactor(SectionFactor);
	FieldDivider.SetFieldMaxW(FovWInner);
	FieldDivider.SetFieldMaxH(FovHInner);	
	FieldDivider.SetPathStartPosX(TestStartPos.x);//確定檢測的起點相同
	FieldDivider.SetPathStartPosY(TestStartPos.y);
	
	//初始化
	RgnCountValid = 0;
	FieldCountValid = 0;	
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }			
		BoardPtr->ClearBoardFieldTempList();		
	}
	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = GetProjectFieldPtr(i, false);
		if ( NULL == FieldPtr ) { continue; }
		DistrictID = FieldPtr->GetFieldDistrictID();
		if ( DistrictID != ProjectDistrictID ) { continue; }
		FieldPtr->SetFieldGrabIndex(-1);
		FieldPtr->SetFieldTempInt(DefNotSet);//區域已經加入路徑列表
		RgnCount = FieldPtr->GetFieldRgnPtrCount();
		RgnCountValid += RgnCount;
		if ( 0 == RgnCount ) 
		{	continue; }
		FieldCountValid ++;
	}

	bool bUseBoardFdFirst=false;	
	if ( FN_ENABLE == GetProjectParameter().m_FieldDivisionBoardFdFirst )
	{
		if ( BOARD_FD_GRAB_INSPECTING == BoardFdGrabMode )
		{	bUseBoardFdFirst = true; }
	}	
	if ( true == bUseBoardFdFirst )	
	{
		size_t         GrabIndex;
		size_t         UserIndex;		
		TJetField      JetField1;
		TJetField      JetField2;
		AOI_OBJ_TYPE   RgnObjType;
		double         PathStartPosX2=PathStartPosX;
		double         PathStartPosY2=PathStartPosY;
		CAOIRgn*       RgnPtr2 = NULL;//檢測區域指標
		CAOIField*     FieldPtr1 = NULL;//區域指標
		CAOIField*     FieldPtr2 = NULL;//區域指標		
		TJetField     *JetFieldPtr1=NULL;
		TJetField     *JetFieldPtr2=NULL;
		TJetFieldList  JetPathList_Fd;
		TJetFieldList  JetFieldList_Fd;
		TJetFieldList  JetPathList_Other;
		TJetFieldList  JetFieldList_Other;
		TJetFieldList  JetPathList_Object;
		TJetFieldList  JetFieldList_Object;	
		std::vector<CAOIRgn*> TempRgnList;
		std::vector<CAOIRgn*> TempRgnList2;				
		if ( FIELD_BUILD_MATRIX == FieldBuildMode )
		{	//等間距移動			
			for ( i=0; i<FieldCount; i++ )
			{
				FieldPtr = GetProjectFieldPtr(i, false);
				if ( NULL == FieldPtr ) { continue; }
				DistrictID = FieldPtr->GetFieldDistrictID();
				if ( DistrictID != ProjectDistrictID ) { continue; }
				RgnCount = FieldPtr->GetFieldRgnPtrCount();
				if ( 0 == RgnCount ) 
				{	continue; }
				FovPos = FieldPtr->GetFieldStagePos();
				JetField.FieldID = i;
				JetField.Ptr  = NULL;
				JetField.Ptr2 = FieldPtr;
				JetField.minX = FovPos.x-FOVW2;
				JetField.maxX = FovPos.x+FOVW2;
				JetField.minY = FovPos.y-FOVH2;
				JetField.maxY = FovPos.y+FOVH2;
				JetFieldList.push_back(JetField);
			}

			if ( FieldDivider.ExecFieldPath(JetFieldList) == false )
			{
				this->m_ErrorString.Format(_T("Error, FieldDivider.ExecFieldPath Fault"));
				return false; 
			}
			FieldDivider.CloneJetPathList(JetPathList);
			const size_t PathCount = JetPathList.size();
			for ( i=0; i<PathCount; i++ )
			{	
				JetPathPtr = &(JetPathList[i]);			
				FieldPtr = (CAOIField*)(JetPathPtr->Ptr2);
				if ( NULL == FieldPtr ) { continue; }							
				FieldPtr->SetFieldTempInt(DefByBoard);
			}	
			
			GrabIndex = 0;
			TempRgnList.clear();			
			const size_t TempPathCount = JetPathList.size();
			for ( i=0; i<TempPathCount; i++ )//要根據檢測次序來排放置單板內
			{
				JetField1 = JetPathList[i];			
				FieldPtr = (CAOIField*)(JetField1.Ptr2);						
				//FieldPtr = GetProjectFieldPtr(i);
				if ( NULL == FieldPtr ) { continue; }
				RgnCount = FieldPtr->GetFieldRgnPtrCount();
				if ( FieldPtr->GetFieldTempInt() == DefNotSet ) { continue; }
				FieldPtr->SetFieldGrabIndex(GrabIndex);
				UserIndex = FieldPtr->GetFieldGrabIndexByUser();
				if ( -1 == UserIndex )
				{	FieldPtr->SetFieldGrabIndexByUser(GrabIndex); }
				GrabIndex ++;
				
				BoardPtr_Last = NULL;			
				for ( k=0; k<RgnCount; k++ )
				{
					RgnPtr = FieldPtr->GetFieldRgnPtr(k, false);
					if ( NULL == RgnPtr ) { continue; }
					RgnPtr->SetRgnTempInt(FN_DISABLE);
					TempRgnList.push_back(RgnPtr);

					RgnPtr2 = RgnPtr->GetRgnParent();
					if ( NULL != RgnPtr2 )
					{	BoardPtr = RgnPtr2->GetRgnBoardPtr();	}
					else
					{	BoardPtr = RgnPtr->GetRgnBoardPtr();	}
					if ( NULL == BoardPtr ) { continue; }
					if ( BoardPtr != BoardPtr_Last )//減少比較次數
					{	BoardPtr->AddBoardFieldTempPtr(FieldPtr, true); }
					BoardPtr_Last = BoardPtr;
				}
			}
		}
		else //任意位置移動-FieldBuildMode = FIELD_BUILD_RANDOM_PANEL/FIELD_BUILD_RANDOM_BOARD
		{	
			//尋找最接近的單板
			for ( i=0; i<FieldCount; i++ )
			{
				FieldPtr = GetProjectFieldPtr(i, false);
				if ( NULL == FieldPtr ) { continue; }
				DistrictID = FieldPtr->GetFieldDistrictID();
				if ( DistrictID != ProjectDistrictID ) { continue; }
				RgnCount = FieldPtr->GetFieldRgnPtrCount();
				if ( 0 == RgnCount ) 
				{	continue; }
				if ( FieldPtr->GetFieldTempInt() == DefByBoard ) { continue; }

				for ( j=0; j<RgnCount; j++ )
				{
					RgnPtr = FieldPtr->GetFieldRgnPtr(j, false);
					if ( NULL == RgnPtr ) { continue; }
					RgnPtr2 = RgnPtr->GetRgnParent();
					if ( NULL != RgnPtr2 )
					{	
						BoardPtr = RgnPtr2->GetRgnBoardPtr();
						RgnObjType = RgnPtr2->GetObjType();	
					}
					else
					{
						BoardPtr = RgnPtr->GetRgnBoardPtr();
						RgnObjType = RgnPtr->GetObjType();	
					}
					if ( AOI_OBJ_FD != RgnObjType ) { continue; }
					break;
				}
				//沒有Fd Ptr
				if ( j == RgnCount ) { continue; }
				FovPos = FieldPtr->GetFieldStagePos();
				JetField.Ptr  = BoardPtr;
				JetField.Ptr2 = FieldPtr;
				JetField.FieldID = i;
				JetField.minX = FovPos.x-FOVW2;
				JetField.maxX = FovPos.x+FOVW2;
				JetField.minY = FovPos.y-FOVH2;
				JetField.maxY = FovPos.y+FOVH2;
				JetFieldList_Fd.push_back(JetField);
			}
			if ( FieldDivider.ExecFieldPath(JetFieldList_Fd) == false )
			{
				this->m_ErrorString.Format(_T("Error, FieldDivider.ExecFieldPath(Fd) Fault"));
				return false; 
			}
			FieldDivider.CloneJetPathList(JetPathList_Fd);
			size_t ObjectPathCount = 0;		
			size_t ObjectFieldCount = 0;		
			const size_t FdPathCount = JetPathList_Fd.size();
			const size_t FdFieldCount = JetFieldList_Fd.size();
			for ( i=0; i<FdPathCount; i++ )
			{
				JetField1 = JetPathList_Fd[i];			
				BoardPtr = (CAOIBoard*)(JetField1.Ptr);
				FieldPtr1 = (CAOIField*)(JetField1.Ptr2);
				if ( NULL == FieldPtr1 ) { continue; }			
				if ( FieldPtr1->GetFieldTempInt() == DefByBoard ) { continue; }
				FieldIdx = FieldPtr1->GetFieldIndex();
				FovPos = FieldPtr1->GetFieldStagePos();
				PathStartPosX2 = FovPos.x;
				PathStartPosY2 = FovPos.y;
				FieldPtr1->SetFieldTempInt(DefByBoard);
				JetField1.FieldID = FieldIdx;
				JetPathList.push_back(JetField1);			
				for ( j=0; j<FdFieldCount; j++ )//加入其餘同單板的定位點
				{
					if ( j == i ) { continue; }
					JetField2 = JetPathList_Fd[j];
					if ( JetField2.Ptr != JetField1.Ptr ) { continue; }
					FieldPtr2 = (CAOIField*)(JetField2.Ptr2);				
					if ( NULL == FieldPtr2 ) { continue; }				
					if ( FieldPtr2->GetFieldTempInt() == DefByBoard ) 
					{	continue; }
					FieldIdx = FieldPtr2->GetFieldIndex();
					FovPos = FieldPtr2->GetFieldStagePos();
					PathStartPosX2 = FovPos.x;
					PathStartPosY2 = FovPos.y;
					FieldPtr2->SetFieldTempInt(DefByBoard);
					JetField2.FieldID = FieldIdx;
					JetPathList.push_back(JetField2);
				}
			
				JetFieldList_Object.clear();
				for ( j=0; j<FieldCount; j++ )
				{				
					FieldPtr = GetProjectFieldPtr(j, false);
					if ( NULL == FieldPtr ) { continue; }
					DistrictID = FieldPtr->GetFieldDistrictID();
					if ( DistrictID != ProjectDistrictID ) { continue; }
					if ( FieldPtr->GetFieldTempInt() == DefByBoard ) { continue; }				
					RgnCount = FieldPtr->GetFieldRgnPtrCount();
					if ( 0 == RgnCount ) 
					{	continue; }
					for ( k=0; k<RgnCount; k++ )
					{
						RgnPtr = FieldPtr->GetFieldRgnPtr(k, false);				
						RgnPtr2 = RgnPtr->GetRgnParent();
						if ( NULL != RgnPtr2 )
						{	BoardPtr = RgnPtr2->GetRgnBoardPtr();	}
						else
						{	BoardPtr = RgnPtr->GetRgnBoardPtr();	}
						if ( BoardPtr == JetField1.Ptr )
						{	break; }					
					}
					//沒有相同單板的零件
					if ( k == RgnCount ) { continue; }
					FovPos = FieldPtr->GetFieldStagePos();
					JetField.Ptr = BoardPtr;
					JetField.Ptr2 = FieldPtr;
					JetField.FieldID = j;
					JetField.minX = FovPos.x-FOVW2;
					JetField.maxX = FovPos.x+FOVW2;
					JetField.minY = FovPos.y-FOVH2;
					JetField.maxY = FovPos.y+FOVH2;
					JetFieldList_Object.push_back(JetField);
				}
				FieldDivider.SetPathStartPosX(PathStartPosX2);
				FieldDivider.SetPathStartPosY(PathStartPosY2);
				if ( FieldDivider.ExecFieldPath(JetFieldList_Object) == false )
				{
					this->m_ErrorString.Format(_T("Error, FieldDivider.ExecFieldPath(Object) Fault"));
					return false; 
				}
				FieldDivider.CloneJetPathList(JetPathList_Object);			
				ObjectPathCount = JetPathList_Object.size();
				ObjectFieldCount = JetFieldList_Object.size();
				for ( j=0; j<ObjectPathCount; j++ )
				{
					JetField1 = JetPathList_Object[j];
					BoardPtr = (CAOIBoard*)(JetField1.Ptr);
					FieldPtr1 = (CAOIField*)(JetField1.Ptr2);
					if ( NULL == FieldPtr1 ) { continue; }				
					if ( FieldPtr1->GetFieldTempInt() == DefByBoard ) { continue; }				
					FieldIdx = FieldPtr1->GetFieldIndex();
					FovPos = FieldPtr1->GetFieldStagePos();
					PathStartPosX2 = FovPos.x;
					PathStartPosY2 = FovPos.y;
					FieldPtr1->SetFieldTempInt(DefByBoard);
					JetField1.FieldID = FieldIdx;
					JetPathList.push_back(JetField1);	
				}
			}
			//剩餘其它的-歸屬整板上的
			JetFieldList_Other.clear();
			for ( i=0; i<FieldCount; i++ )
			{
				FieldPtr = GetProjectFieldPtr(i, false);
				if ( NULL == FieldPtr ) { continue; }
				DistrictID = FieldPtr->GetFieldDistrictID();
				if ( DistrictID != ProjectDistrictID ) { continue; }
				if ( FieldPtr->GetFieldTempInt() == DefByBoard ) { continue; }
				RgnCount = FieldPtr->GetFieldRgnPtrCount();
				if ( 0 == RgnCount ) 
				{	continue; }
				FovPos = FieldPtr->GetFieldStagePos();
				JetField.FieldID = i;
				JetField.Ptr  = NULL;
				JetField.Ptr2 = FieldPtr;
				JetField.minX = FovPos.x-FOVW2;
				JetField.maxX = FovPos.x+FOVW2;
				JetField.minY = FovPos.y-FOVH2;
				JetField.maxY = FovPos.y+FOVH2;			
				JetFieldList_Other.push_back(JetField);
			}
			if ( FieldDivider.ExecFieldPath(JetFieldList_Other) == false )
			{
				this->m_ErrorString.Format(_T("Error, FieldDivider.ExecFieldPath(Others) Fault"));
				return false; 
			}
			FieldDivider.CloneJetPathList(JetPathList_Other);		
			const size_t OtherPathCount = JetPathList_Other.size();
			const size_t OtherFieldCount = JetFieldList_Other.size();
			for ( i=0; i<OtherPathCount; i++ )
			{	
				JetField1 = JetPathList_Other[i];
				BoardPtr = (CAOIBoard*)(JetField1.Ptr);
				FieldPtr1 = (CAOIField*)(JetField1.Ptr2);			
				if ( NULL == FieldPtr1 ) { continue; }			
				if ( FieldPtr1->GetFieldTempInt() == DefByBoard ) { continue; }
				FieldIdx = FieldPtr1->GetFieldIndex();
				FovPos = FieldPtr1->GetFieldStagePos();
				PathStartPosX2 = FovPos.x;
				PathStartPosY2 = FovPos.y;				
				FieldPtr1->SetFieldTempInt(DefByPanel);
				JetField1.FieldID = FieldIdx;
				JetPathList.push_back(JetField1);	
			}
		
			GrabIndex = 0;
			TempRgnList.clear();
			JetFieldList.clear();
			const size_t TempPathCount = JetPathList.size();
			for ( i=0; i<TempPathCount; i++ )//要根據檢測次序來排放置單板內
			{
				JetField1 = JetPathList[i];			
				FieldPtr = (CAOIField*)(JetField1.Ptr2);						
				//FieldPtr = GetProjectFieldPtr(i);
				if ( NULL == FieldPtr ) { continue; }
				RgnCount = FieldPtr->GetFieldRgnPtrCount();
				if ( FieldPtr->GetFieldTempInt() == DefNotSet ) { continue; }
				FieldPtr->SetFieldGrabIndex(GrabIndex);
				UserIndex = FieldPtr->GetFieldGrabIndexByUser();
				if ( -1 == UserIndex )
				{	FieldPtr->SetFieldGrabIndexByUser(GrabIndex); }
				GrabIndex ++;

				FovPos = FieldPtr->GetFieldStagePos();
				JetPathList[i].FieldID = JetFieldList.size();
				JetField.FieldID = FieldPtr->GetFieldIndex();// JetFieldList.size();
				JetField.minX = FovPos.x-FOVW2;
				JetField.maxX = FovPos.x+FOVW2;
				JetField.minY = FovPos.y-FOVH2;
				JetField.maxY = FovPos.y+FOVH2;
				JetFieldList.push_back(JetField);

				BoardPtr_Last = NULL;			
				for ( k=0; k<RgnCount; k++ )
				{
					RgnPtr = FieldPtr->GetFieldRgnPtr(k, false);
					if ( NULL == RgnPtr ) { continue; }
					RgnPtr->SetRgnTempInt(FN_DISABLE);
					TempRgnList.push_back(RgnPtr);

					RgnPtr2 = RgnPtr->GetRgnParent();
					if ( NULL != RgnPtr2 )
					{	BoardPtr = RgnPtr2->GetRgnBoardPtr();	}
					else
					{	BoardPtr = RgnPtr->GetRgnBoardPtr();	}
					if ( NULL == BoardPtr ) { continue; }
					if ( BoardPtr != BoardPtr_Last )//減少比較次數
					{	BoardPtr->AddBoardFieldTempPtr(FieldPtr, true); }
					BoardPtr_Last = BoardPtr;
				}
			}
		}
		//各自單板計算檢測次序-先定位點再來才是其餘檢測物件
		const size_t TempRgnCount = TempRgnList.size();
		for ( i=0; i<BoardCount; i++ )
		{
			BoardPtr = GetProjectBoardPtr(i, false);
			if ( NULL == BoardPtr ) { continue; }
			BoardPtr->LayoutBoardRgnTempList();			
		}		
		//注意以單板的定位點最後取像的排序依據 //GrabIndex CAOIField::GetFieldGrabIndex 
		int                   nGrabIndex=0;
		const bool            FdFirst = true;
		CSortObj              SortObj;
		CSortObj             *SortObjPtr=NULL;
		std::vector<CSortObj> SortList;		
		SortObj.SetSortMode(SORT_BY_INT);
		for ( i=0; i<BoardCount; i++ )
		{
			BoardPtr = GetProjectBoardPtr(i, false);
			if ( NULL == BoardPtr ) { continue; }			
			GrabIndex = BoardPtr->CalcBoardLastFieldGrabIndex(FdFirst);
			if ( -1 == GrabIndex ) 
			{	nGrabIndex = -1; }
			else
			{	nGrabIndex = (int)(GrabIndex); }

			SortObj.SetID(i);
			SortObj.SetPtr(BoardPtr);
			SortObj.SetValueInt(nGrabIndex);
			SortList.push_back(SortObj);
		}
		std::sort(SortList.begin(), SortList.end());
		const size_t SortCount = SortList.size();
		
		std::vector<CAOIBoard*> TmpBoardList;
		TmpBoardList.clear();
		for ( i=0; i<SortCount; i++ )
		{
			SortObjPtr = &(SortList[i]);
			BoardPtr = (CAOIBoard*)(SortObjPtr->GetPtr());
			if ( NULL == BoardPtr ) { continue; }
			TmpBoardList.push_back(BoardPtr);
		}

		//加入檢測的次序需要以取像次序為主
		size_t BoardRgnTempCount=0;
		const size_t TempBoardCount = TmpBoardList.size();		
		for ( i=0; i<TempBoardCount; i++ )
		{
			BoardPtr = TmpBoardList[i];
			if ( NULL == BoardPtr ) { continue; }
			BoardRgnTempCount = BoardPtr->GetBoardRgnTempCount();
			for ( j=0; j<BoardRgnTempCount; j++ )
			{	
				RgnPtr = BoardPtr->GetBoardRgnTempPtr(j, false);				
				TempRgnList2.push_back(RgnPtr);
			}
		}
		//該檢測區域內沒有單板物件時最後算
		for ( i=0; i<TempRgnCount; i++ )
		{
			RgnPtr = TempRgnList[i];
			if ( NULL == RgnPtr ) { continue; }			
			if ( RgnPtr->GetRgnTempInt() == FN_ENABLE ) { continue; }
			RgnPtr->SetRgnTempInt(FN_ENABLE);
			TempRgnList2.push_back(RgnPtr);	
		}

		//將檢測資料放入暫存列表
		const size_t TempRgnCount2 = TempRgnList2.size();
		if ( TempRgnCount2 != TempRgnCount ) 
		{
			str.Format(_T("%s\\RgnList1.TXT"), AOIDataCollect.GetAOITempDirectory());
			DumpProjectRgnList(str, TempRgnList);
			::ShellExecute(NULL, _T("open"), str, NULL, NULL, SW_SHOW);

			str.Format(_T("%s\\RgnList2.TXT"), AOIDataCollect.GetAOITempDirectory());
			DumpProjectRgnList(str, TempRgnList2);
			::ShellExecute(NULL, _T("open"), str, NULL, NULL, SW_SHOW);			
			m_ErrorString = _T("Error, Rgn Count Exception");
			return false;
		}
		//確認是否每個檢測區域都有配置過
		for ( i=0; i<TempRgnCount2; i++ )
		{
			RgnPtr = TempRgnList2[i];
			if ( NULL == RgnPtr ) { continue; }
			if ( RgnPtr->GetRgnTempInt() == FN_ENABLE ) { continue; }
			RgnPtr->SetRgnTempInt(FN_DISABLE);
		}	
		for ( i=0; i<TempRgnCount2; i++ )
		{
			RgnPtr = TempRgnList2[i];
			if ( NULL == RgnPtr ) { continue; }
			RgnPtr->SetRgnLinkPointer(true);
			RgnPtr->SetRgnCalculated(false);
			RgnPtr->SetRgnCalcState(REGION_CALC_NONE);
			AddProjectTempRgnPtr(RgnPtr, false);			
		}
	}
	else		
	{	
		for ( i=0; i<FieldCount; i++ )
		{
			FieldPtr = GetProjectFieldPtr(i, false);
			if ( NULL == FieldPtr ) { continue; }
			DistrictID = FieldPtr->GetFieldDistrictID();
			if ( DistrictID != ProjectDistrictID ) { continue; }
			RgnCount = FieldPtr->GetFieldRgnPtrCount();
			if ( 0 == RgnCount ) 
			{	continue; }
			FovPos = FieldPtr->GetFieldStagePos();
			JetField.FieldID = i;
			JetField.UserIndex = FieldPtr->GetFieldGrabIndexByUser();
			JetField.Ptr  = NULL;
			JetField.Ptr2 = FieldPtr;
			JetField.minX = FovPos.x-FOVW2;
			JetField.maxX = FovPos.x+FOVW2;
			JetField.minY = FovPos.y-FOVH2;
			JetField.maxY = FovPos.y+FOVH2;
			JetFieldList.push_back(JetField);
		}

		if ( FieldDivider.ExecFieldPath(JetFieldList) == false )
		{
			this->m_ErrorString.Format(_T("Error, FieldDivider.ExecFieldPath Fault"));
			return false; 
		}
		FieldDivider.CloneJetPathList(JetPathList);

		size_t       UserIndex;
		const size_t PathCount = JetPathList.size();
		for ( i=0; i<PathCount; i++ )
		{	
			JetPathPtr = &(JetPathList[i]);			
			FieldPtr = (CAOIField*)(JetPathPtr->Ptr2);
			if ( NULL == FieldPtr ) { continue; }			
			FieldPtr->SetFieldGrabIndex(i);
			UserIndex = FieldPtr->GetFieldGrabIndexByUser();
			if ( -1 == UserIndex )
			{	FieldPtr->SetFieldGrabIndexByUser(i); }
		}		
	}
	const size_t JetFieldCount = JetFieldList.size();
	const size_t JetPathCount = JetPathList.size();
	if ( JetPathCount!=JetFieldCount || JetPathCount!=FieldCountValid )
	{
		this->m_ErrorString.Format(_T("Error, FieldDivider.ExecFieldPath Fault"));
		return false; 
	}
	JetAPI::SetFuncTimeEnd(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CAOIProject::CreateProjectInspectionObj#ExecFieldPath Time=%.3f ms"), fnTime);
	AOIDataCollect.SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);

	//提前移動至前一個位置
	if ( false == OfflineMode )
	{
		if ( JetPathCount > 0 ) 
		{		
			JetPathPtr = &(JetPathList[0]);
			JetFieldIdx = JetPathPtr->FieldID;
			if ( JetFieldIdx < JetFieldCount )
			{
				JetFieldPtr = &(JetFieldList[JetFieldIdx]);
				FieldIdx = JetFieldPtr->FieldID;
				if ( FieldIdx < FieldCount )
				{
					FieldPtr = GetProjectFieldPtr(FieldIdx, false);
					FieldPtr = (CAOIField*)(JetPathPtr->Ptr2);
					if ( FieldPtr != JetPathPtr->Ptr2 )
					{	FieldPtr = FieldPtr;	}
					if ( NULL != FieldPtr )
					{
						FovPos = FieldPtr->GetFieldStagePos();
						FovPos.z = GetProjectFocusPos();
						MotionCtrlPtr->XYZMoveTo(FovPos.x, FovPos.y, FovPos.z);
					}
				}
			}		
		}
		//確認取像位置都在機台範圍內
		const double StageMinX = MotionCtrlPtr->GetMotionParameter().m_LimitMinX;
		const double StageMinY = MotionCtrlPtr->GetMotionParameter().m_LimitMinY;
		const double StageMaxX = MotionCtrlPtr->GetMotionParameter().m_LimitMaxX;
		const double StageMaxY = MotionCtrlPtr->GetMotionParameter().m_LimitMaxY;
		for ( i=0; i<JetPathCount; i++ )
		{
			FieldIdx = i;
			JetPathPtr = &(JetPathList[i]);
		
			JetFieldIdx = JetPathPtr->FieldID;
			if ( JetFieldIdx >= JetFieldCount ) 
			{	continue; }
			JetFieldPtr = &(JetFieldList[JetFieldIdx]);
			FieldIdx = JetFieldPtr->FieldID;
			if ( FieldIdx >= FieldCount ) 
			{	continue; }
			FieldPtr = GetProjectFieldPtr(FieldIdx, false);		
			//FieldPtr = (CAOIField*)(JetPathPtr->Ptr2);
			if ( NULL == FieldPtr ) { continue; }
			if ( FieldPtr != JetPathPtr->Ptr2 )
			{	FieldPtr = FieldPtr;	}
			FovPos = FieldPtr->GetFieldStagePos();
			if ( FovPos.x<StageMinX || FovPos.y<StageMinY || FovPos.x>StageMaxX || FovPos.y>StageMaxY )
			{
				m_ErrorString.Format(_T("Error, Field[%d] position out of stage region"), JetFieldIdx+1);
				return false;
			}
		}
	}

	const int    HeightID_Disable=0;
	size_t       FrameSliceCount=0;
	std::vector<CAOISlice*> FrameSlicePtrList;
	str.Format(_T("CAOIProject::CreateProjectInspectionObj#AssignFieldPtr Start"));
	AOIDataCollect.SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	JetAPI::SetFuncTimeStart(fnStart);
	//for ( i=0; i<FieldCount; i++ )
	for ( i=0; i<JetPathCount; i++ )
	{
		FieldIdx = i;
		JetPathPtr = &(JetPathList[i]);
		/*
		JetFieldIdx = JetPathPtr->FieldID;
		if ( JetFieldIdx >= JetFieldCount ) { continue; }
		JetFieldPtr = &(JetFieldList[JetFieldIdx]);
		FieldIdx = JetFieldPtr->FieldID;
		if ( FieldIdx >= FieldCount ) { continue; }
		FieldPtr = GetProjectFieldPtr(FieldIdx);
		*/
		FieldPtr = (CAOIField*)(JetPathPtr->Ptr2);
		if ( NULL == FieldPtr ) { continue; }
		if ( FieldPtr != JetPathPtr->Ptr2 )
		{	FieldPtr = FieldPtr;	}
		FovPos = FieldPtr->GetFieldStagePos();
		FovPos.z = FocusPos;
		FovPtr = AOIObjManager.CreateFovObj();
		if ( NULL == FovPtr )
		{
			ClearProjectAllTempObjects();
			this->m_ErrorString = _T("Error, Create AOI Fov Obj Fault");
			return false;
		}
		this->AddProjectTempFovPtr(FovPtr, false);
		FovPtr->SetFovFrameParamList(FrameParamList);
		FovPtr->SetFovSliceParamList(SliceParamList);
		FovPtr->SetFovStagePos(FovPos);				
		
		FieldPtr->SetFieldLinkPointer(true);
		FieldPtr->SetFieldLockRelease(false);
		FieldPtr->SetFieldIsInSaveList(false);		
		FieldPtr->SetFieldHeightID(HeightID_Disable);
		FieldPtr->SetFieldCalcState(FIELD_CALC_NONE);
		FieldPtr->SetFieldMergeState(FIELD_MERGE_NONE);
		this->AddProjectTempFieldPtr(FieldPtr, false);

		bool bUsing3D=true;		
		if ( false==ProgramOfflineMode && false==bOthersUsing3D && true==bBypassGrab3D )
		{
			bUsing3D=FieldPtr->CheckFieldUsing3D();
			if ( false == bUsing3D )
			{
				FovPtr->SetFovUsing3D(false);
				FovPtr->SetFovFrameParamList(FrameParamList_No3D);
				FovPtr->SetFovSliceParamList(SliceParamList_No3D);
			}
		}	

		//檢測區域的指標		
		if ( BOARD_FD_GRAB_INSPECTING != BoardFdGrabMode || false==bUseBoardFdFirst )
		{
			RgnCount = FieldPtr->GetFieldRgnPtrCount();
			for ( j=0; j<RgnCount; j++ )
			{
				RgnPtr = FieldPtr->GetFieldRgnPtr(j, false);
				if ( NULL == RgnPtr ) { continue; }
				RgnPtr->SetRgnLinkPointer(true);
				RgnPtr->SetRgnCalculated(false);
				RgnPtr->SetRgnCalcState(REGION_CALC_NONE);
				this->AddProjectTempRgnPtr(RgnPtr, false);
			}		
		}
		
		RebuildFrame = false;
		FrameCount = FieldPtr->GetFieldFramePtrCount();
		FrameParamCount = bUsing3D ? FrameParamCount_Full:FrameParamCount_No3D;
		//if ( FrameParamCount!=FrameCount || false==OfflineMode ) 
		if ( FrameParamCount>FrameCount || false==OfflineMode ) 
		{	RebuildFrame = true;	}
		else
		{
			if ( true==OfflineMode )
			{	RebuildFrame = false; }
			else if ( FieldPtr->CheckFieldFrameMatchFrameParam(FrameParamList)==false )
			{	RebuildFrame = true; }
		}		
		if ( true == RebuildFrame )
		{
			FieldPtr->ClearFieldAllFrames();
			for ( j=0; j<FrameParamCount; j++ )
			{
				if ( true == bUsing3D )
				{	FrameParamPtr = &(FrameParamList[j]);	}
				else
				{	FrameParamPtr = &(FrameParamList_No3D[j]);	}
				if ( NULL == FrameParamPtr ) { continue; }
				//FramePtr = CAOIProject::CreateProjectFramePtrByFrameParam(FieldPtr, FrameParamPtr, CameraFrameIdx);				
				FrameSlicePtrList.clear();
				if ( AOIDataCollect.CreateFramePtrByFrameParam(FieldPtr, FrameParamPtr, CameraFrameIdx, FramePtr, FrameSlicePtrList) == false )
				{
					AOIObjManager.DestroyFrameObj(FramePtr);
					FrameSliceCount = FrameSlicePtrList.size();
					for ( k=0; k<FrameSliceCount; k++ )
					{	AOIObjManager.DestroySliceObj(FrameSlicePtrList[k]);	}	
					ClearProjectAllTempObjects();
					return false;
				}
				FrameSliceCount = FrameSlicePtrList.size();
				for ( k=0; k<FrameSliceCount; k++ )
				{	AddProjectTempSlicePtr(FrameSlicePtrList[k], false);	}
				this->AddProjectTempFramePtr(FramePtr, false);
				FieldPtr->AddFieldFramePtr(FramePtr);
				FramePtr->SetFrameLinkPointer(true);
				FramePtr->SetFrameHeightID(HeightID_Disable);
				FramePtr->SetFrameImageIndex((unsigned int)j);
			}
		}
		else
		{
			IMAGE_PTR  ImagePtr=NULL;
			MASK_PTR   MaskPtr=NULL;
			SPACE_PTR  SpacePtr=NULL;			
			FRAME_TYPE FrameType = FRAME_NULL;
			FIELD_CALC_STATE  FieldCalcState=FIELD_CALC_DONE;
			FRAME_MERGE_STATE FrameMergeType=FRAME_MERGE_NONE;
			IMAGE_SIZE FrameW=0, FrameH=0, FrameStep=0, FrameBits=0;
			FrameCount = FieldPtr->GetFieldFramePtrCount();
			for ( j=0; j<FrameCount; j++ )
			{
				FramePtr = FieldPtr->GetFieldFramePtr(j, true);
				if ( NULL == FramePtr )
				{
					ClearProjectAllTempObjects();				
					return false;
				}
				this->AddProjectTempFramePtr(FramePtr, false);				
				FramePtr->SetFrameLinkPointer(true);
				FramePtr->SetFrameHeightID(HeightID_Disable);
				FramePtr->SetFrameImageIndex((unsigned int)j);
				if ( true == AutoReleaseFieldFrame )
				{					
					FramePtr->SetFrameCalcState(FRAME_CALC_NONE);
					FramePtr->SetFrameMergeState(FRAME_MERGE_NONE);
					continue;
				}

				FrameType = FramePtr->GetFrameType();
				switch ( FrameType )
				{
				case FRAME_SPACE:
					FramePtr->GetFrameSpacePtr(FrameW, FrameH, FrameStep, FrameBits, MaskPtr, SpacePtr);
					if ( NULL==MaskPtr || NULL==SpacePtr )
					{	FrameMergeType=FRAME_MERGE_NONE;	}
					else
					{	FrameMergeType=FRAME_MERGE_DONE;	}
					//FrameMergeType=FRAME_MERGE_NONE;
					break;
				default:
					FramePtr->GetFrameImagePtr(FrameW, FrameH, FrameStep, FrameBits, ImagePtr);
					if ( NULL == ImagePtr )
					{	FrameMergeType=FRAME_MERGE_NONE;	}
					else
					{	FrameMergeType=FRAME_MERGE_DONE; }
					break;
				}
				if ( FRAME_MERGE_NONE == FrameMergeType )
				{	
					FramePtr->ClearFrameBuffer(); 
					FramePtr->SetFrameCalcState(FRAME_CALC_NONE);
				}
				else
				{	FramePtr->SetFrameCalcState(FRAME_CALC_DONE); }
				FramePtr->SetFrameMergeState(FrameMergeType);
			}
			if ( FieldPtr->CheckFieldFramesMergeFinish() == true )
			{	FieldPtr->SetFieldMergeState(FIELD_MERGE_DONE);	}
		}
	}

//#ifdef _DEBUG	
	str.Format(_T("%s\\InspectedRgnList.TXT"), AOIDataCollect.GetAOITempDirectory());
	DumpProjectRgnList(str, m_ProjectTempRgnPtrList);
//#endif//_DEBUG

	JetAPI::SetFuncTimeEnd(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CAOIProject::CreateProjectInspectionObj#AssignFieldPtr Time=%.3f ms"), fnTime);
	AOIDataCollect.SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SetProjectFullMapComponentFinsih()//設定專案整板零件的檢測完畢
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }

	size_t         i=0, j=0;	
	size_t         FullMapCnt=0;
	size_t         SubRgnCount=0;
	CAOIRgn*       SubRgnPtr=NULL;	
	CAOIComponent *ComponentPtr = NULL;
	REGION_CALC_STATE RegionState = REGION_CALC_DONE;
	const size_t ComponentCount = ProjectPtr->GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{		
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
		if ( ComponentPtr->CheckComponentType_FullMap() == false ) { continue; }		
		
		SubRgnCount = ComponentPtr->GetComponentSubRgnCount();
		for ( j=0; j<SubRgnCount; j++ )
		{
			SubRgnPtr = ComponentPtr->GetComponentSubRgnPtr(j, false);
			if ( NULL == SubRgnPtr ) { continue; }
			SubRgnPtr->SetRgnCalculated(true);
			SubRgnPtr->SetRgnCalcState(RegionState);		
		#ifdef _DEBUG
			FullMapCnt++;
		#endif//_DEBUG
		}
		ComponentPtr->SetRgnCalculated(true);
		ComponentPtr->SetRgnCalcState(RegionState);		
#ifdef _DEBUG
		FullMapCnt++;
#endif//_DEBUG
	}
	return true;
}
//-------------------------------------------------------------------------------------//
CAOIFrame* CAOIProject::CreateProjectFramePtrByFrameParam(const CAOIField *FieldPtr, TFrameParam *FrameParamPtr, unsigned int &CameraFrameIdx)//建立專案的Frame指標
{
	if ( NULL == FieldPtr ) { return NULL; }
	if ( NULL == FrameParamPtr ) { return NULL; }	

	CAOIFrame *FramePtr = NULL;

	FramePtr = AOIObjManager.CreateFrameObj();
	if ( NULL == FramePtr )
	{	
		this->m_ErrorString = _T("Error, Create AOI Frame Obj Fault");
		return NULL;
	}		
	
	size_t        i=0, j=0, k=0;	
	RECT          FieldRect={0};
	int           Frame3DExpCnt=0;
	int           Frame3DLightCnt=0;
	unsigned int  SliceIndex = -1;	
	double        SliceGainValue=1.0;
	CAOISlice    *SlicePtr = NULL;
	TSliceParam  *SliceParamPtr = NULL;
	
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;
	BAYER_PATTERN_MODE BayerPattern =BAYER_PATTERN_NONE;
	TPOINT3D FovPos = FieldPtr->GetFieldStagePos();

	FieldRect.left = 0;
	FieldRect.top  = 0;
	FieldRect.right = AOIDataCollect.GetCameraImageW(CameraID);
	FieldRect.bottom = AOIDataCollect.GetCameraImageH(CameraID);	
	BayerPattern = CameraCtrl.GetCameraBayerPattern(CameraID);

	FramePtr->SetFrameCameraID(CameraID);
	FramePtr->SetFrameLightMode(LIGHT_MODE_A);
	FramePtr->SetFrameBayerPattern(BayerPattern);
	FramePtr->SetFrameUniqueID(FrameParamPtr->FrameUniqueID);
	FramePtr->SetFrameSaturationRed(FrameParamPtr->FrameSaturationRed);
	FramePtr->SetFrameSaturationGreen(FrameParamPtr->FrameSaturationGreen);
	FramePtr->SetFrameSaturationBlue(FrameParamPtr->FrameSaturationBlue);
	if ( FRAME_GRAY == FrameParamPtr->FrameType )
	{						
		FramePtr->SetFrameType(FRAME_GRAY);
		if ( SLICE_UNIQUE_ID_NULL != FrameParamPtr->FrameSliceID1 )
		{
			SliceIndex = FrameParamPtr->FrameSliceIdx1;
			SliceParamPtr = AOIDataCollect.GetSystemSliceParamPtr(SliceIndex, true);
			if ( NULL == SliceParamPtr )
			{	
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Get Slice Param Ptr Fault");
				return false;
			}
			if ( SliceParamPtr->SliceUniqueID != FrameParamPtr->FrameSliceID1 )
			{
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Slice Param ID1 Exception");
				return false;
			}

			CameraID = SliceParamPtr->SliceCameraID;
			SliceGainValue = SliceParamPtr->SliceGainValue;
			SlicePtr = AOIObjManager.CreateSliceObj();
			if ( NULL == SlicePtr )
			{
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Create AOI Slice Obj Fault");
				return false;
			}
			this->AddProjectTempSlicePtr(SlicePtr, false);				
			FramePtr->AddFrameSlicePtr(SlicePtr);				
			SlicePtr->SetSliceCameraID(CameraID);
			SlicePtr->SetSliceIndex(CameraFrameIdx);
			SlicePtr->SetSliceLightMode(LIGHT_MODE_A);
			SlicePtr->SetSliceLight3DCastID(LIGHT_3D_CAST_00);
			SlicePtr->SetSliceGainValue(SliceGainValue);
			SlicePtr->SetSliceCameraFrameIndex(CameraFrameIdx);
			SlicePtr->SetSliceCameraFrameRect(FieldRect);
			SlicePtr->SetSliceFillState(SLICE_FILL_NONE);
			SlicePtr->SetSliceStagePos(FovPos);
			CameraFrameIdx ++;
		}
	}
	else if ( FRAME_BAYER == FrameParamPtr->FrameType )
	{					
		FramePtr->SetFrameType(FRAME_BAYER);		
		if ( SLICE_UNIQUE_ID_NULL != FrameParamPtr->FrameSliceID1 )
		{
			SliceIndex = FrameParamPtr->FrameSliceIdx1;
			SliceParamPtr = AOIDataCollect.GetSystemSliceParamPtr(SliceIndex, true);
			if ( NULL == SliceParamPtr )
			{	
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Get Slice Param Ptr Fault");
				return false;
			}
			if ( SliceParamPtr->SliceUniqueID != FrameParamPtr->FrameSliceID1 )
			{
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Slice Param ID1 Exception");
				return false;
			}

			CameraID = SliceParamPtr->SliceCameraID;
			SliceGainValue = SliceParamPtr->SliceGainValue;
			SlicePtr = AOIObjManager.CreateSliceObj();
			if ( NULL == SlicePtr )
			{	
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Create AOI Slice Obj Fault");
				return false;
			}
			this->AddProjectTempSlicePtr(SlicePtr, false);				
			FramePtr->AddFrameSlicePtr(SlicePtr);				
			SlicePtr->SetSliceCameraID(CameraID);
			SlicePtr->SetSliceIndex(CameraFrameIdx);
			SlicePtr->SetSliceLightMode(LIGHT_MODE_A);
			SlicePtr->SetSliceLight3DCastID(LIGHT_3D_CAST_00);
			SlicePtr->SetSliceGainValue(SliceGainValue);
			SlicePtr->SetSliceCameraFrameIndex(CameraFrameIdx);
			SlicePtr->SetSliceCameraFrameRect(FieldRect);
			SlicePtr->SetSliceFillState(SLICE_FILL_NONE);
			SlicePtr->SetSliceStagePos(FovPos);
			CameraFrameIdx ++;
		}
	}
	else if ( FRAME_COLOR == FrameParamPtr->FrameType )
	{
		FramePtr->SetFrameType(FRAME_COLOR);		
		if ( SLICE_UNIQUE_ID_NULL != FrameParamPtr->FrameSliceID1 )
		{
			SliceIndex = FrameParamPtr->FrameSliceIdx1;
			SliceParamPtr = AOIDataCollect.GetSystemSliceParamPtr(SliceIndex, true);
			if ( NULL == SliceParamPtr )
			{	
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Get Slice Param Ptr Fault");
				return false;
			}
			if ( SliceParamPtr->SliceUniqueID != FrameParamPtr->FrameSliceID1 )
			{
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Slice Param ID1 Exception");
				return false;
			}

			CameraID = SliceParamPtr->SliceCameraID;
			SliceGainValue = SliceParamPtr->SliceGainValue;
			SlicePtr = AOIObjManager.CreateSliceObj();
			if ( NULL == SlicePtr )
			{	
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Create AOI Slice Obj Fault");
				return false;
			}
			this->AddProjectTempSlicePtr(SlicePtr, false);				
			FramePtr->AddFrameSlicePtr(SlicePtr);				
			SlicePtr->SetSliceCameraID(CameraID);
			SlicePtr->SetSliceIndex(CameraFrameIdx);
			SlicePtr->SetSliceLightMode(LIGHT_MODE_A);
			SlicePtr->SetSliceLight3DCastID(LIGHT_3D_CAST_00);
			SlicePtr->SetSliceGainValue(SliceGainValue);
			SlicePtr->SetSliceCameraFrameIndex(CameraFrameIdx);
			SlicePtr->SetSliceCameraFrameRect(FieldRect);
			SlicePtr->SetSliceFillState(SLICE_FILL_NONE);
			SlicePtr->SetSliceStagePos(FovPos);
			CameraFrameIdx ++;
		}
		if ( SLICE_UNIQUE_ID_NULL != FrameParamPtr->FrameSliceID2 )
		{
			SliceIndex = FrameParamPtr->FrameSliceIdx2;
			SliceParamPtr = AOIDataCollect.GetSystemSliceParamPtr(SliceIndex, true);
			if ( NULL == SliceParamPtr )
			{	
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Get Slice Param Ptr Fault");
				return false;
			}
			if ( SliceParamPtr->SliceUniqueID != FrameParamPtr->FrameSliceID2 )
			{
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Slice Param ID2 Exception");
				return false;
			}

			CameraID = SliceParamPtr->SliceCameraID;
			SliceGainValue = SliceParamPtr->SliceGainValue;
			SlicePtr = AOIObjManager.CreateSliceObj();
			if ( NULL == SlicePtr )
			{	
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Create AOI Slice Obj Fault");
				return false;
			}
			this->AddProjectTempSlicePtr(SlicePtr, false);				
			FramePtr->AddFrameSlicePtr(SlicePtr);

			SlicePtr->SetSliceCameraID(CameraID);
			SlicePtr->SetSliceIndex(CameraFrameIdx);
			SlicePtr->SetSliceLightMode(LIGHT_MODE_A);
			SlicePtr->SetSliceLight3DCastID(LIGHT_3D_CAST_00);
			SlicePtr->SetSliceGainValue(SliceGainValue);
			SlicePtr->SetSliceCameraFrameIndex(CameraFrameIdx);
			SlicePtr->SetSliceCameraFrameRect(FieldRect);
			SlicePtr->SetSliceFillState(SLICE_FILL_NONE);
			SlicePtr->SetSliceStagePos(FovPos);
			CameraFrameIdx ++;
		}
		if ( SLICE_UNIQUE_ID_NULL != FrameParamPtr->FrameSliceID3 )
		{
			SliceIndex = FrameParamPtr->FrameSliceIdx3;
			SliceParamPtr = AOIDataCollect.GetSystemSliceParamPtr(SliceIndex, true);
			if ( NULL == SliceParamPtr )
			{	
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Get Slice Param Ptr Fault");
				return false;
			}
			if ( SliceParamPtr->SliceUniqueID != FrameParamPtr->FrameSliceID3 )
			{
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Slice Param ID3 Exception");
				return false;
			}

			CameraID = SliceParamPtr->SliceCameraID;
			SliceGainValue = SliceParamPtr->SliceGainValue;
			SlicePtr = AOIObjManager.CreateSliceObj();
			if ( NULL == SlicePtr )
			{
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Create AOI Slice Obj Fault");
				return false;
			}
			this->AddProjectTempSlicePtr(SlicePtr, false);				
			FramePtr->AddFrameSlicePtr(SlicePtr);

			SlicePtr->SetSliceCameraID(CameraID);
			SlicePtr->SetSliceIndex(CameraFrameIdx);
			SlicePtr->SetSliceLightMode(LIGHT_MODE_A);
			SlicePtr->SetSliceLight3DCastID(LIGHT_3D_CAST_00);
			SlicePtr->SetSliceGainValue(SliceGainValue);
			SlicePtr->SetSliceCameraFrameIndex(CameraFrameIdx);
			SlicePtr->SetSliceCameraFrameRect(FieldRect);
			SlicePtr->SetSliceFillState(SLICE_FILL_NONE);
			SlicePtr->SetSliceStagePos(FovPos);
			CameraFrameIdx ++;
		}
	}
	else if ( FRAME_SPACE == FrameParamPtr->FrameType )
	{
		size_t TriggerCount = 0;
		SLICE_FUNC_MODE SliceFuncMode;		
		LIGHT_3D_CAST_ID Light3DCastID = LIGHT_3D_CAST_00;
		FramePtr->SetFrameType(FRAME_SPACE);
		if ( SLICE_UNIQUE_ID_NULL != FrameParamPtr->FrameSliceID1 )
		{
			SliceIndex = FrameParamPtr->FrameSliceIdx1;
			SliceParamPtr = AOIDataCollect.GetSystemSliceParamPtr(SliceIndex, true);
			if ( NULL == SliceParamPtr )
			{	
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Get Slice Param Ptr Fault");
				return false;
			}
			if ( SliceParamPtr->SliceUniqueID != FrameParamPtr->FrameSliceID1 )
			{
				ClearProjectAllTempObjects();
				this->m_ErrorString = _T("Error, Slice Param ID1 Exception");
				return false;
			}
			CameraID = SliceParamPtr->SliceCameraID;
			SliceGainValue = SliceParamPtr->SliceGainValue;
			SliceFuncMode = SliceParamPtr->SliceFuncMode;				
			FramePtr->SetFrameSliceFuncMode(SliceFuncMode);
			Frame3DExpCnt = AOIDataCollect.CheckFrameExpCountBySliceFuncMode(SliceFuncMode);
			Frame3DLightCnt = AOIDataCollect.CheckFrameLightCountBySliceFuncMode(SliceFuncMode);
			const bool bSepareDLP2ExpTable = AOIDataCollect.CheckUseSeparateDLP2ExpTable(SliceFuncMode);
			if ( false == bSepareDLP2ExpTable )
			{
				size_t n=0;
				for ( n=0; n<Frame3DLightCnt; n++ )
				{
					for ( j=0; j<DLP_CAST_COUNT; j++ )
					{
						if ( FN_DISABLE == SliceParamPtr->SliceLightTable.DLPCast[j].OnOffState ) { continue; }
						Light3DCastID = CLight3DCtrl::GetLight3DCastIDByIndex(j);
						if ( LIGHT_3D_CAST_00 == Light3DCastID ) { continue; }
						for ( k=0; k<SliceParamPtr->SliceLightTable.DLPCast[j].TriggerCount; k++ )
						{
							SlicePtr = AOIObjManager.CreateSliceObj();
							if ( NULL == SlicePtr )
							{	
								this->m_ErrorString = _T("Error, Create AOI Slice Obj Fault");
								return false;
							}					
							this->AddProjectTempSlicePtr(SlicePtr, false);				
							FramePtr->AddFrameSlicePtr(SlicePtr);				
							SlicePtr->SetSliceCameraID(CameraID);
							SlicePtr->SetSliceIndex(CameraFrameIdx);
							SlicePtr->SetSliceLightMode(LIGHT_MODE_A);
							SlicePtr->SetSliceLight3DCastID(Light3DCastID);
							SlicePtr->SetSliceGainValue(SliceGainValue);
							SlicePtr->SetSliceCameraFrameIndex(CameraFrameIdx);
							SlicePtr->SetSliceCameraFrameRect(FieldRect);
							SlicePtr->SetSliceFillState(SLICE_FILL_NONE);
							SlicePtr->SetSliceStagePos(FovPos);
							CameraFrameIdx ++;
						}
					}
				}
			}
			else
			{
				//低曝光
				for ( j=0; j<DLP_CAST_COUNT; j++ )
				{
					if ( FN_DISABLE == SliceParamPtr->SliceLightTable.DLPCast[j].OnOffState ) { continue; }
					Light3DCastID = CLight3DCtrl::GetLight3DCastIDByIndex(j);
					if ( LIGHT_3D_CAST_00 == Light3DCastID ) { continue; }
					TriggerCount=SliceParamPtr->SliceLightTable.DLPCast[j].TriggerCount/2;
					for ( k=0; k<TriggerCount; k++ )
					{
						SlicePtr = AOIObjManager.CreateSliceObj();
						if ( NULL == SlicePtr )
						{	
							this->m_ErrorString = _T("Error, Create AOI Slice Obj Fault");
							return false;
						}					
						this->AddProjectTempSlicePtr(SlicePtr, false);				
						FramePtr->AddFrameSlicePtr(SlicePtr);				
						SlicePtr->SetSliceCameraID(CameraID);
						SlicePtr->SetSliceIndex(CameraFrameIdx);
						SlicePtr->SetSliceLightMode(LIGHT_MODE_A);
						SlicePtr->SetSliceLight3DCastID(Light3DCastID);
						SlicePtr->SetSliceGainValue(SliceGainValue);
						SlicePtr->SetSliceCameraFrameIndex(CameraFrameIdx);
						SlicePtr->SetSliceCameraFrameRect(FieldRect);
						SlicePtr->SetSliceFillState(SLICE_FILL_NONE);
						SlicePtr->SetSliceStagePos(FovPos);
						CameraFrameIdx ++;
					}
				}	
				//高曝光
				for ( j=0; j<DLP_CAST_COUNT; j++ )
				{
					if ( FN_DISABLE == SliceParamPtr->SliceLightTable.DLPCast[j].OnOffState ) { continue; }
					Light3DCastID = CLight3DCtrl::GetLight3DCastIDByIndex(j);
					if ( LIGHT_3D_CAST_00 == Light3DCastID ) { continue; }
					TriggerCount=SliceParamPtr->SliceLightTable.DLPCast[j].TriggerCount/2;
					for ( k=0; k<TriggerCount; k++ )
					{
						SlicePtr = AOIObjManager.CreateSliceObj();
						if ( NULL == SlicePtr )
						{	
							this->m_ErrorString = _T("Error, Create AOI Slice Obj Fault");
							return false;
						}					
						this->AddProjectTempSlicePtr(SlicePtr, false);				
						FramePtr->AddFrameSlicePtr(SlicePtr);				
						SlicePtr->SetSliceCameraID(CameraID);
						SlicePtr->SetSliceIndex(CameraFrameIdx);
						SlicePtr->SetSliceLightMode(LIGHT_MODE_A);
						SlicePtr->SetSliceLight3DCastID(Light3DCastID);
						SlicePtr->SetSliceGainValue(SliceGainValue);
						SlicePtr->SetSliceCameraFrameIndex(CameraFrameIdx);
						SlicePtr->SetSliceCameraFrameRect(FieldRect);
						SlicePtr->SetSliceFillState(SLICE_FILL_NONE);
						SlicePtr->SetSliceStagePos(FovPos);
						CameraFrameIdx ++;
					}
				}
			}
		}
	}
	return FramePtr;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CheckProjectFdResult_Panel(bool OfflineMode)//確認專案的定位點結果-整板
{
	//return true;
	CString      str;
	size_t       i=0, j=0, k=0;	
	size_t       PanelFdCount=0;
	size_t       FdNGSkipCount=0;
	size_t       PanelFdDefectCount=0;
	TPOINT3D     StagePos;
	TREGION4D    StageRgn;
	INT_PTR      UIResultID=0;
	DISTRICT_ID  DistrictID;
	RESULT_ID    ResultID=RESULT_ID_NONE;
	RESULT_ID    PanelResultID=RESULT_ID_NONE;
	CAOIFd      *FdPtr = NULL;		
	CAOIPanel   *PanelPtr = NULL;		
	CAOIBoard   *BoardPtr = NULL;	
	const LANE_ID LaneID = GetProjectActLaneID();
	const size_t FdCount = GetProjectFdCount();
	const size_t PanelCount = GetProjectPanelCount();	
	const DISTRICT_ID ProjectDistrictID = GetProjectActDistrictID();
	const size_t PanelFdNGSkipCount = GetProjectParameter().m_PanelFdNGSkipCount;	
	FD_NG_HANDLE_MODE PanelFdNGHandleMode = GetProjectParameter().m_PanelFdNGHandleMode;	
	DEFECT_HANDLE_MODE DefectHandleMode = GetProjectParameter().m_DefectHandleMode;
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		if ( PanelPtr->GetPanelBypassed() == true ) { continue; }
		PanelFdCount = PanelPtr->CalcPanelFdCount(ProjectDistrictID);
		if ( 0 == PanelFdCount ) { continue; }

		PanelResultID=PanelPtr->GetPanelResultID();
		if ( FD_NG_HANDLE_XBOARD==PanelFdNGHandleMode )
		{
			FdNGSkipCount = MIN(PanelFdCount, PanelFdNGSkipCount);
			PanelFdDefectCount = PanelPtr->CalcPanelFdDefectCount(ProjectDistrictID);			
			if ( PanelFdDefectCount >= FdNGSkipCount )
			{
				PanelResultID = RESULT_ID_SKIP;
				PanelPtr->SetPanelResultID(PanelResultID);	
				PanelPtr->ExecPanelBeXBoard(LaneID);
			}
		}
		if ( true == OfflineMode )
		{	continue; }

		PanelFdCount = PanelPtr->GetPanelFdCount();
		for ( j=0; j<PanelFdCount; j++ )
		{
			FdPtr = PanelPtr->GetPanelFdPtr(j, false);
			if ( NULL == FdPtr ) { continue; }
			BoardPtr = FdPtr->GetFdBoardPtr();
			if ( NULL != BoardPtr ) { continue; }

			DistrictID = FdPtr->GetFdDistrictID();
			if ( DistrictID != ProjectDistrictID ) { continue; }

			ResultID = FdPtr->GetFdResultID_AOI();
			if ( RESULT_ID_OK==ResultID || RESULT_ID_BYPASS == ResultID || RESULT_ID_SKIP==ResultID )
			{ 
				FdPtr->SetFdKeepImage(false);
				FdPtr->ClearRgnImageBuffer();
				continue; 
			}						
			if ( DEFECT_HANDLE_PASS==DefectHandleMode || FD_NG_HANDLE_NONE==PanelFdNGHandleMode )
			{
				FdPtr->SetFdKeepImage(false);
				FdPtr->ClearRgnImageBuffer();
				//FdPtr->SetFdResultID_AOI(RESULT_ID_OK);
				//FdPtr->SetFdResultID_Alarm(RESULT_ID_OK);
				continue;
			}
			if ( FD_NG_HANDLE_PASS==PanelFdNGHandleMode )
			{
				FdPtr->SetFdKeepImage(false);
				FdPtr->ClearRgnImageBuffer();
				FdPtr->SetFdResultID_AOI(RESULT_ID_OK);
				FdPtr->SetFdResultID_Alarm(RESULT_ID_OK);
				SetProjectFdException(true);
				continue;
			}

			StagePos = FdPtr->GetFdStagePos();
			MotionCtrlPtr->XYMoveTo(StagePos.x, StagePos.y);
			FdPtr->SetFdConfirmUIResultID(0);			
			//避免執行緒啟用沒有最上層, 因此改由CMainFrame來創見
			AOIDataCollect.LockUserInput();
			if ( AOIDataCollect.GetIsStopUserInput() == true )
			{ 
				AOIDataCollect.UnlockUserInput();
				return false; 
			}
			AOIDataCollect.SetIsWaitUserInput(true);
			AOIDataCollect.SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_EXEC_FD_CONFIRM_WND , (LPARAM)(FdPtr));			
			UIResultID = FdPtr->GetFdConfirmUIResultID();
			if ( IDCANCEL == UIResultID )
			{	
				m_ErrorString = AOIDataDefine.GetFdText_NG();
				AOIDataCollect.SetIsStopUserInput(true);
				AOIDataCollect.SetIsWaitUserInput(false);
				AOIDataCollect.UnlockUserInput();
				return false;				
			}	
			AOIDataCollect.SetIsWaitUserInput(false);		
			AOIDataCollect.UnlockUserInput();
		}		
	}		
	return true;
}
//-------------------------------------------------------------------------------------//}
bool CAOIProject::CheckProjectFdResult_Board(bool OfflineMode)//確認專案的定位點結果-單板
{
	//return true;
	CString      str;
	size_t       i=0, j=0, k=0;
	size_t       BoardFdCount=0;
	size_t       FdNGSkipCount=0;
	size_t       BoardFdDefectCount=0;
	TPOINT3D     StagePos;
	TREGION4D    StageRgn;
	INT_PTR      UIResultID=0;
	DISTRICT_ID  DistrictID;
	RESULT_ID    ResultID=RESULT_ID_NONE;
	RESULT_ID    BoardResultID=RESULT_ID_NONE;
	CAOIFd      *FdPtr = NULL;	
	CAOIBoard   *BoardPtr = NULL;	
	const LANE_ID LaneID = GetProjectActLaneID();
	const size_t FdCount = GetProjectFdCount();
	const size_t BoardCount = GetProjectBoardCount();	
	const DISTRICT_ID ProjectDistrictID = GetProjectActDistrictID();
	const size_t BoardFdNGSkipCount = GetProjectParameter().m_BoardFdNGSkipCount;	
	FD_NG_HANDLE_MODE FdNGHandleMode = GetProjectParameter().m_BoardFdNGHandleMode;		
	DEFECT_HANDLE_MODE DefectHandleMode = GetProjectParameter().m_DefectHandleMode;
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
		if ( BoardPtr->CheckBoardBypassedSkipped() == true ) { continue; }
		BoardFdCount = BoardPtr->CalcBoardFdCount(ProjectDistrictID);
		if ( 0 == BoardFdCount ) { continue; }

		BoardResultID=BoardPtr->GetBoardResultID();
		if ( FD_NG_HANDLE_XBOARD==FdNGHandleMode )
		{
			FdNGSkipCount = MIN(BoardFdCount, BoardFdNGSkipCount);
			BoardFdDefectCount = BoardPtr->CalcBoardFdDefectCount(ProjectDistrictID);
			if ( BoardFdDefectCount >= FdNGSkipCount )
			{
				BoardResultID = RESULT_ID_SKIP;
				BoardPtr->SetBoardResultID(BoardResultID);	
				BoardPtr->ExecBoardBeXBoard(LaneID);
			}
		}
		if ( true == OfflineMode )
		{	continue; }

		BoardFdCount = BoardPtr->GetBoardFdCount();
		for ( j=0; j<BoardFdCount; j++ )
		{
			FdPtr = BoardPtr->GetBoardFdPtr(j, false);
			if ( NULL == FdPtr ) { continue; }
			DistrictID = FdPtr->GetFdDistrictID();
			if ( DistrictID != ProjectDistrictID ) { continue; }

			ResultID = FdPtr->GetFdResultID_AOI();
			if ( RESULT_ID_OK==ResultID || RESULT_ID_BYPASS==ResultID || RESULT_ID_SKIP==ResultID )
			{
				FdPtr->SetFdKeepImage(false);
				FdPtr->ClearRgnImageBuffer();
				continue; 
			}	

			if ( FD_NG_HANDLE_NONE==FdNGHandleMode || FD_NG_HANDLE_XBOARD==FdNGHandleMode )
			{
				FdPtr->SetFdKeepImage(false);
				FdPtr->ClearRgnImageBuffer();				
				continue;
			}

			if ( DEFECT_HANDLE_PASS==DefectHandleMode )
			{
				FdPtr->SetFdKeepImage(false);
				FdPtr->ClearRgnImageBuffer();
				FdPtr->SetFdResultID_AOI(RESULT_ID_OK);
				FdPtr->SetFdResultID_Alarm(RESULT_ID_OK);
				continue;
			}

			if ( FD_NG_HANDLE_PASS == FdNGHandleMode )
			{
				FdPtr->SetFdKeepImage(false);
				FdPtr->ClearRgnImageBuffer();
				FdPtr->SetFdResultID_AOI(RESULT_ID_OK);
				FdPtr->SetFdResultID_Alarm(RESULT_ID_OK);
				SetProjectFdException(true);
				continue;
			}

			StagePos = FdPtr->GetFdStagePos();
			MotionCtrlPtr->XYMoveTo(StagePos.x, StagePos.y);			

			FdPtr->SetFdConfirmUIResultID(0);
			//避免執行緒啟用沒有最上層, 因此改由CMainFrame來創見
			AOIDataCollect.LockUserInput();
			if ( AOIDataCollect.GetIsStopUserInput() == true )
			{ 
				AOIDataCollect.UnlockUserInput();
				return false; 
			}
			AOIDataCollect.SetIsWaitUserInput(true);
			AOIDataCollect.SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_EXEC_FD_CONFIRM_WND , (LPARAM)(FdPtr));			
			UIResultID = FdPtr->GetFdConfirmUIResultID();
			if ( IDCANCEL == UIResultID )
			{	
				m_ErrorString = AOIDataDefine.GetFdText_NG();
				AOIDataCollect.SetIsStopUserInput(true);
				AOIDataCollect.SetIsWaitUserInput(false);
				AOIDataCollect.UnlockUserInput();
				return false;
			}
			AOIDataCollect.SetIsWaitUserInput(false);		
			AOIDataCollect.UnlockUserInput();
		}		
	}	
	return true;
}
