{
	CString OfflineFolder = GetProjectProgramOfflineFolder();
	if ( SetProjectProgramFrameFileName(OfflineFolder) == false )	
	{	return false;	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SetProjectProgramFrameFileName(LPCTSTR Folder)
{
	size_t       i=0, j=0;	
	size_t       FrameIndex=0;
	size_t       OldFrameIndex=0;
	size_t       FieldFrameCount = 0;
	CString      FileName;
	CString      OldFileName, OldFileFolder;
	DISTRICT_ID  DistrictID;
	CAOIFrame   *FramePtr = NULL;
	CAOIField   *FieldPtr = NULL;	
	FRAME_TYPE   FrameType = FRAME_NULL;	
	unsigned int FrameIdx[DISTRICT_ID_RETURN];
	const size_t FieldCount = GetProjectProgramFieldCount();
	
	FrameIndex = 0;
	::memset(FrameIdx, 0x00, sizeof(FrameIdx));
	SetProjectProgramOfflineFolder(Folder);
	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = GetProjectProgramFieldPtr(i, false);
		if ( NULL == FieldPtr ) { continue; }
		DistrictID = FieldPtr->GetFieldDistrictID();
		FieldFrameCount = FieldPtr->GetFieldFramePtrCount();
		for ( j=0; j<FieldFrameCount; j++ )
		{
			FramePtr = FieldPtr->GetFieldFramePtr(j, false);
			if ( NULL == FramePtr ) { continue; }

			FrameIndex = FrameIdx[DistrictID];
			FrameType = FramePtr->GetFrameType();
			FileName = AOIDataDefine.GetFrameShortName(FrameIndex, FrameType, false, DistrictID);
		#ifdef _DEBUG
			OldFrameIndex = FramePtr->GetFrameIndexOffline();
			OldFileName = FramePtr->GetFrameFileNameOffline();
			OldFileFolder = FramePtr->GetFrameFileFolderOffline();
			if ( OldFileFolder!=Folder || OldFileName!=FileName || OldFrameIndex!=FrameIndex )
			{	i = i;	}
		#endif//_DEBUG		

			FramePtr->SetFrameIndex(FrameIndex);
			FramePtr->SetFrameFileFolder(Folder);
			FramePtr->SetFrameFileName(FileName);
			FrameIdx[DistrictID] ++;
		}
	}	
	return true;
}
