//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectOfflineFdFile(LPCTSTR pfilename)//儲存專案定位點資料-整板
{
	LARGE_INTEGER fnStart, fnEnd;
	JetAPI::SetFuncTimeStart(fnStart);
	const bool bSucc=SaveProjectOfflineFdFileFn(pfilename);
	JetAPI::SetFuncTimeStart(fnEnd);
	const double Time=JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	if ( false == bSucc )
	{	SetProjectExceptionCode_FileWrite();	}

	CString str;
	str.Format(_T("CAOIProject::SaveProjectOfflineFdFile(Time=%.3f ms)"), Time);	
	AOIDataCollect.SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);	
	return bSucc;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectOfflineFdFileFn(LPCTSTR pfilename)//儲存專案定位點資料-整板
{
	if ( NULL == pfilename ) { return false; }
	CString filename = pfilename;	
	::DeleteFile(filename);
	::Sleep(0);

	size_t       i=0;	
	RESULT_ID    ResultID;
	size_t       FdRealCount=0;
	unsigned int FdUniqueID=0;
	unsigned int BoardIndex=0;
	unsigned int PanelIndex=0;
	double       SpaceBasePlane=0.0;
	double       CadPosX=0, CadPosY=0;
	double       StagePosX=0, StagePosY=0, StagePosZ=0;
	CAOIFd      *FdPtr = NULL;
	CString      Key;
	CString      String;
	CString      Section;	
	CString      FileName;	
	CJetIniFile *pIniFile = GetProjectIniFilePtr();
	const size_t FdCount = GetProjectFdCount();
	DISTRICT_ID  DistrictID = GetProjectActDistrictID();

	if ( NULL != pIniFile )
	{	pIniFile->Initial();	}

	FdRealCount=0;
	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		if ( DistrictID != FdPtr->GetFdDistrictID() ) { continue; }
		FdRealCount ++;
	}

	SetProjectOfflineFdFilename(filename);
	Section = _T("Fiducial Info");
	Key = _T("Fiducial Count");
	String.Format(_T("%d"), FdRealCount);
	if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
	{	return false; }

	Key = _T("Board Fd Grab Mode");
	String.Format(_T("%d"), GetProjectParameter().m_BoardFdGrabMode);
	if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
	{	return false; }

	for ( i=0; i<FdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		if ( DistrictID != FdPtr->GetFdDistrictID() ) { continue; }

		FdUniqueID=FdPtr->GetFdUniqueID();
		PanelIndex = FdPtr->GetFdPanelIndex_Project();
		BoardIndex = FdPtr->GetFdBoardIndex_Project();
		
		CadPosX = FdPtr->GetFdCadPosX();
		CadPosY = FdPtr->GetFdCadPosY();
		StagePosX = FdPtr->GetFdStagePosX();
		StagePosY = FdPtr->GetFdStagePosY();
		StagePosZ = FdPtr->GetFdStagePosZ();
		ResultID = FdPtr->GetFdResultID_AOI();
		SpaceBasePlane = FdPtr->GetFdSpaceBasePlane();

		Section = AOIDataDefine.GetFdSectionText(i);

		Key = _T("Fd Unique ID");
		String.Format(_T("%d"), FdUniqueID+1);
		if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
		{	return false; }

		Key = _T("Panel Index");
		String.Format(_T("%d"), PanelIndex+1);
		if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
		{	return false; }

		Key = _T("Board Index");
		String.Format(_T("%d"), BoardIndex+1);
		if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
		{	return false; }

		Key = _T("Cad Pos X");
		String.Format(_T("%.16f"), CadPosX);
		if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
		{	return false; }

		Key = _T("Cad Pos Y");
		String.Format(_T("%.16f"), CadPosY);
		if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
		{	return false; }

		Key = _T("Stage Pos X");
		String.Format(_T("%.16f"), StagePosX);
		if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
		{	return false; }

		Key = _T("Stage Pos Y");
		String.Format(_T("%.16f"), StagePosY);
		if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
		{	return false; }

		Key = _T("Base Plane");
		String.Format(_T("%.16f"), SpaceBasePlane);
		if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
		{	return false; }

		Key = _T("Result ID");
		switch ( ResultID )
		{		
		default:				String.Format(_T("%d"), ResultID);	break;
		case RESULT_ID_SKIP:	String.Format(_T("%d"), RESULT_ID_NG);	break;
		case RESULT_ID_NONE:	String.Format(_T("%d"), RESULT_ID_OK);	break;
		}		
		if ( SaveINIData(Section, Key, String, filename, m_ErrorString, pIniFile) == false )
		{	return false; }
	}	

	if ( SaveProjectIniFile(filename, pIniFile) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectOfflineFdFile(LPCTSTR pfilename)//載入專案定位點資料-整板
{
	if ( LoadProjectOfflineFdFileFn(pfilename) == false )
	{	
		SetProjectExceptionCode_FileRead();	
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectOfflineFdFileFn(LPCTSTR pfilename)//載入專案定位點資料-整板
{	
	if ( NULL == pfilename ) { return false; }
	CString filename = pfilename;	

	size_t       i=0;	
	RESULT_ID    ResultID;
	size_t       FdCount=0;
	unsigned int FdIndex=0;
	unsigned int UniqueID=0;
	unsigned int FdUniqueID=0;
	unsigned int BoardIndex=0;
	unsigned int PanelIndex=0;
	unsigned int FdBoardIndex=0;
	unsigned int FdPanelIndex=0;
	double       SpaceBasePlane=0;
	double       CadDifX=0, CadDifY=0;
	double       CadPosX=0, CadPosY=0;
	double       FdCadPosX=0, FdCadPosY=0;
	double       StagePosX=0, StagePosY=0, StagePosZ=0;
	double       FdStagePosX=0, FdStagePosY=0, FdStagePosZ=0;
	CAOIFd      *FdPtr = NULL;
	CString      Key;
	CString      Default;
	CString      Section;
	CString      FileName, PathName;		
	const int    textlen = 256;
	const bool   OfflinMode=true;
	TCHAR        String[textlen] = _T("");
	DISTRICT_ID  DistrictID = GetProjectActDistrictID();
	const size_t ProjectFdCount = GetProjectFdCount();
	TObjPos      FdPos;
	std::vector<TObjPos> FdPosList(ProjectFdCount);
	LANE_ID LaneID = GetProjectActLaneID();
	FD_NG_HANDLE_MODE PanelFdNGHandleMode = GetProjectParameter().m_PanelFdNGHandleMode;	
	FD_NG_HANDLE_MODE BoardFdNGHandleMode = GetProjectParameter().m_BoardFdNGHandleMode;	

	SetProjectOfflineFdFilename(filename);
	Section = _T("Fiducial Info");
	Key = _T("Fiducial Count");
	Default.Format(_T("%d"), 0);
	if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
	{	return false; }
	FdCount = ::_ttoi(String);	
	//if ( ProjectFdCount != FdCount ) 
	//{
	//	m_ErrorString.Format(_T("Error, Read Offline Fiducial Count Fault[%u/%u]"), FdCount, ProjectFdCount);
	//	return true; 
	//}	
	
	Key = _T("Board Fd Grab Mode");
	Default.Format(_T("%d"), GetProjectParameter().m_BoardFdGrabMode);
	if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
	{	return false; }
	BOARD_FD_GRAB_MODE BoardFdGrabMode = (BOARD_FD_GRAB_MODE)(::_ttoi(String));	

	FdPosList.clear();
	//先找所有整板的定位點
	for ( i=0; i<ProjectFdCount; i++ )
	{
		FdPtr = GetProjectFdPtr(i, false);
		if ( NULL == FdPtr ) { continue; }
		if ( DistrictID != FdPtr->GetFdDistrictID() ) { continue; }

		FdUniqueID=FdPtr->GetFdUniqueID();
		FdPanelIndex=FdPtr->GetFdPanelIndex_Project();
		FdBoardIndex=FdPtr->GetFdBoardIndex_Project();
		
		FdCadPosX = FdPtr->GetFdCadPosX();
		FdCadPosY = FdPtr->GetFdCadPosY();
		FdStagePosX = FdPtr->GetFdStagePosX();
		FdStagePosY = FdPtr->GetFdStagePosY();
		FdStagePosZ = FdPtr->GetFdStagePosZ();		
		SpaceBasePlane = FdPtr->GetFdSpaceBasePlane();

		//確認Offline有讀到定位點資料
		ResultID = RESULT_ID_OK;//為了與舊的定位點檔案相容
		FdPtr->SetFdResultID_AOI(RESULT_ID_NONE);		
		Section = AOIDataDefine.GetFdSectionText(i);

		Key = _T("Fd Unique ID");
		Default.Format(_T("%d"), 0);
		if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
		{	return false; }
		UniqueID = ::_ttoi(String)-1;
		if ( UniqueID != FdUniqueID )
		{	continue;	}

		Key = _T("Panel Index");
		Default.Format(_T("%d"), 0);
		if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
		{	return false; }
		PanelIndex = ::_ttoi(String)-1;

		Key = _T("Board Index");
		Default.Format(_T("%d"), 0);
		if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
		{	return false; }
		BoardIndex = ::_ttoi(String)-1;

		Key = _T("Cad Pos X");
		Default.Format(_T("%.16f"), FdCadPosX);
		if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
		{	return false; }
		CadPosX = ::_tcstod(String, NULL);

		Key = _T("Cad Pos Y");
		Default.Format(_T("%.16f"), FdCadPosY);
		if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
		{	return false; }
		CadPosY = ::_tcstod(String, NULL);

		Key = _T("Stage Pos X");
		Default.Format(_T("%.16f"), FdStagePosX);
		if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
		{	return false; }
		StagePosX = ::_tcstod(String, NULL);

		Key = _T("Stage Pos Y");
		Default.Format(_T("%.16f"), FdStagePosY);
		if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
		{	return false; }
		StagePosY = ::_tcstod(String, NULL);

		Key = _T("Base Plane");
		Default.Format(_T("%.16f"), SpaceBasePlane);
		if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
		{	return false; }
		SpaceBasePlane = ::_tcstod(String, NULL);

		Key = _T("Result ID");
		Default.Format(_T("%d"), ResultID);
		if ( LoadINIData(Section, Key, Default, String, textlen, filename, false, m_ErrorString) == false )
		{	return false; }
		ResultID = (RESULT_ID)(::_ttoi(String));	

		if ( FdPanelIndex!=PanelIndex || FdBoardIndex!=BoardIndex )
		{	continue;	}
		
		CadDifX = FdCadPosX-CadPosX;
		CadDifY = FdCadPosY-CadPosY;
		//FdPtr->SetFdCadPosX(CadPosX);
		//FdPtr->SetFdCadPosY(CadPosY);
		FdPtr->SetFdResultID_AOI(ResultID);
		FdPtr->SetFdSpaceBasePlane(SpaceBasePlane);		
		if ( fabs(CadDifX)<10 && fabs(CadDifY)<10 ) 
		{
			FdPtr->SetFdStagePosX(StagePosX);
			FdPtr->SetFdStagePosY(StagePosY);
			FdPtr->SetFdStagePosZ(StagePosZ);			
			FdPtr->LayoutFdStageCornerPos();
		}		
		
		FdPos.ObjType = AOI_OBJ_FD;
		FdPos.UniqueID = UniqueID;
		FdPos.FdIndex = (unsigned int)(i);
		FdPos.PanelIndex = PanelIndex;
		FdPos.BoardIndex = BoardIndex;
		FdPos.FdPtr = FdPtr;
		FdPos.CadPosX = CadPosX;
		FdPos.CadPosY = CadPosY;
		FdPos.StagePosX = StagePosX;
		FdPos.StagePosY = StagePosY;
		FdPos.StagePosZ = StagePosZ;
		FdPos.BasePlane = SpaceBasePlane;
		FdPos.ResultID = ResultID;
		FdPosList.push_back(FdPos);
	}
	if ( FD_NG_HANDLE_XBOARD == PanelFdNGHandleMode )
	{	CheckProjectFdResult_Panel(OfflinMode);	}	
	CalcProjectStagePosition_Panel();

	//再找所有單板的定位點
	bool bGetBoardFd=false;
	const size_t FdPosCount = FdPosList.size();	
	for ( i=0; i<FdPosCount; i++ )
	{
		FdPos = FdPosList[i];
		FdIndex = FdPos.FdIndex;
		if ( FdIndex >= ProjectFdCount ) { continue; }

		PanelIndex = FdPos.PanelIndex;
		BoardIndex = FdPos.BoardIndex;		
		if ( -1==BoardIndex ) { continue; }

		CadPosX = FdPos.CadPosX;
		CadPosY = FdPos.CadPosY;
		StagePosX = FdPos.StagePosX;
		StagePosY = FdPos.StagePosY;
		StagePosZ = FdPos.StagePosZ;

		FdPtr = GetProjectFdPtr(FdIndex, true);
		if ( NULL == FdPtr ) { continue; }

		FdCadPosX = FdPtr->GetFdCadPosX();
		FdCadPosY = FdPtr->GetFdCadPosY();
		FdStagePosX = FdPtr->GetFdStagePosX();
		FdStagePosY = FdPtr->GetFdStagePosY();
		FdStagePosZ = FdPtr->GetFdStagePosZ();

		CadDifX = FdCadPosX-CadPosX;
		CadDifY = FdCadPosY-CadPosY;
		//FdPtr->SetFdCadPosX(CadPosX);
		//FdPtr->SetFdCadPosY(CadPosY);
		FdPtr->SetFdResultID_AOI(FdPos.ResultID);
		if ( fabs(CadDifX)<10 && fabs(CadDifY)<10 ) 
		{
			bGetBoardFd = true;
			FdPtr->SetFdStagePosX(StagePosX);
			FdPtr->SetFdStagePosY(StagePosY);
			FdPtr->SetFdStagePosZ(StagePosZ);
			FdPtr->LayoutFdStageCornerPos();
		}				
	}	
	if ( true == bGetBoardFd ) 
	{
		if ( FD_NG_HANDLE_XBOARD == BoardFdNGHandleMode )
		{	CheckProjectFdResult_Board(OfflinMode);	}
		bool bCalcFov=false;
		switch ( BoardFdGrabMode )
		{
		case BOARD_FD_GRAB_INSPECTING: bCalcFov = false;	break;
		default:
		case BOARD_FD_GRAB_AFTER_PANEL: bCalcFov = true;	break;			
		}
		CalcProjectStagePosition_Board(bCalcFov);	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectOfflineFdFileToInspection(LPCTSTR pfilename)//備份專案定位點資料-整板
{
	//複製一份至檢測離線資料夾	
	CString OfflineFolder = GetProjectInspectionOfflineFolder();	
	CString OfflineFdFilename = AOIDataDefine.GetProjectOfflineFdName(OfflineFolder, DISTRICT_ID_A);	
	::CreateDirectory(OfflineFolder, NULL);
	::CopyFile(pfilename, OfflineFdFilename, FALSE);
	if ( GetProjectMultiDistrictMode() == true )
	{
		CString FileFolder, FdFilename;
		JetAPI::ExtractFolder(pfilename, FileFolder);
		FdFilename = AOIDataDefine.GetProjectOfflineFdName(FileFolder, DISTRICT_ID_B);		
		OfflineFdFilename = AOIDataDefine.GetProjectOfflineFdName(OfflineFolder, DISTRICT_ID_B);
		::CopyFile(FdFilename, OfflineFdFilename, FALSE);	
	}
	return true;
}
