//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectProgramOfflineFile(LPCTSTR pfilename)//儲存編程離線檔案
{
	if ( SaveProjectProgramOfflineFileFn(pfilename) == false )
	{
		SetProjectExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectProgramOfflineFileFn(LPCTSTR pfilename)//儲存編程離線檔案		
{
	CAOIFileIO FileIO;	
	CString    TempFileName;
	FileIO.SetFileName(pfilename);
	FileIO.SetFileTarget(FILE_TARGET_OFFLINE);

	::DeleteFile(pfilename);
	::Sleep(0);	
	TempFileName.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("OfflineTemp.TXT"));
	if ( FileIO.OpenSaveFile(TempFileName) == false )
	{	
		m_ErrorString = FileIO.GetErrorString();
		return false; 
	}

	if ( CAOIProject::WriteProjectProgramOfflineFile(FileIO) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		return false;
	}	
	FileIO.CloseFile();
	::Sleep(0);
	SetProjectProgramOfflinename(pfilename);
	::CopyFile(TempFileName, pfilename, FALSE);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::WriteProjectProgramOfflineFile(CAOIFileIO &FileIO)//寫入檢測離線檔案
{
	size_t  i=0, j=0, ID=0;
	size_t  PanelIndex=0;
	size_t  FieldIndex=0;
	size_t  FrameIndex=0;
	size_t  FrameCount = 0;
	size_t  FieldFrameCount = 0;
	unsigned int FrameUniqueID=0;
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;;	
	CString    FileName;	
	CAOIFrame *FramePtr = NULL;
	CAOIField *FieldPtr = NULL;	
	FRAME_TYPE FrameType = FRAME_NULL;
	double CadPosX=0, CadPosY=0;
	double StagePosX=0, StagePosY=0;
	double FovWReal = 0;
	double FovHReal = 0;
	double FovWInner = 0;
	double FovHInner = 0;
	double FovWOuter = 0;
	double FovHOuter = 0;	
	TPOINT2D TestStartPos;
	FIELD_SIZE_MODE FieldSizeModeW = GetProjectFieldSizeModeW();
	FIELD_SIZE_MODE FieldSizeModeH = GetProjectFieldSizeModeH();
	const int ResolutionMode = AOIDataCollect.GetFovResolutionMode();
	const IMAGE_SIZE ImageW  = AOIDataCollect.GetCameraImageW(CameraID);
	const IMAGE_SIZE ImageH  = AOIDataCollect.GetCameraImageH(CameraID);
	const size_t FieldCount  = GetProjectProgramFieldCount();
	const double ResolutionX = AOIDataCollect.GetCameraResolutionX(CameraID);
	const double ResolutionY = AOIDataCollect.GetCameraResolutionY(CameraID);
	const size_t FrameUniqueIDCount = GetProjectFrameUniqueIDCount();
	const double FocusOffsetZ = GetProjectProgramOfflineFocusOffsetZ();
	AOIDataCollect.GetFovSizeReal(FovWReal, FovHReal);
	AOIDataCollect.GetFovSizeInner(FovWInner, FovHInner);
	AOIDataCollect.GetFovSizeOuter(FovWOuter, FovHOuter);	
	GetProjectProgramOfflineStartPos(TestStartPos);
	
	//ModifyProjectFieldSize(FovWInner, FovHInner);
	
	FrameCount = 0;//Count Frame Number
	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = GetProjectProgramFieldPtr(i, false);
		if ( NULL == FieldPtr ) { continue; }
		FieldFrameCount = FieldPtr->GetFieldFramePtrCount();
		FrameCount += FieldFrameCount;
	}	
	
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_START, 0) == false ) {	return false; }

	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FILE_MODE, OFFLINE_FILE_PROGRAM) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FIELD_BUILD_MODE, FIELD_BUILD_MATRIX) == false ) {	return false; }

	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_TEST_START_X, TestStartPos.x) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_TEST_START_Y, TestStartPos.y) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOCUS_OFFSET_Z, FocusOffsetZ) == false ) {	return false; }	
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_IMAGE_SCOPE, OFFLINE_IMAGE_FOV) == false ) {	return false; }	

	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_RESOLUTION_MODE, ResolutionMode) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_FULL_W, FovWReal) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_FULL_H, FovHReal) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_INNER_W, FovWInner) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_INNER_H, FovHInner) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_OUTTER_W, FovWOuter) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_OUTTER_H, FovHOuter) == false ) {	return false; }
	//if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FOV_SIZE_MODE_W, FieldSizeModeW) == false ) {	return false; }
	//if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FOV_SIZE_MODE_H, FieldSizeModeH) == false ) {	return false; }	

	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FIELD_COUNT, FieldCount) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FRAME_COUNT, FrameCount) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FIELD_BUILD_AREA_MODE, FIELD_BUILD_AREA_COMPONENT) == false ) {	return false; }	
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_LANE_ID, GetProjectActLaneID()) == false ) {	return false; }		

	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FRAME_UNIQUE_ID_COUNT, FrameUniqueIDCount) == false ) {	return false; }
	for ( i=0; i<FrameUniqueIDCount; i++ )
	{
		FrameUniqueID = GetProjectFrameUniqueID(i, false);
		if ( FRAME_UNIQUE_ID_NULL == FrameUniqueID ) { continue; }
		switch ( i )
		{
		case 0:
		case 1:
		case 2:
		case 3:
		case 4:
		case 5:
		case 6:
		case 7:
		case 8:
			if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FRAME_UNIQUE_ID_01+i, FrameUniqueID) == false )
			{	return false; }
			break;
		}		
	}
	
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_CAMERA_INFO_1, CameraID) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_CAMERA_START, 0) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_CAMERA_IMAGE_SIZE_W, ImageW) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_CAMERA_IMAGE_SIZE_H, ImageH) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_CAMERA_RESOLUTION_X, ResolutionX) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_CAMERA_RESOLUTION_Y, ResolutionY) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_CAMERA_END, 0) == false ) {	return false; }

	if ( FileIO.SaveChunk_INT(FILE_IO_PROGRAM_FIELD_SECTION_START, 0) == false ) {	return false; }
	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = GetProjectProgramFieldPtr(i, false);
		if ( NULL == FieldPtr ) { continue; }
		if ( FieldPtr->WriteFieldFile(FileIO) == false )
		{	return false;	}		
	}
	if ( FileIO.SaveChunk_INT(FILE_IO_PROGRAM_FIELD_SECTION_END, 0) == false ) {	return false; }

	FrameIndex=0;
	if ( FileIO.SaveChunk_INT(FILE_IO_FRAME_SECTION_START, 0) == false ) {	return false; }
	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = GetProjectProgramFieldPtr(i, false);
		if ( NULL == FieldPtr ) { continue; }

		FieldFrameCount = FieldPtr->GetFieldFramePtrCount();
		for ( j=0; j<FieldFrameCount; j++ )
		{
			FramePtr = FieldPtr->GetFieldFramePtr(j, false);
			if ( NULL == FramePtr ) { continue; }		

			if ( FramePtr->WriteFrameFile(FileIO) == false )
			{	return false;	}			
		}	
	}		
	if ( FileIO.SaveChunk_INT(FILE_IO_FRAME_SECTION_END, 0) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_END, 0) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_END, 0) == false ) { return false; }	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectProgramOfflineFile(LPCTSTR pfilename)//載入編程離線檔案
{
	std::vector<unsigned int> FrameUniqueIDList;
	return LoadProjectProgramOfflineFile(pfilename, FrameUniqueIDList);
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectProgramOfflineFile(LPCTSTR pfilename, std::vector<unsigned int> &FrameUniqueIDList)//載入編程離線檔案
{
	if ( LoadProjectProgramOfflineFileFn(pfilename, FrameUniqueIDList) == false )
	{
		SetProjectExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectProgramOfflineFileFn(LPCTSTR pfilename, std::vector<unsigned int> &FrameUniqueIDList)//載入編程離線檔案		
{
	CAOIFileIO FileIO;
	CString    FileName;
	FileIO.SetFileName(pfilename);
	FileIO.SetFileTarget(FILE_TARGET_OFFLINE);

	FileName.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("OfflineTmp.TXT"));
	::CopyFile(pfilename, FileName, FALSE);	
	if ( FileIO.OpenLoadFile(FileName) == false )
	{
		m_ErrorString = FileIO.GetErrorString();		
		return false;
	}
	if ( ReadProjectProgramOfflineFile(FileIO, FrameUniqueIDList) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		CAOIProject::ClearProjectAllProgramField();	
		return false;
	}	
	FileIO.CloseFile();
	SetProjectProgramOfflinename(pfilename);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ReadProjectProgramOfflineFile(CAOIFileIO &FileIO, std::vector<unsigned int> &FrameUniqueIDList)//讀取編程離線檔案
{
#ifdef _DEBUG
	if ( FileIO.CheckFileMode() == FALSE ) { return false; }
	if ( FileIO.CheckFileOpened() == FALSE ) { return false; }
#endif//_DEBUG

	int        index =0;		
	int        nValue=0;	
	double     dValue = 0;	
	IMAGE_SIZE uValue=0;
	size_t  i=0, ID=0;
	size_t  PanelIndex=0;
	size_t  FieldIndex=0;
	size_t  FrameIndex=0;
	size_t  FieldCount=0;	
	size_t  FrameCount = 0;
	size_t  FieldCount_Read=0;
	size_t  FrameCount_Read=0;
	LANE_ID LaneID = GetProjectActLaneID();
	FIELD_BUILD_MODE   FieldBuildMode=FIELD_BUILD_NONE;
	FIELD_BUILD_AREA_MODE   FieldAreaMode=FIELD_BUILD_AREA_NONE;	
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;	
	FRAME_TYPE FrameType = FRAME_NULL;		
	CString   Folder;	
	TPOINT2D  TestStartPos;
	CString   FileName, PathName;	
	CAOIFrame   *FramePtr = NULL;
	CAOIField   *FieldPtr = NULL;
	CAOIPanel   *PanelPtr = NULL;
	CAOIBoard   *BoardPtr = NULL;
	CAOIProject *ProjectPtr = this;
	IMAGE_SIZE   CameraIndex=0;
	IMAGE_SIZE   CameraImageW[MAX_CAMERA_COUNT]={0};//最多八個相機的影像尺寸-寬度
	IMAGE_SIZE   CameraImageH[MAX_CAMERA_COUNT]={0};//最多八個相機的影像尺寸-高度
	double       CameraResolutionX[MAX_CAMERA_COUNT]={0};//最多八個相機的解析度-X
	double       CameraResolutionY[MAX_CAMERA_COUNT]={0};//最多八個相機的解析度-Y	
	const int ResolutionMode = GetProjectSpaceToGrayRatioMode();
	const IMAGE_SIZE ImageW  = AOIDataCollect.GetCameraImageW(CameraID);
	const IMAGE_SIZE ImageH  = AOIDataCollect.GetCameraImageH(CameraID);

	double FocusOffsetZ=0.0;
	double FovWReal=0, FovHReal=0;
	double FovWInner=0, FovHInner=0;
	double FovWOuter=0, FovHOuter=0;
	double ResolutionX=0, ResolutionY=0;
	double CadPosX=0, CadPosY=0;
	double StagePosX=0, StagePosY=0;	
	unsigned int FrameUniqueID= 0;
	size_t FrameUniqueIDCount = 0;
	
	FrameUniqueIDList.clear();
	FileName = FileIO.GetFileName();
	if ( JetAPI::ExtractFolder(FileName, Folder) == false )
	{
		m_ErrorString.Format(_T("Error, Extract Folder Fault \n[%s]"), FileName);
		FileIO.SetErrorString(m_ErrorString);
		return false;
	}	
	SetProjectOfflineFolder(Folder);
	SetProjectProgramOfflineFolder(Folder);
	AOIDataCollect.GetFovSizeReal(FovWReal, FovHReal);
	AOIDataCollect.GetFovSizeInner(FovWInner, FovHInner);
	AOIDataCollect.GetFovSizeOuter(FovWOuter, FovHOuter);		
	ResolutionX = AOIDataCollect.GetCameraResolutionX(PRIMARY_CAMERA_ID);
	ResolutionY = AOIDataCollect.GetCameraResolutionY(PRIMARY_CAMERA_ID);
	ModifyProjectFieldSize(FovWInner, FovHInner);	

	while ( FileIO.CheckFileEnd()==false )
	{ 	
		if ( FileIO.LoadChunk(index) == false )		
		{	continue; }
		
		switch ( index )
		{
		case FILE_IO_OFFLINE_SECTION_START://離線參數區間-起點		
			break;
		case FILE_IO_OFFLINE_SECTION_END://離線參數區間-終點			
			return true;
			break;		

		case FILE_IO_OFFLINE_START://離線參數區間-起點		
			break;		
		case FILE_IO_OFFLINE_END://離線參數區間-終點	
			SetProjectOfflineImageScope(OFFLINE_IMAGE_FOV);
			SetProjectProgramOfflineStartPos(TestStartPos);
			SetProjectProgramOfflineFocusOffsetZ(FocusOffsetZ);
			if ( FIELD_BUILD_AREA_NONE == FieldAreaMode )
			{	SetProjectFieldBuildAreaMode(FIELD_BUILD_AREA_COMPONENT);	}
			return true;
			break;		
		case FILE_IO_OFFLINE_FILE_MODE://離線參數區間-離線檔案模式		
			nValue = FileIO.GetData_INT();
			if ( OFFLINE_FILE_PROGRAM != nValue ) 
			{
				m_ErrorString.Format(_T("Error, Read Offline File Mode Fault[%d]"), nValue);
				FileIO.SetErrorString(m_ErrorString);
				return true; 
			}
			break;		
		case FILE_IO_OFFLINE_FIELD_BUILD_MODE://離線參數區間-離線檔案模式
			nValue = FileIO.GetData_INT();
			if ( FIELD_BUILD_MATRIX != nValue ) 
			{
				m_ErrorString.Format(_T("Error, Read Offline Field Mode Fault[%d]"), nValue);
				FileIO.SetErrorString(m_ErrorString);
				return true; 
			}
			FieldBuildMode = (FIELD_BUILD_MODE)(nValue);
			SetProjectFieldBuildMode(FieldBuildMode);
			m_ProjectOfflineFileMode = OFFLINE_FILE_PROGRAM;
			break;
		case FILE_IO_OFFLINE_TEST_START_X://離線參數區間-檢測起點-X
			TestStartPos.x = FileIO.GetData_DBL();
			break;
		case FILE_IO_OFFLINE_TEST_START_Y://離線參數區間-檢測起點-Y
			TestStartPos.y = FileIO.GetData_DBL();
			break;
		case FILE_IO_OFFLINE_FOCUS_OFFSET_Z://離線參數區間-焦距偏差-Z
			FocusOffsetZ = FileIO.GetData_DBL();
			break;		
		case FILE_IO_OFFLINE_RESOLUTION_MODE://離線參數區間-解析度模式
			nValue = FileIO.GetData_INT();			
		#ifndef OFFLINE_VERSION	
			if ( ResolutionMode != nValue )
			{
				m_ErrorString.Format(_T("Error, Load Resolution Mode Fault [%d, %d] \n(%s)"), nValue, ResolutionMode, FileName);
				FileIO.SetErrorString(m_ErrorString);
				//return false;
			}
		#else
			AOIDataCollect.SetFovResolutionMode(nValue);
		#endif//OFFLINE_VERSION
			break;		
		case FILE_IO_OFFLINE_FOV_SIZE_FULL_W://離線參數區間-視野-寬-全部					
			FovWReal = FileIO.GetData_DBL();
			break;		
		case FILE_IO_OFFLINE_FOV_SIZE_FULL_H://離線參數區間-視野-長-全部		
			FovHReal = FileIO.GetData_DBL();
			break;				
		case FILE_IO_OFFLINE_FOV_SIZE_INNER_W://離線參數區間-視野-寬-內部		
			FovWInner = FileIO.GetData_DBL();
			break;		
		case FILE_IO_OFFLINE_FOV_SIZE_INNER_H://離線參數區間-視野-長-內部		
			FovHInner = FileIO.GetData_DBL();
			break;
		case FILE_IO_OFFLINE_FOV_SIZE_OUTTER_W://離線參數區間-視野-寬-外部		
			FovWOuter = FileIO.GetData_DBL();
			break;		
		case FILE_IO_OFFLINE_FOV_SIZE_OUTTER_H://離線參數區間-視野-長-外部
			FovHOuter = FileIO.GetData_DBL();
			break;
		case FILE_IO_OFFLINE_FOV_SIZE_MODE_W://離線參數區間-視野-寬-模式
			nValue = (FIELD_SIZE_MODE)(FileIO.GetData_INT());
			//SetProjectFieldSizeModeW(FieldSizeModeW);
			break;
		case FILE_IO_OFFLINE_FOV_SIZE_MODE_H://離線參數區間-視野-長-模式
			nValue = (FIELD_SIZE_MODE)(FileIO.GetData_INT());
			//SetProjectFieldSizeModeW(FieldSizeModeH);
			break;			
		case FILE_IO_OFFLINE_FIELD_COUNT://離線參數區間-區域數量	
			FieldCount = FileIO.GetData_INT();
			break;		
		case FILE_IO_OFFLINE_FRAME_COUNT://離線參數區間-區域影像數量	
			FrameCount = FileIO.GetData_INT();
			break;		
		case FILE_IO_OFFLINE_FIELD_BUILD_AREA_MODE://離線參數區間-離線建立面積模式
			nValue = FileIO.GetData_INT();
			FieldAreaMode = (FIELD_BUILD_AREA_MODE)(nValue);
			SetProjectFieldBuildAreaMode(FieldAreaMode);
			break;
		case FILE_IO_OFFLINE_LANE_ID://離線參數區間-軌道編號
			nValue = FileIO.GetData_INT();
			LaneID = (LANE_ID)(nValue);
			break;
		case FILE_IO_OFFLINE_CAMERA_INFO_1://離線參數區間-相機影像寬度
			CameraIndex = FileIO.GetData_INT();
			break;
		case FILE_IO_CAMERA_START://相機參數-終點
			if ( CameraIndex < MAX_CAMERA_COUNT )
			{
				CameraImageW[CameraIndex] = 0;
				CameraImageH[CameraIndex] = 0;
				CameraResolutionX[CameraIndex] = 1.0;
				CameraResolutionY[CameraIndex] = 1.0;
			}
			break;
		case FILE_IO_CAMERA_END://相機參數-終點
			if ( CameraIndex == CameraID )
			{
				if ( ImageW != CameraImageW[CameraIndex] )
				{
					m_ErrorString.Format(_T("Error, Load ImageW Fault [%d, %d] \n(%s)"), CameraImageW[CameraIndex], ImageW, FileName);
					FileIO.SetErrorString(m_ErrorString);
					return false;
				}
				if ( ImageH != CameraImageH[CameraIndex] )
				{
					m_ErrorString.Format(_T("Error, Load ImageH Fault [%d, %d] \n(%s)"), CameraImageH[CameraIndex], ImageH, FileName);
					FileIO.SetErrorString(m_ErrorString);
					return false;
				}
			}			
			break;
		case FILE_IO_CAMERA_IMAGE_SIZE_W://相機參數-影像寬度
			if ( CameraIndex < MAX_CAMERA_COUNT )
			{	CameraImageW[CameraIndex] = FileIO.GetData_INT();	}
			break;
		case FILE_IO_CAMERA_IMAGE_SIZE_H://相機參數-影像長度
			if ( CameraIndex < MAX_CAMERA_COUNT )
			{	CameraImageH[CameraIndex] = FileIO.GetData_INT();	}
			break;
		case FILE_IO_CAMERA_RESOLUTION_X://相機參數-解析度-X
			if ( CameraIndex < MAX_CAMERA_COUNT )
			{	CameraResolutionX[CameraIndex] = FileIO.GetData_DBL();	}
			break;
		case FILE_IO_CAMERA_RESOLUTION_Y://相機參數-解析度-Y
			if ( CameraIndex < MAX_CAMERA_COUNT )
			{	CameraResolutionY[CameraIndex] = FileIO.GetData_DBL();	}
			break;			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_COUNT://離線參數區間-影像唯一碼數量	
			FrameUniqueIDCount = FileIO.GetData_INT();
			break;		
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_01://離線參數區間-影像唯一碼-1				
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_02://離線參數區間-影像唯一碼-2			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_03://離線參數區間-影像唯一碼-3			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_04://離線參數區間-影像唯一碼-4			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_05://離線參數區間-影像唯一碼-5			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_06://離線參數區間-影像唯一碼-6			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_07://離線參數區間-影像唯一碼-7			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_08://離線參數區間-影像唯一碼-8
			FrameUniqueID = FileIO.GetData_INT();
			if ( FRAME_UNIQUE_ID_NULL != FrameUniqueID )
			{	FrameUniqueIDList.push_back(FrameUniqueID); }			
			break;		
		
		case FILE_IO_PROGRAM_FIELD_SECTION_START://區域參數區間-起點
			FieldCount_Read=0;
			ClearProjectAllProgramField();	
			break;
		case FILE_IO_PROGRAM_FIELD_SECTION_END://區域參數區間-終點
			break;
		case FILE_IO_FIELD_START://區域參數-起點
			FieldPtr = AOIObjManager.CreateFieldObj();
			if ( NULL == FieldPtr )
			{
				m_ErrorString.Format(_T("Error, Create Field Obj Fault [%d]"), FieldCount_Read+1);
				FileIO.SetErrorString(m_ErrorString);
				return false;
			}
			if ( FieldPtr->ReadFieldFile(FileIO) == false )
			{	
				AOIObjManager.DestroyFieldObj(FieldPtr);
				return false;	
			}
			PanelIndex = FieldPtr->GetFieldPanelIndex();
			PanelPtr = CAOIProject::GetProjectPanelPtr(PanelIndex, true);
			if ( NULL != PanelPtr )
			{	PanelPtr->AddPanelFieldPtr(FieldPtr);	}
			//CAOIBoard *BoardPtr = NULL;

			FieldPtr->SetFieldSizeW_Real(FovWReal);
			FieldPtr->SetFieldSizeH_Real(FovHReal);
			FieldPtr->SetFieldSizeW_Inner(FovWInner);
			FieldPtr->SetFieldSizeH_Inner(FovHInner);
			FieldPtr->SetFieldSizeW_Outer(FovWOuter);
			FieldPtr->SetFieldSizeH_Outer(FovHOuter);
			AddProjectProgramFieldPtr(FieldPtr, false);
			FieldCount_Read ++;
			break;
		case FILE_IO_FRAME_SECTION_START://區域影像參數區間-起點
			FrameCount_Read = 0;
			break;
		case FILE_IO_FRAME_SECTION_END://區域影像參數區間-終點
			break;
		case FILE_IO_FRAME_START://區域影像參數-起點
			FramePtr = AOIObjManager.CreateFrameObj();
			if ( NULL == FramePtr )
			{
				m_ErrorString.Format(_T("Error, Create Frame Obj Fault [%d]"), FrameCount_Read+1);
				FileIO.SetErrorString(m_ErrorString);
				return false;
			}
			if ( FramePtr->ReadFrameFile(FileIO) == false )
			{	
				AOIObjManager.DestroyFrameObj(FramePtr);
				return false;
			}
			CameraID = FramePtr->GetFrameCameraID();
			FieldIndex = FramePtr->GetFrameFieldIndex();
			FramePtr->SetFrameIndex(FrameCount_Read);		
			FramePtr->SetFrameIndexOffline(FrameCount_Read);			
			FramePtr->SetFrameResolutionX(CameraResolutionX[CameraID]);
			FramePtr->SetFrameResolutionY(CameraResolutionY[CameraID]);

			FramePtr->SetFrameFileFolder(Folder);			
			FramePtr->SetFrameFileFolderOffline(Folder);
			FieldPtr = GetProjectProgramFieldPtr(FieldIndex, true);
			if ( NULL != FieldPtr )
			{	
				FieldPtr->AddFieldFramePtr(FramePtr);	
				FramePtr->SetFrameLinkPointer(true);
			}
			else
			{	AOIObjManager.DestroyFrameObj(FramePtr);	}
			FrameCount_Read ++;
			break;
		case FILE_IO_END://寫檔結束
			return true;
			break;
		}
	};	
	return true;
}
//-------------------------------------------------------------------------------------//
void CAOIProject::SetProjectInspectionOfflineStartPos(const TPOINT2D &Pos)//離線檢測的檢測位置
{
	m_ProjectInspectionOfflineStartPos = Pos;
}
//-------------------------------------------------------------------------------------//
void CAOIProject::GetProjectInspectionOfflineStartPos(TPOINT2D &Pos) const//離線檢測的檢測位置
{
	Pos = m_ProjectInspectionOfflineStartPos;
}
//-------------------------------------------------------------------------------------//
double CAOIProject::GetProjectInspectionOfflineFocusOffsetZ() const//離線檢測的焦距位置Z
{
	return m_ProjectInspectionOfflineFocusOffsetZ;
}
//-------------------------------------------------------------------------------------//
void CAOIProject::SetProjectInspectionOfflineFocusOffsetZ(double val)//離線檢測的焦距位置Z
{
	m_ProjectInspectionOfflineFocusOffsetZ = val;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectInspectionOfflineFile(LPCTSTR pfilename)//儲存檢測離線檔案
{
	if ( SaveProjectInspectionOfflineFileFn(pfilename, OFFLINE_IMAGE_FOV) == false )
	{
		SetProjectExceptionCode_FileWrite();
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectInspectionOfflineFileFn(LPCTSTR pfilename, OFFLINE_IMAGE_SCOPE Scope)//儲存檢測離線檔案		
{		
	CAOIFileIO FileIO;
	CString    TempFileName;

	FileIO.SetFileName(pfilename);
	FileIO.SetFileTarget(FILE_TARGET_OFFLINE);
	::DeleteFile(pfilename);
	::Sleep(0);
	TempFileName.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("OfflineTemp.TXT"));
	if ( FileIO.OpenSaveFile(TempFileName) == false )
	{	
		m_ErrorString = FileIO.GetErrorString(); 
		return false; 
	}

	if ( WriteProjectInspectionOfflineFile(FileIO, Scope) == false )
	{
		m_ErrorString = FileIO.GetErrorString(); 
		return false; 
	}
	FileIO.CloseFile();
	::Sleep(0);
	::CopyFile(TempFileName, pfilename, FALSE);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::WriteProjectInspectionOfflineFile(CAOIFileIO &FileIO, OFFLINE_IMAGE_SCOPE Scope)//寫入檢測離線檔案
{
	size_t  i=0, j=0, ID=0;
	size_t  PanelIndex=0;
	size_t  FieldIndex=0;
	size_t  FrameIndex=0;
	size_t  FrameCount = 0;
	size_t  FieldFrameCount = 0;
	unsigned int FrameUniqueID=0;
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;	
	CString    FileName;	
	CAOIFrame *FramePtr = NULL;
	CAOIField *FieldPtr = NULL;	
	FRAME_TYPE FrameType = FRAME_NULL;
	double CadPosX=0, CadPosY=0;
	double StagePosX=0, StagePosY=0;
	double FovWReal = 0;
	double FovHReal = 0;
	double FovWInner = 0;
	double FovHInner = 0;
	double FovWOuter = 0;
	double FovHOuter = 0;	
	TPOINT2D  TestStartPos;
	FIELD_SIZE_MODE FieldSizeModeW = GetProjectFieldSizeModeW();
	FIELD_SIZE_MODE FieldSizeModeH = GetProjectFieldSizeModeH();
	const int ResolutionMode = AOIDataCollect.GetFovResolutionMode();
	const IMAGE_SIZE ImageW  = AOIDataCollect.GetCameraImageW(CameraID);
	const IMAGE_SIZE ImageH  = AOIDataCollect.GetCameraImageH(CameraID);	
	const double ResolutionX = AOIDataCollect.GetCameraResolutionX(CameraID);
	const double ResolutionY = AOIDataCollect.GetCameraResolutionY(CameraID);
	const size_t FrameUniqueIDCount = GetProjectFrameUniqueIDCount();
	const double FocusOffsetZ = GetProjectInspectionOfflineFocusOffsetZ();
	const size_t FieldCount  = GetProjectInspectionFieldUsedCount(Scope);

	AOIDataCollect.GetFovSizeReal(FovWReal, FovHReal);
	AOIDataCollect.GetFovSizeInner(FovWInner, FovHInner);
	AOIDataCollect.GetFovSizeOuter(FovWOuter, FovHOuter);	
	ModifyProjectFieldSize(FovWInner, FovHInner);
	GetProjectInspectionOfflineStartPos(TestStartPos);	

	FrameCount = 0;//Count Frame Number
	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = GetProjectInspectionFieldUsedPtr(i, false, Scope);
		if ( NULL == FieldPtr ) { continue; }
		FieldFrameCount = FieldPtr->GetFieldFramePtrCount();
		FrameCount += FieldFrameCount;
	}

	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_START, 0) == false ) {	return false; }

	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FILE_MODE, OFFLINE_FILE_INSPECTION) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FIELD_BUILD_MODE, GetProjectInspectionFieldBuildMode()) == false ) {	return false; }

	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_TEST_START_X, TestStartPos.x) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_TEST_START_Y, TestStartPos.y) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOCUS_OFFSET_Z, FocusOffsetZ) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_IMAGE_SCOPE, Scope) == false ) {	return false; }		

	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_RESOLUTION_MODE, ResolutionMode) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_FULL_W, FovWReal) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_FULL_H, FovHReal) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_INNER_W, FovWInner) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_INNER_H, FovHInner) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_OUTTER_W, FovWOuter) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_OFFLINE_FOV_SIZE_OUTTER_H, FovHOuter) == false ) {	return false; }

	//if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FOV_SIZE_MODE_W, FieldSizeModeW) == false ) {	return false; }
	//if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FOV_SIZE_MODE_H, FieldSizeModeH) == false ) {	return false; }	

	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FIELD_COUNT, FieldCount) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FRAME_COUNT, FrameCount) == false ) {	return false; }

	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FIELD_BUILD_AREA_MODE, GetProjectInspectionFieldBuildAreaMode()) == false ) {	return false; }	
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_LANE_ID, GetProjectActLaneID()) == false ) {	return false; }		

	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FRAME_UNIQUE_ID_COUNT, FrameUniqueIDCount) == false ) {	return false; }
	for ( i=0; i<FrameUniqueIDCount; i++ )
	{
		FrameUniqueID = GetProjectFrameUniqueID(i, false);
		if ( FRAME_UNIQUE_ID_NULL == FrameUniqueID ) { continue; }
		switch ( i )
		{
		case 0:
		case 1:
		case 2:
		case 3:
		case 4:
		case 5:
		case 6:
		case 7:
		case 8:
			if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_FRAME_UNIQUE_ID_01+i, FrameUniqueID) == false )
			{	return false; }			
			break;
		}		
	}
	
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_CAMERA_INFO_1, CameraID) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_CAMERA_START, 0) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_CAMERA_IMAGE_SIZE_W, ImageW) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_CAMERA_IMAGE_SIZE_H, ImageH) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_CAMERA_RESOLUTION_X, ResolutionX) == false ) {	return false; }
	if ( FileIO.SaveChunk_DBL(FILE_IO_CAMERA_RESOLUTION_Y, ResolutionY) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_CAMERA_END, 0) == false ) {	return false; }

	if ( FileIO.SaveChunk_INT(FILE_IO_INSPECTION_FIELD_SECTION_START, 0) == false ) {	return false; }
	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = GetProjectInspectionFieldUsedPtr(i, false, Scope);
		if ( NULL == FieldPtr ) { continue; }
		if ( FieldPtr->WriteFieldFile(FileIO) == false )
		{	return false;	}		
	}
	if ( FileIO.SaveChunk_INT(FILE_IO_INSPECTION_FIELD_SECTION_END, 0) == false ) {	return false; }

	FrameIndex=0;
	if ( FileIO.SaveChunk_INT(FILE_IO_FRAME_SECTION_START, 0) == false ) {	return false; }
	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = GetProjectInspectionFieldUsedPtr(i, false, Scope);
		if ( NULL == FieldPtr ) { continue; }

		FieldFrameCount = FieldPtr->GetFieldFramePtrCount();
		for ( j=0; j<FieldFrameCount; j++ )
		{
			FramePtr = FieldPtr->GetFieldFramePtr(j, false);
			if ( NULL == FramePtr ) { continue; }		

			if ( FramePtr->WriteFrameFile(FileIO) == false )
			{	return false;	}			
		}	
	}		
	if ( FileIO.SaveChunk_INT(FILE_IO_FRAME_SECTION_END, 0) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_OFFLINE_END, 0) == false ) {	return false; }
	if ( FileIO.SaveChunk_INT(FILE_IO_END, 0) == false ) { return false; }	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectInspectionOfflineFile(LPCTSTR pfilename)//載入檢測離線檔案
{
	if ( LoadProjectInspectionOfflineFileFn(pfilename) == false )
	{
		SetProjectExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectInspectionOfflineFileFn(LPCTSTR pfilename)//載入檢測離線檔案		
{	
	CAOIFileIO FileIO;
	CString    FileName;
	FileIO.SetFileName(pfilename);
	FileIO.SetFileTarget(FILE_TARGET_OFFLINE);

	FileName.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("OfflineTmp.TXT"));
	::DeleteFile(FileName);
	::Sleep(0);
	::CopyFile(pfilename, FileName, FALSE);	
	if ( FileIO.OpenLoadFile(FileName) == false )
	{
		m_ErrorString = FileIO.GetErrorString();		
		return false;
	}
	if ( ReadProjectInspectionOfflineFile(FileIO) == false )
	{
		m_ErrorString = FileIO.GetErrorString();	
		ClearProjectAllInspectionField();	
		return false;
	}
	FileIO.CloseFile();	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ReadProjectInspectionOfflineFile(CAOIFileIO &FileIO)//讀取編程離線檔案
{
#ifdef _DEBUG
	if ( FileIO.CheckFileMode() == FALSE ) { return false; }
	if ( FileIO.CheckFileOpened() == FALSE ) { return false; }
#endif//_DEBUG

	int        index =0;		
	int        nValue=0;	
	double     dValue = 0;	
	IMAGE_SIZE uValue=0;
	unsigned int  i=0, ID=0;
	unsigned int  PanelIndex=0;
	unsigned int  BoardIndex=0;
	unsigned int  ComponentIndex=0;
	unsigned int  FieldIndex=0;
	unsigned int  FrameIndex=0;
	unsigned int  FieldCount=0;
	unsigned int  FrameCount = 0;
	unsigned int  FieldCount_Read=0;
	unsigned int  FrameCount_Read=0;
	LANE_ID LaneID = GetProjectActLaneID();
	FIELD_BUILD_MODE   FieldBuildMode=FIELD_BUILD_NONE;
	FIELD_BUILD_AREA_MODE   FieldAreaMode=FIELD_BUILD_AREA_NONE;	
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;	
	FRAME_TYPE FrameType = FRAME_NULL;		
	CString   Folder;	
	TPOINT3D  FocusPos;
	TPOINT2D  TestStartPos;
	CString   FileName, PathName;
	CAOIFrame   *FramePtr = NULL;
	CAOIField   *FieldPtr = NULL;
	CAOIPanel   *PanelPtr = NULL;
	CAOIBoard   *BoardPtr = NULL;
	CAOIProject *ProjectPtr = this;
	CAOIComponent *ComponentPtr = NULL;
	IMAGE_SIZE   CameraIndex=0;
	IMAGE_SIZE   CameraImageW[MAX_CAMERA_COUNT]={0};//最多八個相機的影像尺寸-寬度
	IMAGE_SIZE   CameraImageH[MAX_CAMERA_COUNT]={0};//最多八個相機的影像尺寸-高度
	double       CameraResolutionX[MAX_CAMERA_COUNT]={0};//最多八個相機的解析度-X
	double       CameraResolutionY[MAX_CAMERA_COUNT]={0};//最多八個相機的解析度-Y
	const int ResolutionMode = GetProjectSpaceToGrayRatioMode();
	const IMAGE_SIZE ImageW  = AOIDataCollect.GetCameraImageW(CameraID);
	const IMAGE_SIZE ImageH  = AOIDataCollect.GetCameraImageH(CameraID);

	double FocusOffsetZ=0.0;
	double FovWReal=0, FovHReal=0;
	double FovWInner=0, FovHInner=0;
	double FovWOuter=0, FovHOuter=0;
	double ResolutionX=0, ResolutionY=0;
	double CadPosX=0, CadPosY=0;
	double StagePosX=0, StagePosY=0;	
	unsigned int FrameUniqueID= 0;
	size_t FrameUniqueIDCount = 0;
	std::vector<unsigned int> FrameUniqueIDList;
	std::vector<unsigned int> ProjectFrameUniqueIDList;
	CloneProjectFrameUniqueIDList(ProjectFrameUniqueIDList);
	OFFLINE_IMAGE_SCOPE OfflineImageScope = OFFLINE_IMAGE_FOV;

	FileName = FileIO.GetFileName();
	if ( JetAPI::ExtractFolder(FileName, Folder) == false )
	{
		m_ErrorString.Format(_T("Error, Extract Folder Fault \n[%s]"), FileName);
		FileIO.SetErrorString(m_ErrorString);
		return false;
	}	
	SetProjectOfflineFolder(Folder);
	SetProjectInspectionOfflineFolder(Folder);
	AOIDataCollect.GetFovSizeReal(FovWReal, FovHReal);
	AOIDataCollect.GetFovSizeInner(FovWInner, FovHInner);
	AOIDataCollect.GetFovSizeOuter(FovWOuter, FovHOuter);			
	ResolutionX = AOIDataCollect.GetCameraResolutionX(PRIMARY_CAMERA_ID);
	ResolutionY = AOIDataCollect.GetCameraResolutionY(PRIMARY_CAMERA_ID);
	ModifyProjectFieldSize(FovWInner, FovHInner);	

	while ( FileIO.CheckFileEnd()==false )
	{ 	
		if ( FileIO.LoadChunk(index) == false )		
		{	continue; }
		
		switch ( index )
		{
		case FILE_IO_OFFLINE_SECTION_START://離線參數區間-起點		
			break;
		case FILE_IO_OFFLINE_SECTION_END://離線參數區間-終點			
			return true;
			break;		

		case FILE_IO_OFFLINE_START://離線參數區間-起點		
			break;		
		case FILE_IO_OFFLINE_END://離線參數區間-終點		
			SetProjectOfflineImageScope(OfflineImageScope);
			SetProjectInspectionOfflineStartPos(TestStartPos);
			SetProjectInspectionOfflineFocusOffsetZ(FocusOffsetZ);
			if ( FIELD_BUILD_AREA_NONE == FieldAreaMode )
			{	
				SetProjectFieldBuildAreaMode(FIELD_BUILD_AREA_COMPONENT);	
				SetProjectInspectionFieldBuildAreaMode(FIELD_BUILD_AREA_COMPONENT);	
			}
			if ( OFFLINE_IMAGE_FOV == OfflineImageScope )			
			{
				RestoreProjectObjectFieldIndex();
				SetProjectObjectFieldPtrByIndex();	
			}
			return true;
			break;		
		case FILE_IO_OFFLINE_FILE_MODE://離線參數區間-離線檔案模式		
			nValue = FileIO.GetData_INT();
			if ( OFFLINE_FILE_INSPECTION != nValue ) 
			{
				m_ErrorString.Format(_T("Error, Read Offline File Mode Fault[%d]"), nValue);
				FileIO.SetErrorString(m_ErrorString);
				return true; 
			}
			break;		
		case FILE_IO_OFFLINE_FIELD_BUILD_MODE://離線參數區間-離線檔案模式
			nValue = FileIO.GetData_INT();
			if ( FIELD_BUILD_NONE == nValue ) 
			{
				m_ErrorString.Format(_T("Error, Read Offline Field Mode Fault[%d]"), nValue);
				FileIO.SetErrorString(m_ErrorString);
				return true; 
			}
			FieldBuildMode = (FIELD_BUILD_MODE)(nValue);
			SetProjectFieldBuildMode(FieldBuildMode);
			SetProjectInspectionFieldBuildMode(FieldBuildMode);
			m_ProjectOfflineFileMode = OFFLINE_FILE_INSPECTION;			
			break;
		case FILE_IO_OFFLINE_TEST_START_X://離線參數區間-檢測起點-X
			TestStartPos.x = FileIO.GetData_DBL();
			break;
		case FILE_IO_OFFLINE_TEST_START_Y://離線參數區間-檢測起點-Y
			TestStartPos.y = FileIO.GetData_DBL();
			break;
		case FILE_IO_OFFLINE_FOCUS_OFFSET_Z://離線參數區間-焦距偏差-Z	
			FocusOffsetZ = FileIO.GetData_DBL();
			break;
		case FILE_IO_OFFLINE_IMAGE_SCOPE://離線參數區間-影像範疇
			OfflineImageScope = (OFFLINE_IMAGE_SCOPE)(FileIO.GetData_INT());
			break;
		case FILE_IO_OFFLINE_RESOLUTION_MODE://離線參數區間-解析度模式
			nValue = FileIO.GetData_INT();			
		#ifndef OFFLINE_VERSION	
			if ( ResolutionMode != nValue )
			{
				m_ErrorString.Format(_T("Error, Load Resolution Mode Fault [%d, %d] \n(%s)"), nValue, ResolutionMode, FileName);
				FileIO.SetErrorString(m_ErrorString);
				//return false;
			}
		#else
			AOIDataCollect.SetFovResolutionMode(nValue);
		#endif//OFFLINE_VERSION
			break;		
		case FILE_IO_OFFLINE_FOV_SIZE_FULL_W://離線參數區間-視野-寬-全部					
			FovWReal = FileIO.GetData_DBL();
			break;		
		case FILE_IO_OFFLINE_FOV_SIZE_FULL_H://離線參數區間-視野-長-全部		
			FovHReal = FileIO.GetData_DBL();
			break;				
		case FILE_IO_OFFLINE_FOV_SIZE_INNER_W://離線參數區間-視野-寬-內部		
			FovWInner = FileIO.GetData_DBL();
			break;		
		case FILE_IO_OFFLINE_FOV_SIZE_INNER_H://離線參數區間-視野-長-內部		
			FovHInner = FileIO.GetData_DBL();
			break;
		case FILE_IO_OFFLINE_FOV_SIZE_OUTTER_W://離線參數區間-視野-寬-外部		
			FovWOuter = FileIO.GetData_DBL();
			//SetProjectFieldSizeModeW(FieldSizeModeW);
			break;		
		case FILE_IO_OFFLINE_FOV_SIZE_OUTTER_H://離線參數區間-視野-長-外部
			FovHOuter = FileIO.GetData_DBL();
			//SetProjectFieldSizeModeW(FieldSizeModeH);
			break;			
		case FILE_IO_OFFLINE_FIELD_COUNT://離線參數區間-區域數量	
			FieldCount = FileIO.GetData_INT();
			break;
		case FILE_IO_OFFLINE_FOV_SIZE_MODE_W://離線參數區間-視野-寬-模式
			nValue = (FIELD_SIZE_MODE)(FileIO.GetData_INT());
			break;
		case FILE_IO_OFFLINE_FOV_SIZE_MODE_H://離線參數區間-視野-長-模式
			nValue = (FIELD_SIZE_MODE)(FileIO.GetData_INT());
			break;
		case FILE_IO_OFFLINE_FRAME_COUNT://離線參數區間-區域影像數量	
			FrameCount = FileIO.GetData_INT();
			break;		
		case FILE_IO_OFFLINE_FIELD_BUILD_AREA_MODE://離線參數區間-離線建立面積模式
			nValue = FileIO.GetData_INT();			
			FieldAreaMode = (FIELD_BUILD_AREA_MODE)(nValue);
			SetProjectFieldBuildAreaMode(FieldAreaMode);
			SetProjectInspectionFieldBuildAreaMode(FieldAreaMode);
			break;
		case FILE_IO_OFFLINE_LANE_ID://離線參數區間-軌道編號
			nValue = FileIO.GetData_INT();
			LaneID = (LANE_ID)(nValue);
			break;
		case FILE_IO_OFFLINE_CAMERA_INFO_1://離線參數區間-相機影像寬度
			CameraIndex = FileIO.GetData_INT();
			break;
		case FILE_IO_CAMERA_START://相機參數-終點
			if ( CameraIndex < MAX_CAMERA_COUNT )
			{
				CameraImageW[CameraIndex] = 0;
				CameraImageH[CameraIndex] = 0;
				CameraResolutionX[CameraIndex] = 1.0;
				CameraResolutionY[CameraIndex] = 1.0;
			}
			break;
		case FILE_IO_CAMERA_END://相機參數-終點
			if ( CameraIndex == CameraID )
			{
				if ( ImageW != CameraImageW[CameraIndex] )
				{
					m_ErrorString.Format(_T("Error, Load ImageW Fault [%d, %d] \n(%s)"), CameraImageW[CameraIndex], ImageW, FileName);
					FileIO.SetErrorString(m_ErrorString);
					return false;
				}
				if ( ImageH != CameraImageH[CameraIndex] )
				{
					m_ErrorString.Format(_T("Error, Load ImageH Fault [%d, %d] \n(%s)"), CameraImageH[CameraIndex], ImageH, FileName);
					FileIO.SetErrorString(m_ErrorString);
					return false;
				}
			}			
			break;
		case FILE_IO_CAMERA_IMAGE_SIZE_W://相機參數-影像寬度
			if ( CameraIndex < MAX_CAMERA_COUNT )
			{	CameraImageW[CameraIndex] = FileIO.GetData_INT();	}
			break;
		case FILE_IO_CAMERA_IMAGE_SIZE_H://相機參數-影像長度
			if ( CameraIndex < MAX_CAMERA_COUNT )
			{	CameraImageH[CameraIndex] = FileIO.GetData_INT();	}
			break;
		case FILE_IO_CAMERA_RESOLUTION_X://相機參數-解析度-X
			if ( CameraIndex < MAX_CAMERA_COUNT )
			{	CameraResolutionX[CameraIndex] = FileIO.GetData_DBL();	}
			break;
		case FILE_IO_CAMERA_RESOLUTION_Y://相機參數-解析度-Y
			if ( CameraIndex < MAX_CAMERA_COUNT )
			{	CameraResolutionY[CameraIndex] = FileIO.GetData_DBL();	}
			break;			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_COUNT://離線參數區間-影像唯一碼數量	
			FrameUniqueIDCount = FileIO.GetData_INT();
			break;		
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_01://離線參數區間-影像唯一碼-1				
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_02://離線參數區間-影像唯一碼-2			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_03://離線參數區間-影像唯一碼-3			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_04://離線參數區間-影像唯一碼-4			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_05://離線參數區間-影像唯一碼-5			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_06://離線參數區間-影像唯一碼-6			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_07://離線參數區間-影像唯一碼-7			
		case FILE_IO_OFFLINE_FRAME_UNIQUE_ID_08://離線參數區間-影像唯一碼-8
			FrameUniqueID = FileIO.GetData_INT();
			if ( FRAME_UNIQUE_ID_NULL != FrameUniqueID )
			{	FrameUniqueIDList.push_back(FrameUniqueID); }			
			break;		
		
		case FILE_IO_INSPECTION_FIELD_SECTION_START://區域參數區間-起點			
			if ( FrameUniqueIDList.size() != ProjectFrameUniqueIDList.size() )
			{
				m_ErrorString.Format(_T("Error, Check Frame UniqueID List Fault [%d//%d]"), FrameUniqueIDList.size(), ProjectFrameUniqueIDList.size());
				FileIO.SetErrorString(m_ErrorString);
				return false;
			}
			for ( size_t ii=0; ii<FrameUniqueIDList.size(); ii++ )
			{
				FrameUniqueID = FrameUniqueIDList[ii];
				const int ProjectFrameUniqueID = ProjectFrameUniqueIDList[ii];
				if ( FrameUniqueID != ProjectFrameUniqueID )
				{
					m_ErrorString.Format(_T("Error, Check Frame UniqueID Fault [%d//%d]"), FrameUniqueID, ProjectFrameUniqueID);
					FileIO.SetErrorString(m_ErrorString);
					return false;
				}
			}
			
			FieldCount_Read=0;
			if ( OFFLINE_IMAGE_PART == OfflineImageScope )
			{	ClearProjectAllInspectionPartField();	}
			else
			{	
				BackupProjectObjectFieldIndex();
				ClearProjectAllInspectionField();	
			}
			break;
		case FILE_IO_INSPECTION_FIELD_SECTION_END://區域參數區間-終點
			break;
		case FILE_IO_FIELD_START://區域參數-起點
			FieldPtr = AOIObjManager.CreateFieldObj();
			if ( NULL == FieldPtr )
			{
				m_ErrorString.Format(_T("Error, Create Field Obj Fault [%d]"), FieldCount_Read+1);
				FileIO.SetErrorString(m_ErrorString);
				return false;
			}
			if ( FieldPtr->ReadFieldFile(FileIO) == false )
			{	
				AOIObjManager.DestroyFieldObj(FieldPtr);
				return false;	
			}
			PanelIndex = FieldPtr->GetFieldPanelIndex();
			PanelPtr = GetProjectPanelPtr(PanelIndex, true);
			if ( NULL != PanelPtr )
			{	PanelPtr->AddPanelFieldPtr(FieldPtr);	}

			BoardIndex = FieldPtr->GetFieldBoardIndex();
			BoardPtr = GetProjectBoardPtr(BoardIndex, true);
			if ( NULL != BoardPtr )
			{	BoardPtr->AddBoardFieldPtr(FieldPtr);	}

			ComponentIndex = FieldPtr->GetFieldComponentIndex();
			ComponentPtr = GetProjectComponentPtr(ComponentIndex, true);
			if ( NULL != ComponentPtr )
			{	ComponentPtr->SetComponentSelfFieldPtr(FieldPtr);	}	

			if ( OFFLINE_IMAGE_PART == OfflineImageScope )
			{
				FieldPtr->SetFieldSizeW_Real(FieldPtr->GetFieldSizeW_Outer());
				FieldPtr->SetFieldSizeH_Real(FieldPtr->GetFieldSizeH_Outer());
				AddProjectInspectionPartFieldPtr(FieldPtr, false);
			}
			else
			{
				FieldPtr->SetFieldSizeW_Real(FovWReal);
				FieldPtr->SetFieldSizeH_Real(FovHReal);
				FieldPtr->SetFieldSizeW_Inner(FovWInner);
				FieldPtr->SetFieldSizeH_Inner(FovHInner);
				FieldPtr->SetFieldSizeW_Outer(FovWOuter);
				FieldPtr->SetFieldSizeH_Outer(FovHOuter);
				AddProjectInspectionFieldPtr(FieldPtr, false);
			}
			FieldCount_Read ++;
			break;
		case FILE_IO_FRAME_SECTION_START://區域影像參數區間-起點
			FrameCount_Read = 0;
			break;
		case FILE_IO_FRAME_SECTION_END://區域影像參數區間-終點
			break;
		case FILE_IO_FRAME_START://區域影像參數-起點
			FramePtr = AOIObjManager.CreateFrameObj();
			if ( NULL == FramePtr )
			{
				m_ErrorString.Format(_T("Error, Create Frame Obj Fault [%d]"), FrameCount_Read+1);
				FileIO.SetErrorString(m_ErrorString);
				return false;
			}
			if ( FramePtr->ReadFrameFile(FileIO) == false )
			{	
				AOIObjManager.DestroyFrameObj(FramePtr);
				return false;
			}
			CameraID = FramePtr->GetFrameCameraID();
			FieldIndex = FramePtr->GetFrameFieldIndex();
			FramePtr->SetFrameIndex(FrameCount_Read);		
			FramePtr->SetFrameIndexOffline(FrameCount_Read);
			FramePtr->SetFrameResolutionX(CameraResolutionX[CameraID]);
			FramePtr->SetFrameResolutionY(CameraResolutionY[CameraID]);

			FramePtr->SetFrameFileFolder(Folder);			
			FramePtr->SetFrameFileFolderOffline(Folder);
			if ( OFFLINE_IMAGE_PART == OfflineImageScope )
			{	FieldPtr = GetProjectInspectionPartFieldPtr(FieldIndex, true); }
			else
			{	FieldPtr = GetProjectInspectionFieldPtr(FieldIndex, true); }
			if ( NULL != FieldPtr )
			{	
				FieldPtr->AddFieldFramePtr(FramePtr);	
				FramePtr->SetFrameLinkPointer(true);
			}
			else
			{	AOIObjManager.DestroyFrameObj(FramePtr);	}
			FrameCount_Read ++;
			break;
		case FILE_IO_END://寫檔結束
			return true;
			break;
		}
	};
	return true;
}
//-------------------------------------------------------------------------------------//
