//-------------------------------------------------------------------------------------//
bool CAOIProject::ExecProjectPreLoadInspectionImage_MT()//執行專案預先載入檢測圖檔-多執行緒	
{
	CString      str;
	WORD         Res = 0;
	DWORD        i=0, j=0;	
	DWORD        ThreadIdx = 0;	
	DWORD        Count = 0;		
	const DWORD  dwTime  = 1000;//1 sec	
	const DWORD  dwMaxCount = 60;  //60 loop
	const DWORD  MaxFrameLoadCount = MAX_THREAD_COUNT_FRAME_LOAD;
	const DWORD  CPUCoreNumber = AOIDataCollect.GetComputerCPUCoreNumber();
	const DWORD  ThreadCount = MIN(CPUCoreNumber, MaxFrameLoadCount);		

	str.Format(_T("CAOIProject::ExecProjectPreLoadInspectionImage_MT::CPUCoreNumber=%d"), CPUCoreNumber);	
	AOIDataCollect.SaveCurrentProcess(str);

	SetProjectInspectionFieldMustToLoad(true);
	for ( i=0; i<MaxFrameLoadCount; i++ )
	{
		ProjectLoadFrameImageThreadID[i] = 0;
		ProjectLoadFrameImageThreadHandle[i] = NULL;		
	}

	m_ProjectPreLoadFrameImageCount = 0;
	m_ProjectPreLoadFrameImageThreadCmd = THREAD_COMMAND_TO_RUN;
	for ( i=0; i<ThreadCount; i++ )
	{
		ThreadIdx = i;
		ProjectLoadFrameImageThreadHandle[ThreadIdx] = (HANDLE)::_beginthreadex(NULL, NULL, &ProjectLoadInspectionImageThreadFn, (void*)this, NULL, &ProjectLoadFrameImageThreadID[ThreadIdx]);
		if ( NULL == ProjectLoadFrameImageThreadHandle[ThreadIdx] )
		{			
			this->m_ErrorString = _T("Eorror, Create Thread Fault (ProjectLoadFrameImageThreadHandle == NULL)");			
			AOIExceptionCodeCtrl.SetAOIExceptionCode_Thread(AOI_EXCEPTION_THREAD_CREATE, m_ErrorString);
			CloseProjectPreLoadFrameImageThread(j, 100);
			SetProjectInspectionFieldMustToLoad(false);
			return false;
		}	
	}

	Count = 0;
	while ( true ) 
	{
		Res = ::WaitForMultipleObjects(ThreadCount, ProjectLoadFrameImageThreadHandle, TRUE, 1000);
		if ( WAIT_TIMEOUT != Res ) 
		{	break;	}

		Count ++;
		if ( Count >= dwMaxCount )
		{
			this->m_ErrorString.Format(_T("Error, wait for ProjectLoadFrameImageThreadHandle finish too long"));
			CloseProjectPreLoadFrameImageThread(ThreadCount, 100);	
			SetProjectInspectionFieldMustToLoad(false);
			return false;
		}
	};
	CloseProjectPreLoadFrameImageThread(ThreadCount, 0);	
	SetProjectInspectionFieldMustToLoad(false);
	SetProjectInspectionFieldBufferReleased(false);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ExecProjectPreLoadInspectionImage_MP()//執行專案預先載入檢測圖檔-平行載入
{
	CAOIProject *ProjectPtr = (this);
	if ( NULL == ProjectPtr ) { return false; }

	CString      str;
	WORD         Res = 0;
	int          i=0, j=0;			
	int          FrameCount = 0;
	CAOIFrame   *FramePtr = NULL;
	CAOIField   *FieldPtr = NULL;		
	std::vector<CAOIFrame*> FramePtrList;	
	const int    FieldCount = (int)(ProjectPtr->GetProjectInspectionFieldCount());
	const DWORD  CPUCoreNumber = AOIDataCollect.GetComputerCPUCoreNumber();	

	str.Format(_T("CAOIProject::ExecProjectPreLoadInspectionImage_MP::CPUCoreNumber=%d"), CPUCoreNumber);	
	AOIDataCollect.SaveCurrentProcess(str);

	SetProjectInspectionFieldMustToLoad(true);	
	//先放入佇列內
	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = ProjectPtr->GetProjectInspectionFieldPtr(i, false);
		if ( NULL == FieldPtr ) { continue; }

		FrameCount = FieldPtr->GetFieldFramePtrCount();
		for ( j=0; j<FrameCount; j++ )
		{			
			FramePtr = FieldPtr->GetFieldFramePtr(j, false);
			if ( NULL == FramePtr ) { continue; }
			FramePtrList.push_back(FramePtr);
		}		
	}
	
	bool IsOK = true;
	const int FrameTotalCount = (int)(FramePtrList.size());
	const int LoadFrameThreadCount = AOIDataCollect.GetSystemParameter().m_MTCount_FrameLoad;		
#ifdef OPEN_MP_USE
	#pragma omp parallel for num_threads(LoadFrameThreadCount)
#endif//OPEN_MP_USE		
	for ( int ii=0; ii<FrameTotalCount; ii++ )
	{
		//需要使用迴圈內變數
		CAOIFrame *FramePtr_MP = FramePtrList[ii];
		if ( NULL == FramePtr_MP ) { continue; }		
		if ( FramePtr_MP->ExecFrameLoad() == false )
		{	continue;	}
		FramePtr_MP->SetFrameCalcState(FRAME_CALC_NONE);
		FramePtr_MP->SetFrameMergeState(FRAME_MERGE_DONE);		
	}	

	FRAME_MERGE_STATE FrameMergeState=FRAME_MERGE_NONE;
	for ( i=0; i<FrameTotalCount; i++ )
	{
		FramePtr = FramePtrList[i];
		if ( NULL == FramePtr ) { continue; }
		FrameMergeState = FramePtr->GetFrameMergeState();
		if ( FRAME_MERGE_DONE != FrameMergeState )
		{	break; }
	}	
	if ( i < FrameTotalCount ) 
	{	
		CString ImageFileName;
		CString FileName = FramePtr->GetFrameFileName();
		CString FileFolder = FramePtr->GetFrameFileFolder();
		ImageFileName.Format(_T("%s\\%s"), FileFolder, FileName);
		str.Format(_T("Error Load Frame Fault (%s)"), FramePtr->GetFrameFileName());
		ProjectPtr->SetErrorString(str);
		return false;
	}

	for ( i=0; i<FieldCount; i++ )
	{	
		FieldPtr = ProjectPtr->GetProjectInspectionFieldPtr(i, false);
		if ( NULL == FieldPtr ) { continue; }
		FieldPtr->SetFieldMergeState(FIELD_MERGE_NONE);
		if ( FieldPtr->CheckFieldFramesMergeFinish() == true )
		{	FieldPtr->SetFieldMergeState(FIELD_MERGE_DONE);	}
	}

	SetProjectInspectionFieldMustToLoad(false);
	SetProjectInspectionFieldBufferReleased(false);
	return true;
}
