//-------------------------------------------------------------------------------------//
bool CAOIProject::CloseProjectPreLoadFrameImageThread(size_t ThreadCount, DWORD dwDelay)//關閉專案預先載入執行緒
{
	size_t i=0;
	m_ProjectPreLoadFrameImageThreadCmd = THREAD_COMMAND_TO_EXIT;
	if ( dwDelay > 0 ) 
	{	::Sleep(dwDelay); }
	for ( i=0; i<ThreadCount; i++ )
	{	
		::CloseHandle(ProjectLoadFrameImageThreadHandle[i]); 
		ProjectLoadFrameImageThreadHandle[i] = NULL;	
	}
	m_ProjectPreLoadFrameImageThreadCmd = THREAD_COMMAND_TO_NONE;
	return true;
}
