//-------------------------------------------------------------------------------------//
bool CAOIProject::InitProjectInspectionData_PartGroup()//初始化專案檢測資料-群組資料
{	
	if ( InitialProjectGroupInspection() == false )
	{	return false; }

	size_t         i=0;	
	CAOIPartGroup *PartGroupPtr = NULL;
	const size_t   PartGroupCount = GetProjectPartGroupCount();	
	for ( i=0; i<PartGroupCount; i++ )
	{
		PartGroupPtr = GetProjectPartGroupPtr(i, false);
		if ( NULL == PartGroupPtr ) { continue; }		
		PartGroupPtr->SetGroupComponentKeepImage();
	}

	AssignProjectPartGroupToPanelBoard();
	return true;
}
//-------------------------------------------------------------------------------------//
bool  CAOIProject::InitProjectInspectionData_LocalBasePlane(LANE_ID LaneID)//初始化專案檢測資料-局部基準面
{
	CAOIProject *ProjectPtr=this;	
	if ( CheckProjectPtr(ProjectPtr) == false )
	{	return false; }

	size_t       i=0, j=0, k=0;				
	CAOIMark    *MarkPtr = NULL;	
	int          LocalBasePlaneID=0;
	int          LocalBasePlaneIDMax=0;	
	std::vector<int> LocalBasePlaneIDMap;
	std::vector<int> LocalBasePlaneIDUsed;	
	CAOIBoard   *BoardPtr = NULL;
	const size_t BoardCount = ProjectPtr->GetProjectBoardCount();
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = ProjectPtr->GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }

		LocalBasePlaneIDMap.clear();		
		LocalBasePlaneIDMax = BoardPtr->GetBoardMarkMaxLocalBasePlaneID();
		if ( 0 == LocalBasePlaneIDMax ) { continue; }
		size_t LocalBasePlaneIDMapCnt=LocalBasePlaneIDMax+1;
		LocalBasePlaneIDMap.resize(LocalBasePlaneIDMapCnt);
		LocalBasePlaneIDUsed.resize(LocalBasePlaneIDMapCnt);
		std::fill(LocalBasePlaneIDMap.begin(), LocalBasePlaneIDMap.end(), 0);
		std::fill(LocalBasePlaneIDUsed.begin(), LocalBasePlaneIDUsed.end(), 0);

		size_t BoardMarkCount = BoardPtr->GetBoardMarkCount();
		for ( j=0; j<BoardMarkCount; j++ )
		{
			MarkPtr = BoardPtr->GetBoardMarkPtr(j, false);
			if ( NULL == MarkPtr ) { continue; }
			if ( MarkPtr->GetMarkBypassed() == true ) { continue; }
			if ( MarkPtr->CheckMarktType_BasePlane() == false ) { continue; }			
			LocalBasePlaneID = MarkPtr->GetMarkLocalBasePlaneID();
			if ( LocalBasePlaneID >= LocalBasePlaneIDMapCnt )
			{	continue; }
			LocalBasePlaneIDMap[LocalBasePlaneID] = FN_ENABLE;			
		}

		//For Fd
		size_t BoardFdCount = BoardPtr->GetBoardFdCount();

		//For Barcode
		CAOIBarcode *BarcodePtr = NULL;
		size_t BoardBarcodeCount = BoardPtr->GetBoardBarcodeCount();
		for ( j=0; j<BoardBarcodeCount; j++ )
		{
			BarcodePtr = BoardPtr->GetBoardBarcodePtr(j, false);
			if ( NULL == BarcodePtr ) { continue; }
			if ( BarcodePtr->GetBarcodeNeedToCalculate() == false ) { continue; }
			if ( BarcodePtr->CheckRgnLocalBasePlaneUsed() == false ) { continue; }
			LocalBasePlaneID = BarcodePtr->GetBarcodeLocalBasePlaneID();
			if ( LocalBasePlaneID >= LocalBasePlaneIDMapCnt )
			{	continue; }
			LocalBasePlaneIDUsed[LocalBasePlaneID] = FN_ENABLE;
			if ( FN_ENABLE != LocalBasePlaneIDMap[LocalBasePlaneID]  ) { continue; }			
			BarcodePtr->SetBarcodeLocalBasePlaneFinish(false);
		}
		
		//For Component
		CAOIComponent *ComponentPtr = NULL;
		size_t BoardComponentCount = BoardPtr->GetBoardComponentCount();
		for ( j=0; j<BoardComponentCount; j++ )
		{
			ComponentPtr = BoardPtr->GetBoardComponentPtr(j, false);
			if ( NULL == ComponentPtr ) { continue; }
			if ( ComponentPtr->GetComponentNeedToCalculate() == false ) { continue; }
			if ( ComponentPtr->CheckRgnLocalBasePlaneUsed() == false ) { continue; }			
			LocalBasePlaneID = ComponentPtr->GetComponentLocalBasePlaneID();	
			if ( LocalBasePlaneID >= LocalBasePlaneIDMapCnt )
			{	continue; }
			LocalBasePlaneIDUsed[LocalBasePlaneID] = FN_ENABLE;
			if ( FN_ENABLE != LocalBasePlaneIDMap[LocalBasePlaneID]  ) { continue; }			
			ComponentPtr->SetComponentLocalBasePlaneFinish(false);
		}
		//Enable Mark
		for ( k=0; k<LocalBasePlaneIDMapCnt; k++ )
		{
			if ( FN_ENABLE != LocalBasePlaneIDUsed[k] ) { continue; }
			LocalBasePlaneID = (int)(k);
			for ( j=0; j<BoardMarkCount; j++ )
			{
				MarkPtr = BoardPtr->GetBoardMarkPtr(j, false);
				if ( NULL == MarkPtr ) { continue; }
				if ( MarkPtr->GetMarkBypassed() == true ) { continue; }
				if ( MarkPtr->CheckMarktType_BasePlane() == false ) { continue; }				
				if ( LocalBasePlaneID != MarkPtr->GetMarkLocalBasePlaneID() ) { continue; }
				MarkPtr->SetMarkNeedToCalculate(true);
			}
		}		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::WaitProjectLastInspectionEnd()//等待專案上一次檢測結束
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }	
	const bool bSaveFieldThreadExecuted = GetProjectSaveFieldThreadExecuted();
	if ( true == bSaveFieldThreadExecuted )
	{
		AOIDataCollect.SaveMovingTimeMsg(_T("CAOIProject::WaitProjectLastInspectionEnd Start"));
		bool bUpdateOnlineStateNode=false;		
		LANE_ID LaneID = ProjectPtr->GetProjectActLaneID();
		THREAD_STATE_MODE CopyFileSts=ProjectPtr->GetProjectCopyFileThreadState();
		THREAD_STATE_MODE SaveFieldSts=ProjectPtr->GetProjectSaveFieldThreadState();
		if ( THREAD_STATE_RUNNING==CopyFileSts || THREAD_STATE_RUNNING==SaveFieldSts )
		{
			CString str;
			str.Format(_T("Wait for Saving Image Files"));
			str = ProjectPtr->LoadMultiLanguageString(str, str);
			bUpdateOnlineStateNode = true;
			AOIDataCollect.SetOnlineStateNode(str, LaneID);			
			AOIDataCollect.PostMainFrameWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_REDRAW_VIEW_WND, NULL);
		}
		//避免將等待時間納入計算
		bool bSucc=true;
		if ( ProjectPtr->WaitForProjectSaveFieldThreadFinish() == false )
		{	bSucc = false;	}	
		else if ( ProjectPtr->WaitForProjectCopyFileThreadFinish() == false )
		{	bSucc = false;	}
		if ( true == bUpdateOnlineStateNode )
		{	AOIDataCollect.SetOnlineStateNode(_T(""), LaneID);	}
		if ( false == bSucc )
		{	return false; }	
	
		ProjectPtr->ClearProjectSaveFiledList();
		ProjectPtr->ClearProjectAllInspectionPartField();
		AOIDataCollect.SaveMovingTimeMsg(_T("CAOIProject::WaitProjectLastInspectionEnd End"));
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::InitProjectInspection(LANE_ID LaneID)//初始化專案檢測
{
	if ( WaitProjectLastInspectionEnd() == false )
	{	return false; }
	const bool OfflineMode = AOIDataCollect.GetOfflineMode();
	if ( false == OfflineMode )
	{
		ReleaseProjectProgramFieldFrameImageBuffer();
		ReleaseProjectInspectionFieldFrameImageBuffer();
	}

	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }	
	AOIDataCollect.SaveMovingTimeMsg(_T("CAOIProject::InitProjectInspection Start"));

	size_t       i=0, j=0;
	CString      str;
	CString      TempFolder1;
	CString      TempFolder2;
	CString      FileMainName;
	CString      TestDateTime;		
	CString      OfflineFolder;
	CString      OfflineFolderDefault;
	CString      ProjectFolder;
	CString      AIImageFolder;	
	CString      SpcFileFolder;	
	CString      SpcImageFolder;	
	CString      SpcResultFolder;		
	CString      TestTrackFolder;
	CString      SpcProjectFolder;	
	CString      SpcPartImageFolder;
	CString      ProjectDebugFolder;
	CString      SpcImageFolderLocal;	
	CString      BarcodeProjectFolder;	
	CString      OnlineTuningImageFolder;
	CString      OnlineTuningProjectFolder;	
	CString      OnlineOfflineImageFolder;
	CString      OnlineOfflineProjectFolder;	
	TASK_MODE    TaskMode = AOIDataCollect.GetTaskMode();	
	CString      TempFolder = AOIDataCollect.GetAOITempDirectory();
	CString      ResultFolder = AOIDataCollect.GetAOIResultDirectory();
	CString      RawFolder = AOIDataCollect.GetAOIProjectRawDirectory();
	CString      DebugFolder = AOIDataCollect.GetAOIProjectDebugDirectory();
	CString      BarcodeFolder = AOIDataCollect.GetAOIOnlineBarcodeDirectory();
	CString      OnlineTuningFolder = AOIDataCollect.GetAOIOnlineTuningDirectory();
	CString      OnlineOfflineFolder = AOIDataCollect.GetAOIOnlineOfflineDirectory();
	const int    SaveDropOutImage = GetProjectDropOutPartSaveImage();
	const int    SaveScratchImage = GetProjectScratchPartSaveImage();	
	const int    SaveDimonsionImage = GetProjectPartDimensionSaveImage();	
	const bool   OnlineTuningEnable = CheckProjectOnlineTuningRunning();		
	const bool   UseLocalFolder = AOIDataCollect.GetProjectLocalFolderEnabled();
	const TSystemParameter &SystemParam = AOIDataCollect.GetSystemParameter();
	SAVE_TEST_IMAGE_MODE SaveFieldImageMode = GetProjectSaveFieldImageMode();
	SAVE_TEST_IMAGE_MODE  OnlineTuningMode = ProjectPtr->GetProjectOnlineTuningMode();
	SAVE_SPC_PART_IMAGE_MODE SaveSpcPartImageMode = GetProjectSaveSpcPartImageMode();
	SAVE_SPC_FILE_MODE    SaveSpcFileMode=AOIDataCollect.GetSaveProjectSpcFileMode();

	::CreateDirectory(ResultFolder, NULL);
	::CreateDirectory(RawFolder, NULL);
	::CreateDirectory(DebugFolder, NULL);	
	::CreateDirectory(OnlineTuningFolder, NULL);

	//先清除舊有的資料, 否則記憶體指標會亂掉
	if ( InitProjectInspectionData(LaneID) == false )
	{	return false; }

	FileMainName = ProjectPtr->GetProjectFileMainName();
	JetAPI::GetTime(TestDateTime, m_ProjectResultCurrent.sDateTimeS);//確保時間一樣
	CString strDate = TestDateTime.Left(8);
	CString strTime = TestDateTime.Right(6);

	ProjectFolder.Format(_T("%s\\%s"), TempFolder, FileMainName);
	::CreateDirectory(ProjectFolder, NULL);	::Sleep(0);

	ProjectDebugFolder.Format(_T("%s\\%s"), DebugFolder, FileMainName);
	::CreateDirectory(ProjectDebugFolder, NULL);	::Sleep(0);

	if ( AOI_CUSTOMER_ID_FOXCONN_LONGHUA == SystemParam.m_AOICustomerID )
	{	AIImageFolder = AOIDataCollect.CreateAIImageTempFolder(FileMainName, TestDateTime);	}
	else
	{
		TempFolder1.Format(_T("%s\\%s"), AOIDataCollect.GetAIImageExportFolder(), FileMainName);
		::CreateDirectory(TempFolder1, NULL);	::Sleep(0);
		TempFolder2.Format(_T("%s\\%s"), TempFolder1, strDate);
		::CreateDirectory(TempFolder2, NULL);	::Sleep(0);
		AIImageFolder.Format(_T("%s\\%s"), TempFolder2, strTime);		
		::CreateDirectory(AIImageFolder, NULL);	::Sleep(0);
	}

	SpcProjectFolder.Format(_T("%s\\%s"), ResultFolder, FileMainName);
	::CreateDirectory(SpcProjectFolder, NULL);	::Sleep(0);

	BarcodeProjectFolder.Format(_T("%s\\%s"), BarcodeFolder, FileMainName);
	::CreateDirectory(BarcodeProjectFolder, NULL);	::Sleep(0);	

	SpcImageFolderLocal.Format(_T("%s\\%s"), ProjectFolder, TestDateTime);
	::CreateDirectory(SpcImageFolderLocal, NULL);	::Sleep(0);

	SpcFileFolder.Format(_T("%s\\%s"), SpcProjectFolder, _T("Spc"));
	::CreateDirectory(SpcFileFolder, NULL);	::Sleep(0);	

	SpcImageFolder.Format(_T("%s\\%s"), SpcProjectFolder, TestDateTime);
	::CreateDirectory(SpcImageFolder, NULL);	::Sleep(0);

	SpcResultFolder = AOIDataDefine.GetProjectSpcResultFolder(SpcProjectFolder, SaveSpcFileMode);	
	::CreateDirectory(SpcResultFolder, NULL);	::Sleep(0);			

	SpcPartImageFolder.Format(_T("%s\\%s"), SpcProjectFolder, PROJECT_SPC_COMPONENT_FOLDER);
	::CreateDirectory(SpcPartImageFolder, NULL);	::Sleep(0);		
	
	OfflineFolder = ProjectPtr->GetProjectInspectionOfflineFolder();
	OfflineFolderDefault = ProjectPtr->GetProjectInspectionOfflineFolderDefault();
	if ( TASK_TUNING_OFFLINE != TaskMode )
	{
		ProjectPtr->SetProjectInspectionOfflineFolder(OfflineFolderDefault);
		JetAPI::ClearFolder(OfflineFolderDefault);
	}	

	if ( JetAPI::IsFolderExist(AIImageFolder) == false)
	{
		m_ErrorString.Format(_T("Error, Create AI Image Folder Fault (%s)"), AIImageFolder);
		return false;
	}	
	if ( JetAPI::IsFolderExist(SpcImageFolder) == false)
	{
		m_ErrorString.Format(_T("Error, Create Spc Image Folder Fault (%s)"), SpcImageFolder);
		return false;
	}
	if ( JetAPI::IsFolderExist(SpcPartImageFolder) == false)
	{
		m_ErrorString.Format(_T("Error, Create Spc Component Image Folder Fault (%s)"), SpcPartImageFolder);
		return false;
	}
	if ( JetAPI::IsFolderExist(SpcImageFolderLocal) == false)
	{
		m_ErrorString.Format(_T("Error, Create Spc Image Local Folder Fault (%s)"), SpcImageFolderLocal);		
		return false;
	}

	if ( FN_ENABLE == SystemParam.m_SaveTestTrackFile )
	{
		TempFolder1.Format(_T("%s\\%s"), SystemParam.m_AOITestTrackFolder, FileMainName);
		::CreateDirectory(TempFolder1, NULL);	::Sleep(0);
		TestTrackFolder.Format(_T("%s\\%s%s"), TempFolder1, strDate, strTime);
		::CreateDirectory(TestTrackFolder, NULL);	::Sleep(0);	
		if ( JetAPI::IsFolderExist(TestTrackFolder) == false)
		{
			m_ErrorString.Format(_T("Error, Create Test Track Folder Fault (%s)"), TestTrackFolder);		
			return false;
		}
	}

	if ( SAVE_SPC_PART_IMAGE_EVERYONE == SaveSpcPartImageMode )
	{	JetAPI::ClearFolder(SpcPartImageFolder); }
	else if ( SAVE_SPC_PART_IMAGE_SELECTED == SaveSpcPartImageMode )
	{	ProjectPtr->DeleteProjectSpcPartImageSelected(SpcPartImageFolder); }
	else if ( SAVE_SPC_PART_IMAGE_SELECTED_COPY == SaveSpcPartImageMode ) 
	{	ProjectPtr->DeleteProjectSpcPartImageSelectedWithTheSameName(SpcPartImageFolder);	}
	
	ProjectPtr->SetProjectAlarmStop(false);
	ProjectPtr->SetProjectFdException(false);
	ProjectPtr->SetProjectIsException(false);	
	ProjectPtr->SetProjectActTaskMode(TaskMode);
	ProjectPtr->SetProjectInspectionResultFileTmp(_T(""));
	ProjectPtr->SetProjectUseLocalFolder(UseLocalFolder);
	ProjectPtr->SetProjectAIImageFolder(AIImageFolder);
	ProjectPtr->SetProjectSpcFolder(SpcProjectFolder);	
	ProjectPtr->SetProjectSpcFileFolder(SpcFileFolder);
	ProjectPtr->SetProjectSpcImageFolder(SpcImageFolder);
	ProjectPtr->SetProjectSpcResultFolder(SpcResultFolder);	
	ProjectPtr->SetProjectTestTrackFolder(TestTrackFolder);	
	ProjectPtr->SetProjectSpcPartImageFolder(SpcPartImageFolder);		
	ProjectPtr->SetProjectSpcImageFolderLocal(SpcImageFolderLocal);
	ProjectPtr->SetProjectOnlineBarcodeFolder(BarcodeProjectFolder);	

	if ( FN_ENABLE == SaveDropOutImage )
	{
		TempFolder1.Format(_T("%s\\%s"), ProjectDebugFolder, _T("DropOut"));
		::CreateDirectory(TempFolder1, NULL);
		TempFolder2.Format(_T("%s\\%s"), TempFolder1, TestDateTime);
		::CreateDirectory(TempFolder2, NULL);		
		ProjectPtr->SetProjectDebugFolderDropOut(TempFolder2);
	}
	else
	{	ProjectPtr->SetProjectDebugFolderDropOut(ProjectDebugFolder); }	

	if ( FN_ENABLE == SaveScratchImage )
	{
		TempFolder1.Format(_T("%s\\%s"), ProjectDebugFolder, _T("Scratch"));
		::CreateDirectory(TempFolder1, NULL);
		TempFolder2.Format(_T("%s\\%s"), TempFolder1, TestDateTime);
		::CreateDirectory(TempFolder2, NULL);		
		ProjectPtr->SetProjectDebugFolderScratch(TempFolder2);
	}
	else
	{	ProjectPtr->SetProjectDebugFolderScratch(ProjectDebugFolder); }	
	
	if ( FN_ENABLE == SaveDimonsionImage )
	{
		TempFolder1.Format(_T("%s\\%s"), ProjectDebugFolder, _T("Dimension"));
		::CreateDirectory(TempFolder1, NULL);
		TempFolder2.Format(_T("%s\\%s"), TempFolder1, TestDateTime);
		::CreateDirectory(TempFolder2, NULL);		
		ProjectPtr->SetProjectDebugFolderDimonsion(TempFolder2);
	}
	else
	{	ProjectPtr->SetProjectDebugFolderDimonsion(ProjectDebugFolder); }	

	AOIDataCollect.SetSaveProjectRawImageFolder(_T(""));
	if ( false == OfflineMode )
	{
		if ( AOIDataCollect.GetSaveProjectRawImage() == true )
		{
			CString RawFolder1, RawFolder2;
			RawFolder1.Format(_T("%s\\%s"), RawFolder, FileMainName);
			::CreateDirectory(RawFolder1, NULL);	::Sleep(0);
			RawFolder2.Format(_T("%s\\%s"), RawFolder1, TestDateTime);
			::CreateDirectory(RawFolder2, NULL);	::Sleep(0);
			AOIDataCollect.SetSaveProjectRawImageFolder(RawFolder2);
		}

		if ( true == OnlineTuningEnable )
		{
			OnlineTuningProjectFolder.Format(_T("%s\\%s"), OnlineTuningFolder, FileMainName);
			::CreateDirectory(OnlineTuningProjectFolder, NULL);	
			OnlineTuningImageFolder.Format(_T("%s\\%s"), OnlineTuningProjectFolder, TestDateTime);
			::CreateDirectory(OnlineTuningImageFolder, NULL);
			ProjectPtr->SetProjectOnlineTuningFolder(OnlineTuningImageFolder);

			if ( JetAPI::IsFolderExist(OnlineTuningImageFolder) == false)
			{
				m_ErrorString.Format(_T("Error, Create Online Tuning Folder Fault (%s)"), OnlineTuningImageFolder);
				return false;
			}
		}
		else
		{	ProjectPtr->SetProjectOnlineTuningFolder(_T("")); }

		if ( (SAVE_TEST_IMAGE_DISABLE==SaveFieldImageMode) || (TASK_INSPECT_PROJECT!=TaskMode) )
		{	ProjectPtr->SetProjectOnlineOfflineFolder(_T("")); }
		else
		{
			OnlineOfflineProjectFolder.Format(_T("%s\\%s"), OnlineOfflineFolder, FileMainName);
			::CreateDirectory(OnlineOfflineProjectFolder, NULL);	
			OnlineOfflineImageFolder.Format(_T("%s\\%s"), OnlineOfflineProjectFolder, TestDateTime);
			::CreateDirectory(OnlineOfflineImageFolder, NULL);
			ProjectPtr->SetProjectOnlineOfflineFolder(OnlineOfflineImageFolder);	

			if ( JetAPI::IsFolderExist(OnlineOfflineImageFolder) == false)
			{
				m_ErrorString.Format(_T("Error, Create Online Offline Folder Fault (%s)"), OnlineOfflineImageFolder);
				return false;
			}
		}		
	}
	
	if ( TASK_INSPECT_PROJECT == TaskMode )
	{
		const bool bSaveFiledUsingThread=ProjectPtr->GetProjectSaveFiledUsingThread();
		if ( true == bSaveFiledUsingThread )
		{			
			if ( ProjectPtr->StartProjectSaveFieldThread(true) == false )
			{	return false;	}
		}
	}
	AOIDataCollect.SaveMovingTimeMsg(_T("CAOIProject::InitProjectInspection End"));
	return true;
}
//-------------------------------------------------------------------------------------//
CAOIWnd* CAOIProject::FindProjectWndByUUID(const UUID &uuid)//尋找專案內的檢測框
{
	size_t i=0;
	CAOIWnd       *WndPtr = NULL;
	CAOIModel     *ModelPtr = NULL;
	CAOIComponent *ComponentPtr = NULL;
	const size_t ComponentCount = GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }

		ModelPtr = ComponentPtr->GetComponentModelPtr();
		WndPtr = ModelPtr->GetModelWndPtrByUUID(uuid);
		if ( NULL != WndPtr ) { return WndPtr; }
	}
	return NULL;
}
//-------------------------------------------------------------------------------------//
CAOILand* CAOIProject::FindProjectLandByUUID(const UUID &uuid)//尋找專案內的檢測框
{
	size_t i=0;
	CAOILand      *LandPtr = NULL;
	CAOIModel     *ModelPtr = NULL;
	CAOIComponent *ComponentPtr = NULL;
	const size_t ComponentCount = GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }

		ModelPtr = ComponentPtr->GetComponentModelPtr();
		LandPtr = ModelPtr->GetModelLandPtrByUUID(uuid);
		if ( NULL != LandPtr ) { return LandPtr; }
	}
	return NULL;
}
//-------------------------------------------------------------------------------------//
CAOIModel* CAOIProject::FindProjectModelByUUID(const UUID &uuid)//尋找專案內的檢測框
{
	size_t i=0;	
	RPC_STATUS     Status=0;	
	UUID           ModelUUID;
	UUID           RefUUID = uuid;
	CAOIModel     *ModelPtr = NULL;		
	CAOIComponent *ComponentPtr = NULL;
	const size_t ComponentCount = GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }

		ModelPtr = ComponentPtr->GetComponentModelPtr();
		ModelUUID = ModelPtr->GetObjUuid();
		if ( ::UuidEqual(&ModelUUID, &RefUUID, &Status) == FALSE ) { continue; }	
		return ModelPtr;
	}
	return NULL;
}
