//-------------------------------------------------------------------------------------//
void CAOIProject::BuildProjectSaveModelImageOnOff_AI_Text(int Val, CString &Text) const//儲存模組圖片開關-AI	
{
	CString str;
	DWORD Bit = 1;
	DWORD Flag = (DWORD)(Val);	
	const bool ShowUniID = false;
	const std::vector<TFrameParam> &List=m_ProjectFrameParamList;//影像參數列表	
	const size_t Count = List.size();

	Text = _T("");
	for ( size_t i=0; i<Count; i++ )
	{
		const TFrameParam &Node = List[i];
		if ( 0 != (Flag&Bit) )
		{
			if ( Text.GetLength() == 0 )
			{	Text = Node.GetFrameGridName(ShowUniID);	}
			else
			{
				str = Text;
				Text.Format(_T("%s;%s"), str, Node.GetFrameGridName(ShowUniID));
			}
		}
		Bit = Bit << 1;
	}
	return;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::DecodeProjectSaveModelImageOnOff_AI(int OnOff, size_t Count, std::vector<bool> &OnOffList) const//解碼儲存模組圖片開關-AI	
{
	DWORD Bit = 1;
	DWORD Flag = OnOff;	
	OnOffList.resize(Count, true);
	for ( size_t i=0; i<Count; i++ )
	{
		if ( 0 != (Flag&Bit) )
		{	OnOffList[i] = true;	}
		else
		{	OnOffList[i] = false;	}
		Bit = Bit << 1;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CheckProjectSpecTestFieldDefectPart()//確認專案特殊檢測視野瑕疵零件-整板零件
{
	CAOIProject *ProjectPtr=this;
	if ( CheckProjectSpecTestEnabled() == false ) { return true; }	

	CString ComName;
	RESULT_ID ResultID;
	CAOIField *FieldPtr=NULL;	
	std::set<CAOIField*> FieldSet;
	std::vector<CAOIField*> FieldList;
	CAOIComponent *ComponentPtr=NULL;
	const size_t ComponentCount = ProjectPtr->GetProjectComponentCount();
	for ( size_t i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->CheckComponentType_ModelTest() == true ) { continue; }
		ComName = ComponentPtr->GetComponentName();
		ResultID = ComponentPtr->GetComponentResultID_AOI();
		if ( RESULT_ID_NONE == ResultID ) { continue; }
		if ( RESULT_ID_OK == ResultID ) { continue; }
		if ( RESULT_ID_BYPASS == ResultID ) { continue; }
		if ( RESULT_ID_SKIP == ResultID ) { continue; }
		//RESULT_ID_NG
		//RESULT_ID_EXCEPTION
		FieldPtr = ComponentPtr->GetComponentFieldPtr();
		if ( NULL == FieldPtr ) { continue; }
		size_t BefCnt=FieldSet.size();
		FieldSet.insert(FieldPtr);
		if ( BefCnt != FieldSet.size() )
		{	FieldList.push_back(FieldPtr);	}
	}
	const size_t Count=FieldList.size();
	for ( size_t i=0; i<Count; i++ )
	{
		FieldPtr = FieldList[i];
		if ( NULL == FieldPtr ) { continue; }

		CAOIRgn *RgnPtr=NULL;
		bool bFindComponent=false;
		const size_t FeildRgnCount=FieldPtr->GetFieldRgnPtrCount();
		for ( size_t j=0; j<FeildRgnCount; j++ )
		{
			RgnPtr = FieldPtr->GetFieldRgnPtr(j, false);
			if ( NULL == RgnPtr ) { continue; }
			if ( RgnPtr->GetRgnParent() != NULL )
			{	RgnPtr = RgnPtr->GetRgnParent();	}			
			if ( AOI_OBJ_COMPONENT == RgnPtr->GetObjType() )
			{
				ComponentPtr = dynamic_cast<CAOIComponent*>(RgnPtr);
				if ( NULL == ComponentPtr ) { continue; }
				if ( ComponentPtr->CheckComponentType_ModelTest() == true )
				{
					bFindComponent = true;
					break;
				}
			}
		}
		if ( true == bFindComponent ) { continue; }		
		for ( size_t j=0; j<FeildRgnCount; j++ )
		{
			RgnPtr = FieldPtr->GetFieldRgnPtr(j, false);
			if ( NULL == RgnPtr ) { continue; }
			if ( RgnPtr->GetRgnParent() != NULL )
			{	RgnPtr = RgnPtr->GetRgnParent();	}			
			if ( AOI_OBJ_COMPONENT == RgnPtr->GetObjType() )
			{
				ComponentPtr = dynamic_cast<CAOIComponent*>(RgnPtr);
				if ( NULL == ComponentPtr ) { continue; }
				if ( ComponentPtr->CheckComponentType_FullMap() == true )
				{
					ComponentPtr->SetComponentResultID_AOI(RESULT_ID_NG);
					bFindComponent = true;
					break;
				}
			}
		}
	}
	return true;
}
bool CAOIProject::AddProjectSpecTestComonentList(std::vector<CAOIComponent*> &SpecComponentList)
{
	size_t i=0;
	CAOIComponent *ComponentPtr=NULL;
	const size_t SpecTestCount = SpecComponentList.size();
	for ( i=0; i<SpecTestCount; i++ )
	{
		ComponentPtr = SpecComponentList[i];
		if ( NULL == ComponentPtr ) { continue; }		
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }		
		AddProjectComponentPtr(ComponentPtr, false);				
	}
	for ( i=0; i<SpecTestCount; i++ )
	{
		ComponentPtr = SpecComponentList[i];
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == false ) { continue; }
		AOIObjManager.DestroyComponentObj(SpecComponentList[i]);
	}
	SpecComponentList.clear();
	return true;
}
