bool CAOIProject::ResetProjectTop10List(std::vector<TTop10Node> &Top10List, bool ResetAOI, bool ResetARS)//重設前十大不良
{
	size_t       i=0;
	TTop10Node  *Top10NodelPtr=NULL;	
	const size_t Count = Top10List.size();

	for ( i=0; i<Count; i++ )
	{
		Top10NodelPtr = &(Top10List[i]);
		if ( NULL == Top10NodelPtr ) { continue; }
		if ( true == ResetAOI )
		{	Top10NodelPtr->DefectCountAOI = 0; }
		if ( true == ResetARS )
		{	Top10NodelPtr->DefectCountARS = 0; }
	}
	return true;
}
