bool CAOIProject::AnalyzeProjectComponentMasterResult()//分析專案零件本尊結果
{	
	CAOIProject *ProjectPtr = this;

	CString         str;
	CString         ComName;
	CString         ExtName;
	CString         MainName;	
	RESULT_ID       ResultID;
	unsigned int    UniqueID=0;
	std::vector<unsigned int> UniqueIDList;	
	CAOIComponent  *ComponentPtr =NULL;
	const size_t    ComponentCount=GetProjectComponentCount();	
	CString         AIImageFolder = ProjectPtr->GetProjectAIImageFolder();
	CString         SpcImageFolder = ProjectPtr->GetProjectSpcImageFolder();

	ProjectPtr->CloneProjectFrameUniqueIDList(UniqueIDList);//複製專案影像表格編號列表	
	const size_t FrameUniqueIDCount = UniqueIDList.size();

	if ( GetProjectUseLocalFolder() )
	{	SpcImageFolder = GetProjectSpcImageFolderLocal();	}	

	ExtName = _T("JPG");

	for ( size_t i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
		//if ( ComponentPtr->GetComponentNeedToCalculate() == false ) { continue; }
		if ( ComponentPtr->CheckComponentOrAgentNeedToCalculate() == false ) { continue; }		
		if ( ComponentPtr->CheckComponentIsMaster() == false ) { continue; }
		ComponentPtr->UpdateComponentMasterResultID();
		ResultID = ComponentPtr->CheckComponentResultID_AOI();
		if ( RESULT_ID_OK == ResultID )
		{			
			CString ComName = ComponentPtr->GetComponentFullName();
			bool ComponentModelImageIsSaved = ComponentPtr->GetComponentModelImageIsSaved();
			if ( true == ComponentModelImageIsSaved )
			{	//移除瑕疵圖檔案				
				MainName.Format(_T("%s\\%s"), SpcImageFolder, ComName);
				for ( size_t k=0; k<FrameUniqueIDCount; k++ )
				{
					UniqueID = UniqueIDList[k];
					str.Format(_T("%s#%d.%s"), MainName, k+1, ExtName);
					::DeleteFile(str);

					if ( FRAME_UNIQUE_ID_DLP == UniqueID )
					{
						str.Format(_T("%s#%d.%s"), MainName, k+1, EXT_NAME_SPACE);
						::DeleteFile(str);
					}					
				}
				ComponentPtr->SetComponentModelImageIsSaved(false);
			}

			bool ComponentModelImageIsSaved_AI = ComponentPtr->GetComponentModelImageIsSaved_AI();
			if ( true == ComponentModelImageIsSaved_AI )
			{	//移除瑕疵圖檔案				
				MainName.Format(_T("%s\\%s"), AIImageFolder, ComName);
				const bool bSave3D = GetProjectSaveModelImage3DFile_AI();
				for ( size_t k=0; k<FrameUniqueIDCount; k++ )
				{	
					UniqueID = UniqueIDList[k];
					str = AOIDataDefine.GetAITempName(MainName, k);
					str = str+CString(_T(".JPG"));	
					::DeleteFile(str);

					if ( true==bSave3D && FRAME_UNIQUE_ID_DLP==UniqueID )
					{
						str = AOIDataDefine.GetAITempName(MainName, k);
						str = str+CString(EXT_NAME_SPACE);
						::DeleteFile(str);
					}
				}
				ComponentPtr->SetComponentModelImageIsSaved_AI(false);
			}
		}		
	}	
	return true;
}
