//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectGrrSigmaItemFile(LPCTSTR pfilename)
{
#ifndef OFFLINE_VERSION
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }
	if ( NULL == pfilename ) { return false; }

	CString       str;	
	double        fnTime=0;
	bool          IsOK=false;	
	CAOIFileIO    FileIO;
	CString       Filename=pfilename;

	//FileIO.CreateProgressWnd();
	FileIO.SetFileTarget(FILE_TARGET_OTHERS);		
	
	FileIO.SetFileName(Filename);
	if ( FileIO.OpenSaveFile(Filename) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		return false;
	}
	if ( WriteProjectGrrSigmaItemFile(FileIO) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		return false; 
	}
	FileIO.CloseFile();
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::WriteProjectGrrSigmaItemFile(CAOIFileIO &FileIO)
{
#ifndef OFFLINE_VERSION
#ifdef _DEBUG
	if ( FileIO.CheckFileMode() == false ) { return false; }
	if ( FileIO.CheckFileOpened() == false ) { return false; }
#endif//_DEBUG

	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false )
	{	return false; }

	CAOIComponent *ComponentPtr = NULL;
	UUID     uuid = GetObjUuid();	
	char     uuidStr[MAX_JET_PATH]="";	
	wchar_t  uuidWStr[MAX_JET_PATH]=L"";		
	const size_t ComponentCount = ProjectPtr->GetProjectComponentCount();

	FileIO.SetFnName(_T("CAOIProject::WriteProjectGrrSigmaItemFile"));
	if ( FileIO.SaveChunk_INT(FILE_IO_START, 0) == false ) { return false; }	
	if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_SECTION_START, 0) == false ) { return false; }
	for ( size_t i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		COMPONENT_TYPE ComponentType = ComponentPtr->GetComponentType();
		if ( COMPONENT_TYPE_SCRATCH == ComponentType ) { continue; }
		if ( COMPONENT_TYPE_DROP_OUT == ComponentType ) { continue; }
		if ( COMPONENT_TYPE_TEMPORARY == ComponentType ) { continue; }

		uuid = ComponentPtr->GetObjUuid();	
		JetAPI::UUIDToStringA(uuid, uuidStr);
		JetAPI::UUIDToStringW(uuid, uuidWStr);

		if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_START, 0) == false ) { return false; }	
		if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_PANEL_INDEX, ComponentPtr->GetComponentPanelIndex_Project()) == false ) { return false; }
		if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_BOARD_INDEX, ComponentPtr->GetComponentBoardIndex_Project()) == false ) { return false; }
		if ( FileIO.SaveChunk_STR(FILE_IO_COMPONENT_NAME, ComponentPtr->GetComponentName()) == false ) { return false; }
		if ( FileIO.GetSaveWStr() == true ) 
		{	
			if ( FileIO.SaveChunk_STR(FILE_IO_COMPONENT_OBJ_UUID, uuidWStr) == false )
			{	return false; } 
		}
		else
		{	
			if ( FileIO.SaveChunk_STR(FILE_IO_COMPONENT_OBJ_UUID, uuidStr) == false )
			{	return false; } 
		}
		if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_GRR_SIGMA_ITEM_INDEX, ComponentPtr->GetComponentGrrSigmaItemIdx()) == false ) { return false; }		
		if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_GRR_SIGMA_ITEM_LIST_NODE, 0) == false ) { return false; }			
		const auto &rList=ComponentPtr->GetComponentGrrSigmaItemList();
		for ( size_t j=0; j<rList.size(); j++ )
		{
			if ( FileIO.WriteGrrSigmaItemFile(rList[j]) == false )
			{	return false; }		
		}
		if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_END, 0) == false ) { return false; }	
	}	
	if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_SECTION_END, 0) == false ) { return false; }	
	if ( FileIO.SaveChunk_INT(FILE_IO_END, 0) == false ) { return false; }
#endif//OFFLINE_VERSION
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectGrrSigmaItemFile()
{
	if ( CheckProjectGrrSigmaItemEnabled() == false ) { return true; }

	CString FileFolder;	
	CString Filename = GetProjectShowName();
	JetAPI::ExtractMainFileName(Filename, FileFolder);	
	Filename = AOIDataDefine.GetProjectGrrSigmaItemFileName(FileFolder);
	if ( JetAPI::IsFileExist(Filename) == false )
	{	return true;	}
	if ( LoadProjectGrrSigmaItemFile(Filename) == false )
	{
		SetProjectExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectGrrSigmaItemFile(LPCTSTR pfilename)
{
#ifndef OFFLINE_VERSION
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }
	if ( NULL == pfilename ) { return false; }

	CAOIFileIO     FileIO;	
	CString        Filename = pfilename;
	
	FileIO.SetFileName(Filename);
	if ( FileIO.OpenLoadFile(Filename) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		return false;
	}
	if ( ReadProjectGrrSigmaItemFile(FileIO) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		FileIO.CloseFile();
		return false;
	}
	FileIO.CloseFile();
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ReadProjectGrrSigmaItemFile(CAOIFileIO &FileIO)
{
#ifndef OFFLINE_VERSION
#ifdef _DEBUG
	if ( FileIO.CheckFileMode() == false ) { return false; }
	if ( FileIO.CheckFileOpened() == false ) { return false; }
#endif//_DEBUG

	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }
	
	UUID           uuid;	
	size_t         i=0;	
	int            index = 0;
	double         dValue = 0.0;
	bool           bGetUuid=false;
	unsigned int   PanelIndex=0;
	unsigned int   BoardIndex=0;	
	int            GrrSigmaItemIdx=0;
	bool           bWrongComponent=false;
	CString        BoardBarcode;
	CString        PanelBarcode;
	CString        ProjectBarcode;	
	CString        ComponentName;	
	CString        ComponentName2;	
	CAOIComponent *ComponentPtr = NULL;		
	TGrrSigmaItem  GrrSigmaItem;
	std::vector<TGrrSigmaItem> GrrSigmaItemList;
	FileIO.SetFnName(_T("CAOIProject::ReadProjectGrrSigmaItemFile"));		
	//----------------------------------------------------------------------------------------//	
	while ( FileIO.CheckFileEnd()==false )
	{ 		
		if ( FileIO.LoadChunk(index) == false )		
		{	continue; }		
		
		switch ( index )
		{
		case FILE_IO_START:
			break;		
		case FILE_IO_END:
			return true;
			break;
		case FILE_IO_COMPONENT_SECTION_START://零件區間參數-起點
			break;
		case FILE_IO_COMPONENT_SECTION_END://零件區間參數-終點
			break;
		case FILE_IO_COMPONENT_START://零件參數-起點
			PanelIndex = -1;
			BoardIndex = -1;
			ComponentName = _T("");
			bGetUuid=false;
			GrrSigmaItemIdx = -1;
			GrrSigmaItemList.clear();
			bWrongComponent = false;			
			break;
		case FILE_IO_COMPONENT_END://零件參數-終點
			if ( true == bGetUuid )
			{
				ComponentPtr = ProjectPtr->GetProjectComponentPtrByComponentUUID(uuid);
				if ( NULL != ComponentPtr )
				{
				#ifdef _DEBUG					
					ComponentName2 = ComponentPtr->GetComponentName();
					if ( ComponentName.CompareNoCase(ComponentName2) != 0 )
					{	bWrongComponent = true;	}
				#endif//_DEBUG
					ComponentPtr->SetComponentGrrSigmaItemIdx(GrrSigmaItemIdx);						
					ComponentPtr->SetComponentGrrSigmaItemList(GrrSigmaItemList);	
				}
			}
			bGetUuid = false;
			GrrSigmaItemIdx = -1;
			GrrSigmaItemList.clear();
			break;		
		case FILE_IO_COMPONENT_PANEL_INDEX://零件參數-的整板引數
			PanelIndex = (FileIO.GetData_INT());
			break;
		case FILE_IO_COMPONENT_BOARD_INDEX://零件參數-的單板引數
			BoardIndex = (FileIO.GetData_INT());
			break;
		case FILE_IO_COMPONENT_NAME://零件參數-名稱			
			if ( FileIO.GetLoadWStr()==true )
			{	ComponentName = (FileIO.GetData_WSTR());	}
			else
			{	ComponentName = (FileIO.GetData_STR()); }
			break;
		case FILE_IO_COMPONENT_OBJ_UUID://零件參數-的UUID
			bGetUuid=false;
			if ( FileIO.GetLoadWStr()==true )
			{
				if ( JetAPI::UUIDFromStringW(FileIO.GetData_WSTR(), uuid) == true )
				{	bGetUuid = true;	}
			}
			else
			{
				if ( JetAPI::UUIDFromStringA(FileIO.GetData_STR(), uuid) == true )
				{	bGetUuid = true;	}
			}			
			break;
		case FILE_IO_COMPONENT_GRR_SIGMA_ITEM_INDEX://零件參數-GRR標準差引數
			GrrSigmaItemIdx = FileIO.GetData_INT();
			break;
		case FILE_IO_COMPONENT_GRR_SIGMA_ITEM_LIST_NODE:
			GrrSigmaItemList.clear();
			break;
		case FILE_IO_GRR_SIGMA_ITEM_START:
			GrrSigmaItem.Count = 0;
			GrrSigmaItem.Barcode = L"";
			if ( FileIO.ReadGrrSigmaItemFile(GrrSigmaItem) == false )
			{	return false; }
			GrrSigmaItemList.push_back(GrrSigmaItem);
			break;
		}
	};
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ResetProjectGrrSigmaItem_Barcode()
{	
	const std::wstring ProjectBarcode = GetProjectBarcode();
	const std::wstring ProjectBarcodeLast = GetProjectBarcodeLast();	
	if ( ProjectBarcode == ProjectBarcodeLast )
	{	return true; }

	const bool bChkBarcode = true;	
	CAOIComponent *ComponentPtr = NULL;	
	const size_t   ComponentCount = GetProjectComponentCount();
	for ( size_t i=0; i<ComponentCount; i++ )//全部零件數	
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }			
		ComponentPtr->ResetComponentGrrSigmaItem(ProjectBarcode.c_str(), bChkBarcode);			
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ResetProjectGrrSigmaItem_Match()
{
	CAOIComponent *ComponentPtr = NULL;
	const std::wstring ProjectBarcode = GetProjectBarcode();
	const size_t   ComponentCount = GetProjectComponentCount();		
	const int MaxGrrSigmaItemCount=GRR_SIGMA_ITEM_MAX_COUNT;	
	const TSystemParameter &SystemParam = AOIDataCollect.GetSystemParameter();	

	CString str;
	bool GrrAdded = true;
	double GrrOffsetX=0;
	double GrrOffsetY=0;
	double GrrSkewA=0;
	double GrrBodyHeight=0;
	int AddCount=0;
	int TotalCount=0;
	int ComponentUsed=0;
	int ComponentGrrSigmaItemIdx=0;
	size_t ComponentGrrSigmaItem=0;
	int ComponentPass[MaxGrrSigmaItemCount]={0};
	int ComponentTotal[MaxGrrSigmaItemCount]={0};
	double ComponentPassRatio[MaxGrrSigmaItemCount]={0};
	::memset(ComponentPass, 0x00, sizeof(ComponentPass));
	::memset(ComponentTotal, 0x00, sizeof(ComponentPass));
	::memset(ComponentPassRatio, 0x00, sizeof(ComponentPassRatio));			
	for ( int j=0; j<MaxGrrSigmaItemCount; j++ )
	{
		AddCount = 0;
		TotalCount = 0;
		for ( size_t i=0; i<ComponentCount; i++ )//全部零件數	
		{
			GrrAdded = false;
			ComponentPtr = GetProjectComponentPtr(i, false);
			if ( NULL == ComponentPtr ) { continue; }							
			if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
			if ( ComponentPtr->GetComponentNeedToCalculate() == false ) { continue; }
			ComponentGrrSigmaItemIdx = ComponentPtr->GetComponentGrrSigmaItemIdx();
			ComponentGrrSigmaItem = ComponentPtr->GetComponentGrrSigmaItemList().size();
			if ( j >= ComponentGrrSigmaItem )
			{	continue; }

			TotalCount ++;			
			ComponentPtr->SetComponentGrrSigmaItemIdx(j);
			ComponentPtr->GetComponentGrrTempValue(GrrOffsetX, GrrOffsetY, GrrSkewA, GrrBodyHeight);				
			ComponentPtr->UpdateComponentGrrValue(GrrOffsetX, GrrOffsetY, GrrSkewA, GrrBodyHeight, GrrAdded);					
			ComponentPtr->SetComponentGrrSigmaItemIdx(ComponentGrrSigmaItemIdx);
			if ( true == GrrAdded )
			{	AddCount ++;	}
		}
		ComponentPass[j] = AddCount;
		ComponentTotal[j] = TotalCount;
		if ( 0 == TotalCount )
		{	ComponentPassRatio[j] = 0.0; }
		else
		{	ComponentPassRatio[j] = (100.0*AddCount)/TotalCount;	}

		if ( TotalCount > 0 )
		{	
			str.Format(_T("CAOIProject::ProjectMatchRatio[%d]=%.1f"), j+1, ComponentPassRatio[j]);
			AOIDataCollect.SaveMovingTimeMsg(str);
		}
	}					
		
	double MaxPassRatio=0;
	int MaxPassRatioIdx=INVALID_INDEX;
	const double MasPassRatioLSL = SystemParam.m_GrrAverageResetMatchRatio;			
	for ( int j=0; j<MaxGrrSigmaItemCount; j++ )
	{
		if ( INVALID_INDEX==MaxPassRatioIdx || MaxPassRatio<ComponentPassRatio[j] )
		{
			MaxPassRatioIdx = j;
			MaxPassRatio = ComponentPassRatio[j];
		}
	}		
	if ( MaxPassRatio < MasPassRatioLSL )
	{	MaxPassRatioIdx = INVALID_INDEX;	}
	str.Format(_T("CAOIProject::ProjectMatchRatioIdx=%d"), MaxPassRatioIdx+1);
	AOIDataCollect.SaveMovingTimeMsg(str);
	const bool bChkBarcode = false;
	for ( size_t i=0; i<ComponentCount; i++ )//全部零件數	
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }							
		if ( INVALID_INDEX != MaxPassRatioIdx )
		{	ComponentPtr->SetComponentGrrSigmaItemIdx(MaxPassRatioIdx);	}
		else
		{	ComponentPtr->ResetComponentGrrSigmaItem(ProjectBarcode.c_str(), bChkBarcode);	}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AddProjectStatisticRecords()//加入專案統計紀錄
{
	size_t         i=0, j=0;	
	CAOIComponent *ComponentPtr = NULL;
	const LANE_ID  LaneID = GetProjectActLaneID();
	TTestResult    TestResult = GetProjectResultLatest();
	TTestResult    StatisResult = GetProjectResultStatistic();
	TTestResult    StatisResultLane = GetProjectResultStatistic_Lane(LaneID);
	const bool bIsGetBarcode = GetProjectIsGetBarcode();
	const TProjectParameter &Param = GetProjectParameter();
	const size_t   ComponentCount = GetProjectComponentCount();		
	const std::wstring ProjectBarcode = GetProjectBarcode();
	//const std::wstring ProjectBarcodeLast = GetProjectBarcodeLast();
	const TSystemParameter &SystemParam = AOIDataCollect.GetSystemParameter();	
	if ( FN_ENABLE == SystemParam.m_GrrAverageResetEnabled )
	{
		if ( true == bIsGetBarcode )
		{	ResetProjectGrrSigmaItem_Barcode();	}
		else
		{	ResetProjectGrrSigmaItem_Match();	}
	}
	SetProjectBarcodeLast(ProjectBarcode.c_str());

	//全部零件數
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }		
		ComponentPtr->AddComponentGrrSigmaItem();
		ComponentPtr->AddComponentResultToStatisticAOI(LaneID);//加入零件結果至統計內
		ComponentPtr->AddComponentResultSigmaItem_Lane(LaneID);	
	}	

	AddProjectStatisticResult(TestResult, StatisResult);
	AddProjectStatisticResult(TestResult, StatisResultLane);
	
	SetProjectResultStatistic(StatisResult);	
	SetProjectResultStatistic_Lane(LaneID, StatisResultLane);	

	STATISTIC_BY_MODE StatisticByMode = Param.m_StatisticByMode;	
	if ( DEFECT_FROM_AOI==Param.m_StatisticDefectFromMode && STATISTIC_BY_NONE!=StatisticByMode )
	{
		AddProjectResultAOI(TestResult);
		ShiftProjectResultListAOI();
	}

	AddProjectResultCpkList_Lane(LaneID);
	SaveProjectGrrSigmaItemFile();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AddProjectStatisticRecords_ARS(LANE_ID LaneID)//加入專案統計紀錄-ARS
{
	size_t         i=0, j=0;	
	CAOIComponent *ComponentPtr = NULL;
	TTestResult    TestResult = GetProjectResultLatest_ARS();
	TTestResult    StatisResult = GetProjectResultStatistic_ARS();
	TTestResult    StatisResultLane = GetProjectResultStatistic_ARS_Lane(LaneID);
	const TProjectParameter &Param = GetProjectParameter();
	const size_t   ComponentCount = GetProjectComponentCount();		

	//全部零件數
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
		ComponentPtr->AddComponentResultToStatisticARS(LaneID);//加入零件結果至統計內
	}	

	AddProjectStatisticResult(TestResult, StatisResult);	
	AddProjectStatisticResult(TestResult, StatisResultLane);	
	
	SetProjectResultStatistic_ARS(StatisResult);
	SetProjectResultStatistic_ARS_Lane(LaneID, StatisResultLane);

	STATISTIC_BY_MODE StatisticByMode = Param.m_StatisticByMode;	
	if ( DEFECT_FROM_ARS==Param.m_StatisticDefectFromMode && STATISTIC_BY_NONE!=StatisticByMode )
	{
		AddProjectResultARS(TestResult);
		ShiftProjectResultListARS();
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AnalyzeProjectStatisticAlarm()//分析專案統計警報	
{
	size_t         i=0, j=0;
	CString        strAlaram;
	CString        strAlaram2;
	CString        strAlaram3;	
	CString        ComponentName;	
	size_t         ComponentDefectCountAOI = 0;
	size_t         ComponentDefectCountARS = 0;
	size_t         ComponentContinueNGCntAOI=0;
	size_t         ComponentContinueNGCntARS=0;	

	bool           bAlaram=false;
	bool           bAlaramOnARS=false;
	bool           bYieldOn = false;
	CAOIComponent *ComponentPtr = NULL;		
	bool           ComponentEnableAlarm=false;		
	TTestResult    TestResult;
	const TProjectParameter &Param = GetProjectParameter();	
	const size_t   ComponentCount = GetProjectComponentCount();	
	const ALARM_LOCK_MODE AlarmLockMode = Param.m_AlarmLockMode;
	DEFECT_HANDLE_MODE DefectHandleMode = Param.m_DefectHandleMode;
	DEFECT_FROM_MODE   DefectFromMode = Param.m_StatisticDefectFromMode;	

	CString strTest = AOIDataDefine.GetTestText();
	CString strPanel = AOIDataDefine.GetPanelText();
	CString strBoard = AOIDataDefine.GetBoardText();
	CString strYield = AOIDataDefine.GetYieldText();
	CString strRatio = AOIDataDefine.GetRatioText();
	CString strDefect = AOIDataDefine.GetDefectText();	
	CString strContinue = AOIDataDefine.GetContinueText();
	CString strComponent = AOIDataDefine.GetComponentText();
	CString strDefectFromAOI = AOIDataDefine.GetDefectFromText(DEFECT_FROM_AOI);
	CString strDefectFromARS = AOIDataDefine.GetDefectFromText(DEFECT_FROM_ARS);
	double dTestYielding=0.0, dPanelYielding=0.0, dBoardYielding=0.0, dComponentYielding=0.0;
	
	if ( DEFECT_HANDLE_STOP_ALARM == DefectHandleMode )
	{
		TestResult = GetProjectResultLatest();
		switch ( TestResult.sResultID )
		{
		case TEST_RESULT_NG:
		case TEST_RESULT_FD:
			SetProjectAlarmStop(true);
			break;
		}		
	}
	if ( DEFECT_FROM_NONE == DefectFromMode )
	{	return true; }
	else if ( DEFECT_FROM_AOI == DefectFromMode )
	{	
		bYieldOn = GetProjectResultYieldOnAOI();
		TestResult = GetProjectResultLatest();
	}
	else if ( DEFECT_FROM_ARS == DefectFromMode )
	{
		bYieldOn = GetProjectResultYieldOnARS();
		TestResult = GetProjectResultLatest_ARS();
	}	

	if ( true == bYieldOn )//統計良率開始
	{	
		if ( DEFECT_FROM_AOI == DefectFromMode )
		{	CalcProjectResultYieldingAOI(dTestYielding, dPanelYielding, dBoardYielding, dComponentYielding); }
		else if ( DEFECT_FROM_ARS == DefectFromMode )
		{	CalcProjectResultYieldingARS(dTestYielding, dPanelYielding, dBoardYielding, dComponentYielding);	}	

		if ( Param.m_AlaramTestYieldMin > 0.0 ) 
		{
			if ( dTestYielding < Param.m_AlaramTestYieldMin )
			{
				strAlaram3 = GetProjectAlarmString();
				if ( DEFECT_FROM_AOI == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s[%.2f]"), strDefectFromAOI, strTest, strYield, dTestYielding);	}
				else if ( DEFECT_FROM_ARS == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s[%.2f]"), strDefectFromARS, strTest, strYield, dTestYielding);	}
				
				if ( strAlaram3.GetLength() == 0 ) 
				{	strAlaram = strAlaram2; }
				else
				{	strAlaram.Format(_T("%s\n%s"), strAlaram3, strAlaram2); }				
				SetProjectAlarmDefect(true);
				SetProjectAlarmString(strAlaram);		
			}
		}

		if ( Param.m_AlaramPanelYieldMin > 0.0 ) 
		{
			if ( dPanelYielding < Param.m_AlaramPanelYieldMin )
			{
				strAlaram3 = GetProjectAlarmString();
				if ( DEFECT_FROM_AOI == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s[%.2f]"), strDefectFromAOI, strPanel, strYield, dPanelYielding);	}
				else if ( DEFECT_FROM_ARS == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s[%.2f]"), strDefectFromARS, strPanel, strYield, dPanelYielding);	}
				
				if ( strAlaram3.GetLength() == 0 ) 
				{	strAlaram = strAlaram2; }
				else
				{	strAlaram.Format(_T("%s\n%s"), strAlaram3, strAlaram2); }				
				SetProjectAlarmDefect(true);
				SetProjectAlarmString(strAlaram);		
			}
		}

		if ( Param.m_AlaramBoardYieldMin > 0.0 ) 
		{
			if ( dBoardYielding < Param.m_AlaramBoardYieldMin )
			{
				strAlaram3 = GetProjectAlarmString();
				if ( DEFECT_FROM_AOI == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s[%.2f]"), strDefectFromAOI, strBoard, strYield, dBoardYielding);	}
				else if ( DEFECT_FROM_ARS == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s[%.2f]"), strDefectFromARS, strBoard, strYield, dBoardYielding);	}
				
				if ( strAlaram3.GetLength() == 0 ) 
				{	strAlaram = strAlaram2; }
				else
				{	strAlaram.Format(_T("%s\n%s"), strAlaram3, strAlaram2); }				
				SetProjectAlarmDefect(true);
				SetProjectAlarmString(strAlaram);		
			}
		}	

		if ( Param.m_AlaramComponentYieldMin > 0.0 ) 
		{
			if ( dComponentYielding < Param.m_AlaramComponentYieldMin )
			{
				strAlaram3 = GetProjectAlarmString();
				if ( DEFECT_FROM_AOI == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s[%.2f]"), strDefectFromAOI, strComponent, strYield, dComponentYielding);	}
				else if ( DEFECT_FROM_ARS == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s[%.2f]"), strDefectFromARS, strComponent, strYield, dComponentYielding);	}
				
				if ( strAlaram3.GetLength() == 0 ) 
				{	strAlaram = strAlaram2; }
				else
				{	strAlaram.Format(_T("%s\n%s"), strAlaram3, strAlaram2); }				
				SetProjectAlarmDefect(true);
				SetProjectAlarmString(strAlaram);		
			}
		}
	}
	if ( Param.m_AlaramComponentDefectRateMax < 100.0 ) //警報-零件單次瑕疵率上限-%
	{
		if ( TestResult.sComponent.Total > 0 ) 
		{
			double dNGRate = TestResult.sComponent.NG*100.0/TestResult.sComponent.Total;
			if ( dNGRate > Param.m_AlaramComponentDefectRateMax )
			{
				strAlaram3 = GetProjectAlarmString();
				if ( DEFECT_FROM_AOI == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s %s[%.2f]"), strDefectFromAOI, strComponent, strDefect, strRatio, dNGRate);	}
				else if ( DEFECT_FROM_ARS == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s %s[%.2f]"), strDefectFromARS, strComponent, strDefect, strRatio, dNGRate);	}

				if ( strAlaram3.GetLength() == 0 ) 
				{	strAlaram = strAlaram2; }
				else
				{	strAlaram.Format(_T("%s\n%s"), strAlaram3, strAlaram2); }				
				SetProjectAlarmDefect(true);
				SetProjectAlarmString(strAlaram);		
			}
		}
	}

	if ( Param.m_AlaramEachComponentTotalNGCount>0 || Param.m_AlaramEachComponentContinueNGCount>0 )
	{			
		size_t ComponentTotalNGCountLimit = Param.m_AlaramEachComponentTotalNGCount;
		size_t ComponentContinueNGCountLimit = Param.m_AlaramEachComponentContinueNGCount;
		for ( i=0; i<ComponentCount; i++ )
		{
			ComponentPtr = GetProjectComponentPtr(i, false);
			if ( NULL == ComponentPtr ) { continue; }
			if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }			
			//ComponentEnableAlarm = ComponentPtr->GetComponentEnableAlarm();			
			//if ( false == ComponentEnableAlarm ) { continue; }

			ComponentName = ComponentPtr->GetComponentFullName();			
			ComponentDefectCountAOI = ComponentPtr->GetComponentTotalNGCountAOI();
			ComponentDefectCountARS = ComponentPtr->GetComponentTotalNGCountARS();		
			ComponentContinueNGCntAOI = ComponentPtr->GetComponentContinueNGCountAOI();
			ComponentContinueNGCntARS = ComponentPtr->GetComponentContinueNGCountARS();
			ComponentTotalNGCountLimit= ComponentPtr->GetComponentTotalNGCountLimit();
			ComponentContinueNGCountLimit = ComponentPtr->GetComponentContinueNGCountLimit();

			bAlaram=false;
			if ( ComponentPtr->GetComponentTotalNGCountEnable() == true )
			{
				if ( false==bAlaram && ComponentTotalNGCountLimit>0 )
				{
					const size_t ComponentTotalNGCountLimit2=ComponentTotalNGCountLimit-1;				
					if ( DEFECT_FROM_AOI == DefectFromMode )//For Test
					{	
						if ( false==bAlaram && ComponentDefectCountAOI>ComponentTotalNGCountLimit2 )//累計不良					
						{
							bAlaram = true;
							ComponentPtr->SetComponentTotalNGCountAlarm(true);
							strAlaram.Format(_T("%s(%d)"), strDefect, ComponentDefectCountAOI);					
						}										
					}
					if ( DEFECT_FROM_ARS == DefectFromMode )//For Repair
					{	
						if ( false==bAlaram && ComponentDefectCountARS>ComponentTotalNGCountLimit2 )//累計不良
						{
							bAlaram = true;							
							ComponentPtr->SetComponentTotalNGCountAlarm(true);
							strAlaram.Format(_T("%s(%d)"), strDefect, ComponentDefectCountARS);
						}										
					}				
				}
			}
			if ( ComponentPtr->GetComponentContinueNGCountEnable() == true )
			{
				if ( false==bAlaram && ComponentContinueNGCountLimit>0 )
				{
					const size_t ComponentContinueNGCountLimit2=ComponentContinueNGCountLimit-1;				
					if ( DEFECT_FROM_AOI == DefectFromMode )//For Test
					{	
						if ( false==bAlaram && ComponentContinueNGCntAOI>ComponentContinueNGCountLimit2 )//連續不良
						{
							bAlaram = true;							
							ComponentPtr->SetComponentContinueNGCountAlarm(true);
							strAlaram.Format(_T("%s %s(%d)"), strContinue, strDefect, ComponentContinueNGCntAOI);					
						}
					}
					if ( DEFECT_FROM_ARS == DefectFromMode )//For Repair
					{	
						if ( false==bAlaram && ComponentContinueNGCntARS>ComponentContinueNGCountLimit2 )//連續不良
						{
							bAlaram = true;
							ComponentPtr->SetComponentContinueNGCountAlarm(true);
							strAlaram.Format(_T("%s %s(%d)"), strContinue, strDefect, ComponentContinueNGCntARS);
						}
					}
				}
			}
			
			if ( true == bAlaram )
			{
				strAlaram3 = GetProjectAlarmString();
				if ( DEFECT_FROM_AOI == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s"), strDefectFromAOI, ComponentName, strAlaram);	}
				else if ( DEFECT_FROM_ARS == DefectFromMode )
				{	strAlaram2.Format(_T("%s %s %s"), strDefectFromARS, ComponentName, strAlaram);	}
				
				if ( strAlaram3.GetLength() == 0 ) 
				{	strAlaram = strAlaram2; }
				else
				{	strAlaram.Format(_T("%s\n%s"), strAlaram3, strAlaram2); }
				if ( ALARM_LOCK_ARS == AlarmLockMode )
				{	bAlaramOnARS=true;	}
				else //if ( ALARM_LOCK_AOI == AlarmLockMode )
				{
					SetProjectAlarmDefect(true);
					SetProjectAlarmString(strAlaram);
				}
			}
		}
	}	

	const TTestResult &TestResultAlarm = GetProjectResultAlarm();
	if ( TEST_RESULT_NG == TestResultAlarm.sResultID )
	{	SetProjectAlarmDefect(true);	}

	if ( GetProjectAlarmDefect() == true )
	{	SetProjectAlarmStop(true);	}
	
	if ( true == bAlaramOnARS )
	{
		for ( i=0; i<ComponentCount; i++ )
		{
			ComponentPtr = GetProjectComponentPtr(i, false);
			if ( NULL == ComponentPtr ) { continue; }
			if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }			
			//ComponentEnableAlarm = ComponentPtr->GetComponentEnableAlarm();			
			//if ( false == ComponentEnableAlarm ) { continue; }
			ComponentPtr->SetComponentTotalNGCountAOI(0);
			ComponentPtr->SetComponentTotalNGCountARS(0);		
			ComponentPtr->SetComponentContinueNGCountAOI(0);
			ComponentPtr->SetComponentContinueNGCountARS(0);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CalcProjectTestAverageTime(const TTestResult &Now, TTestResult &Ave)//計算專案統計時間
{
	TTestResult Total=Ave;	
	Total.sTestTime.tFd   *= (double)(Total.sTest.Total);
	Total.sTestTime.tGrab *= (double)(Total.sTest.Total);
	Total.sTestTime.tCalc *= (double)(Total.sTest.Total);
	Total.sTestTime.tTest *= (double)(Total.sTest.Total);	
	Total.sTestTime.tCycle *= (double)(Total.sTest.Total);	
	

	Total.sTest.Total     += Now.sTest.Total;	
	Total.sTestTime.tFd   += Now.sTestTime.tFd;
	Total.sTestTime.tGrab += Now.sTestTime.tGrab;
	Total.sTestTime.tCalc += Now.sTestTime.tCalc;
	Total.sTestTime.tTest += Now.sTestTime.tTest;
	Total.sTestTime.tCycle += Now.sTestTime.tCycle;	

	if ( 0 == Total.sTest.Total )
	{	return true;	}

	Ave.sTestTime.tFd   = (double)(Total.sTestTime.tFd/Total.sTest.Total);
	Ave.sTestTime.tGrab = (double)(Total.sTestTime.tGrab/Total.sTest.Total);
	Ave.sTestTime.tCalc = (double)(Total.sTestTime.tCalc/Total.sTest.Total);
	Ave.sTestTime.tTest = (double)(Total.sTestTime.tTest/Total.sTest.Total);	
	Ave.sTestTime.tCycle = (double)(Total.sTestTime.tCycle/Total.sTest.Total);		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AddProjectStatisticResult(const TTestResult &TestResult, TTestResult &StatisResult)//加入專案統計
{
	//計算平均檢測時間
	StatisResult.sLaneID = TestResult.sLaneID;
	CalcProjectTestAverageTime(TestResult, StatisResult);

	if ( 0 == StatisResult.sTest.Total )
	{
		StatisResult.sDateTimeS = TestResult.sDateTimeS;
		StatisResult.sDateTimeE = TestResult.sDateTimeE;
	}
	else
	{
		if ( StatisResult.sDateTimeE < TestResult.sDateTimeS )
		{	StatisResult.sDateTimeE = TestResult.sDateTimeS;	}
	}

	StatisResult.sTest.OK += TestResult.sTest.OK;
	StatisResult.sTest.NG += TestResult.sTest.NG;
	StatisResult.sTest.Total += TestResult.sTest.Total;
	StatisResult.sTest.Bypass += TestResult.sTest.Bypass;	
	
	StatisResult.sPanel.OK += TestResult.sPanel.OK;
	StatisResult.sPanel.NG += TestResult.sPanel.NG;
	StatisResult.sPanel.Total += TestResult.sPanel.Total;
	StatisResult.sPanel.Bypass += TestResult.sPanel.Bypass;

	StatisResult.sBoard.OK += TestResult.sBoard.OK;
	StatisResult.sBoard.NG += TestResult.sBoard.NG;
	StatisResult.sBoard.Total += TestResult.sBoard.Total;
	StatisResult.sBoard.Bypass += TestResult.sBoard.Bypass;

	StatisResult.sComponent.OK += TestResult.sComponent.OK;
	StatisResult.sComponent.NG += TestResult.sComponent.NG;
	StatisResult.sComponent.Total += TestResult.sComponent.Total;
	StatisResult.sComponent.Bypass += TestResult.sComponent.Bypass;		
	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ResetProjectStatisticRecords()//復歸專案統計紀錄
{
	size_t         i=0, j=0;
	TTop10Node    *Top10NodelPtr=NULL;	
	CAOIComponent *ComponentPtr = NULL;		
	const size_t   ComponentCount = GetProjectComponentCount();
	
	SetProjectBarcodeLast(L"");
	SetProjectAlarmDefect(false);	
	m_ProjectResultListAOI.clear();
	m_ProjectResultListARS.clear();
	m_ProjectResultLatest = TTestResult();
	m_ProjectResultLatest_LA = TTestResult();
	m_ProjectResultLatest_LB = TTestResult();
	m_ProjectResultStatistic = TTestResult();	
	m_ProjectResultStatistic_LA = TTestResult();	
	m_ProjectResultStatistic_LB = TTestResult();	
	m_ProjectResultLatest_ARS = TTestResult();
	m_ProjectResultLatest_ARS_LA = TTestResult();
	m_ProjectResultLatest_ARS_LB = TTestResult();
	m_ProjectResultStatistic_ARS = TTestResult();	
	m_ProjectResultStatistic_ARS_LA = TTestResult();
	m_ProjectResultStatistic_ARS_LB = TTestResult();
	ResetProjectResultCpkList(m_ProjectResultCpkList_LA);
	ResetProjectResultCpkList(m_ProjectResultCpkList_LB);

	//全部零件數
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->ResetComponentResultStatistic();		
	}
	
	const bool bResetAOI=true;
	const bool bResetARS=true;
	ResetProjectTop10List(m_ProjectTop10ListModel, bResetAOI, bResetARS);		
	ResetProjectTop10List(m_ProjectTop10ListModel_LA, bResetAOI, bResetARS);	
	ResetProjectTop10List(m_ProjectTop10ListModel_LB, bResetAOI, bResetARS);		
	ResetProjectTop10List(m_ProjectTop10ListPartNumber, bResetAOI, bResetARS);
	ResetProjectTop10List(m_ProjectTop10ListPartNumber_LA, bResetAOI, bResetARS);
	ResetProjectTop10List(m_ProjectTop10ListPartNumber_LB, bResetAOI, bResetARS);	
	SaveProjectGrrSigmaItemFile();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AnalyzeProjectStatisticRecords()//分析專案統計紀錄-前十大不良
{
	size_t         i=0, j=0;	
	CAOIComponent *ComponentPtr = NULL;
	const LANE_ID  LaneID = GetProjectActLaneID();
	const size_t   ComponentCount = GetProjectComponentCount();		

	//僅有瑕疵零件數
	const bool     ResetAOI=true;
	const bool     ResetARS=false;	
	const bool     DefectAOI=true;
	ResetProjectTop10List(m_ProjectTop10ListModel, ResetAOI, ResetARS);
	ResetProjectTop10List(m_ProjectTop10ListPartNumber, ResetAOI, ResetARS);	
	if ( LANE_ID_A == LaneID )
	{	
		ResetProjectTop10List(m_ProjectTop10ListModel_LA, ResetAOI, ResetARS);
		ResetProjectTop10List(m_ProjectTop10ListPartNumber_LA, ResetAOI, ResetARS);		
	}
	if ( LANE_ID_B == LaneID )
	{		
		ResetProjectTop10List(m_ProjectTop10ListModel_LB, ResetAOI, ResetARS);
		ResetProjectTop10List(m_ProjectTop10ListPartNumber_LB, ResetAOI, ResetARS);
	}	
	
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }

		//模組部分
		ComponentPtr->AddComponentToTop10ModeList(m_ProjectTop10ListModel, DefectAOI);
		switch ( LaneID )
		{
		case LANE_ID_A:
			ComponentPtr->AddComponentToTop10ModeList_Lane(LaneID, m_ProjectTop10ListModel_LA, DefectAOI);
			break;
		case LANE_ID_B:
			ComponentPtr->AddComponentToTop10ModeList_Lane(LaneID, m_ProjectTop10ListModel_LB, DefectAOI);
			break;
		}
		
		//料號部分
		ComponentPtr->AddComponentToTop10PartNumberList(m_ProjectTop10ListPartNumber, DefectAOI);		
		switch ( LaneID )
		{
		case LANE_ID_A:
			ComponentPtr->AddComponentToTop10PartNumberList_Lane(LaneID, m_ProjectTop10ListPartNumber_LA, DefectAOI);
			break;
		case LANE_ID_B:
			ComponentPtr->AddComponentToTop10PartNumberList_Lane(LaneID, m_ProjectTop10ListPartNumber_LB, DefectAOI);
			break;
		}
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AnalyzeProjectStatisticRecords_ARS(LANE_ID LaneID)//分析專案統計紀錄-前十大不良_ARS
{
	size_t         i=0, j=0;	
	CAOIComponent *ComponentPtr = NULL;				
	const size_t   ComponentCount = GetProjectComponentCount();		

	//僅有瑕疵零件數
	const bool     ResetAOI=false;
	const bool     ResetARS=true;
	const bool     DefectAOI=false;	
	ResetProjectTop10List(m_ProjectTop10ListModel, ResetAOI, ResetARS);
	ResetProjectTop10List(m_ProjectTop10ListPartNumber, ResetAOI, ResetARS);	
	if ( LANE_ID_A == LaneID )
	{		
		ResetProjectTop10List(m_ProjectTop10ListModel_LA, ResetAOI, ResetARS);		
		ResetProjectTop10List(m_ProjectTop10ListPartNumber_LA, ResetAOI, ResetARS);		
	}
	if ( LANE_ID_B == LaneID )
	{	
		ResetProjectTop10List(m_ProjectTop10ListModel_LB, ResetAOI, ResetARS);		
		ResetProjectTop10List(m_ProjectTop10ListPartNumber_LB, ResetAOI, ResetARS);		
	}
	
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
		
		//模組部分
		ComponentPtr->AddComponentToTop10ModeList(m_ProjectTop10ListModel, DefectAOI);
		switch ( LaneID )
		{
		case LANE_ID_A:
			ComponentPtr->AddComponentToTop10ModeList_Lane(LaneID, m_ProjectTop10ListModel_LA, DefectAOI);
			break;
		case LANE_ID_B:
			ComponentPtr->AddComponentToTop10ModeList_Lane(LaneID, m_ProjectTop10ListModel_LB, DefectAOI);
			break;
		}
		
		//料號部分
		ComponentPtr->AddComponentToTop10PartNumberList(m_ProjectTop10ListPartNumber, DefectAOI);		
		switch ( LaneID )
		{
		case LANE_ID_A:
			ComponentPtr->AddComponentToTop10PartNumberList_Lane(LaneID, m_ProjectTop10ListPartNumber_LA, DefectAOI);
			break;
		case LANE_ID_B:
			ComponentPtr->AddComponentToTop10PartNumberList_Lane(LaneID, m_ProjectTop10ListPartNumber_LB, DefectAOI);
			break;
		}
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CalcProjectTop10ListModel(DEFECT_FROM_MODE DefectFrom, std::vector<TTop10Node> &Top10List)//取出前十大模組不良
{
	size_t    Index=0;
	size_t    Value=0;
	size_t    i=0, j=0;
	CSortObj  SortNode;
	CSortObj *pSortNode=NULL;	
	std::vector<CSortObj> SortList;	
	TTop10Node  *Top10NodePtr = NULL;
	const size_t Top10Count = m_ProjectTop10ListModel.size();
	Top10List.clear();

	SortNode.SetSortMode(SORT_BY_INT);
	for ( i=0; i<Top10Count; i++ )
	{
		Top10NodePtr = &(m_ProjectTop10ListModel[i]);
		if ( NULL == Top10NodePtr ) { continue; }
		if ( DEFECT_FROM_ARS == DefectFrom )
		{	Value = Top10NodePtr->DefectCountARS; }
		else
		{	Value = Top10NodePtr->DefectCountAOI; }
		if ( 0 == Value ) { continue; }
		SortNode.SetID(i);
		SortNode.SetValueInt(Value);
		SortList.push_back(SortNode);
	}
	std::sort(SortList.begin(), SortList.end());
	const size_t NSortDatas = SortList.size();
	j = 0;
	for ( i=NSortDatas-1; i!=-1; i-- )
	{
		pSortNode = &(SortList[i]);
		Index = pSortNode->GetID();
		if ( Index<0 || Index >=Top10Count ) { continue; }
		Value = pSortNode->GetValueInt();
		if ( Value <= 0 ) { continue; }

		Top10NodePtr = &(m_ProjectTop10ListModel[Index]);
		Top10List.push_back(*Top10NodePtr);
		j ++;

		if ( j >= 10 ) 
		{	break; }		
	}
	return true;
}
