//-------------------------------------------------------------------------------------//
bool CAOIProject::CalcProjectTop10ListComponent(DEFECT_FROM_MODE DefectFrom, std::vector<TTop10Node> &Top10List)//取出前十大零件不良
{
	size_t    Index=0;
	size_t    Value=0;
	size_t    i=0, j=0;
	unsigned int PanelIndex=0;
	unsigned int BoardIndex=0;
	CString   ComponentName;
	CSortObj  SortNode;
	CSortObj *pSortNode=NULL;	
	std::vector<CSortObj> SortList;	
	TTop10Node   Top10Node;
	CAOIComponent *ComponentPtr = NULL;
	const size_t ComponentCount = GetProjectComponentCount();
	Top10List.clear();

	SortNode.SetSortMode(SORT_BY_INT);
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
		if ( ComponentPtr->GetComponentBypassed() == true ) { continue; }
		if ( DEFECT_FROM_ARS == DefectFrom )
		{	Value = ComponentPtr->GetComponentTotalNGCountARS(); }
		else
		{	Value = ComponentPtr->GetComponentTotalNGCountAOI(); }
		if ( 0 == Value ) { continue; }
		SortNode.SetID(i);
		SortNode.SetValueInt(Value);
		SortList.push_back(SortNode);
	}
	std::sort(SortList.begin(), SortList.end());
	const size_t NSortDatas = SortList.size();
	j = 0;
	for ( i=NSortDatas-1; i!=-1; i-- )
	{
		pSortNode = &(SortList[i]);
		Index = pSortNode->GetID();
		if ( Index<0 || Index >=ComponentCount ) { continue; }
		Value = pSortNode->GetValueInt();
		if ( Value <= 0 ) { continue; }

		ComponentPtr = GetProjectComponentPtr(Index, false);
		PanelIndex = ComponentPtr->GetComponentPanelIndex_Project();
		BoardIndex = ComponentPtr->GetComponentBoardIndex_Panel();
		ComponentName = ComponentPtr->GetComponentName();

		Top10Node = TTop10Node();		
		Top10Node.NodeName = AOIDataDefine.GetComponentFullNameReverse(PanelIndex, BoardIndex, ComponentName);
		Top10Node.DefectCountAOI = ComponentPtr->GetComponentTotalNGCountAOI();
		Top10Node.DefectCountARS = ComponentPtr->GetComponentTotalNGCountARS();
		Top10Node.StatisticsIndex = Index;		
		Top10List.push_back(Top10Node);
		j ++;

		if ( j >= 10 ) 
		{	break; }		
	}
	return true;
}
