//-------------------------------------------------------------------------------------//
void CAOIProject::ModifyProjectWndDefectItemAlarm(CWndDefectItem &DefectItem)
{
	const int  ItemDisable=WND_DEFECT_ITEM_DISABLE;
	const std::vector<WND_DEFECT_ID> &List=AOIDataCollect.GetWndDefectIDList();
	const size_t Count=List.size();
	for ( size_t i=0; i<Count; i++ )
	{
		WND_DEFECT_ID WndDefectID=List[i];
		const int nItemCount=DefectItem.GetItemCount(WndDefectID);
		if ( WND_DEFECT_ITEM_ENABLE != nItemCount )
		{	DefectItem.SetItemCount(WndDefectID, ItemDisable);	}
	}	
	return ;
}
