void CAOIProject::CheckProjectXBoardUseRatioMode()//確認專案X板是否使用比例模式
{
	bool  bRatioMode=false;	
	const double CheckRatio = GetProjectParameter().m_ProjectXBoardCheckRatio;
	if ( CheckRatio<0.00001 || CheckRatio>(100.00-0.00001) )
	{	bRatioMode = false; }
	else
	{	bRatioMode = true; }
	SetProjectXBoardUseRatioMode(bRatioMode);
	return;
}
