bool CAOIProject::GetProjectConveyerPreRunEnabled()//專案軌道提前運轉
{
	if ( AOIDataCollect.CheckMultiLaneMode_Off() == true ) { return false; }
	const int EnableConveyerPreRun = GetProjectParameter().m_EnableConveyerPreRun;
	if ( FN_DISABLE == EnableConveyerPreRun ) { return false; }	
	DEFECT_HANDLE_MODE DefectHandelMode = GetProjectParameter().m_DefectHandleMode;
	if ( DEFECT_HANDLE_STOP_ALARM == DefectHandelMode ) { return false; }
	if ( DEFECT_HANDLE_CONTROL_CENTER == DefectHandelMode ) { return false; }
	if ( DEFECT_HANDLE_WAIT_FOR_REPAIR == DefectHandelMode ) { return false; }		
	DISTRICT_ID DistrictID = GetProjectActDistrictID();
	const bool  bMultiDistrictMode = GetProjectMultiDistrictMode();
	if ( true == bMultiDistrictMode )
	{
		if ( DISTRICT_ID_B != DistrictID )
		{	return false; }
	}
	return true;
}
