double CAOIProject::GetProjectFocusPos()//取得專案焦距位置
{
	return GetProjectFocusPos(m_ProjectActLaneID);
}
//-------------------------------------------------------------------------------------//
double CAOIProject::GetProjectFocusPos(LANE_ID LaneID)//取得專案焦距位置
{
	double Offset=0.0;	
	double FocusPos=0;
	double LaneFocus=0;
	const bool IsRightIn = PlcCtrlPtr->GetIsPCBRightInDirection();	
	Offset = GetProjectParameter().m_ProjectFocusOffset;	
	switch ( LaneID )
	{
	case LANE_ID_A:			
		if ( true == IsRightIn )
		{	LaneFocus = MotionCtrlPtr->GetMotionParameter().m_PCBStopLPosZ_LA;	}
		else
		{	LaneFocus = MotionCtrlPtr->GetMotionParameter().m_PCBStopRPosZ_LA;	}		
		break;
	case LANE_ID_B:		
		if ( true == IsRightIn )
		{	LaneFocus = MotionCtrlPtr->GetMotionParameter().m_PCBStopLPosZ_LB;	}
		else
		{	LaneFocus = MotionCtrlPtr->GetMotionParameter().m_PCBStopRPosZ_LB; }
		break;
	}
	FocusPos = LaneFocus+Offset;
	return FocusPos;
}
