bool CAOIProject::AssignProjectPanelBoardBarcode()//分配專案整板單板的條碼
{
	CAOIProject   *ProjectPtr = this;		
	bool           bFindProjectBarcode=false;
	RESULT_ID      ResultID;
	std::wstring   Barcode=L"";
	size_t         i=0, j=0, k=0;
	size_t         PanelBoardCount = 0;	
	CAOIPanel     *PanelPtr = NULL;
	CAOIBoard     *BoardPtr = NULL;
	INSPECTING_MODE InspectingMode = AOIDataCollect.GetInspectingMode();		
	const size_t PanelCount = ProjectPtr->GetProjectPanelCount();
	const size_t BoardCount = ProjectPtr->GetProjectBoardCount();
	const size_t BarcodeCount = ProjectPtr->GetProjectBarcodeCount();	
	const bool   bLoadInspectionResultFile = GetProjectLoadInspectionResultFile();

	if ( true == bLoadInspectionResultFile )
	{
		ProjectPtr->RestoreProjectBarcode();
		for ( i=0; i<PanelCount; i++ )
		{
			PanelPtr = ProjectPtr->GetProjectPanelPtr(i, false);
			if ( NULL == PanelPtr ) { continue; }
			PanelPtr->RestorePanelBarcode();
		}
		for ( i=0; i<BoardCount; i++ )
		{
			BoardPtr = ProjectPtr->GetProjectBoardPtr(i, false);
			if ( NULL == BoardPtr ) { continue; }
			BoardPtr->RestoreBoardBarcode();
		}
		SetProjectLoadInspectionResultFile(false);
		return true;
	}
	
	if ( AssignProjectPanelBoardBarcodeFn() == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AssignProjectPanelBoardBarcodeFn()//分配專案整板單板的條碼
{
	CAOIProject *ProjectPtr = this;		
	std::wstring Barcode=L"";
	size_t       i=0, j=0, k=0;
	size_t       PanelBoardCount = 0;	
	CAOIPanel   *PanelPtr = NULL;
	CAOIBoard   *BoardPtr = NULL;	
	BARCODE_BELONG_MODE BarcodeBelongMode;
	bool         bFindProjectBarcode=false;
	const size_t PanelCount = ProjectPtr->GetProjectPanelCount();
	const size_t BoardCount = ProjectPtr->GetProjectBoardCount();
	const size_t BarcodeCount = ProjectPtr->GetProjectBarcodeCount();

	//條碼更新-單板	
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = ProjectPtr->GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }				
		//if ( BoardPtr->GetBoardBypassed() == true ) { continue; }
		if ( BoardPtr->GetBoardIsGetBarcode() == false ) { continue; }
		Barcode = BoardPtr->GetBoardBarcode();

		PanelPtr = BoardPtr->GetBoardPanelPtr();
		if ( NULL != PanelPtr )
		{
			if ( PanelPtr->GetPanelBarcodeEnabled() == true )
			{
				if ( PanelPtr->GetPanelIsGetBarcode() == false )
				{
					PanelPtr->SetPanelIsGetBarcode(true);
					PanelPtr->SetPanelBarcode(Barcode.c_str());
					PanelPtr->SetPanelBarcodeBelongMode(BARCODE_BELONG_BOARD);
				}
			}			
		}		
	}	

	//條碼更新-整板
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = ProjectPtr->GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		//if ( PanelPtr->GetPanelBypassed() == true ) { continue; }
		if ( PanelPtr->GetPanelIsGetBarcode() == false ) { continue; }		
		Barcode = PanelPtr->GetPanelBarcode();	
		BarcodeBelongMode = PanelPtr->GetPanelBarcodeBelongMode();
		if ( BARCODE_BELONG_BOARD == BarcodeBelongMode ) { continue; }

		PanelBoardCount = PanelPtr->GetPanelBoardCount();
		for ( j=0; j<PanelBoardCount; j++ )
		{
			BoardPtr = PanelPtr->GetPanelBoardPtr(j, false);
			if ( NULL == BoardPtr ) { continue; }
			if ( BoardPtr->GetBoardIsGetBarcode() == true ) { continue; }
			if ( BoardPtr->GetBoardBarcodeEnabled() == false ) { continue; }
			BoardPtr->SetBoardIsGetBarcode(true);
			BoardPtr->SetBoardBarcode(Barcode.c_str());
			BoardPtr->SetBoardBarcodeBelongMode(BarcodeBelongMode);
		}
	}

	//尋找第1個整板條碼	
	BarcodeBelongMode = BARCODE_BELONG_NONE;	
	bFindProjectBarcode = ProjectPtr->GetProjectIsGetBarcode();
	if ( false == bFindProjectBarcode )
	{
		for ( i=0; i<PanelCount; i++ )
		{
			PanelPtr = ProjectPtr->GetProjectPanelPtr(i, false);
			if ( NULL == PanelPtr ) { continue; }
			if ( PanelPtr->GetPanelBypassed() == true ) { continue; }
			if ( PanelPtr->GetPanelIsGetBarcode() == false ) { continue; }
			bFindProjectBarcode = true;				
			Barcode = PanelPtr->GetPanelBarcode();
			BarcodeBelongMode = PanelPtr->GetPanelBarcodeBelongMode();
			break;
		}
		if ( false == bFindProjectBarcode )
		{
			//尋找第1個單板條碼
			for ( i=0; i<BoardCount; i++ )
			{
				BoardPtr = ProjectPtr->GetProjectBoardPtr(i, false);
				if ( NULL == BoardPtr ) { continue; }
				if ( BoardPtr->GetBoardBypassed() == true ) { continue; }				
				if ( BoardPtr->GetBoardIsGetBarcode() == false ) { continue; }
				bFindProjectBarcode = true;				
				Barcode = BoardPtr->GetBoardBarcode();
				BarcodeBelongMode = BoardPtr->GetBoardBarcodeBelongMode();
				break;
			}
		}
		if ( true == bFindProjectBarcode )//只更新至專案條碼
		{
			ProjectPtr->SetProjectIsGetBarcode(true);
			ProjectPtr->SetProjectBarcode(Barcode.c_str());
			ProjectPtr->SetProjectBarcodeBelongMode(BarcodeBelongMode);
		}
	}	

	//將專案條碼更新至其他整板與單板上
	bFindProjectBarcode = ProjectPtr->GetProjectIsGetBarcode();
	if ( true == bFindProjectBarcode )
	{	
		Barcode = ProjectPtr->GetProjectBarcode();
		BarcodeBelongMode = ProjectPtr->GetProjectBarcodeBelongMode();
		if ( BARCODE_BELONG_PROJECT == BarcodeBelongMode )
		{
			for ( i=0; i<PanelCount; i++ )
			{
				PanelPtr = ProjectPtr->GetProjectPanelPtr(i, false);
				if ( NULL == PanelPtr ) { continue; }			
				if ( PanelPtr->GetPanelIsGetBarcode() == true ) { continue; }
				if ( PanelPtr->GetPanelBarcodeEnabled() == false ) { continue; }
				PanelPtr->SetPanelIsGetBarcode(true);
				PanelPtr->SetPanelBarcode(Barcode.c_str());
				PanelPtr->SetPanelBarcodeBelongMode(BarcodeBelongMode);
			}
			for ( i=0; i<BoardCount; i++ )
			{
				BoardPtr = ProjectPtr->GetProjectBoardPtr(i, false);
				if ( NULL == BoardPtr ) { continue; }				
				if ( BoardPtr->GetBoardIsGetBarcode() == true ) { continue; }
				if ( BoardPtr->GetBoardBarcodeEnabled() == false ) { continue; }
				BoardPtr->SetBoardIsGetBarcode(true);
				BoardPtr->SetBoardBarcode(Barcode.c_str());
				BoardPtr->SetBoardBarcodeBelongMode(BarcodeBelongMode);
			}
		}
	}
	return true;
}
