//-------------------------------------------------------------------------------------//
void CAOIProject::CalcProjectTestTime(TTestTime &TestTime, DWORD CTStamp) const//取得專案檢測花費時間
{		
	TTestTime TestTimeDA;
	DWORD PCBMoveToDistrictB=0;
	const double ratio = 1000.0;	
	TestTimeDA.tFd  = m_ProjectTickCountFdFinish_DA-m_ProjectTickCountTestFirst_DA;
	TestTimeDA.tGrab = m_ProjectTickCountGrabFinish_DA-m_ProjectTickCountTestFirst_DA;
	TestTimeDA.tCalc = m_ProjectTickCountCalcFinish_DA-m_ProjectTickCountGrabFinish_DA;
	TestTimeDA.tTest = m_ProjectTickCountTestFinish_DA-m_ProjectTickCountTestFirst_DA;	

	const bool bMultiDistrictMode = GetProjectMultiDistrictMode();
	if ( false == bMultiDistrictMode )
	{	TestTime = TestTimeDA;	}
	else
	{
		TTestTime TestTimeDB;
		PCBMoveToDistrictB = m_ProjectTickCountTestFirst_DB-m_ProjectTickCountTestFinish_DA;
		TestTimeDB.tFd  = m_ProjectTickCountFdFinish_DB-m_ProjectTickCountTestFirst_DB;
		TestTimeDB.tGrab = m_ProjectTickCountGrabFinish_DB-m_ProjectTickCountTestFirst_DB;
		TestTimeDB.tCalc = m_ProjectTickCountCalcFinish_DB-m_ProjectTickCountGrabFinish_DB;
		TestTimeDB.tTest = m_ProjectTickCountTestFinish_DB-m_ProjectTickCountTestFirst_DB;

		TestTime.tFd = TestTimeDA.tFd+TestTimeDB.tFd;
		TestTime.tGrab = TestTimeDA.tGrab+TestTimeDB.tGrab;
		TestTime.tCalc = TestTimeDA.tCalc+TestTimeDB.tCalc;
		TestTime.tTest = TestTimeDA.tTest+TestTimeDB.tTest;		
	}
	TestTime.tCycle = TestTime.tTest+m_ProjectTickCountPCBIn+m_ProjectTickCountPCBExit+PCBMoveToDistrictB;			
	if ( CTStamp > 0 )
	{	TestTime.tCycle = CTStamp;	}
	TestTime.tFd /= ratio;
	TestTime.tGrab /= ratio;
	TestTime.tCalc /= ratio;
	TestTime.tTest /= ratio;
	TestTime.tCycle /= ratio;	
	return;
}
