void CAOIProject::SetProjectResultStatistic_ARS_Lane(LANE_ID LaneID, const TTestResult &value)
{
	switch ( LaneID )
	{
	case LANE_ID_A:	SetProjectResultStatistic_ARS_LA(value); break;
	case LANE_ID_B:	SetProjectResultStatistic_ARS_LB(value); break;
	}
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AddProjectResultCpkList_Lane(LANE_ID LaneID)
{
	//Calc Cpk			
	int ValueCount=0;
	const size_t ComponentCount = GetProjectComponentCount();
	double Value_OX=0, Max_OX=0, Min_OX=0, Sum_OX=0, LSL_OX=0, USL_OX=0;//OffsetX
	double Value_OY=0, Max_OY=0, Min_OY=0, Sum_OY=0, LSL_OY=0, USL_OY=0;//OffsetY
	double Value_SA=0, Max_SA=0, Min_SA=0, Sum_SA=0, LSL_SA=0, USL_SA=0;//SkewAngle	

	for ( size_t i=0 ; i<ComponentCount; i++ )
	{
		CAOIComponent *ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->SetComponentTempInt(FN_DISABLE);		
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }		
		//if ( ComponentPtr->GetComponentBypassed() == true ) { continue; }				
		//if ( ComponentPtr->GetComponentNeedToCalculate() == false ) { continue; }
		RESULT_ID ResultID = ComponentPtr->GetComponentResultID_AOI();		
		if ( RESULT_ID_NONE == ResultID ) { continue; }
		if ( RESULT_ID_SKIP == ResultID ) { continue; }
		if ( RESULT_ID_BYPASS == ResultID ) { continue; }

		ComponentPtr->SetComponentTempInt(FN_ENABLE);
		Value_OX = ComponentPtr->GetComponentResultOffsetX();
		Value_OY = ComponentPtr->GetComponentResultOffsetY();
		Value_SA = ComponentPtr->GetComponentResultSkewAngle();			
		if ( 0 == ValueCount )
		{	
			Max_OX = Min_OX = Value_OX;	
			Max_OY = Min_OY = Value_OY;	
			Max_SA = Min_SA = Value_SA;
			USL_OX = ComponentPtr->GetComponentResultOffsetX_USL();	
			LSL_OX = ComponentPtr->GetComponentResultOffsetX_LSL();	
			USL_OY = ComponentPtr->GetComponentResultOffsetY_USL();
			LSL_OY = ComponentPtr->GetComponentResultOffsetY_LSL();
			USL_SA = ComponentPtr->GetComponentResultSkewAngle_USL();
			LSL_SA = ComponentPtr->GetComponentResultSkewAngle_LSL();			
		}
		else
		{
			if ( Max_OX < Value_OX ) { Max_OX = Value_OX; }
			if ( Min_OX > Value_OX ) { Min_OX = Value_OX; }

			if ( Max_OY < Value_OY ) { Max_OY = Value_OY; }
			if ( Min_OY > Value_OY ) { Min_OY = Value_OY; }

			if ( Max_SA < Value_SA ) { Max_SA = Value_SA; }
			if ( Min_SA > Value_SA ) { Min_SA = Value_SA; }
		}
		ValueCount ++;
		Sum_OX += Value_OX;
		Sum_OY += Value_OY;
		Sum_SA += Value_SA;
	}
	if ( 0 == ValueCount )
	{	return true; }

	const double Ave_OX = Sum_OX/ValueCount;
	const double Ave_OY = Sum_OY/ValueCount;
	const double Ave_SA = Sum_SA/ValueCount;
	const int nMax_OX = MAX(0, JetAPI::Ceil(Max_OX));
	const int nMin_OX = MIN(0, JetAPI::Floor(Min_OX));	
	const int nMax_OY = MAX(0, JetAPI::Ceil(Max_OY));
	const int nMin_OY = MIN(0, JetAPI::Floor(Min_OY));	
	const int nMax_SA = MAX(0, JetAPI::Ceil(Max_SA));
	const int nMin_SA = MIN(0, JetAPI::Floor(Min_SA));	
	const int nLimit_OX = MAX(nMax_OX, -nMin_OX);	
	const int nLimit_OY = MAX(nMax_OY, -nMin_OY);	
	const int nLimit_SA = MAX(nMax_SA, -nMin_SA);	
	const int nLimitMax_OX =  nLimit_OX;
	const int nLimitMin_OX = -nLimit_OX;
	const int nLimitMax_OY =  nLimit_OY;
	const int nLimitMin_OY = -nLimit_OY;
	const int nLimitMax_SA =  nLimit_SA;
	const int nLimitMin_SA = -nLimit_SA;	
	
	Sum_OX = Sum_OY = Sum_SA = 0;	
	for ( size_t i=0 ; i<ComponentCount; i++ )
	{
		CAOIComponent *ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( FN_ENABLE != ComponentPtr->GetComponentTempInt() ) { continue; }

		Value_OX = ComponentPtr->GetComponentResultOffsetX();
		Value_OY = ComponentPtr->GetComponentResultOffsetY();
		Value_SA = ComponentPtr->GetComponentResultSkewAngle();

		double Value2_OX=Value_OX-Ave_OX;
		double Value2_OY=Value_OY-Ave_OY;
		double Value2_SA=Value_SA-Ave_SA;
		Sum_OX += Value2_OX*Value2_OX;
		Sum_OY += Value2_OY*Value2_OY;
		Sum_SA += Value2_SA*Value2_SA;
	}	

	double Cpk_OX=0, Cpk_OY=0, Cpk_SA=0;	
	const int nSigma = 3;
	const double Variance_OX=Sum_OX/ValueCount;	
	const double Variance_OY=Sum_OY/ValueCount;	
	const double Variance_SA=Sum_SA/ValueCount;	
	const double Sigma_OX = ::sqrt(Variance_OX);//標準差	
	const double Sigma_OY = ::sqrt(Variance_OY);//標準差	
	const double Sigma_SA = ::sqrt(Variance_SA);//標準差	
	const double Sigma_3_OX = Sigma_OX*3;
	const double Sigma_3_OY = Sigma_OY*3;
	const double Sigma_3_SA = Sigma_SA*3;
	const double TotalSigma_OX=(nSigma*Sigma_OX); 	
	const double TotalSigma_OY=(nSigma*Sigma_OY); 	
	const double TotalSigma_SA=(nSigma*Sigma_SA); 	
	const double LCL_OX = Ave_OX-(TotalSigma_OX);
	const double UCL_OX = Ave_OX+(TotalSigma_OX);		
	const double LCL_OY = Ave_OY-(TotalSigma_OY);
	const double UCL_OY = Ave_OY+(TotalSigma_OY);		
	const double LCL_SA = Ave_SA-(TotalSigma_SA);
	const double UCL_SA = Ave_SA+(TotalSigma_SA);		
	const double Bin_OX = MAX(1, Sigma_OX/2);	
	const double Bin_OY = MAX(1, Sigma_OY/2);	
	const double Bin_SA = MAX(1, Sigma_SA/2);	
	const double LimitL_OX= MIN(Ave_OX-(1.5*TotalSigma_OX), LSL_OX);
	const double LimitU_OX= MAX(Ave_OX+(1.5*TotalSigma_OX), USL_OX);	
	const double LimitL_OY= MIN(Ave_OY-(1.5*TotalSigma_OY), LSL_OY);
	const double LimitU_OY= MAX(Ave_OY+(1.5*TotalSigma_OY), USL_OY);
	const double LimitL_SA= MIN(Ave_SA-(1.5*TotalSigma_SA), LSL_SA);
	const double LimitU_SA= MAX(Ave_SA+(1.5*TotalSigma_SA), USL_SA);	

	const int nCount_OX = (int)((LimitU_OX-LimitL_OX)/Bin_OX)+1;
	const int nCount_OY = (int)((LimitU_OY-LimitL_OY)/Bin_OY)+1;
	const int nCount_SA = (int)((LimitU_SA-LimitL_SA)/Bin_SA)+1;
	if ( Sigma_3_OX > 0.000001 )
	{	Cpk_OX = MIN((Ave_OX-LSL_OX)/Sigma_3_OX, (USL_OX-Ave_OX)/Sigma_3_OX);	}
	if ( Sigma_3_OY > 0.000001 )
	{	Cpk_OY = MIN((Ave_OY-LSL_OY)/Sigma_3_OY, (USL_OY-Ave_OY)/Sigma_3_OY);	}
	if ( Sigma_3_SA > 0.000001 )
	{	Cpk_SA = MIN((Ave_SA-LSL_SA)/Sigma_3_SA, (USL_SA-Ave_SA)/Sigma_3_SA);	}

	
	size_t idx_OX, idx_OY, idx_SA=0;		
	std::vector<float> BarList_OX, BarList_OY, BarList_SA;
	bool bException_OX=false, bException_OY=false, bException_SA=false;
	BarList_OX.resize(nCount_OX+1, 0);	
	BarList_OY.resize(nCount_OY+1, 0);	
	BarList_SA.resize(nCount_SA+1, 0);	
	for ( size_t i=0 ; i<ComponentCount; i++ )
	{
		CAOIComponent *ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( FN_ENABLE != ComponentPtr->GetComponentTempInt() ) { continue; }

		bException_OX = bException_OY = bException_SA = false;
		Value_OX = ComponentPtr->GetComponentResultOffsetX();
		Value_OY = ComponentPtr->GetComponentResultOffsetY();
		Value_SA = ComponentPtr->GetComponentResultSkewAngle();

		if ( Value_OX<LimitL_OX || Value_OX>LimitU_OX )
		{	bException_OX = true;	}
		else
		{
			idx_OX = JetAPI::Floor((Value_OX-LimitL_OX)/Bin_OX);
			if ( idx_OX < nCount_OX )
			{	BarList_OX[idx_OX] += 1.0f; }
			else
			{	bException_OX = true;	}
		}		

		if ( Value_OY<LimitL_OY || Value_OY>LimitU_OY )
		{	bException_OY = true;	}
		else
		{
			idx_OY = JetAPI::Floor((Value_OY-LimitL_OY)/Bin_OY);
			if ( idx_OY < nCount_OY )
			{	BarList_OY[idx_OY] += 1.0f; }
			else
			{	bException_OY = true;	}
		}	

		if ( Value_SA<LimitL_SA || Value_SA>LimitU_SA )
		{	bException_SA = true;	}
		else
		{
			idx_SA = JetAPI::Floor((Value_SA-LimitL_SA)/Bin_SA);
			if ( idx_SA < nCount_SA )
			{	BarList_SA[idx_SA] += 1.0f; }
			else
			{	bException_SA = true;	}
		}	
	}

	//const int MaxCount = ValueCount;
	const int MaxCount_OX=*(std::max_element(BarList_OX.begin(), BarList_OX.end()));	
	const int MaxCount_OY=*(std::max_element(BarList_OY.begin(), BarList_OY.end()));	
	const int MaxCount_SA=*(std::max_element(BarList_SA.begin(), BarList_SA.end()));	
	if ( MaxCount_OX > 0 )
	{
		for ( size_t i=0; i<BarList_OX.size(); i++ )
		{	BarList_OX[i] = BarList_OX[i]*100.0f/MaxCount_OX;	}
	}	
	if ( MaxCount_OY > 0 )
	{
		for ( size_t i=0; i<BarList_OY.size(); i++ )
		{	BarList_OY[i] = BarList_OY[i]*100.0f/MaxCount_OY;	}
	}
	if ( MaxCount_SA > 0 )
	{
		for ( size_t i=0; i<BarList_SA.size(); i++ )
		{	BarList_SA[i] = BarList_SA[i]*100.0f/MaxCount_SA;	}
	}

	TCpkItem CpkResult;
	CpkResult.Barcode = GetProjectBarcode();
	CpkResult.DateTime = GetProjectResultCurrent().sDateTimeS;
	CpkResult.ResultID = GetProjectResultCurrent().sResultID;		

	CpkResult.OffsetX.Ave = (float)(Ave_OX);
	CpkResult.OffsetX.Min = (float)(Min_OX);
	CpkResult.OffsetX.Max = (float)(Max_OX);
	CpkResult.OffsetX.Sigma = (float)(Sigma_OX);
	CpkResult.OffsetX.USL = (float)(USL_OX);
	CpkResult.OffsetX.LSL = (float)(LSL_OX);
	CpkResult.OffsetX.Cpk = (float)(Cpk_OX);	
	CpkResult.OffsetX.Bin = (float)(Bin_OX);
	CpkResult.OffsetX.BinList = BarList_OX;

	CpkResult.OffsetY.Ave = (float)(Ave_OY);
	CpkResult.OffsetY.Min = (float)(Min_OY);
	CpkResult.OffsetY.Max = (float)(Max_OY);
	CpkResult.OffsetY.Sigma = (float)(Sigma_OY);
	CpkResult.OffsetY.USL = (float)(USL_OY);
	CpkResult.OffsetY.LSL = (float)(LSL_OY);
	CpkResult.OffsetY.Cpk = (float)(Cpk_OY);	
	CpkResult.OffsetY.Bin = (float)(Bin_OY);
	CpkResult.OffsetY.BinList = BarList_OY;

	CpkResult.SkewAngle.Ave = (float)(Ave_SA);
	CpkResult.SkewAngle.Min = (float)(Min_SA);
	CpkResult.SkewAngle.Max = (float)(Max_SA);
	CpkResult.SkewAngle.Sigma = (float)(Sigma_SA);
	CpkResult.SkewAngle.USL = (float)(USL_SA);
	CpkResult.SkewAngle.LSL = (float)(LSL_SA);
	CpkResult.SkewAngle.Cpk = (float)(Cpk_SA);	
	CpkResult.SkewAngle.Bin = (float)(Bin_SA);
	CpkResult.SkewAngle.BinList = BarList_SA;

	switch ( LaneID )
	{
	case LANE_ID_B: AddProjectResultCpkList(CpkResult, m_ProjectResultCpkList_LB);	break;
	default:
	case LANE_ID_A: AddProjectResultCpkList(CpkResult, m_ProjectResultCpkList_LA);	break;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
const std::vector<TCpkItem>& CAOIProject::GetProjectResultCpkList_Lane(LANE_ID LaneID) const
{
	if ( LANE_ID_B == LaneID )
	{	return m_ProjectResultCpkList_LB; }
	return m_ProjectResultCpkList_LA;
}
//-------------------------------------------------------------------------------------//
void CAOIProject::ResetProjectResultCpkList(std::vector<TCpkItem> &List)
{
	const size_t Count=List.size();
	for ( size_t i=0; i<Count; i++ )
	{	List[i] = TCpkItem();	}
	return;
}
//-------------------------------------------------------------------------------------//
void CAOIProject::AddProjectResultCpkList(const TCpkItem &CpkItem, std::vector<TCpkItem> &List)
{
	//Shift Data in List
	const size_t Count=List.size();
	if ( 0 == Count ) { return; }
	if ( Count > 2 )
	{
		for ( size_t i=Count-1; i>0; i-- )
		{	List[i] = List[i-1];	}
	}	
	//Add First One
	List[0] = CpkItem;
	return;
}
