//-------------------------------------------------------------------------------------//
bool CAOIProject::WriteProjectShareFile(LPCTSTR KeyName, LPCTSTR Value)//寫入專案共享資料
{
	CString Section;		
	CString FileFolder;
	CString IniFilename;
	CString mainFilename;
	UUID    uuid = GetObjUuid();	
	CString PrgName = GetProjectShowName();	
	TCHAR   strUUID[MAX_JET_PATH]=_T("");

	JetAPI::ExtractFolder(PrgName, FileFolder);
	JetAPI::ExtractMainFileNameNoPath(PrgName, mainFilename);
	FileFolder = AOIDataCollect.GetAOIProjectDirectory();	
	IniFilename.Format(_T("%s\\%s"), FileFolder, _T("Project.INI"));
	Section = mainFilename;	
#ifndef _UNICODE
	JetAPI::UUIDToStringA(uuid, strUUID);
#else
	JetAPI::UUIDToStringW(uuid, strUUID);
#endif//_UNICODE
	Section = strUUID;
	if ( SaveINIData(Section, KeyName, Value, IniFilename, m_ErrorString) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ReadProjectShareFile(LPCTSTR KeyName, LPCTSTR Default, CString &Value)//讀取專案共享資料
{
	int nSaveFinish = 0;
	CString Section;	
	const size_t StringSize = MAX_JET_PATH;
	TCHAR String[StringSize] = _T("");	
	TCHAR   strUUID[MAX_JET_PATH] = _T("");
	CString FileFolder;
	CString IniFilename;
	CString mainFilename;
	UUID    uuid = GetObjUuid();
	CString PrgName = GetProjectShowName();
	JetAPI::ExtractFolder(PrgName, FileFolder);
	JetAPI::ExtractMainFileNameNoPath(PrgName, mainFilename);

	FileFolder = AOIDataCollect.GetAOIProjectDirectory();
	IniFilename.Format(_T("%s\\%s"), FileFolder, _T("Project.INI"));
	Section = mainFilename;
#ifndef _UNICODE
	JetAPI::UUIDToStringA(uuid, strUUID);
#else
	JetAPI::UUIDToStringW(uuid, strUUID);
#endif//_UNICODE
	Section = strUUID;
	if ( LoadINIData(Section, KeyName, Default, String, StringSize, IniFilename, false, m_ErrorString) == false )
	{	return false; }
	Value = String;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CheckProjectOnlineTuningRunning() const//確定專案線上調機運作中
{
	if ( GetProjectOnlineTuningEnable() == false ) { return false; }	
	const size_t SavedCount=GetProjectOnlineTuningSavedCount();
	const size_t MaxSavedCount=AOIDataCollect.GetOnlineTuningSavedMaxCount();
	if ( 0 != MaxSavedCount )
	{
		if ( SavedCount >= MaxSavedCount )
		{	return false; }		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CheckProjectOnlineTuningSaveInspectionFile() const//確認線上調機儲存檢測檔案
{
	if ( CheckProjectOnlineTuningRunning() == false ) { return false; }
	TEST_RESULT_ID TestResultID = GetProjectResultCurrent().sResultID;
	if ( TEST_RESULT_NONE == TestResultID ) { return false; }
	if ( TEST_RESULT_OK == TestResultID ) { return false; }
	return true;
}
