bool CAOIProject::StartWriteStaticDataToLibraryThread()
{
	if ( FN_ENABLE != GetProjectParameter().m_SaveStaticData )
	{	return true; }
	SetWriteStaticDataToLibraryThreadCmd(THREAD_COMMAND_TO_RUN);
	m_WriteStaticDataToLibraryThread = std::thread(WriteStaticDataToLibraryFn, this);
	if(m_WriteStaticDataToLibraryThread.joinable())
		m_WriteStaticDataToLibraryThread.detach();
	return true;
}
