//-------------------------------------------------------------------------------------//
bool CAOIProject::WaitForWriteStaticDataToLibraryThreadFinish()//等待專案複製檔案執行緒
{
#ifndef OFFLINE_VERSION	

#endif//OFFLINE_VERSION
	size_t i = 0;
	DWORD Res = 0;
	const DWORD MaxCounts = 10000;
	const DWORD SleepTime = 100;
	if (NULL == m_ProjectCopyFileEvent) { return true; }
	AOIDataCollect.SaveDebugMessage(_T("WaitForWriteStaticDataToLibraryThreadFinish-Start"));
	for (i = 0; i<MaxCounts; i++)
	{
		if (AOIDataCollect.GetIsSystemReleased() == true) { return true; }
		if (AOIDataCollect.GetIsSystemException() == true) { return true; }
		if (THREAD_COMMAND_TO_EXIT == m_WriteStaticDataToLibraryThreadCmd) { return true; }
		if (THREAD_COMMAND_TO_IDLE == m_WriteStaticDataToLibraryThreadCmd)
		{
			break;
		}
		std::this_thread::sleep_for(std::chrono::microseconds(SleepTime));
		if (m_WriteStaticDataToLibraryThreadState != THREAD_STATE_RUNNING) { break; }
		if (Res != WAIT_TIMEOUT) { break; }
	}
	if (MaxCounts == i)
	{
		AOIDataCollect.SaveDebugMessage(_T("WaitForWriteStaticDataToLibraryThreadFinish-Fault"));
		m_ErrorString = _T("Error, Wait for WaitForWriteStaticDataToLibraryThreadFinish too long");
		AOIExceptionCodeCtrl.SetAOIExceptionCode_Thread(AOI_EXCEPTION_THREAD_WAIT_FOR_FINISH, m_ErrorString);
		return false;
	}
	AOIDataCollect.SaveDebugMessage(_T("WaitForWriteStaticDataToLibraryThreadFinish-End"));
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::DeleteProjectServerLockFile()//刪除專案伺服器鎖住檔案
{
	CString str;
	CString LockFileName;		
	CString LockFileNameTmp;		
	CString ExtNameLock=_T("TMP");	
	CString TempFolder = AOIDataCollect.GetAOITempDirectory();			
	CString ServerFolder = AOIDataCollect.GetAOIServerFolder();
	LockFileNameTmp.Format(_T("%s\\%s.%s"), TempFolder, _T("LockFile"), ExtNameLock);		
	LockFileName.Format(_T("%s\\%s.%s"), ServerFolder, _T("LockFile"), ExtNameLock);	
	::DeleteFile(LockFileName);
	::DeleteFile(LockFileNameTmp);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CreateProjectServerLockFile(bool &bLock)//建立專案伺服器鎖住檔案
{	
	CString str;
	CString LockFileName;		
	CString LockFileNameTmp;		
	CString ExtNameLock=_T("TMP");
	CString MainFilename = GetProjectFileMainName();
	CString TempFolder = AOIDataCollect.GetAOITempDirectory();		
	CString ServerFolder = AOIDataCollect.GetAOIServerFolder();

	bLock = false;
	LockFileNameTmp.Format(_T("%s\\%s.%s"), TempFolder, _T("LockFile"), ExtNameLock);		
	LockFileName.Format(_T("%s\\%s.%s"), ServerFolder, _T("LockFile"), ExtNameLock);		
	
	if ( JetAPI::IsFileExist(LockFileName) == true )//確認是否鎖住
	{	
		bLock = true;
		str = _T("Error, Server Project File Locked");
		m_ErrorString = LoadMultiLanguageString(str, str);
		return true;	
	}
	if ( JetAPI::CreateTempFile(LockFileNameTmp, MainFilename) == false )
	{
		bLock = false;
		str = _T("Error, Create Lock File Fault");
		str = LoadMultiLanguageString(str, str);
		m_ErrorString.Format(_T("%s [%s]"), str, LockFileNameTmp);
		return false;	
	}
	//複製鎖住檔案時, 如果錯誤視為別人正在操作
	if ( ::CopyFile(LockFileNameTmp, LockFileName, TRUE) == FALSE )
	{	
		bLock = true;
		::DeleteFile(LockFileNameTmp);		
		str = _T("Error, Server Project File Locked");
		m_ErrorString = LoadMultiLanguageString(str, str);
		return true;	
	}	
	return true;
}
