//-------------------------------------------------------------------------------------//
bool CAOIProject::ReadProjectServerProjectLinkMode(PROJECT_LINK_SERVER_MODE &LinkMode)//讀取專案伺服器共享資料-連線模式
{
	CString Value;
	CString Default;	
	CString KeyName=_T("Server Link Mode");	
	Default.Format(_T("%d"), PROJECT_LINK_SERVER_DISABLE);
	if ( ReadProjectServerProjectShareFile(KeyName, Default, Value) == false )
	{	return false; }
	const int TempI = ::_ttoi(Value);
	switch ( TempI )
	{
	case PROJECT_LINK_SERVER_DISABLE:
	case PROJECT_LINK_SERVER_ENABLE_ALL:
	case PROJECT_LINK_SERVER_PROJECT_ONLY:
	case PROJECT_LINK_SERVER_ENABLE_ALL_ASK:
	case PROJECT_LINK_SERVER_PROJECT_ONLY_ASK:
		LinkMode = (PROJECT_LINK_SERVER_MODE)(TempI);
		break;
	default:
		LinkMode = PROJECT_LINK_SERVER_DISABLE;
		break;
	}
	return true;
}
