//-------------------------------------------------------------------------------------//
bool CAOIProject::BuildProjectAliasList(std::vector<TAliasNode> &AliasList)//建立別名列表
{
	size_t          i=0;	
	std::wstring    ModelName;
	std::wstring    PartNumber;	
	CAOIComponent  *ComponentPtr = NULL;
	const size_t ComponentCount = this->GetProjectComponentCount();		
	std::map<std::wstring, std::wstring> NameMap;
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
		ModelName = ComponentPtr->GetComponentModelName();
		PartNumber = ComponentPtr->GetComponentPartNumber();	
		JetAPI::wstring2upper(ModelName);
		JetAPI::wstring2upper(PartNumber);
		NameMap[PartNumber] = ModelName;
	}

	TAliasNode      AliasNode;
	std::map<std::wstring, std::wstring>::iterator MapIter;
	AliasList.clear();
	for ( MapIter=NameMap.begin();  MapIter!=NameMap.end(); MapIter++ )
	{
		AliasNode.wsPartNumber = (*MapIter).first; 
		AliasNode.wsModelName  = (*MapIter).second ;
		AliasList.push_back(AliasNode);
	}
	return true;
}
