//-------------------------------------------------------------------------------------//
bool CAOIProject::MergeProjectLibrary(CAOIProject *ProjectPtr)//合併專案的模組列表
{	
	bool         bExist=false;
	size_t       i=0, j=0;
	size_t       SelfModelCount = 0;	
	MODEL_TYPE   ModelType;
	CString      str;
	CString      NewModelName;
	CString      SelfModelName;	
	CString      NewModelFolder;
	CString      SelfModelFolder;
	CString      NewLibraryFolder;
	CString      SelfLibraryFolder;
	CAOIModel   *NewModelPtr = NULL;
	CAOIModel   *SelfModelPtr = NULL;	
	std::vector<CString> FailModelNameList;
	const size_t NewModelCount = ProjectPtr->GetProjectModelCount();
	
	unsigned int   DefaultFrameIndex=0;
	unsigned int   DefaultFrameUniqueID = 0;	
	std::vector<CColorGroup>  ColorGroupList;
	std::vector<unsigned int> FrameIndexMapList;
	ProjectPtr->CloneProjectColorGroupList(ColorGroupList);
	ProjectPtr->BuildProjectFrameIndexMapParam(FrameIndexMapList, DefaultFrameIndex, DefaultFrameUniqueID);			

	SelfLibraryFolder = GetProjectLibraryFolder();
	NewLibraryFolder = ProjectPtr->GetProjectLibraryFolder();
	for ( i=0; i<NewModelCount; i++ )
	{
		NewModelPtr = ProjectPtr->GetProjectModelPtr(i, false);
		if ( NULL == NewModelPtr ) { continue; }
		ModelType = NewModelPtr->GetModelType();
		//if ( MODEL_TYPE_NULL == ModelType ) { continue; }
		if ( CAOIModel::CheckModelTypeEnabled(ModelType) == false )
		{	continue; }

		bExist=false;		
		NewModelName = NewModelPtr->GetModelName();
		NewModelName.MakeUpper();

		SelectProjectAllModels(false);
		SelfModelCount = GetProjectModelCount();
		for ( j=0; j<SelfModelCount; j++ )
		{
			SelfModelPtr = GetProjectModelPtr(j, false);
			if ( NULL == SelfModelPtr ) { continue; }
			SelfModelName = SelfModelPtr->GetModelName();
			if ( SelfModelName.CompareNoCase(NewModelName) != 0 ) { continue; }
			SelfModelPtr->SetModelSelected(true);
			bExist=true;			
		}		
		if ( true == bExist )
		{	DeleteProjectModelSelected();	}
		SelfModelPtr = NewModelPtr->CloneModelObj();
		if ( NULL == SelfModelPtr )
		{
			FailModelNameList.push_back(NewModelName);
			continue;
		}
		
		AddProjectModelPtr(SelfModelPtr, false);
		NewModelFolder = NewModelPtr->GetModelFolder();
		//SelfModelFolder = SelfModelPtr->GetModelFolder();
		SelfModelFolder.Format(_T("%s\\%s"), SelfLibraryFolder, NewModelName);
		SelfModelPtr->SetModelNeedSaveFiles(true);
		SelfModelPtr->SetModelFolderModel(SelfModelFolder);
		SelfModelPtr->AssignModelFolder();
		SelfModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);
		SelfModelPtr->UpdateModelFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);
		::CreateDirectory(SelfModelFolder, NULL);
		if ( JetAPI::CopyFolderAToFolderB(NewModelFolder, SelfModelFolder, false, true, _T(""), -1, -1) == false )
		{
			FailModelNameList.push_back(NewModelName);
			continue;
		}

	}
	
	const size_t FailModelCount = FailModelNameList.size();
	if ( FailModelCount > 0 ) 
	{
		FILE *pfile = NULL;	
		char  ansiBuffer[MAX_JET_PATH]="";
		TCHAR TMode[32] = _T("");
		_tcscpy(TMode, _T("w+"));
		JetAPI::ModifyOpenFileMode_Write(TMode);
		str.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("MergeLibraryFault.TXT"));
		pfile = _tfopen(str, TMode);
		if ( NULL != pfile )
		{
			for ( i=0; i<FailModelCount; i++ )
			{
				NewModelName = FailModelNameList[i];
				::_ftprintf(pfile, _T("%s\n"), (LPCTSTR)NewModelName);
				//JetAPI::TCHAR2char(NewModelName, ansiBuffer, MAX_JET_PATH);				
			}
			::fclose(pfile); pfile=NULL;
			::Sleep(0);
			::ShellExecute(NULL, _T("open"), str, NULL, NULL, SW_SHOW);	
		}
	}
	//FailModelNameList
	return true;
}
