//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectPartBarcodeFileFn()//儲存專案零件條碼檔案
{
	return true;//改由JSON檔案匯出

	size_t         i=0, j=0, k=0;		
	CAOIPanel     *PanelPtr = NULL;			
	CString        TempName;
	CString        Filename;
	std::wstring   wsProjectBarocde;
	std::wstring   wsPartBarcodeList;
	std::set<std::wstring> BoardBarcodeSet;
	CString DstFolder = GetProjectSpcImageFolder();
	CString TempFolder = AOIDataCollect.GetAOITempDirectory();
	const size_t PanelCount =GetProjectPanelCount();	
	CString strDateTime = GetProjectResultCurrent().sDateTimeS.Format(_T("%Y%m%d%H%M%S"));
	
	wsProjectBarocde = GetProjectBarcode();
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }

		const size_t BoardCount=PanelPtr->GetPanelBoardCount();
		for ( j=0; j<BoardCount; j++ )
		{
			CAOIBoard *BoardPtr = PanelPtr->GetPanelBoardPtr(j, false);
			if ( NULL == BoardPtr ) { continue; }			
			BoardBarcodeSet.insert(BoardPtr->GetBoardBarcode());
			const size_t ComponentCount=BoardPtr->GetBoardComponentCount();
			for ( k=0; k<ComponentCount; k++ )
			{
				CAOIComponent *ComponentPtr = BoardPtr->GetBoardComponentPtr(k, false);
				if ( NULL == ComponentPtr ) { continue;}
				CAOIModel *ModelPtr = ComponentPtr->GetComponentModelPtr();
				if ( NULL == ModelPtr ) { continue; }
				std::wstring ComName=ComponentPtr->GetComponentName();
				const size_t WndCount = ModelPtr->GetModelWndCount();
				for ( size_t s=0; s<WndCount; s++ )
				{
					CAOIWnd *WndPtr = ModelPtr->GetModelWndPtr(s, false);
					if ( NULL == WndPtr ) { continue; }					
					if ( WND_DEFECT_BODY_WRONG_CODE != WndPtr->GetWndDefectID() ) { continue; }

					RESULT_ID ResultID  = WndPtr->GetWndResultID();
					CAlgParam &AlgParam = WndPtr->GetWndAlgParam();
					TALG_PARAM_BARCODE_RECOGNIZE &brParam = AlgParam.GetAlgParamBarcodeRecognize();
					std::wstring barcode = brParam.brBarcodeResult;
					const size_t barLen = barcode.length();
					if ( 0 == barLen )
					{	barcode = ComName + std::wstring(L"_NG");	}
					wsPartBarcodeList = wsPartBarcodeList+barcode+std::wstring(L",");
				}
				const size_t Len=wsPartBarcodeList.length();				
				if ( Len > 0 ) 
				{
					const size_t CommaPos=Len-1;
					wsPartBarcodeList[CommaPos] = L'\n'; 
				}
			}
		}
	}

	const size_t Len = wsPartBarcodeList.length();
	if ( Len > 0 ) 
	{
		std::string PartBarcodeList;
		if ( JetAPI::wchar2string(wsPartBarcodeList.c_str(), PartBarcodeList) > 0 )
		{
			CString Name=strDateTime;
			Filename.Format(_T("%s\\%s.BAR"), DstFolder, Name);	
			TempName.Format(_T("%s\\%s.TXT"), TempFolder, Name);
			::DeleteFile(Filename);

			FILE *pfile = ::_tfopen(TempName, _T("w+"));
			if ( NULL == pfile )
			{
				m_ErrorString.Format(_T("Error, Open File Fault (%s)"), TempName);
				return false;
			}
			::fprintf(pfile, "%s", PartBarcodeList.c_str());
			::fclose(pfile); pfile = NULL;
			if ( ::CopyFile(TempName, Filename, FALSE) == FALSE ) 
			{
				m_ErrorString.Format(_T("Error, Save File Fault (%s)"), Filename);
				return false;
			}
			::DeleteFile(TempName);			
		}
	}

	if ( BoardBarcodeSet.empty() == false )
	{
		std::string BoardBarcodeList;
		auto Iter = BoardBarcodeSet.begin();
		for ( Iter=BoardBarcodeSet.begin(); Iter!=BoardBarcodeSet.end(); ++Iter )
		{	
			std::string BoardBarcode;			
			if ( JetAPI::wchar2string(Iter->c_str(), BoardBarcode) == 0 ) 
			{	continue; }

			char TempBarcode[256]="";
			JetAPI::AdjustTextA(BoardBarcode.c_str(), '_', TempBarcode, 256);
			BoardBarcodeList += std::string(TempBarcode)+('_');
		}
		const size_t Len=BoardBarcodeList.length();
		if ( Len > 0 ) 
		{	
			const size_t UnderLinePos=Len-1;
			BoardBarcodeList[UnderLinePos] = '\0';

			TempName.Format(_T("%s\\%s.TXT"), TempFolder, _T("BoardBarcode"));			
			FILE *pfile = ::_tfopen(TempName, _T("w+"));
			if ( NULL == pfile )
			{
				m_ErrorString.Format(_T("Error, Open File Fault (%s)"), TempName);
				return false;
			}			
			::fclose(pfile); pfile = NULL;

			CString Name=BoardBarcodeList.c_str();
			Filename.Format(_T("%s\\%s.TXT"), DstFolder, Name);
			if ( ::CopyFile(TempName, Filename, FALSE) == FALSE ) 
			{
				m_ErrorString.Format(_T("Error, Save File Fault (%s)"), Filename);
				return false;
			}
			::DeleteFile(TempName);		
		}
	}
	return true;
}
