//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectInspectionResultFileFn()//儲存專案檢測結果檔案-給線上調機使用			
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }

	size_t      i=0;
	CString     FolderSpc;
	CString     FolderTmp;
	CString     FolderTmp2;
	CString     FolderTuning;
	CString     FolderOffline;
	CString     FilenameSpc;
	CString     FilenameTmp;
	CString     FilenameTuning;
	CString     FilenameOffline;
	CString     MainName;
	LANE_ID     LaneID = ProjectPtr->GetProjectActLaneID();
	const bool  OfflineMode = AOIDataCollect.GetOfflineMode();
	const bool  OnlineTuningEnable = CheckProjectOnlineTuningRunning();		
	CAOIFileIO  FileIO;
	MainName = _T("InspectionResult.TXT");
	FolderTmp = AOIDataCollect.GetAOITempDirectory();
	FolderSpc = ProjectPtr->GetProjectSpcImageFolder();		
	FolderTmp2 = FolderTmp;
	switch ( LaneID )
	{
	case LANE_ID_B:	FolderTmp.Format(_T("%s\\%s"), FolderTmp2, _T("LB"));	break;
	default:
	case LANE_ID_A:	FolderTmp.Format(_T("%s\\%s"), FolderTmp2, _T("LA"));	break;
	}	
	::CreateDirectory(FolderTmp, NULL);
	FilenameSpc.Format(_T("%s\\%s"), FolderSpc, MainName);
	FilenameTmp.Format(_T("%s\\%s"), FolderTmp, MainName);	
	
	FileIO.SetFileName(FilenameSpc);
	if ( FileIO.OpenSaveFile(FilenameTmp) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		return false;
	}
	if ( WriteProjectInspectionResultFile(FileIO) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		return false; 
	}
	FileIO.CloseFile();
	::CopyFile(FilenameTmp, FolderSpc, FALSE);
	SetProjectInspectionResultFileTmp(FilenameTmp);
	const bool bSaveFiledUsingThread=ProjectPtr->GetProjectSaveFiledUsingThread();
	if ( false == bSaveFiledUsingThread )
	{
		FolderOffline = ProjectPtr->GetProjectOnlineOfflineFolder();
		if ( FolderOffline.GetLength() > 0 )
		{
			FilenameOffline.Format(_T("%s\\%s"), FolderOffline, MainName);
			::CopyFile(FilenameTmp, FilenameOffline, FALSE);
		}	
	
		if ( false==OfflineMode )
		{
			if ( true == OnlineTuningEnable ) 
			{				
				FolderTuning = ProjectPtr->GetProjectOnlineTuningFolder();
				if ( FolderTuning.GetLength() > 0 )
				{
					if ( ProjectPtr->CheckProjectOnlineTuningSaveInspectionFile() == false )
					{
						JetAPI::RemoveFolder(FolderTuning);
						ProjectPtr->SetProjectOnlineTuningFolder(_T(""));
					}
					else
					{
						FilenameTuning.Format(_T("%s\\%s"), FolderTuning, MainName);
						::CopyFile(FilenameTmp, FilenameTuning, FALSE);
					}
				}				
			}
		}
	}	
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::WriteProjectInspectionResultFile(CAOIFileIO &FileIO)//儲存專案檢測結果檔案-給線上調機使用
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }

	size_t         i=0,j=0;	
	size_t         WndCount=0;
	CString        Barcode;
	RESULT_ID      ResultID=RESULT_ID_NONE;
	CAOIWnd       *WndPtr = NULL;
	CAOIModel     *ModelPtr = NULL;
	CAOIPanel     *PanelPtr = NULL;
	CAOIBoard     *BoardPtr = NULL;
	CAOIComponent *ComponentPtr = NULL;
	const size_t   PanelCount = ProjectPtr->GetProjectPanelCount();
	const size_t   BoardCount = ProjectPtr->GetProjectBoardCount();
	const size_t   ComponentCount = ProjectPtr->GetProjectComponentCount();	
	
#ifdef _DEBUG
	if ( FileIO.CheckFileMode() == false ) { return false; }
	if ( FileIO.CheckFileOpened() == false ) { return false; }
#endif//_DEBUG

	UUID     uuid;	
	char     uuidStr[MAX_JET_PATH]="";	
	wchar_t  uuidWStr[MAX_JET_PATH]=L"";
	FileIO.SetFnName(_T("CAOIProject::WriteProjectInspectionResultFile"));

	//Project
	if ( FileIO.SaveChunk_INT(FILE_IO_PROJECT_SECTION_START, 0) == false ) { return false; }		
	if ( FileIO.SaveChunk_STR(FILE_IO_PROJECT_BASIC_BARCODE_RESULT, ProjectPtr->GetProjectBarcode()) == false ) { return false; }	
	if ( FileIO.SaveChunk_INT(FILE_IO_PROJECT_SECTION_END, 0) == false ) { return false; }	

	//Panel
	if ( FileIO.SaveChunk_INT(FILE_IO_PANEL_SECTION_START, 0) == false ) { return false; }	
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = ProjectPtr->GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		if ( PanelPtr->GetPanelDeleted() == true ) { continue; }
		if ( FileIO.SaveChunk_INT(FILE_IO_PANEL_START, 0) == false ) { return false; }	

		uuid = PanelPtr->GetObjUuid();	
		JetAPI::UUIDToStringA(uuid, uuidStr);
		JetAPI::UUIDToStringW(uuid, uuidWStr);
		if ( FileIO.GetSaveWStr() == true ) 
		{	if ( FileIO.SaveChunk_STR(FILE_IO_PANEL_OBJ_UUID, uuidWStr) == false ) { return false; } }
		else
		{	if ( FileIO.SaveChunk_STR(FILE_IO_PANEL_OBJ_UUID, uuidStr) == false ) { return false; } }

		if ( FileIO.SaveChunk_STR(FILE_IO_PANEL_BARCODE_RESULT, PanelPtr->GetPanelBarcode()) == false ) { return false; }
		if ( FileIO.SaveChunk_INT(FILE_IO_PANEL_END, 0) == false ) { return false; }	
	}
	if ( FileIO.SaveChunk_INT(FILE_IO_PANEL_SECTION_END, 0) == false ) { return false; }

	//Board
	if ( FileIO.SaveChunk_INT(FILE_IO_BOARD_SECTION_START, 0) == false ) { return false; }	
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = ProjectPtr->GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
		if ( BoardPtr->GetBoardDeleted() == true ) { continue; }
		if ( FileIO.SaveChunk_INT(FILE_IO_BOARD_START, 0) == false ) { return false; }	

		uuid = BoardPtr->GetObjUuid();	
		JetAPI::UUIDToStringA(uuid, uuidStr);
		JetAPI::UUIDToStringW(uuid, uuidWStr);
		if ( FileIO.GetSaveWStr() == true ) 
		{	if ( FileIO.SaveChunk_STR(FILE_IO_BOARD_OBJ_UUID, uuidWStr) == false ) { return false; } }
		else
		{	if ( FileIO.SaveChunk_STR(FILE_IO_BOARD_OBJ_UUID, uuidStr) == false ) { return false; } }

		if ( FileIO.SaveChunk_STR(FILE_IO_BOARD_BARCODE_RESULT, BoardPtr->GetBoardBarcode()) == false ) { return false; }
		if ( FileIO.SaveChunk_INT(FILE_IO_BOARD_END, 0) == false ) { return false; }	
	}
	if ( FileIO.SaveChunk_INT(FILE_IO_BOARD_SECTION_END, 0) == false ) { return false; }

	//Mark
	CAOIMark      *MarkPtr = NULL;
	const size_t   MarkCount = ProjectPtr->GetProjectMarkCount();	
	if ( FileIO.SaveChunk_INT(FILE_IO_MARK_SECTION_START, 0) == false ) { return false; }	
	for ( i=0; i<MarkCount; i++ )
	{
		MarkPtr = ProjectPtr->GetProjectMarkPtr(i, false);
		if ( NULL == MarkPtr ) { continue; }
		if ( MarkPtr->GetMarkDeleted() == true ) { continue; }
		
		uuid = MarkPtr->GetObjUuid();	
		JetAPI::UUIDToStringA(uuid, uuidStr);
		JetAPI::UUIDToStringW(uuid, uuidWStr);

		if ( FileIO.SaveChunk_INT(FILE_IO_MARK_START, 0) == false ) { return false; }	
		if ( FileIO.SaveChunk_INT(FILE_IO_MARK_PANEL_INDEX, MarkPtr->GetMarkPanelIndex_Project()) == false ) { return false; }
		if ( FileIO.SaveChunk_INT(FILE_IO_MARK_BOARD_INDEX, MarkPtr->GetMarkBoardIndex_Project()) == false ) { return false; }
		
		if ( FileIO.GetSaveWStr() == true ) 
		{	if ( FileIO.SaveChunk_STR(FILE_IO_MARK_OBJ_UUID, uuidWStr) == false ) { return false; } }
		else
		{	if ( FileIO.SaveChunk_STR(FILE_IO_MARK_OBJ_UUID, uuidStr) == false ) { return false; } }

		const TBasePlaneParam &BasePlaneParamRef=MarkPtr->GetMarkSpaceBasePlaneParam();		
		//if ( FileIO.SaveChunk_DBL(FILE_IO_MARK_LOCAL_BASE_RESULT_NX, BasePlaneParamRef.NormalX) == false ) { return false; }//20240327拿掉
		//if ( FileIO.SaveChunk_DBL(FILE_IO_MARK_LOCAL_BASE_RESULT_NY, BasePlaneParamRef.NormalY) == false ) { return false; }//20240327拿掉
		//if ( FileIO.SaveChunk_DBL(FILE_IO_MARK_LOCAL_BASE_RESULT_NZ, BasePlaneParamRef.NormalZ) == false ) { return false; }//20240327拿掉
		const CJetGroundEquation &GroundEquationRef=BasePlaneParamRef.GroundEquation;		
		if ( FileIO.SaveChunk_INT(FILE_IO_MARK_LOCAL_GROUND_RESULT, 0) == false ) { return false; }	
		if ( FileIO.WriteGroundEquationFile(GroundEquationRef) == false ) { return false; }

		if ( FileIO.SaveChunk_INT(FILE_IO_MARK_END, 0) == false ) { return false; }		
	}
	if ( FileIO.SaveChunk_INT(FILE_IO_MARK_SECTION_END, 0) == false ) { return false; }	


	//Component
	if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_SECTION_START, 0) == false ) { return false; }	
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
		
		ResultID = ComponentPtr->CheckComponentResultID_AOI();
		if ( RESULT_ID_NONE == ResultID ) { continue; }
		if ( RESULT_ID_OK == ResultID ) { continue; }
		if ( RESULT_ID_SKIP == ResultID ) { continue; }
		if ( RESULT_ID_BYPASS == ResultID ) { continue; }
	
		uuid = ComponentPtr->GetObjUuid();	
		JetAPI::UUIDToStringA(uuid, uuidStr);
		JetAPI::UUIDToStringW(uuid, uuidWStr);

		if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_START, 0) == false ) { return false; }	
		if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_PANEL_INDEX, ComponentPtr->GetComponentPanelIndex_Project()) == false ) { return false; }
		if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_BOARD_INDEX, ComponentPtr->GetComponentBoardIndex_Project()) == false ) { return false; }
		if ( FileIO.SaveChunk_STR(FILE_IO_COMPONENT_NAME, ComponentPtr->GetComponentName()) == false ) { return false; }
		if ( FileIO.GetSaveWStr() == true ) 
		{	if ( FileIO.SaveChunk_STR(FILE_IO_COMPONENT_OBJ_UUID, uuidWStr) == false ) { return false; } }
		else
		{	if ( FileIO.SaveChunk_STR(FILE_IO_COMPONENT_OBJ_UUID, uuidStr) == false ) { return false; } }

		ModelPtr = ComponentPtr->GetComponentModelPtr();
		if ( NULL != ModelPtr )
		{
			WndCount = ModelPtr->GetModelWndCount();
			if ( FileIO.SaveChunk_INT(FILE_IO_WND_SECTION_START, 0) == false ) { return false; }	
			for ( j=0; j<WndCount; j++ )
			{
				WndPtr = ModelPtr->GetModelWndPtr(j, false);
				if ( NULL == WndPtr ) { continue; }				
				ResultID = WndPtr->GetWndLogicResultID();
				if ( RESULT_ID_NONE == ResultID ) { continue; }
				if ( RESULT_ID_OK == ResultID ) { continue; }
				if ( RESULT_ID_SKIP == ResultID ) { continue; }
				if ( RESULT_ID_BYPASS == ResultID ) { continue; }				

				if ( FileIO.SaveChunk_INT(FILE_IO_WND_START, 0) == false ) { return false; }
				if ( FileIO.SaveChunk_INT(FILE_IO_WND_INDEX, j) == false ) { return false; }
				if ( FileIO.SaveChunk_INT(FILE_IO_WND_END, 0) == false ) { return false; }	
			}
			if ( FileIO.SaveChunk_INT(FILE_IO_WND_SECTION_END, 0) == false ) { return false; }	
		}		
		if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_END, 0) == false ) { return false; }
	}
	if ( FileIO.SaveChunk_INT(FILE_IO_COMPONENT_SECTION_END, 0) == false ) { return false; }	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectInspectionResultFile(LPCTSTR pfilename)//載入專案檢測結果檔案-給線上調機使用
{
	if ( LoadProjectInspectionResultFileFn(pfilename) == false )
	{
		SetProjectExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectInspectionResultFileFn(LPCTSTR pfilename)//載入專案檢測結果檔案-給線上調機使用
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }
	if ( NULL == pfilename ) { return false; }

	size_t         i=0, j=0;	
	size_t         WndCount=0;
	CAOIFileIO     FileIO;	
	RESULT_ID      ResultID;
	CAOIWnd       *WndPtr = NULL;
	CAOIModel     *ModelPtr = NULL;
	CAOIComponent *ComponentPtr = NULL;
	CString        Filename = pfilename;
	const size_t   ComponentCount = ProjectPtr->GetProjectComponentCount();	

	FileIO.SetFileName(Filename);
	if ( FileIO.OpenLoadFile(Filename) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		return false;
	}
	
	CAOIMark    *MarkPtr = NULL;	
	const size_t MarkCount = ProjectPtr->GetProjectMarkCount();	
	for ( i=0; i<MarkCount; i++ )
	{
		MarkPtr = ProjectPtr->GetProjectMarkPtr(i, false);
		if ( NULL == MarkPtr ) { continue; }
		MarkPtr->GetMarkGroundEquation_Online().ClearGroundParam();
	}

	ResultID = RESULT_ID_NONE;
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }		
		ComponentPtr->InitComponentInspection();
		ComponentPtr->SetComponentSelected(false);		
	}

	if ( ReadProjectInspectionResultFile(FileIO) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		FileIO.CloseFile();
		return false;
	}
	FileIO.CloseFile();

	SetProjectLoadInspectionResultFile(true);
	BuildProjectDefectComponentList();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ReadProjectInspectionResultFile(CAOIFileIO &FileIO)//載入專案檢測結果檔案-給線上調機使用
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }

#ifdef _DEBUG
	if ( FileIO.CheckFileMode() == false ) { return false; }
	if ( FileIO.CheckFileOpened() == false ) { return false; }
#endif//_DEBUG
	
	UUID           uuid;	
	size_t         i=0;	
	size_t         WndIdxCnt=0;
	int            index = 0;
	double         dValue = 0.0;
	bool           bGetUuid=false;
	unsigned int   PanelIndex=0;
	unsigned int   BoardIndex=0;
	int            WndIndex=0;
	std::vector<int>  WndIdxList;
	bool           bWrongComponent=false;
	CString        BoardBarcode;
	CString        PanelBarcode;
	CString        ProjectBarcode;	
	CString        ComponentName;
	CString        ComponentName2;
	RESULT_ID      ResultID=RESULT_ID_NONE;
	CAOIWnd       *WndPtr = NULL;
	CAOIMark      *MarkPtr = NULL;
	CAOIModel     *ModelPtr = NULL;
	CAOIPanel     *PanelPtr = NULL;
	CAOIBoard     *BoardPtr = NULL;
	CAOIComponent *ComponentPtr = NULL;	
	CJetGroundEquation GroundEquation;
	FileIO.SetFnName(_T("CAOIProject::ReadProjectInspectionResultFile"));		
	//----------------------------------------------------------------------------------------//	
	while ( FileIO.CheckFileEnd()==false )
	{ 		
		if ( FileIO.LoadChunk(index) == false )		
		{	continue; }		
		
		switch ( index )
		{
		case FILE_IO_PROJECT_SECTION_START://專案參數區間-起點
			break;
		case FILE_IO_PROJECT_SECTION_END://專案參數區間-終點
			break;
		case FILE_IO_PROJECT_BASIC_BARCODE_RESULT://專案參數-條碼結果
			if ( FileIO.GetLoadWStr()==true )
			{	ProjectBarcode = FileIO.GetData_WSTR();	}
			else
			{	ProjectBarcode = FileIO.GetData_STR();	}
			SetProjectBarcode(ProjectBarcode);
			BackupProjectBarcode();			
			break;
		case FILE_IO_PANEL_SECTION_START://整板參數區間-起點
			break;
		case FILE_IO_PANEL_SECTION_END://整板參數區間-終點
			break;
		case FILE_IO_PANEL_START://整板參數-起點
			bGetUuid=false;
			PanelBarcode = _T("");
			break;
		case FILE_IO_PANEL_END://整板參數-終點
			if ( true == bGetUuid )
			{
				PanelPtr = ProjectPtr->GetProjectPanelPtrByPanelUUID(uuid);
				if ( NULL != PanelPtr )
				{	
					PanelPtr->SetPanelBarcode(PanelBarcode);	
					PanelPtr->BackupPanelBarcode();
				}
			}
			bGetUuid=false;			
			break;
		case FILE_IO_PANEL_OBJ_UUID://整板參數-OBJ-UUID
			bGetUuid=false;
			if ( FileIO.GetLoadWStr()==true )
			{
				if ( JetAPI::UUIDFromStringW(FileIO.GetData_WSTR(), uuid) == true )
				{	bGetUuid = true;	}
			}
			else
			{
				if ( JetAPI::UUIDFromStringA(FileIO.GetData_STR(), uuid) == true )
				{	bGetUuid = true;	}
			}
			break;
		case FILE_IO_PANEL_BARCODE_RESULT://整板參數-條碼機引數
			if ( FileIO.GetLoadWStr()==true )
			{	PanelBarcode = FileIO.GetData_WSTR();	}
			else
			{	PanelBarcode = FileIO.GetData_STR();	}	
			break;
		case FILE_IO_BOARD_SECTION_START://單板參數區間-起點
			break;
		case FILE_IO_BOARD_SECTION_END://單板參數區間-終點
			break;
		case FILE_IO_BOARD_START://單板參數-起點
			bGetUuid=false;
			BoardBarcode = _T("");
			break;
		case FILE_IO_BOARD_END://單板參數-終點
			if ( true == bGetUuid )
			{
				BoardPtr = ProjectPtr->GetProjectBoardPtrByBoardUUID(uuid);
				if ( NULL != BoardPtr )
				{	
					BoardPtr->SetBoardBarcode(BoardBarcode);	
					BoardPtr->BackupBoardBarcode();
				}
			}
			bGetUuid=false;	
			break;
		case FILE_IO_BOARD_OBJ_UUID://單板參數-OBJ-UUID
			bGetUuid=false;
			if ( FileIO.GetLoadWStr()==true )
			{
				if ( JetAPI::UUIDFromStringW(FileIO.GetData_WSTR(), uuid) == true )
				{	bGetUuid = true;	}
			}
			else
			{
				if ( JetAPI::UUIDFromStringA(FileIO.GetData_STR(), uuid) == true )
				{	bGetUuid = true;	}
			}
			break;
		case FILE_IO_BOARD_BARCODE_RESULT:
			if ( FileIO.GetLoadWStr()==true )
			{	BoardBarcode = FileIO.GetData_WSTR();	}
			else
			{	BoardBarcode = FileIO.GetData_STR();	}	
			break;

		case FILE_IO_MARK_SECTION_START:
			break;			
		case FILE_IO_MARK_SECTION_END:
			break;	
		case FILE_IO_MARK_START:
			MarkPtr = NULL;			
			break;			
		case FILE_IO_MARK_END:			
			break;	
		case FILE_IO_MARK_PANEL_INDEX:
			PanelIndex = (FileIO.GetData_INT());
			break;
		case FILE_IO_MARK_BOARD_INDEX:
			BoardIndex = (FileIO.GetData_INT());
			break;			
		case FILE_IO_MARK_OBJ_UUID:
			bGetUuid=false;
			if ( FileIO.GetLoadWStr()==true )
			{
				if ( JetAPI::UUIDFromStringW(FileIO.GetData_WSTR(), uuid) == true )
				{	bGetUuid = true;	}
			}
			else
			{
				if ( JetAPI::UUIDFromStringA(FileIO.GetData_STR(), uuid) == true )
				{	bGetUuid = true;	}
			}	
			if ( true == bGetUuid )
			{	MarkPtr = ProjectPtr->GetProjectMarkPtrByMarkUUID(uuid);	}
			break;		
		case FILE_IO_MARK_LOCAL_BASE_RESULT_NX://20240327拿掉			
			break;
		case FILE_IO_MARK_LOCAL_BASE_RESULT_NY://20240327拿掉			
			break;
		case FILE_IO_MARK_LOCAL_BASE_RESULT_NZ://20240327拿掉			
			break;
		case FILE_IO_MARK_LOCAL_GROUND_RESULT://特徵點參數-局部基準面結果
			if ( NULL == MarkPtr )
			{	FileIO.ReadGroundEquationFile(GroundEquation);	}
			else
			{	FileIO.ReadGroundEquationFile(MarkPtr->GetMarkGroundEquation_Online());	}		
			break;

		case FILE_IO_COMPONENT_SECTION_START://零件區間參數-起點
			break;
		case FILE_IO_COMPONENT_SECTION_END://零件區間參數-終點
			break;
		case FILE_IO_COMPONENT_START://零件參數-起點
			PanelIndex = -1;
			BoardIndex = -1;
			ComponentName = _T("");
			bGetUuid=false;
			WndIdxList.clear();
			bWrongComponent = false;			
			break;
		case FILE_IO_COMPONENT_END://零件參數-終點
			if ( true == bGetUuid )
			{
				ComponentPtr = ProjectPtr->GetProjectComponentPtrByComponentUUID(uuid);
				if ( NULL != ComponentPtr )
				{
				#ifdef _DEBUG					
					ComponentName2 = ComponentPtr->GetComponentName();
					if ( ComponentName.CompareNoCase(ComponentName2) != 0 )
					{	bWrongComponent = true;	}
				#endif//_DEBUG
					ComponentPtr->SetComponentResultID_AOI(RESULT_ID_NG);				
					ComponentPtr->SetComponentSelected(true);					
					
					WndIdxCnt = WndIdxList.size();
					ModelPtr = ComponentPtr->GetComponentModelPtr();
					if ( NULL != ModelPtr )
					{	
						for ( i=0; i<WndIdxCnt; i++ )
						{
							WndIndex = WndIdxList[i];
							WndPtr = ModelPtr->GetModelWndPtr(WndIndex, true);
							if ( NULL == WndPtr ) { continue; }
							WndPtr->SetWndResultID(RESULT_ID_NG);
							WndPtr->SetWndLogicResultID(RESULT_ID_NG);
							WndPtr->GetWndAlgParam().SetAlgResultID(RESULT_ID_NG);
						}
						ModelPtr->BuildModelDefectWndGroupIDList();
					}					
				}
			}
			bGetUuid = false;
			WndIdxList.clear();
			break;		
		case FILE_IO_COMPONENT_PANEL_INDEX://零件參數-的整板引數
			PanelIndex = (FileIO.GetData_INT());
			break;
		case FILE_IO_COMPONENT_BOARD_INDEX://零件參數-的單板引數
			BoardIndex = (FileIO.GetData_INT());
			break;
		case FILE_IO_COMPONENT_NAME://零件參數-名稱			
			if ( FileIO.GetLoadWStr()==true )
			{	ComponentName = (FileIO.GetData_WSTR());	}
			else
			{	ComponentName = (FileIO.GetData_STR()); }
			break;
		case FILE_IO_COMPONENT_OBJ_UUID://零件參數-的UUID
			bGetUuid=false;
			if ( FileIO.GetLoadWStr()==true )
			{
				if ( JetAPI::UUIDFromStringW(FileIO.GetData_WSTR(), uuid) == true )
				{	bGetUuid = true;	}
			}
			else
			{
				if ( JetAPI::UUIDFromStringA(FileIO.GetData_STR(), uuid) == true )
				{	bGetUuid = true;	}
			}			
			break;
		case FILE_IO_WND_SECTION_START://模組框參數區間-起點
			break;
		case FILE_IO_WND_SECTION_END://模組框參數區間-終點
			break;
		case FILE_IO_WND_START://模組框參數-起點
			break;
		case FILE_IO_WND_END://模組框參數-終點
			break;
		case FILE_IO_WND_OBJ_UUID://模組框參數-OBJ-UUID-無意義			
			break;			
		case FILE_IO_WND_INDEX:			
			WndIdxList.push_back(FileIO.GetData_INT());	
			break;
		}
	};
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CopyProjectSpcImage()//複製專案SPC圖檔
{
	CString FolderSpc=GetProjectSpcImageFolder();
	CString FolderLocal=GetProjectSpcImageFolderLocal();
	if ( GetProjectUseLocalFolder() == false )
	{ 
		JetAPI::RemoveFolder(FolderLocal);
		return true; 
	}		
	
	bool IsOK=true;
	CString CopyFnName;
	
	const bool bDeleteSrc = true;
	const bool bDeleteDst = true;
	const COPY_HUGE_FILES_MODE CopyHugeFilesMode = AOIDataCollect.GetCopyHugeFilesMode();
	switch ( CopyHugeFilesMode )
	{
	case COPY_HUGE_FILES_XCOPY:
		CopyFnName = _T("XCopyFolder");
		IsOK = JetAPI::XCopyFolderAToFolderB(FolderLocal, FolderSpc, bDeleteSrc, bDeleteDst, _T(""), -1, -1);
		break;
	case COPY_HUGE_FILES_ROBOCOPY:
		CopyFnName = _T("RoboCopyFolder");
		IsOK = JetAPI::RoboCopyFolderAToFolderB(FolderLocal, FolderSpc, bDeleteSrc, bDeleteDst, _T(""), -1, -1);
		break;			
	default:
	case COPY_HUGE_FILES_COPY:
		CopyFnName = _T("CopyFolder");
		IsOK = JetAPI::CopyFolderAToFolderB(FolderLocal, FolderSpc, bDeleteSrc, bDeleteDst, _T(""), -1, -1);
		break;
	}
	if ( false == IsOK )
	{
		m_ErrorString.Format(_T("Error, Copy Local Folder Fault [%s]\n%s -->\n%s"), CopyFnName, FolderLocal, FolderSpc);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CopyProjectSpcComponentImage(LPCTSTR FileMainNameSrc)//複製專案SPC零件圖檔
{	
	if ( NULL == FileMainNameSrc ) { return true; }
	if ( FN_DISABLE == AOIDataCollect.GetSystemParameter().m_AutoCopySpcComponentImageFiles )
	{	return true; }
	
	CString FileMainNameDst = GetProjectFileMainName();	
	if ( FileMainNameDst.CompareNoCase(FileMainNameSrc) == 0 )
	{	return true; }

	CString FolderSrc;
	CString FolderDst;
	CString CopyFnName;
	CString SpcFolderSrc;
	CString SpcFolderDst;
	CString SpcFolderBase = AOIDataCollect.GetAOIResultDirectory();
	SpcFolderSrc.Format(_T("%s\\%s"), SpcFolderBase, FileMainNameSrc);
	SpcFolderDst.Format(_T("%s\\%s"), SpcFolderBase, FileMainNameDst);	
	
	FolderSrc.Format(_T("%s\\%s"), SpcFolderSrc, PROJECT_SPC_COMPONENT_FOLDER);
	FolderDst.Format(_T("%s\\%s"), SpcFolderDst, PROJECT_SPC_COMPONENT_FOLDER);
	if ( JetAPI::IsFolderExist(FolderSrc) == false )
	{	return true; }

	CString       str;
	bool          IsOK=true;
	double        fnTime;
	LARGE_INTEGER fnStart;
	LARGE_INTEGER fnEnd;
	const bool bRemoveMsg = true;
	const bool bDeleteDst = false;	
	const bool bDeleteSrc = false;
	const COPY_HUGE_FILES_MODE CopyHugeFilesMode = AOIDataCollect.GetCopyHugeFilesMode();
	JetAPI::SetFuncTimeStart(fnStart);
	::CreateDirectory(SpcFolderDst, NULL);	::Sleep(0);
	::CreateDirectory(FolderDst, NULL);	::Sleep(0);
	switch ( CopyHugeFilesMode )
	{
	case COPY_HUGE_FILES_XCOPY:
		CopyFnName = _T("XCopyFolder");
		IsOK = JetAPI::XCopyFolderAToFolderB(FolderSrc, FolderDst, bDeleteSrc, bDeleteDst, _T(""), -1, -1);
		break;
	case COPY_HUGE_FILES_ROBOCOPY:
		CopyFnName = _T("RoboCopyFolder");
		IsOK = JetAPI::RoboCopyFolderAToFolderB(FolderSrc, FolderDst, bDeleteSrc, bDeleteDst, _T(""), -1, -1);
		break;			
	default:
	case COPY_HUGE_FILES_COPY:
		CopyFnName = _T("CopyFolder");
		IsOK = JetAPI::CopyFolderAToFolderB(FolderSrc, FolderDst, bDeleteSrc, bDeleteDst, _T(""), -1, -1);
		break;
	}
	JetAPI::SetFuncTimeStart(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("%s[%s] Time=%.3f ms"), CopyFnName, FolderDst, fnTime);
	AOIDataCollect.SaveMovingTimeMsg(str);
	if ( true == bRemoveMsg )
	{	JetAPI::RemoveWndBusy(NULL);	}					
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectSpcHeader()//儲存專案SPC檔頭
{
	if ( SaveProjectSpcHeaderFn() == false )
	{
		SetProjectExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectSpcHeaderFn()//儲存專案SPC檔頭
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }

	CString SpcFile;
	CString SrcFolder;
	CString SpcFolder;
	CString BaseFolder;	
	CString FileName = ProjectPtr->GetProjectFileName();
	CString FileMainName = ProjectPtr->GetProjectFileMainName();
	
	JetAPI::ExtractMainFileName(FileName, SrcFolder);
	BaseFolder = AOIDataCollect.GetAOIResultDirectory();
	SpcFolder.Format(_T("%s\\%s"), BaseFolder, FileMainName);
	SpcFile.Format(_T("%s\\%s.PRG"), BaseFolder, FileMainName);

	if ( JetAPI::CreateFolder(SpcFolder) == false )
	{
		m_ErrorString.Format(_T("Error, Create Folder Fault (%s)"), SpcFolder);
		return false;
	}

	//只有複製第1層資料
	const bool bDelSrc = false;
	const bool bClrDst = false;
	if ( JetAPI::CopyFolderAToFolderB(SrcFolder, SpcFolder, bDelSrc, bClrDst, _T(""), 0, 0) == false )
	{
		m_ErrorString.Format(_T("Error, Copy Folder Files Fault (%s -> %s )"), SrcFolder, SpcFolder);
		return false;
	}

	const CString ProjectFolderSrc=SrcFolder;
	const CString ProjectFolderDst=SpcFolder;	
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	COPY_HUGE_FILES_MODE CopyHugeFilesMode = AOIDataCollect.GetCopyHugeFilesMode();
	SAVE_SPC_OTHER_FILE_MODE SaveSpcLibraryMode = SysParam.m_SaveProjectSpcLibraryMode;		

	DWORD Res=IDYES;//複製資料庫資料夾
	if ( SAVE_SPC_OTHER_FILE_OFF == SaveSpcLibraryMode )
	{	Res=IDNO; }
	if ( SAVE_SPC_OTHER_FILE_AUTO == SaveSpcLibraryMode )
	{	Res=IDYES; }
	if ( SAVE_SPC_OTHER_FILE_ASK == SaveSpcLibraryMode )
	{
		CString str = _T("Save the project library to [Repair Buffer]?");
		str=LoadMultiLanguageString(str, str);
		Res = JetAPI::ShowMessageBox(str, MB_YESNO);
	}	

	if ( IDYES == Res )
	{
		const int MaxLevel=-1;
		const int CurrentLevel=-1;

		CString FdFolderSrc=AOIDataDefine.GetProjectFdFolderName(ProjectFolderSrc);
		CString FdFolderDst=AOIDataDefine.GetProjectFdFolderName(ProjectFolderDst);
		SrcFolder = FdFolderSrc;
		SpcFolder = FdFolderDst;	
		JetAPI::ClearFolder(SpcFolder);
		if ( JetAPI::CopyFolderAToFolderB(SrcFolder, SpcFolder, bDelSrc, bClrDst, _T(""), CurrentLevel, MaxLevel) == false )
		{
			m_ErrorString.Format(_T("Error, Copy Folder Files Fault (%s -> %s )"), SrcFolder, SpcFolder);
			return false;
		}

		CString FieldMarkFolderSrc=AOIDataDefine.GetProjectFieldMarkFolderName(ProjectFolderSrc);
		CString FieldMarkFolderDst=AOIDataDefine.GetProjectFieldMarkFolderName(ProjectFolderDst);
		SrcFolder = FieldMarkFolderSrc;
		SpcFolder = FieldMarkFolderDst;	
		JetAPI::ClearFolder(SpcFolder);
		if ( JetAPI::CopyFolderAToFolderB(SrcFolder, SpcFolder, bDelSrc, bClrDst, _T(""), CurrentLevel, MaxLevel) == false )
		{
			m_ErrorString.Format(_T("Error, Copy Folder Files Fault (%s -> %s )"), SrcFolder, SpcFolder);
			return false;
		}

		CString LibraryFolderSrc=AOIDataDefine.GetProjectLibraryFolderName(ProjectFolderSrc);
		CString LibraryFolderDst=AOIDataDefine.GetProjectLibraryFolderName(ProjectFolderDst);
		SrcFolder = LibraryFolderSrc;
		SpcFolder = LibraryFolderDst;	
		JetAPI::ClearFolder(SpcFolder);
		if ( JetAPI::HugeCopyFolderAToFolderB(CopyHugeFilesMode, SrcFolder, SpcFolder, bDelSrc, bClrDst, _T(""), CurrentLevel, MaxLevel) == false )
		{
			m_ErrorString.Format(_T("Error, Copy Folder Files Fault (%s -> %s )"), SrcFolder, SpcFolder);
			return false;
		}	
			
		CString PartLibraryFolderSrc=AOIDataDefine.GetProjectPartLibraryFolderName(ProjectFolderSrc);
		CString PartLibraryFolderDst=AOIDataDefine.GetProjectPartLibraryFolderName(ProjectFolderDst);
		SrcFolder = PartLibraryFolderSrc;
		SpcFolder = PartLibraryFolderDst;
		JetAPI::ClearFolder(SpcFolder);
		if ( JetAPI::HugeCopyFolderAToFolderB(CopyHugeFilesMode, SrcFolder, SpcFolder, bDelSrc, bClrDst, _T(""), CurrentLevel, MaxLevel) == false )
		{
			m_ErrorString.Format(_T("Error, Copy Folder Files Fault (%s -> %s )"), SrcFolder, SpcFolder);
			return false;
		}
	}
	
	::CopyFile(FileName, SpcFile, FALSE);

	SpcFile.Format(_T("%s\\%s.JSON"), BaseFolder, FileMainName);
	if ( SaveProjectSpcHeader_JSON(SpcFile) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectSpcHeader_JSON(bool bChkModified)//儲存專案SPC檔頭
{
	CAOIProject *ProjectPtr = this;
	if (FN_ENABLE != ProjectPtr->GetProjectParameter().m_SaveSPCHeaderJSONBeforeInspection) { return true; }
	if ( true == bChkModified )
	{
		if ( false == ProjectPtr->GetProjectHasModified() )
		{	return true; }
	}

	CString SpcFile;
	CString BaseFolder = AOIDataCollect.GetAOIResultDirectory();
	CString FileMainName = ProjectPtr->GetProjectFileMainName();
	SpcFile.Format(_T("%s\\%s.JSON"), BaseFolder, FileMainName);
	return ProjectPtr->SaveProjectSpcHeader_JSON(SpcFile);
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectSpcHeader_JSON(LPCTSTR pfilename)//儲存專案SPC檔頭
{		
	CAOIProject *ProjectPtr = this;
	if (NULL == ProjectPtr) { return false; }	
	if ( NULL == pfilename ) { return false; }

	ProjectPtr->SetProjectHasModified(false);
	
	CString          strText;
	size_t           szWrite = 0;
	const size_t     szBuffer = 256;
	wchar_t          strTag[szBuffer] = L"";
	wchar_t          strBuffer[szBuffer] = L"";	
	std::vector<CAOIComponent*> SpecComponentList;	
	const TProjectParameter &ProParam = GetProjectParameter();
	const LANE_ID    LaneID = ProjectPtr->GetProjectActLaneID();		
	DISTRICT_ID      DistrictID = ProjectPtr->GetProjectActDistrictID();
	const size_t     FrameCount = ProjectPtr->GetProjectFrameUniqueIDCount();
	const int        PanelCount = (int)(ProjectPtr->GetProjectPanelCount());
	const int        BoardCount = (int)(ProjectPtr->GetProjectBoardCount());
	const int        ComponentCount = (int)(ProjectPtr->GetProjectComponentCount());
	const unsigned int FrameIndex_3D = ProjectPtr->GetProjectFrameIndexByUniqueID(FRAME_UNIQUE_ID_DLP);		

	TCHAR   TMode[32] = _T("");
	CString filename;
	filename.Format(_T("%s\\%s.TMP"), AOIDataCollect.GetAOITempDirectory(), _T("SpcHeader"));

	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	FILE *pfile = ::_tfopen(filename, TMode);
	if (NULL == pfile)
	{
		m_ErrorString.Format(_T("Error, Open SPC Header to Save Fault (%s)"), filename);
		return false;
	}
	
	::fwprintf(pfile, L"{\n");
	
	//固定輸出"JET"
	::wcscpy(strTag, L"Identifier");
	wcscpy(strBuffer, AOI3D_VENDOR_W);//L"JET"
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	//檔案名稱
	::wcscpy(strTag, L"Project_File_Name");	
	strText.Format(_T("%s.PRG"), ProjectPtr->GetProjectFileMainName());	
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	//主版本
	::wcscpy(strTag, L"Major_Version");
	strText = _T("");
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);	

	::wcscpy(strTag, L"Data_Mode");	
	const int ProjectMode=0;
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, ProjectMode);

	::wcscpy(strTag, L"Location");
	strText = AOIDataCollect.GetMachineLocation();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	::wcscpy(strTag, L"Building");
	strText = AOIDataCollect.GetMachineBuilding();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	::wcscpy(strTag, L"Floor");
	strText = AOIDataCollect.GetMachineFloor();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	::wcscpy(strTag, L"Line");
	strText = AOIDataCollect.GetMachineLine(LaneID);
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	::wcscpy(strTag, L"Station");
	strText = AOIDataCollect.GetMachineStation(LaneID);
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	::wcscpy(strTag, L"RoomName");
	strText = AOIDataCollect.GetMachineRoom();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	::wcscpy(strTag, L"SN");
	strText = AOIDataCollect.GetMachineSN();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);	

	::wcscpy(strTag, L"Machine_Name");
	strText = AOIDataCollect.GetMachineName();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);	

	::wcscpy(strTag, L"Machine_Type");
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, AOIDataCollect.GetMachineType());	

	//3D圖是用幾號光源
	::wcscpy(strTag, L"Frame_3D");//20200720由3D_Frame改成Frame_3D	
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, FrameIndex_3D+1);

	//"Marge Mode" : 0,		// SFC合併用(整數)( 0:不合併 1~:第幾站 )(TB:上方為1下方為2)
	::wcscpy(strTag, L"Marge_Mode");
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, 0);

	//"Module": "NEW MODULE", //機種(字串-64 Byte)
	::wcscpy(strTag, L"Module");
	strText = ProjectPtr->GetProjectModuleName();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	//"N_Panels": 2, //大板總板數	
	::wcscpy(strTag, L"N_Panels");	
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, PanelCount);

	//"Scale_X:
	::wcscpy(strTag, L"Scale_X");
	::fwprintf(pfile, L"  \"%s\": %.3f,\n", strTag, AOIDataCollect.GetCameraResolutionX(PRIMARY_CAMERA_ID));

	//"Scale_Y:
	::wcscpy(strTag, L"Scale_Y");
	::fwprintf(pfile, L"  \"%s\": %.3f,\n", strTag, AOIDataCollect.GetCameraResolutionY(PRIMARY_CAMERA_ID));

	//"TotalParts": 345, //零件總數	
	::wcscpy(strTag, L"TotalParts");	
	size_t TotalParts=ProjectPtr->GetProjectComponentNotAgentCount();	
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, TotalParts);

	//GeneralStringParameter1
	::wcscpy(strTag, L"GeneralStringParameter1");
	strText = ProParam.m_ProjectGeneralParamStr_01.c_str();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);	

	//GeneralStringParameter2
	::wcscpy(strTag, L"GeneralStringParameter2");
	strText = ProParam.m_ProjectGeneralParamStr_02.c_str();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);	

	//GeneralStringParameter3
	::wcscpy(strTag, L"GeneralStringParameter3");
	strText = ProParam.m_ProjectGeneralParamStr_03.c_str();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);	

	//GeneralStringParameter4
	::wcscpy(strTag, L"GeneralStringParameter4");
	strText = ProParam.m_ProjectGeneralParamStr_04.c_str();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);	

	//MaxNumberCumulativeDefectsPart //警報-每個零件瑕疵數上限_ARS
	::wcscpy(strTag, L"MaxNumberCumulativeDefectsPart");
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, ProParam.m_AlaramEachComponentTotalNGCount_ARS);

	//MaxNumberConsecutiveDefectsPart //警報-每個零件連續瑕疵次數上限_ARS
	::wcscpy(strTag, L"MaxNumberConsecutiveDefectsPart");
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, ProParam.m_AlaramEachComponentContinueNGCount_ARS);

	if (SaveProjectSpcHeader_JSON_detail(pfile) == false) {
		CString str;
		JetAPI::GetSystemLastError(str);
		m_ErrorString.Format(_T("Error, %s"), str);
		return false;
	}

	::fwprintf(pfile, L"}\n");
	::fclose(pfile); pfile = NULL;	

	CString filename2 = pfilename;	
	if ( filename.CompareNoCase(filename2) != 0 )
	{
		if ( ::CopyFile(filename, filename2, FALSE) == FALSE )
		{
			CString str;
			JetAPI::GetSystemLastError(str);
			m_ErrorString.Format(_T("Error, %s"), str);
			return false;
		}
		::DeleteFile(filename);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectSpcHeader_JSON_detail(FILE *pfile) {

	CAOIProject *ProjectPtr = this;
	CAOIPanel *PanelPtr = NULL;
	CAOIModel *ModelPtr = NULL;

	const size_t     szBuffer = 256;
	wchar_t          strTag[szBuffer] = L"";
	wchar_t          strBuffer[szBuffer] = L"";

	const size_t PanelCount = ProjectPtr->GetProjectPanelCount();
	const size_t ModelCount = ProjectPtr->GetProjectModelCount();

	size_t i;

	::wcscpy(strTag, L"Panel_List");
	::fwprintf(pfile, L"  \"%s\":[\n", strTag);

	for (i = 0; i < PanelCount; i++) {
		PanelPtr = ProjectPtr->GetProjectPanelPtr(i, false);
		if (NULL == PanelPtr) { continue; }
		if (PanelPtr->WritePanelSpcHeader_JSON_detail(pfile, this) == false) { return FALSE; }
		//Prevent Trailing Comma
		if (i == PanelCount - 1) { ::fwprintf(pfile, L"\n"); }
		else { ::fwprintf(pfile, L",\n"); }
	}
	::fwprintf(pfile, L"  ],\n");

	::wcscpy(strTag, L"Model_List");
	::fwprintf(pfile, L"  \"%s\":[\n", strTag);

	for (i = 0; i < ModelCount; i++) {
		//if (i > 2)break;
		ModelPtr = ProjectPtr->GetProjectModelPtr(i, false);
		if (NULL == ModelPtr) { continue; }
		if (ModelPtr->WriteModelSpcHeader_JSON_detail(pfile, this) == false) { return FALSE; }
		//Prevent Trailing Comma
		if (i == ModelCount - 1) { ::fwprintf(pfile, L"\n"); }
		else { ::fwprintf(pfile, L",\n"); }
	}

	::fwprintf(pfile, L"  ]\n");
	return TRUE;
}
