//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectSpcFile_Binary(LPCTSTR pfilename)//儲存專案SPC檔案
{
	CAOIProject *ProjectPtr = this;
	if (NULL == ProjectPtr) { return false; }

	int              i = 0, j = 0;
	int              SpcPanelCount = 0;
	int              SpcBoardCount = 0;
	int              SpcComponentCount = 0;
	CString          strText;
	size_t           szWrite = 0;
	const size_t     szBufferSize = 256;
	char             ansiBuffer[szBufferSize] = "";
	TSpcChunk        SpcChunk;
	TSpcHeader       SpcHeader;
	TSpcProjectInfo  SpcProjectInfo;
	TSpcWindow       SpcWindow;
	TSpcPanel       *SpcPanelList = NULL;
	TSpcBoard       *SpcBoardList = NULL;
	TSpcComponent   *SpcComponentList = NULL;
	std::vector<TSpcChunk>  SpcChunkList;
	std::vector<TSpcWindow> SpcWindowList;
	CAOIPanel       *PanelPtr = NULL;
	CAOIBoard       *BoardPtr = NULL;
	CAOIComponent   *ComponentPtr = NULL;
	RECT             WndRect = { 0 };
	TPOINT2D         CornerPos[8];
	size_t           ModelWndCount = 0;
	CAOIWnd         *WndPtr = NULL;
	CAOIModel       *ModelPtr = NULL;
	DISTRICT_ID      DistrictID = ProjectPtr->GetProjectActDistrictID();
	const int        PanelCount = (int)(ProjectPtr->GetProjectPanelCount());
	const int        BoardCount = (int)(ProjectPtr->GetProjectBoardCount());
	const int        ComponentCount = (int)(ProjectPtr->GetProjectComponentCount());
	TTestResult      ResultLatest = ProjectPtr->GetProjectResultCurrent();

	CString filename;
	filename.Format(_T("%s\\%s.TMP"), AOIDataCollect.GetAOITempDirectory(), _T("SpcFile"));//20200407
	
	FILE *pfile = ::_tfopen(filename, _T("wb"));
	if (NULL == pfile)
	{
		m_ErrorString.Format(_T("Error, Open SPC File to Save Fault (%s)"), filename);
		return false;
	}
	//怕沒有資料
	SpcPanelCount = MAX(1, PanelCount);
	SpcBoardCount = MAX(1, BoardCount);
	SpcComponentCount = MAX(1, ComponentCount);

	SpcPanelList = new TSpcPanel[SpcPanelCount];
	SpcBoardList = new TSpcBoard[SpcBoardCount];
	SpcComponentList = new TSpcComponent[SpcComponentCount];
	if (NULL == SpcPanelList || NULL == SpcBoardList || NULL == SpcComponentList)
	{
		if (NULL != SpcPanelList)
		{
			delete[] SpcPanelList; SpcPanelList = NULL;
		}
		if (NULL != SpcBoardList)
		{
			delete[] SpcBoardList; SpcBoardList = NULL;
		}
		if (NULL != SpcComponentList)
		{
			delete[] SpcComponentList; SpcComponentList = NULL;
		}
		m_ErrorString.Format(_T("Error, Create SPC Data List Fault (%s)"), filename);
		return false;
	}
	//資訊資料
	SpcChunk.nType = CHUNK_TYPE_PROJECT_INFO;
	SpcChunk.nSize = (int)(sizeof(TSpcProjectInfo));
	SpcChunk.nCount = 1;
	SpcChunkList.push_back(SpcChunk);

	//整板資料
	SpcPanelCount = 0;
	for (i = 0; i<PanelCount; i++)
	{
		PanelPtr = ProjectPtr->GetProjectPanelPtr(i, false);
		if (NULL == PanelPtr) { continue; }
		if (PanelPtr->ConvertToSpcPanel(DistrictID, SpcPanelList[SpcPanelCount]) == false) { continue; }
		SpcPanelCount++;
	}
	const int szSpcPanelCount = SpcPanelCount;
	SpcChunk.nType = CHUNK_TYPE_PANEL_NODE;
	SpcChunk.nSize = (int)(sizeof(TSpcPanel));
	SpcChunk.nCount = SpcPanelCount;
	SpcChunkList.push_back(SpcChunk);

	//單板資料	
	SpcBoardCount = 0;
	for (i = 0; i<BoardCount; i++)
	{
		BoardPtr = ProjectPtr->GetProjectBoardPtr(i, false);
		if (NULL == BoardPtr) { continue; }
		if (BoardPtr->ConvertToSpcBoard(DistrictID, SpcBoardList[SpcBoardCount]) == false) { continue; }
		SpcBoardCount++;
	}
	const int szSpcBoardCount = SpcBoardCount;
	SpcChunk.nType = CHUNK_TYPE_BOARD_NODE;
	SpcChunk.nSize = (int)(sizeof(TSpcBoard));
	SpcChunk.nCount = SpcBoardCount;
	SpcChunkList.push_back(SpcChunk);

	//零件資料
	SpcComponentCount = 0;
	for (i = 0; i<ComponentCount; i++)
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if (NULL == ComponentPtr) { continue; }
		if ( ComponentPtr->CheckComponentIsAgent() == true ) { continue; }
		ComponentPtr = ComponentPtr->GetComponentResultPtr();
		if (ComponentPtr->ConvertToSpcComponent(SpcComponentList[SpcComponentCount]) == false) { continue; }
		SpcComponentCount++;

		//檢測框資料
		ModelPtr = ComponentPtr->GetComponentModelPtr();
		if (NULL == ModelPtr) { continue; }
		ModelWndCount = ModelPtr->GetModelWndCount();
		for (j = 0; j<ModelWndCount; j++)
		{
			WndPtr = ModelPtr->GetModelWndPtr(j, false);
			if (NULL == WndPtr) { continue; }
			WndPtr->GetWndExtendImageRect(WndRect);
			WndPtr->GetWndCornerPosStageRes(CornerPos);

			SpcWindow = TSpcWindow();
			SpcWindow.uuidWindow = WndPtr->GetObjUuid();
			SpcWindow.uuidComponent = ComponentPtr->GetObjUuid();
			SpcWindow.uComponentIndex = ComponentPtr->GetComponentIndex_Project();//零件編號
			SpcWindow.uWindowIndex = j;//檢測框編號
			SpcWindow.nDefectID = WndPtr->GetWndDefectID();//瑕疵編號
			SpcWindow.nAlgorithmID = WndPtr->GetWndAlgType();//演算法編號

			SpcWindow.rcImageRect = WndRect;//視窗影像區域
			SpcWindow.fStageCornerPosX[0] = CornerPos[0].x;//機台角落座標-X
			SpcWindow.fStageCornerPosY[0] = CornerPos[0].y;//機台角落座標-Y
			SpcWindow.fStageCornerPosX[1] = CornerPos[1].x;//機台角落座標-X
			SpcWindow.fStageCornerPosY[1] = CornerPos[1].y;//機台角落座標-Y
			SpcWindow.fStageCornerPosX[2] = CornerPos[2].x;//機台角落座標-X
			SpcWindow.fStageCornerPosY[2] = CornerPos[2].y;//機台角落座標-Y
			SpcWindow.fStageCornerPosX[3] = CornerPos[3].x;//機台角落座標-X
			SpcWindow.fStageCornerPosY[3] = CornerPos[3].y;//機台角落座標-Y

			SpcWindowList.push_back(SpcWindow);
		}
	}
	const int szSpcComponentCount = SpcComponentCount;
	SpcChunk.nType = CHUNK_TYPE_COMPONENT_NODE;
	SpcChunk.nSize = (int)(sizeof(TSpcComponent));
	SpcChunk.nCount = SpcComponentCount;
	SpcChunkList.push_back(SpcChunk);

	const int szSpcWindowCount = (int)(SpcWindowList.size());
	SpcChunk.nType = CHUNK_TYPE_WINDOW_NODE;
	SpcChunk.nSize = (int)(sizeof(TSpcWindow));
	SpcChunk.nCount = (int)(SpcWindowList.size());
	SpcChunkList.push_back(SpcChunk);
	const int nSpcChunkCount = (int)(SpcChunkList.size());

	::memset(&SpcHeader, 0x00, sizeof(SpcHeader));
	::strcpy(SpcHeader.sSymbol, "JETAOI3D");//標記
	SpcHeader.nVersion = 1;//板本編號
	SpcHeader.nChunkTypeNumber = nSpcChunkCount;//Chunk樣式數量
	szWrite = ::fwrite(&SpcHeader, sizeof(SpcHeader), 1, pfile);
	if (1 != szWrite)
	{
		if (NULL != SpcPanelList)
		{
			delete[] SpcPanelList; SpcPanelList = NULL;
		}
		if (NULL != SpcBoardList)
		{
			delete[] SpcBoardList; SpcBoardList = NULL;
		}
		if (NULL != SpcComponentList)
		{
			delete[] SpcComponentList; SpcComponentList = NULL;
		}
		m_ErrorString.Format(_T("Error, Write SPC File Fault (%s)"), _T("SpcHeader"));
		::fclose(pfile); pfile = NULL;
		return false;
	}
	for (i = 0; i<nSpcChunkCount; i++)
	{
		SpcChunk = SpcChunkList[i];
		szWrite = ::fwrite(&SpcChunk, sizeof(SpcChunk), 1, pfile);
		if (1 != szWrite)
		{
			if (NULL != SpcPanelList)
			{
				delete[] SpcPanelList; SpcPanelList = NULL;
			}
			if (NULL != SpcBoardList)
			{
				delete[] SpcBoardList; SpcBoardList = NULL;
			}
			if (NULL != SpcComponentList)
			{
				delete[] SpcComponentList; SpcComponentList = NULL;
			}
			m_ErrorString.Format(_T("Error, Write SPC File Fault (%s)"), _T("SpcChunk"));
			::fclose(pfile); pfile = NULL;
			return false;
		}
	}

	//專案資訊		
	if (ProjectPtr->ConvertToSpcProjectInfo(SpcProjectInfo) == false)
	{
		if (NULL != SpcPanelList)
		{
			delete[] SpcPanelList; SpcPanelList = NULL;
		}
		if (NULL != SpcBoardList)
		{
			delete[] SpcBoardList; SpcBoardList = NULL;
		}
		if (NULL != SpcComponentList)
		{
			delete[] SpcComponentList; SpcComponentList = NULL;
		}
		m_ErrorString.Format(_T("Error, Write SPC File Fault (%s)"), _T("ConvertToSpcProjectInfo"));
		::fclose(pfile); pfile = NULL;
		return false;
	}

	szWrite = ::fwrite(&SpcProjectInfo, sizeof(SpcProjectInfo), 1, pfile);
	if (1 != szWrite)
	{
		if (NULL != SpcPanelList)
		{
			delete[] SpcPanelList; SpcPanelList = NULL;
		}
		if (NULL != SpcBoardList)
		{
			delete[] SpcBoardList; SpcBoardList = NULL;
		}
		if (NULL != SpcComponentList)
		{
			delete[] SpcComponentList; SpcComponentList = NULL;
		}
		m_ErrorString.Format(_T("Error, Write SPC File Fault (%s)"), _T("SpcProjectInfo"));
		::fclose(pfile); pfile = NULL;
		return false;
	}

	szWrite = ::fwrite(SpcPanelList, sizeof(TSpcPanel), szSpcPanelCount, pfile);
	if (szSpcPanelCount != szWrite)
	{
		if (NULL != SpcPanelList)
		{
			delete[] SpcPanelList; SpcPanelList = NULL;
		}
		if (NULL != SpcBoardList)
		{
			delete[] SpcBoardList; SpcBoardList = NULL;
		}
		if (NULL != SpcComponentList)
		{
			delete[] SpcComponentList; SpcComponentList = NULL;
		}
		m_ErrorString.Format(_T("Error, Write SPC File Fault (%s)"), _T("SpcPanelList"));
		::fclose(pfile); pfile = NULL;
		return false;
	}

	szWrite = ::fwrite(SpcBoardList, sizeof(TSpcBoard), szSpcBoardCount, pfile);
	if (szSpcBoardCount != szWrite)
	{
		if (NULL != SpcPanelList)
		{
			delete[] SpcPanelList; SpcPanelList = NULL;
		}
		if (NULL != SpcBoardList)
		{
			delete[] SpcBoardList; SpcBoardList = NULL;
		}
		if (NULL != SpcComponentList)
		{
			delete[] SpcComponentList; SpcComponentList = NULL;
		}
		m_ErrorString.Format(_T("Error, Write SPC File Fault (%s)"), _T("SpcBoardList"));
		::fclose(pfile); pfile = NULL;
		return false;
	}

	szWrite = ::fwrite(SpcComponentList, sizeof(TSpcComponent), szSpcComponentCount, pfile);
	if (szSpcComponentCount != szWrite)
	{
		if (NULL != SpcPanelList)
		{
			delete[] SpcPanelList; SpcPanelList = NULL;
		}
		if (NULL != SpcBoardList)
		{
			delete[] SpcBoardList; SpcBoardList = NULL;
		}
		if (NULL != SpcComponentList)
		{
			delete[] SpcComponentList; SpcComponentList = NULL;
		}
		m_ErrorString.Format(_T("Error, Write SPC File Fault (%s)"), _T("SpcComponentList"));
		::fclose(pfile); pfile = NULL;
		return false;
	}

	for (i = 0; i<szSpcWindowCount; i++)
	{
		SpcWindow = SpcWindowList[i];
		szWrite = ::fwrite(&SpcWindow, sizeof(TSpcWindow), 1, pfile);
		if (1 != szWrite)
		{
			if (NULL != SpcPanelList)
			{
				delete[] SpcPanelList; SpcPanelList = NULL;
			}
			if (NULL != SpcBoardList)
			{
				delete[] SpcBoardList; SpcBoardList = NULL;
			}
			if (NULL != SpcComponentList)
			{
				delete[] SpcComponentList; SpcComponentList = NULL;
			}
			m_ErrorString.Format(_T("Error, Write SPC File Fault (%s)"), _T("SpcWindowList"));
			::fclose(pfile); pfile = NULL;
			return false;
		}
	}
	if (NULL != SpcPanelList)
	{
		delete[] SpcPanelList; SpcPanelList = NULL;
	}
	if (NULL != SpcBoardList)
	{
		delete[] SpcBoardList; SpcBoardList = NULL;
	}
	if (NULL != SpcComponentList)
	{
		delete[] SpcComponentList; SpcComponentList = NULL;
	}
	::fclose(pfile); pfile = NULL;

	CString filename2;
	if (NULL != pfilename)
	{	filename2 = pfilename;	}
	else
	{		
		CString ResultFolder=GetProjectSpcFileFolder();
		JetAPI::GetTime(strText, ResultLatest.sDateTimeS);		
		filename2.Format(_T("%s\\%s.DAT"), ResultFolder, strText);
		::DeleteFile(filename2);
	}
	if ( filename.CompareNoCase(filename2) != 0 )
	{
		if ( ::CopyFile(filename, filename2, FALSE) == FALSE )
		{
			CString str;
			JetAPI::GetSystemLastError(str);
			m_ErrorString.Format(_T("Error, %s"), str);
			return false;
		}
		::DeleteFile(filename);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectSpcFile_TXT(LPCTSTR pfilename)//儲存專案SPC檔案
{
	CAOIProject *ProjectPtr = this;
	if (NULL == ProjectPtr) { return false; }

	int              i = 0, j = 0;
	UUID             uuid;
	UINT             nFlag=0;
	UINT             nFlagBkLv1=0;
	UINT             nFlagBkLv2=0;
	TREGION4D        Region;
	CString          strText;
	size_t           szWrite = 0;
	const size_t     szBuffer = 256;
	wchar_t          strBuffer[szBuffer] = L"";		
	CAOIPanel       *PanelPtr = NULL;
	CAOIBoard       *BoardPtr = NULL;
	CAOIComponent   *ComponentPtr = NULL;
	RECT             WndRect = { 0 };
	TPOINT2D         CornerPos[8];
	size_t           ModelWndCount = 0;
	CAOIWnd         *WndPtr = NULL;
	CAOIModel       *ModelPtr = NULL;	
	double           StageCornerPosX[4]={0};
	double           StageCornerPosY[4]={0};
	const LANE_ID    LaneID = ProjectPtr->GetProjectActLaneID();
	DISTRICT_ID      DistrictID = ProjectPtr->GetProjectActDistrictID();
	const int        PanelCount = (int)(ProjectPtr->GetProjectPanelCount());
	const int        BoardCount = (int)(ProjectPtr->GetProjectBoardCount());
	const int        ComponentCount = (int)(ProjectPtr->GetProjectComponentCount());
	TTestResult      ResultLatest = ProjectPtr->GetProjectResultCurrent();

	CString filename;
	TCHAR   TMode[32] = _T("");
	filename.Format(_T("%s\\%s.TMP"), AOIDataCollect.GetAOITempDirectory(), _T("SpcFile"));//20200407

	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	FILE *pfile = ::_tfopen(filename, TMode);
	if (NULL == pfile)
	{
		m_ErrorString.Format(_T("Error, Open SPC File to Save Fault (%s)"), filename);
		return false;
	}	
	
	nFlag = 0;

	//專案資訊	
	uuid = ProjectPtr->GetObjUuid();
	JetAPI::UUIDToStringW(uuid, strBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = AOIDataCollect.GetMachineLocation();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = AOIDataCollect.GetMachineBuilding();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = AOIDataCollect.GetMachineFloor();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = AOIDataCollect.GetMachineRoom();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = AOIDataCollect.GetMachineLine(LaneID);
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = AOIDataCollect.GetMachineStation(LaneID);
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = AOIDataCollect.GetMachineSN();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = AOIDataDefine.GetLaneIDText(LaneID);
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = ProjectPtr->GetProjectModuleName();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = AOIDataDefine.GetPanelSideModeText(ProjectPtr->GetProjectPanelSideMode());
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = ProjectPtr->GetProjectWorkNumber();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	::fwprintf(pfile, L"%d, %.2f\n", nFlag, ResultLatest.sTestTime.tTest);	nFlag++;

	JetAPI::GetTime(strText, ResultLatest.sDateTimeS);
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	JetAPI::GetTime(strText, ResultLatest.sDateTimeS);
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	::fwprintf(pfile, L"%d, %d\n", nFlag, ResultLatest.sResultID);	nFlag++;

	::fwprintf(pfile, L"%d, %d\n", nFlag, ResultLatest.sResultID);	nFlag++;

	strText = AOIDataCollect.GetCurrentUserName();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	strText = AOIDataCollect.GetCurrentUserName();
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

	//整板資訊
	nFlagBkLv1 = nFlag;	
	for (i=0; i<PanelCount; i++)
	{
		PanelPtr = ProjectPtr->GetProjectPanelPtr(i, false);
		if (NULL == PanelPtr) {	continue; }
		nFlag = nFlagBkLv1;
		
		uuid = PanelPtr->GetObjUuid();
		JetAPI::UUIDToStringW(uuid, strBuffer);		
		::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;
		
		::fwprintf(pfile, L"%d, %d\n", nFlag, i+1);	nFlag++;
		
		strText = PanelPtr->GetPanelBarcode();
		JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
		::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

		::fwprintf(pfile, L"%d, %d\n", nFlag, PanelPtr->GetPanelResultID());	nFlag++;

		::fwprintf(pfile, L"%d, %d\n", nFlag, PanelPtr->GetPanelResultID());	nFlag++;		
		
		
		Region = PanelPtr->GetPanelRgnStage(DistrictID);
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, Region.minX);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, Region.minY);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, Region.maxX);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, Region.maxY);	nFlag++;
	}

	//單板資訊
	nFlagBkLv1 = nFlag;	
	for (i=0; i<BoardCount; i++)
	{
		BoardPtr = ProjectPtr->GetProjectBoardPtr(i, false);
		if (NULL == BoardPtr) {	continue; }
		nFlag = nFlagBkLv1;
		
		uuid = BoardPtr->GetObjUuid();
		JetAPI::UUIDToStringW(uuid, strBuffer);		
		::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;
		
		::fwprintf(pfile, L"%d, %d\n", nFlag, i+1);	nFlag++;
		
		strText = BoardPtr->GetBoardBarcode();
		JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
		::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

		::fwprintf(pfile, L"%d, %d\n", nFlag, BoardPtr->GetBoardResultID());	nFlag++;

		::fwprintf(pfile, L"%d, %d\n", nFlag, BoardPtr->GetBoardResultID());	nFlag++;				
		
		Region = BoardPtr->GetBoardRgnStage(DistrictID);
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, Region.minX);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, Region.minY);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, Region.maxX);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, Region.maxY);	nFlag++;
	}

	//零件資訊
	nFlagBkLv1 = nFlag;	
	for (i=0; i<ComponentCount; i++)
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if (NULL == ComponentPtr) {	continue; }
		if ( ComponentPtr->CheckComponentIsAgent() == true ) { continue; }
		ComponentPtr = ComponentPtr->GetComponentResultPtr();

		nFlag = nFlagBkLv1;
		
		uuid = ComponentPtr->GetObjUuid();
		JetAPI::UUIDToStringW(uuid, strBuffer);		
		::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;
		
		::fwprintf(pfile, L"%d, %d\n", nFlag, i+1);	nFlag++;
		
		strText = ComponentPtr->GetComponentName();
		JetAPI::UUIDToStringW(uuid, strBuffer);		
		::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

		strText = ComponentPtr->GetComponentPartNumber();
		JetAPI::UUIDToStringW(uuid, strBuffer);		
		::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

		strText = ComponentPtr->GetComponentModelName();
		JetAPI::UUIDToStringW(uuid, strBuffer);		
		::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

		strText = ComponentPtr->GetComponentNozzleName();
		JetAPI::UUIDToStringW(uuid, strBuffer);		
		::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

		strText = ComponentPtr->GetComponentNozzleName();
		JetAPI::UUIDToStringW(uuid, strBuffer);		
		::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

		ComponentPtr->GetComponentRoiStageCornerPosX(StageCornerPosX);
		ComponentPtr->GetComponentRoiStageCornerPosY(StageCornerPosY);
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, StageCornerPosX[0]);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, StageCornerPosX[1]);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, StageCornerPosX[2]);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, StageCornerPosX[3]);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, StageCornerPosY[0]);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, StageCornerPosY[1]);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, StageCornerPosY[2]);	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, StageCornerPosY[3]);	nFlag++;

		::fwprintf(pfile, L"%d, %.0f\n", nFlag, ComponentPtr->GetComponentResultOffsetX());	nFlag++;
		::fwprintf(pfile, L"%d, %.0f\n", nFlag, ComponentPtr->GetComponentResultOffsetY());	nFlag++;
		::fwprintf(pfile, L"%d, %.2f\n", nFlag, ComponentPtr->GetComponentResultSkewAngle());	nFlag++;

		::fwprintf(pfile, L"%d, %d\n", nFlag, ComponentPtr->GetComponentResultID_AOI());	nFlag++;
		::fwprintf(pfile, L"%d, %d\n", nFlag, ComponentPtr->GetComponentResultID_AOI());	nFlag++;
		
		ModelPtr = ComponentPtr->GetComponentModelPtr();
		if ( NULL != ModelPtr )
		{
			nFlagBkLv2 = nFlag;	
			ModelWndCount = ModelPtr->GetModelWndCount();
			for ( j=0; j<ModelWndCount; j++ )
			{
				WndPtr = ModelPtr->GetModelWndPtr(j, false);
				if ( NULL == WndPtr ) { continue; }
				nFlag = nFlagBkLv2;	

				uuid = ComponentPtr->GetObjUuid();
				JetAPI::UUIDToStringW(uuid, strBuffer);		
				::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;
		
				::fwprintf(pfile, L"%d, %d\n", nFlag, j+1);	nFlag++;

				strText = AOIDataDefine.GetWndDefectIDText(WndPtr->GetWndDefectID());
				JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
				::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;
		
				strText = AOIDataDefine.GetAlgTypeText(WndPtr->GetWndAlgType());
				JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
				::fwprintf(pfile, L"%d, %s\n", nFlag, strBuffer);	nFlag++;

				WndPtr->GetWndExtendImageRect(WndRect);
				::fwprintf(pfile, L"%d, %d\n", nFlag, WndRect.left);	nFlag++;
				::fwprintf(pfile, L"%d, %d\n", nFlag, WndRect.top);	nFlag++;
				::fwprintf(pfile, L"%d, %d\n", nFlag, WndRect.right);	nFlag++;
				::fwprintf(pfile, L"%d, %d\n", nFlag, WndRect.bottom);	nFlag++;

				WndPtr->GetWndCornerPosStageRes(CornerPos);
				::fwprintf(pfile, L"%d, %.0f\n", nFlag, CornerPos[0].x);	nFlag++;
				::fwprintf(pfile, L"%d, %.0f\n", nFlag, CornerPos[1].x);	nFlag++;
				::fwprintf(pfile, L"%d, %.0f\n", nFlag, CornerPos[2].x);	nFlag++;
				::fwprintf(pfile, L"%d, %.0f\n", nFlag, CornerPos[3].x);	nFlag++;

				::fwprintf(pfile, L"%d, %.0f\n", nFlag, CornerPos[0].y);	nFlag++;
				::fwprintf(pfile, L"%d, %.0f\n", nFlag, CornerPos[1].y);	nFlag++;
				::fwprintf(pfile, L"%d, %.0f\n", nFlag, CornerPos[2].y);	nFlag++;
				::fwprintf(pfile, L"%d, %.0f\n", nFlag, CornerPos[3].y);	nFlag++;
			}
		}
	}	
	::fclose(pfile); pfile = NULL;

	CString filename2;
	if (NULL != pfilename)
	{	filename2 = pfilename;	}
	else
	{
		CString ResultFolder=GetProjectSpcFileFolder();
		JetAPI::GetTime(strText, ResultLatest.sDateTimeS);
		filename2.Format(_T("%s\\%s.TXT"), ResultFolder, strText);
		::DeleteFile(filename2);
	}
	if ( filename.CompareNoCase(filename2) != 0 )
	{
		if ( ::CopyFile(filename, filename2, FALSE) == FALSE )
		{
			CString str;
			JetAPI::GetSystemLastError(str);
			m_ErrorString.Format(_T("Error, %s"), str);
			return false;
		}
		::DeleteFile(filename);
	}
	return true;
}
