	::wcscpy(strTag, L"Resolution X");
	::fwprintf(pfile, L"  \"%s\": %.16f,\n", strTag, ImageResX);

	//Resolution Y 解析度Y
	::wcscpy(strTag, L"Resolution Y");
	::fwprintf(pfile, L"  \"%s\": %.16f,\n", strTag, ImageResY);
	
	::wcscpy(strTag, L"Test_Time");
