	::wcscpy(strTag, L"Check_Time");
	JetAPI::GetTime(strText, ResultLatest.sDateTimeS);
	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	::wcscpy(strTag, L"Cost_Time");
	::fwprintf(pfile, L"  \"%s\": %.2f,\n", strTag, ResultLatest.sTestTime.tTest);

	::wcscpy(strTag, L"3D_Frame");	
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, FrameIndex_3D+1);
	
	//Panel Statistic
