	JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
	::fwprintf(pfile, L"  \"%s\": \"%s\",\n", strTag, strBuffer);

	//"Image Mode" : 2,		// 圖片格式(整數) 1:JPG 2:PNG 3:BMP
	::wcscpy(strTag, L"Image_Mode");
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, 1);

	//"Marge Mode" : 0,		// SFC合併用(整數)( 0:不合併 1~:第幾站 )(TB:上方為1下方為2)
	::wcscpy(strTag, L"Marge_Mode");
	::fwprintf(pfile, L"  \"%s\": %d,\n", strTag, 0);

	//Resolution X 解析度X
