bool CAOIProject::ClearProjectOnlineTuningFolder()//清除專案線上調機資料夾
{
#ifndef OFFLINE_VERSION
	CString FileMainName;
	CString OnlineTuningFolder;
	CString OnlineTuningProjectFolder;

	FileMainName = GetProjectFileMainName();
	if ( FileMainName.GetLength() == 0 ) { return true; }
	OnlineTuningFolder = AOIDataCollect.GetAOIOnlineTuningDirectory();
	OnlineTuningProjectFolder.Format(_T("%s\\%s"), OnlineTuningFolder, FileMainName);
	JetAPI::RemoveFolder(OnlineTuningProjectFolder);
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CopyToProjectOnlineTuningFolder()//複製到專案線上調機資料夾
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }
	if ( CheckProjectOnlineTuningRunning() == false ) { return true; }
	//return true;

	CString SrcFolder;
	CString DstFolder;
	SrcFolder = ProjectPtr->GetProjectInspectionOfflineFolder();
	DstFolder = ProjectPtr->GetProjectOnlineTuningFolder();
	if ( DstFolder.GetLength() == 0 ) { return true; }
	SAVE_TEST_IMAGE_MODE OnlineTuningMode = ProjectPtr->GetProjectOnlineTuningMode();
	if ( SAVE_TEST_IMAGE_EVERYONE == OnlineTuningMode )
	{		
		const bool bEnable = false;
		ProjectPtr->WriteProjectOnlineTuningEnable(bEnable);
		ProjectPtr->SetProjectOnlineTuningEnable(bEnable);
		ProjectPtr->SetProjectOnlineTuningEnableUI(bEnable);
	}
	else
	{
		if ( ProjectPtr->CheckProjectOnlineTuningSaveInspectionFile() == false )
		{
			JetAPI::RemoveFolder(DstFolder);
			ProjectPtr->SetProjectOnlineTuningFolder(_T(""));
			return true; 
		}
	}

	ProjectPtr->AddProjectOnlineTuningSavedCount();
	ProjectPtr->AddProjectCopyFile(SrcFolder, DstFolder, false);	
	if ( GetProjectSaveFiledUsingThread() == true )
	{
		CString DstFile, MainName;
		CString SrcFile=GetProjectInspectionResultFileTmp();
		JetAPI::ExtractFileNameNoPath(SrcFile, MainName);
		DstFile.Format(_T("%s\\%s"), DstFolder, MainName);
		ProjectPtr->AddProjectCopyFile(SrcFile, DstFile, true);		
	}
	AOIDataCollect.AddRemoveFolder_OnlineTuning(DstFolder);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CopyToProjectOnlineOfflineFolder()//複製到專案線上離線編程資料夾
{
	CAOIProject *ProjectPtr = this;
	if ( NULL == ProjectPtr ) { return false; }	
	//return true;

	bool      CheckSaveImage = false;
	TASK_MODE TaskMode = ProjectPtr->GetProjectActTaskMode();
	if ( TASK_INSPECT_PROJECT != TaskMode ) { return true; }
	SAVE_TEST_IMAGE_MODE SaveFieldImageMode = ProjectPtr->GetProjectSaveFieldImageMode();
	if ( SAVE_TEST_IMAGE_DISABLE == SaveFieldImageMode ) { return true; }
	
	CString SrcFolder;
	CString DstFolder;
	SrcFolder = ProjectPtr->GetProjectInspectionOfflineFolder();
	DstFolder = ProjectPtr->GetProjectOnlineOfflineFolder();
	if ( DstFolder.GetLength() == 0 ) { return true; }
	ProjectPtr->AddProjectCopyFile(SrcFolder, DstFolder, false);	
	if ( GetProjectSaveFiledUsingThread() == true )
	{
		CString DstFile, MainName;
		CString SrcFile=GetProjectInspectionResultFileTmp();
		JetAPI::ExtractFileNameNoPath(SrcFile, MainName);
		DstFile.Format(_T("%s\\%s"), DstFolder, MainName);
		ProjectPtr->AddProjectCopyFile(SrcFile, DstFile, true);	
	}
	return true;
}
