//-------------------------------------------------------------------------------------//	
bool CAOIProject::ExecProjectCopyFileFn()//執行專案複製檔案執行緒
{	
#ifndef OFFLINE_VERSION
	size_t       i=0;
	TCopyFolder  CopyFolder;
	std::vector<TCopyFolder>  ProjectCopyFileListTmp;

	LockProject();
	ProjectCopyFileListTmp = m_ProjectCopyFileList;
	m_ProjectCopyFileList.clear();
	UnlockProject();
	
	bool           IsOK=true;
	CString        str;
	double         fnTime=0.0;	
	LARGE_INTEGER  fnStart, fnEnd;	
	
	AOIDataCollect.SaveDebugMessage(_T("CAOIProject::SaveProjectTestMapFile Start"));
	JetAPI::SetFuncTimeStart(fnStart);
	IsOK = SaveProjectTestMapFile();
	JetAPI::SetFuncTimeEnd(fnEnd);
	AOIDataCollect.SaveDebugMessage(_T("CAOIProject::SaveProjectTestMapFile End"));
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);	
	str.Format(_T("CAOIProject::SaveProjectTestMapFile: %.2f ms"), fnTime);
	AOIDataCollect.SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	if ( false == IsOK )
	{	return false;	}

	const size_t CopyFileCount = ProjectCopyFileListTmp.size();
	if ( 0 == CopyFileCount ) { return true; }

	const bool bClearSrc=false;
	const bool bClearDst=false;
	for ( i=0; i<CopyFileCount; i++ )
	{		
		CopyFolder = ProjectCopyFileListTmp[i];
		if ( GetProjectIsClosing() == true ) { return true; }
		if ( AOIDataCollect.GetIsSystemReleased() == true ) { return true; }
		if ( AOIDataCollect.GetIsSystemException() == true ) { return true; }
		if ( GetProjectCopyFileThreadCmd() == THREAD_COMMAND_TO_EXIT ) { return true; }
		if ( GetProjectCopyFileThreadCmd() == THREAD_COMMAND_TO_IDLE ) { return true; }
		if ( true == CopyFolder.bFileMode )
		{
			if ( FALSE == ::CopyFile(CopyFolder.SrcFolder, CopyFolder.DstFolder, FALSE) )
			{
				this->m_ErrorString.Format(_T("Error, Copy Project File Fault (From:[%s] To:[%s])"), CopyFolder.SrcFolder, CopyFolder.DstFolder);
				return false;
			}
		}
		else
		{
			const bool bChkStop=true;
			JetAPI::SetStopCopyFunc(false);
			if ( JetAPI::CopyFolderAToFolderB(CopyFolder.SrcFolder, CopyFolder.DstFolder, bClearSrc, bClearDst, _T(""), -1, -1, bChkStop) == false )
			{
				this->m_ErrorString.Format(_T("Error, Copy Project Folder Fault (From:[%s] To:[%s])"), CopyFolder.SrcFolder, CopyFolder.DstFolder);
				return false;
			}
		}		
	}
#endif//OFFLINE_VERSION	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SetProjectCopyFileEvent()//啟用專案複製檔案事件
{
#ifndef OFFLINE_VERSION
	if ( NULL == m_ProjectCopyFileEvent ) { return true; }
	::SetEvent(m_ProjectCopyFileEvent);
#endif//OFFLINE_VERSION	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CreateProjectCopyFileThread()//建立專案複製檔案執行緒
{	
#ifndef OFFLINE_VERSION
	size_t  i=0;
	CString str;
	size_t ThreadIdx = 0;
	if ( this->DeleteProjectCopyFileThread() == false ) { return false; }	
	m_ProjectCopyFileThreadCmd = THREAD_COMMAND_TO_IDLE;	
	m_ProjectCopyFileHandle = (HANDLE)::_beginthreadex(NULL, NULL, &ProjectCopyFileThreadFn, (void*)this, NULL, &m_ProjectCopyFileID);
	if ( NULL == m_ProjectCopyFileHandle )
	{	
		m_ProjectCopyFileThreadState = THREAD_STATE_NONE;
		m_ErrorString = _T("Eorror, Create Thread Fault (m_ProjectCopyFileHandle == NULL)");
		AOIExceptionCodeCtrl.SetAOIExceptionCode_Thread(AOI_EXCEPTION_THREAD_CREATE, m_ErrorString);
		JetAPI::ShowMessageBox(m_ErrorString);
		return false;		
	}

	SYSTEMTIME LocalTime;
	::GetLocalTime(&LocalTime);
	str.Format(_T("%s_%.4d%.2d%.2d%.2d%.2d%.2d"), _T("Project Copy File Event"), 
		LocalTime.wYear, LocalTime.wMonth, LocalTime.wDay, LocalTime.wHour, LocalTime.wMinute, LocalTime.wSecond);
	m_ProjectCopyFileEvent = JetAPI::CreateEvent(NULL, TRUE, TRUE, str);	
	if ( NULL == m_ProjectCopyFileEvent )
	{
		::CloseHandle(m_ProjectCopyFileHandle); m_ProjectCopyFileHandle=NULL;
		m_ErrorString = _T("Eorror, Create Event Fault (m_ProjectCopyFileEvent == NULL)");
		AOIExceptionCodeCtrl.SetAOIExceptionCode_Thread(AOI_EXCEPTION_THREAD_CREATE, m_ErrorString);
		JetAPI::ShowMessageBox(m_ErrorString);
		return false;		
	}
	::SetThreadPriority(m_ProjectCopyFileHandle, THREAD_PRIORITY_BELOW_NORMAL); 	
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::DeleteProjectCopyFileThread()//刪除專案複製檔案執行緒
{	
#ifndef OFFLINE_VERSION	
	size_t i = 0;
	size_t ThreadIdx = 0;
	DWORD WaitTime = 10000;//1 sec
	if ( NULL == m_ProjectCopyFileHandle ) { return true; }
	SetProjectCopyFileThreadCmd(THREAD_COMMAND_TO_EXIT);	
	DWORD Res = ::WaitForSingleObject(m_ProjectCopyFileHandle, WaitTime);
	::CloseHandle(m_ProjectCopyFileHandle); 
	m_ProjectCopyFileHandle = NULL;
	if ( NULL != m_ProjectCopyFileEvent )
	{	
		::CloseHandle(m_ProjectCopyFileEvent); 
		m_ProjectCopyFileEvent=NULL; 
	}	
	m_ProjectCopyFileList.clear();
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::IdleProjectCopyFileThread(bool WaitOn)//閒置專案複製檔案執行緒	
{	
#ifndef OFFLINE_VERSION	
	size_t i=0, j=0;
	if ( NULL == m_ProjectCopyFileHandle ) { return true; }	
	if ( THREAD_STATE_RUNNING != m_ProjectCopyFileThreadState ) { return true; }
	
	JetAPI::SetStopCopyFunc(true);
	SetProjectCopyFileThreadCmd(THREAD_COMMAND_TO_IDLE);
	if ( WaitOn == true ) 
	{	
		const size_t MaxCount = 2000;
		const size_t SleepTime = 10;
		for ( i=0; i<MaxCount; i++ )
		{
			if ( THREAD_COMMAND_TO_EXIT == m_ProjectCopyFileThreadCmd ) { break; }			
			if ( THREAD_STATE_NONE == m_ProjectCopyFileThreadState ) {	break; }
			if ( THREAD_STATE_IDLE == m_ProjectCopyFileThreadState ) {	break; }
			::Sleep(SleepTime);
		}
		ClearProjectCopyFileList();
		if ( i == MaxCount )
		{
			JetAPI::SetStopCopyFunc(false);
			this->m_ErrorString = _T("Error, wait for IdleProjectCopyFileThread too long");
			return false;
		}		
	}	
	JetAPI::SetStopCopyFunc(false);
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::StartProjectCopyFileThread(bool WaitOn)//開始專案複製檔案執行緒	
{
#ifndef OFFLINE_VERSION	
	size_t i=0, j=0;
	if ( NULL == m_ProjectCopyFileHandle ) { return true; }
	const size_t CopyFileCount = m_ProjectCopyFileList.size();
	SAVE_TEST_MAP_MODE SaveProjectTestMap = GetProjectParameter().m_SaveProjectTestMap;
	if ( 0==CopyFileCount && SAVE_TEST_MAP_DISABLE==SaveProjectTestMap ) { return true; }

	if ( NULL != m_ProjectCopyFileEvent )
	{	::ResetEvent(m_ProjectCopyFileEvent);	}
	if ( THREAD_STATE_FINISH == m_ProjectCopyFileThreadState )
	{	SetProjectCopyFileThreadState(THREAD_STATE_IDLE); }	
	SetProjectCopyFileThreadCmd(THREAD_COMMAND_TO_RUN);

	if ( WaitOn == true ) 
	{	
		const size_t MaxCount = 200;
		const size_t SleepTime = 10;
		for ( i=0; i<MaxCount; i++ )
		{
			if ( THREAD_COMMAND_TO_RUN != m_ProjectCopyFileThreadCmd )//切入下一個階段
			{	break; }
			if ( THREAD_STATE_IDLE != m_ProjectCopyFileThreadState )
			{	break; }
			::Sleep(SleepTime);
		}
		if ( i == MaxCount )
		{
			this->m_ErrorString = _T("Error, wait for StartProjectCopyFileThread too long");
			AOIExceptionCodeCtrl.SetAOIExceptionCode_Thread(AOI_EXCEPTION_THREAD_WAIT_FOR_START, m_ErrorString);
			return false;
		}		
	}	
#endif//OFFLINE_VERSION
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::WaitForProjectCopyFileThreadFinish()//等待專案複製檔案執行緒
{
#ifndef OFFLINE_VERSION		
	size_t i=0;	
	DWORD Res = 0;		
	const DWORD MaxCounts = 1000;
	const DWORD SleepTime = 100;
	if ( NULL == m_ProjectCopyFileEvent ) { return true; }		
	AOIDataCollect.SaveDebugMessage(_T("WaitForProjectCopyFileThreadFinish-Start"));
	for ( i=0; i<MaxCounts; i++ )
	{
		if ( AOIDataCollect.GetIsSystemReleased() == true ) { return true; }
		if ( AOIDataCollect.GetIsSystemException() == true ) { return true; }
		if ( THREAD_COMMAND_TO_EXIT == m_ProjectCopyFileThreadCmd ) { return true; }	
		if ( THREAD_COMMAND_TO_IDLE == m_ProjectCopyFileThreadCmd )
		{	break; }
		Res = ::WaitForSingleObject(m_ProjectCopyFileEvent, SleepTime);
		if ( Res != WAIT_TIMEOUT ) { break; }
	}	
	if ( MaxCounts == i ) 
	{
		AOIDataCollect.SaveDebugMessage(_T("WaitForProjectCopyFileThreadFinish-Fault"));
		m_ErrorString = _T("Error, Wait for WaitForProjectCopyFileThreadFinish too long");
		AOIExceptionCodeCtrl.SetAOIExceptionCode_Thread(AOI_EXCEPTION_THREAD_WAIT_FOR_FINISH, m_ErrorString);
		return false;
	}
	AOIDataCollect.SaveDebugMessage(_T("WaitForProjectCopyFileThreadFinish-End"));
#endif//OFFLINE_VERSION
	return true;
}
