//-------------------------------------------------------------------------------------//
bool CAOIProject::ExecProjectSaveFieldFn()//執行專案儲存視野執行緒
{
#ifndef OFFLINE_VERSION	
	size_t       i=0;
	bool bPartImageMode=false;
	CAOIField   *FieldPtr=NULL;
	std::vector<CAOIField*>  SaveFieldListTmp;

	LockProject();
	SaveFieldListTmp = m_ProjectSaveFieldList;
	m_ProjectSaveFieldList.clear();
	UnlockProject();

	const size_t SaveFieldCount = SaveFieldListTmp.size();
	if ( 0 == SaveFieldCount ) { return true; }

	for ( i=0; i<SaveFieldCount; i++ )
	{		
		FieldPtr = SaveFieldListTmp[i];
		if ( NULL == FieldPtr ) { continue; }
		if ( GetProjectIsClosing() == true ) { break; }
		if ( AOIDataCollect.GetIsSystemReleased() == true ) { break; }
		if ( AOIDataCollect.GetIsSystemException() == true ) { break; }
		if ( GetProjectSaveFieldThreadCmd() == THREAD_COMMAND_TO_EXIT ) { break; }		
		if ( GetProjectSaveFieldThreadCmd() == THREAD_COMMAND_TO_IDLE ) { break; }		
		int OpenMpCnt=2;
		bool bSucc=true;
		TCHAR ErrMsg[128]=_T("");
		const bool bCalcFinish=GetProjectTestCalcFinish();
		const int FrameCount=(int)(FieldPtr->GetFieldFramePtrCount());
		if ( true == bCalcFinish )
		{	OpenMpCnt = 8;	}
		else
		{	OpenMpCnt = 2;	}
		OpenMpCnt = MIN(FrameCount, OpenMpCnt);
	#ifdef OPEN_MP_USE
		#pragma omp parallel for num_threads(OpenMpCnt)
	#endif//OPEN_MP_USE
		for ( int j=0; j<FrameCount; j++ )
		{
			if ( false == bSucc )
			{	break; }
			CAOIFrame *FramePtr = FieldPtr->GetFieldFramePtr(j, true);
			if ( NULL == FramePtr ) { continue; }
			if ( FramePtr->ExecFrameSave_Thread() == false )
			{
				CAOIFrame::LockFrame();
				bSucc = false;
				::_stprintf(ErrMsg, _T("Error, Save Frame Fault\n(%s\\%s)"), FramePtr->GetFrameFileFolder(), FramePtr->GetFrameFileName());
				CAOIFrame::UnlockFrame();
			}
		}		
		//FieldPtr->SetFieldLockRelease(false);
		if ( false == bSucc )
		{
			SetErrorString(ErrMsg);
			for ( size_t k=i+1; k<SaveFieldCount; k++ )
			{
				FieldPtr = SaveFieldListTmp[k];
				if ( NULL == FieldPtr ) { continue; }
				bPartImageMode = FieldPtr->GetFieldPartImageMode();

				if ( true == bPartImageMode )
				{
					CAOIField::LockField();
					FieldPtr->SetFieldMergeState(FIELD_MERGE_CLEAR);
					CAOIField::UnlockField();
				}
				FieldPtr->SetFieldLockRelease(false);
				
				const int FrameCount=(int)(FieldPtr->GetFieldFramePtrCount());
				for ( int j=0; j<FrameCount; j++ )
				{	
					CAOIFrame *FramePtr = FieldPtr->GetFieldFramePtr(j, true);
					if ( NULL == FramePtr ) { continue; }
					FramePtr->SetFrameImageSaved(true);
					if ( true == bPartImageMode )
					{
						FramePtr->ClearFrameBuffer();
						CAOIFrame::LockFrame();
						FramePtr->SetFrameMergeState(FRAME_MERGE_CLEAR);
						CAOIFrame::UnlockFrame();
					}
				}
			}
			return false;
		}
	}	

	for ( size_t k=0; k<SaveFieldCount; k++ )
	{
		FieldPtr = SaveFieldListTmp[k];
		if ( NULL == FieldPtr ) { continue; }
		bPartImageMode = FieldPtr->GetFieldPartImageMode();

		if ( true == bPartImageMode )
		{
			CAOIField::LockField();
			FieldPtr->SetFieldMergeState(FIELD_MERGE_CLEAR);
			CAOIField::UnlockField();
		}
		FieldPtr->SetFieldLockRelease(false);
		
		const int FrameCount=(int)(FieldPtr->GetFieldFramePtrCount());
		for ( int j=0; j<FrameCount; j++ )
		{	
			CAOIFrame *FramePtr = FieldPtr->GetFieldFramePtr(j, true);
			if ( NULL == FramePtr ) { continue; }
			FramePtr->SetFrameImageSaved(true);
			if ( true == bPartImageMode )
			{
				FramePtr->ClearFrameBuffer();
				CAOIFrame::LockFrame();
				FramePtr->SetFrameMergeState(FRAME_MERGE_CLEAR);
				CAOIFrame::UnlockFrame();
			}
		}
	}
#endif//OFFLINE_VERSION		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SetProjectSaveFieldEvent()//啟用專案儲存視野事件		
{
#ifndef OFFLINE_VERSION
	if ( NULL == m_ProjectSaveFieldEvent ) { return true; }
	::SetEvent(m_ProjectSaveFieldEvent);
#endif//OFFLINE_VERSION	

	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CreateProjectSaveFieldThread()//建立專案儲存視野執行緒
{
#ifndef OFFLINE_VERSION
	size_t  i=0;
	CString str;
	size_t ThreadIdx = 0;
	if ( this->DeleteProjectSaveFieldThread() == false ) { return false; }		
	m_ProjectSaveFieldThreadCmd = THREAD_COMMAND_TO_IDLE;	
	m_ProjectSaveFieldHandle = (HANDLE)::_beginthreadex(NULL, NULL, &ProjectSaveFieldThreadFn, (void*)this, NULL, &m_ProjectSaveFieldID);
	if ( NULL == m_ProjectSaveFieldHandle )
	{	
		m_ProjectSaveFieldThreadState = THREAD_STATE_NONE;
		m_ErrorString = _T("Eorror, Create Thread Fault (m_ProjectSaveFieldHandle == NULL)");
		AOIExceptionCodeCtrl.SetAOIExceptionCode_Thread(AOI_EXCEPTION_THREAD_CREATE, m_ErrorString);
		JetAPI::ShowMessageBox(m_ErrorString);
		return false;		
	}

	SYSTEMTIME LocalTime;
	::GetLocalTime(&LocalTime);
	str.Format(_T("%s_%.4d%.2d%.2d%.2d%.2d%.2d"), _T("Project Save Defect Field Event"), 
		LocalTime.wYear, LocalTime.wMonth, LocalTime.wDay, LocalTime.wHour, LocalTime.wMinute, LocalTime.wSecond);
	m_ProjectSaveFieldEvent = JetAPI::CreateEvent(NULL, TRUE, TRUE, str);	
	if ( NULL == m_ProjectSaveFieldEvent )
	{
		::CloseHandle(m_ProjectSaveFieldHandle); m_ProjectSaveFieldHandle=NULL;
		m_ErrorString = _T("Eorror, Create Event Fault (m_ProjectSaveFieldEvent == NULL)");
		AOIExceptionCodeCtrl.SetAOIExceptionCode_Thread(AOI_EXCEPTION_THREAD_CREATE, m_ErrorString);
		JetAPI::ShowMessageBox(m_ErrorString);
		return false;		
	}
	::SetThreadPriority(m_ProjectSaveFieldHandle, THREAD_PRIORITY_BELOW_NORMAL); 	
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::DeleteProjectSaveFieldThread()//刪除專案儲存視野執行緒
{
#ifndef OFFLINE_VERSION	
	size_t i = 0;
	size_t ThreadIdx = 0;
	DWORD WaitTime = 10000;//1 sec
	if ( NULL == m_ProjectSaveFieldHandle ) { return true; }
	SetProjectSaveFieldThreadCmd(THREAD_COMMAND_TO_EXIT);	
	DWORD Res = ::WaitForSingleObject(m_ProjectSaveFieldHandle, WaitTime);
	::CloseHandle(m_ProjectSaveFieldHandle); 
	m_ProjectSaveFieldHandle = NULL;
	if ( NULL != m_ProjectSaveFieldEvent )
	{	
		::CloseHandle(m_ProjectSaveFieldEvent); 
		m_ProjectSaveFieldEvent=NULL; 
	}	
	ClearProjectSaveFiledList();
	SetProjectSaveFieldThreadExecuted(false);
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::IdleProjectSaveFieldThread(bool WaitOn)//閒置專案儲存視野執行緒	
{	
#ifndef OFFLINE_VERSION	
	size_t i=0, j=0;
	if ( NULL == m_ProjectSaveFieldHandle ) { return true; }	
	if ( THREAD_STATE_RUNNING != m_ProjectSaveFieldThreadState ) { return true; }	
	SetProjectSaveFieldThreadCmd(THREAD_COMMAND_TO_IDLE);

	if ( WaitOn == true ) 
	{	
		const size_t MaxCount = 2000;
		const size_t SleepTime = 10;
		for ( i=0; i<MaxCount; i++ )
		{
			if ( THREAD_COMMAND_TO_EXIT == m_ProjectSaveFieldThreadCmd ) { break; }			
			if ( THREAD_STATE_NONE == m_ProjectSaveFieldThreadState ) {	break; }
			if ( THREAD_STATE_IDLE == m_ProjectSaveFieldThreadState ) {	break; }
			::Sleep(SleepTime);
		}
		LockProject();
		ClearProjectSaveFiledList();
		UnlockProject();
		if ( i == MaxCount )
		{
			this->m_ErrorString = _T("Error, wait for IdleProjectSaveFieldThread too long");
			return false;
		}		
	}	
#endif//OFFLINE_VERSION	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::StartProjectSaveFieldThread(bool WaitOn)//開始專案儲存視野執行緒
{
#ifndef OFFLINE_VERSION	
	size_t i=0, j=0;
	if ( NULL == m_ProjectSaveFieldHandle ) { return true; }
	if ( NULL != m_ProjectSaveFieldEvent )
	{	::ResetEvent(m_ProjectSaveFieldEvent);	}
	if ( THREAD_STATE_FINISH == m_ProjectSaveFieldThreadState )
	{	SetProjectSaveFieldThreadState(THREAD_STATE_IDLE); }	
	SetProjectSaveFieldThreadExecuted(true);
	SetProjectSaveFieldThreadCmd(THREAD_COMMAND_TO_RUN);

	if ( WaitOn == true ) 
	{	
		const size_t MaxCount = 200;
		const size_t SleepTime = 10;
		for ( i=0; i<MaxCount; i++ )
		{
			if ( THREAD_COMMAND_TO_RUN != m_ProjectSaveFieldThreadCmd )//切入下一個階段
			{	break; }
			if ( THREAD_STATE_IDLE != m_ProjectSaveFieldThreadState )
			{	break; }
			::Sleep(SleepTime);
		}
		if ( i == MaxCount )
		{
			this->m_ErrorString = _T("Error, wait for StartProjectSaveFieldThread too long");
			AOIExceptionCodeCtrl.SetAOIExceptionCode_Thread(AOI_EXCEPTION_THREAD_WAIT_FOR_START, m_ErrorString);
			return false;
		}		
	}	
#endif//OFFLINE_VERSION	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::WaitForProjectSaveFieldThreadFinish()//等待專案儲存視野執行緒
{
#ifndef OFFLINE_VERSION		
	size_t i=0;	
	DWORD Res = 0;		
	const DWORD MaxCounts = 1000;
	const DWORD SleepTime = 100;
	if ( NULL == m_ProjectSaveFieldEvent ) { return true; }		
	AOIDataCollect.SaveDebugMessage(_T("WaitForProjectSaveFieldThreadFinish-Start"));
	for ( i=0; i<MaxCounts; i++ )
	{
		if ( AOIDataCollect.GetIsSystemReleased() == true ) { return true; }
		if ( AOIDataCollect.GetIsSystemException() == true ) { return true; }
		if ( THREAD_COMMAND_TO_EXIT == m_ProjectSaveFieldThreadCmd ) { return true; }	
		if ( THREAD_COMMAND_TO_IDLE == m_ProjectSaveFieldThreadCmd )
		{	break; }
		Res = ::WaitForSingleObject(m_ProjectSaveFieldEvent, SleepTime);
		if ( Res != WAIT_TIMEOUT ) { break; }
	}	
	if ( MaxCounts == i ) 
	{
		AOIDataCollect.SaveDebugMessage(_T("WaitForProjectSaveFieldThreadFinish-Fault"));
		m_ErrorString = _T("Error, Wait for WaitForProjectSaveFieldThreadFinish too long");
		AOIExceptionCodeCtrl.SetAOIExceptionCode_Thread(AOI_EXCEPTION_THREAD_WAIT_FOR_FINISH, m_ErrorString);
		return false;
	}
	SetProjectSaveFieldThreadExecuted(false);
	AOIDataCollect.SaveDebugMessage(_T("WaitForProjectSaveFieldThreadFinish-End"));
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AddProjectSaveField(CAOIField *FieldPtr)//新增專案儲存視野資料夾	
{
	if ( NULL == FieldPtr ) { return true; }
#ifndef OFFLINE_VERSION	
	if ( GetProjectSaveFieldThreadExecuted() == false ) { return true; }
	if ( FieldPtr->GetFieldIsInSaveList() == true ) { return true; }
	LockProject();
	if ( FieldPtr->GetFieldIsInSaveList() == true )
	{ 
		UnlockProject();
		return true; 
	}
	FieldPtr->SetFieldLockRelease(true);
	FieldPtr->SetFieldIsInSaveList(true);	
	m_ProjectSaveFieldList.push_back(FieldPtr);

	const size_t FrameCount=FieldPtr->GetFieldFramePtrCount();
	for ( size_t i=0; i<FrameCount; i++ )
	{
		CAOIFrame *FramePtr=FieldPtr->GetFieldFramePtr(i, false);
		if ( FramePtr->GetFrameImageSaved() == true ) { continue; }
		m_ProjectSaveFrameList.push_back(FramePtr);		
	}
	UnlockProject();
#endif//OFFLINE_VERSION
	return true;
}
