//-------------------------------------------------------------------------------------//
bool CAOIProject::CloneProjectMarkImage(IMAGE_SIZE &ImageW, IMAGE_SIZE &ImageH, IMAGE_SIZE &ImageStep, IMAGE_SIZE &BitCount, IMAGE_PTR &ImagePtr)//取得專案標記圖資訊	
{
	const char fnName[] ="CAOIProject::CloneProjectMarkImage";
	JetMemory.free_func(ImagePtr);
	if ( NULL == m_ProjectMarkPtr )
	{
		m_ErrorString = _T("Error, No Project Mark Image");
		return false; 
	}
	ImageW = m_ProjectMarkW;
	ImageH = m_ProjectMarkH;
	ImageStep = m_ProjectMarkStep;
	BitCount = m_ProjectMarkBitCount;
	const size_t BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);
	if ( 0 == BufferSize ) { return false; }	
	if ( JetMemory.alloc_func(BufferSize, ImagePtr, fnName, "ImagePtr") == false )
	{	
		m_ErrorString = JetMemory.GetErrorString();
		return false; 
	}
	::memcpy(ImagePtr, m_ProjectMarkPtr, sizeof(IMAGE_DATA)*BufferSize);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::InspectProjectMark(const TPOINT2D &StagePos, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, IMAGE_PTR ImagePtr)//檢測專案標記
{
	if ( InspectProjectMarkFn(StagePos, ImageW, ImageH, ImageStep, BitCount, ImagePtr) == false )
	{
		SetProjectExceptionCode(AOI_EXCEPTION_PROJECT_MARK_IMAGE_TEST);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::InspectProjectMarkFn(const TPOINT2D &StagePos, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, IMAGE_PTR ImagePtr)//檢測專案標記
{
	CString str;
	BOOL bSave=TRUE;
	const unsigned int ProjectIndex = GetProjectIndex();	
	IMAGE_PTR      MarkPtr = m_ProjectMarkPtr;
	IMAGE_SIZE     MarkW = m_ProjectMarkW;
	IMAGE_SIZE     MarkH = m_ProjectMarkH;
	IMAGE_SIZE     MarkStep = m_ProjectMarkStep;
	IMAGE_SIZE     MarkBitCount = m_ProjectMarkBitCount;
	IMAGE_SIZE     RoiW = MarkW+256;//外擴256個像素
	IMAGE_SIZE     RoiH = MarkH+256;//外擴256個像素	
	if ( NULL == MarkPtr )
	{
		m_ErrorString = _T("Error, no project mark image");
		return false;
	}
	if ( MarkBitCount != BitCount )
	{
		m_ErrorString = _T("Error, project mark image bitcount exception");
		return false;
	}	
	if ( RoiW>ImageW || RoiH>ImageH )
	{
		m_ErrorString = _T("Error, project mark image roi size exception");
		return false;
	}
#ifdef _DEBUG
	if ( TRUE == bSave )
	{
		str.Format(_T("%s\\ProjectMarkFov[%d].PNG"), AOIDataCollect.GetAOITempDirectory(), ProjectIndex+1);
		ImageAPI.SaveImage(str, ImageW, ImageH, ImageStep, BitCount, ImagePtr, true);
	}
#endif//_DEBUG

	RECT           RoiRect={0};
	IMAGE_PTR      RoiPtr = NULL;
	IMAGE_SIZE     RoiStep = JetAPI::GetBMPImagePixelsPerLine(RoiW, BitCount, 4);
	RoiRect.left = (ImageW-RoiW)/2;
	RoiRect.top  = (ImageH-RoiH)/2;
	RoiRect.right = RoiRect.left + RoiW;
	RoiRect.bottom = RoiRect.top + RoiH;
	if ( ImageAPI.ExtractRoiImage(ImageW, ImageH, ImageStep, BitCount, ImagePtr, RoiRect, RoiStep, RoiPtr, false) == false )
	{
		m_ErrorString = ImageAPI.GetImageApiErrorString();
		return false;
	}

	CJetMatch    Match;
	JET_MATCH_LIB_TYPE MatchLibType = AOIDataCollect.GetMatchLibType();
	if ( Match.SetMatchLibType(MatchLibType)==false )
	{
		JetMemory.free_func(RoiPtr);
		m_ErrorString = Match.GetErrorString();
		return false;
	}
	//initial eMatch
	Match.SetMatchDefaultParam();
	//Match.SetMinReducedArea(nMinReduceArea);
	//Match.SetFinalReduction(nFinalReduction);
	if ( Match.LearnPattern((int)MarkW, (int)MarkH, (int)MarkStep, (int)MarkBitCount, MarkPtr, true) == false )
	{	
		JetMemory.free_func(RoiPtr);
		m_ErrorString = Match.GetErrorString();
		return false;
	}

	Match.SetInterpolate(false);
	//Match.SetInterpolate(false);
	Match.SetMinScore(-1);//fMinScore
	if ( Match.Match((int)RoiW, (int)RoiH, (int)RoiStep, (int)MarkBitCount, RoiPtr, true) == false )
	{
		JetMemory.free_func(RoiPtr);
		m_ErrorString = Match.GetErrorString();
		return false;
	}
	JetMemory.free_func(RoiPtr);

	int       idx=0;
	double    ResultS=0;
	double    ResultX=0;
	double    ResultY=0;
	double    ResultA=0;
	double    ResultSX=0;
	double    ResultSY=0;
	const int NResults = Match.GetNumPositions();
	if ( NResults > 0 ) 
	{
		idx=0;
		ResultS = Match.GetResultScore(idx)*100.0;
		ResultX = Match.GetResultPosX(idx);
		ResultY = Match.GetResultPosY(idx);
		ResultA = Match.GetResultAngle(idx);		
		ResultSX = Match.GetResultScaleX(idx);
		ResultSY = Match.GetResultScaleY(idx);		
	}	
	m_ProjectMarkScore = ResultS;

#ifdef _DEBUG
	if ( TRUE == bSave )
	{
		FILE *pfile = NULL;
		TCHAR TMode[32] = _T("");
		_tcscpy(TMode, _T("w+"));
		JetAPI::ModifyOpenFileMode_Write(TMode);
		str.Format(_T("%s\\ProjectMarkFov[%d].TXT"), AOIDataCollect.GetAOITempDirectory(), ProjectIndex+1);
		pfile = ::_tfopen(str, TMode);
		if ( NULL != pfile )
		{
			::_ftprintf(pfile, _T("Result Scope = %.16f\n"), ResultS);
			::_ftprintf(pfile, _T("Result Pos-X = %.16f\n"), ResultX);
			::_ftprintf(pfile, _T("Result Pos-Y = %.16f\n"), ResultY);
			::_ftprintf(pfile, _T("Result Skew = %.16f\n"), ResultA);
			::_ftprintf(pfile, _T("Result Scale-X = %.16f\n"), ResultSX);
			::_ftprintf(pfile, _T("Result Scale-Y = %.16f\n"), ResultSY);

			::fclose(pfile);
			pfile = NULL;
		}		
	}
#endif//_DEBUG

	return true;
}
//-------------------------------------------------------------------------------------//
std::string CAOIProject::RemoveProjectBarcodeCharCount(const char *Barcode)//移除專案條碼字元數
{	
	std::string Code=Barcode;
	const int Len = (int)(::strlen(Barcode));	
	const int EndRemoveCharCount=GetProjectParameter().m_BarcodeEndRemoveCharCount;
	const int BeginRemoveCharCount=GetProjectParameter().m_BarcodeBeginRemoveCharCount;	
	if ( EndRemoveCharCount>Len || BeginRemoveCharCount>Len )
	{	return Code;	}
	const int Begin=BeginRemoveCharCount;
	const int End=Len-EndRemoveCharCount;	
	if ( Begin >= End )
	{	return Code;	}	

	int i=0;
	const int Range=End-Begin;
	Code.assign(&Barcode[Begin], Range);	
	return Code;
}
//-------------------------------------------------------------------------------------//
std::wstring CAOIProject::RemoveProjectBarcodeCharCount(const wchar_t *Barcode)//移除專案條碼字元數
{
	std::wstring Code=Barcode;
	const int Len = (int)(::wcslen(Barcode));
	const int EndRemoveCharCount=GetProjectParameter().m_BarcodeEndRemoveCharCount;
	const int BeginRemoveCharCount=GetProjectParameter().m_BarcodeBeginRemoveCharCount;	
	if ( EndRemoveCharCount>Len || BeginRemoveCharCount>Len )
	{	return Code;	}
	const int Begin=BeginRemoveCharCount;
	const int End=Len-EndRemoveCharCount;	
	if ( Begin >= End )
	{	return Code;	}	

	int i=0;
	const int Range=End-Begin;
	Code.assign(&Barcode[Begin], Range);	
	return Code;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectBarcodeFile(TASK_MODE TaskMode)//儲存專案條碼檔案-JET_INI
{
	CAOIProject *ProjectPtr = this;
	int BarcodeInputFileEnabled = m_ProjectParameter.m_BarcodeInputFileEnabled;
	if ( FN_ENABLE == BarcodeInputFileEnabled ) { return true; }
	if ( TASK_INSPECT_PROJECT != TaskMode ) { return true; }
	if ( SaveProjectBarcodeFile_INIFile(TaskMode) == false )
	{
		SetProjectExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectBarcodeFile(TASK_MODE TaskMode)//載入專案條碼檔案-JET_INI
{
	CAOIProject *ProjectPtr = this;	
	int BarcodeInputFileEnabled = m_ProjectParameter.m_BarcodeInputFileEnabled;	
	if ( FN_ENABLE != BarcodeInputFileEnabled ) { return true; }
	if ( LoadProjectBarcodeFile_INIFile(TaskMode) == false )
	{
		SetProjectExceptionCode_FileRead();
		return false;
	}
	return true;
}
bool CAOIProject::SaveProjectBarcodeFile_INIFile(TASK_MODE TaskMode)//儲存專案條碼檔案-JET_INI
{
	CAOIProject *ProjectPtr = this;

	size_t  i=0;	
	CString Barcode;
	CString filename;
	CString BarcodeOut;
	unsigned int PanelIndex=0;
	unsigned int BoardIndex=0;
	CAOIPanel *PanelPtr = NULL;
	CAOIBoard *BoardPtr = NULL;	
	std::vector<CString> BarcodeList;
	const LANE_ID LaneID = ProjectPtr->GetProjectActLaneID();
	const size_t PanelCount = ProjectPtr->GetProjectPanelCount();
	const size_t BoardCount = ProjectPtr->GetProjectBoardCount();

	filename.Format(_T("%s\\%s.TMP"), AOIDataCollect.GetAOITempDirectory(), _T("ProjectBarcodeWrite"));

	if ( ProjectPtr->GetProjectIsGetBarcode() == true ) 
	{
		Barcode = ProjectPtr->GetProjectBarcode();
		BarcodeOut.Format(_T("%s#0#0"), Barcode);
		BarcodeList.push_back(BarcodeOut);
	}

	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = ProjectPtr->GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		if ( PanelPtr->GetPanelIsGetBarcode() == false ) { continue; }
		Barcode = PanelPtr->GetPanelBarcode();
		BarcodeOut.Format(_T("%s#0#%d"), Barcode, i+1);
		BarcodeList.push_back(BarcodeOut);
	}

	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = ProjectPtr->GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
		if ( BoardPtr->GetBoardIsGetBarcode() == false ) { continue; }
		Barcode = BoardPtr->GetBoardBarcode();
		BoardIndex=BoardPtr->GetBoardIndex_Panel();
		PanelIndex=BoardPtr->GetBoardPanelIndex_Project();

		BarcodeOut.Format(_T("%s#%d#%d"), Barcode, BoardIndex+1, PanelIndex+1);
		BarcodeList.push_back(BarcodeOut);
	}	
	
	//[General]//通用定義
    //Separate=#//定義後面文字解法的分隔符號
    //Barcode Count=4//解析出來的條碼數量
    //[Barcode]//條碼資料
    //Barcode_0001=CodeText#1#1//第1個條碼的內容=條碼內容#單板編號#整板編號
    //Barcode_0002=CodeText#2#1//第2個條碼的內容=條碼內容#單板編號#整板編號
    //Barcode_0003=CodeText#3#1//第3個條碼的內容=條碼內容#單板編號#整板編號
    //Barcode_0004=CodeText#4#1//第4個條碼的內容=條碼內容#單板編號#整板編號

	CString Key;
	CString Err;
	CString String;
	CString Section;	
	const size_t BarcodeCount = BarcodeList.size();

	Section = _T("General");
	Key = _T("Separate");
	String = _T("#");
	if ( SaveINIData(Section, Key, String, filename, Err) == false )
	{
		SetErrorString(Err);
		return false;
	}

	Key = _T("Barcode Count");
	String.Format(_T("%d"), BarcodeCount);
	if ( SaveINIData(Section, Key, String, filename, Err) == false )
	{
		SetErrorString(Err);
		return false;
	}

	Section = _T("Barcode");
	for ( i=0; i<BarcodeCount; i++ )
	{
		Key.Format(_T("Barcode_%04d"), i+1);
		String = BarcodeList[i];
		if ( SaveINIData(Section, Key, String, filename, Err) == false )
		{
			SetErrorString(Err);
			return false;
		}
	}
	
	CString filename2;	
	if ( AOIDataCollect.GetProjectBarcodeFilename(LaneID, true, filename2) == false )
	{
		SetErrorString(AOIDataCollect.GetErrorString());
		return false;
	}
	if ( filename.CompareNoCase(filename2) != 0 )
	{
		if ( ::CopyFile(filename, filename2, FALSE) == FALSE )
		{
			CString str;
			JetAPI::GetSystemLastError(str);
			m_ErrorString.Format(_T("Error, %s"), str);
			return false;
		}
		::DeleteFile(filename);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectBarcodeFile_INIFile(TASK_MODE TaskMode)//載入專案條碼檔案-JET_INI
{
	CAOIProject *ProjectPtr = this;	
	const int ReadDelayTime = m_ProjectParameter.m_BarcodeInputFileDelayTime;

	size_t  i=0;	
	int     nValue=0;
	size_t  BarcodeCount = 0;
	CString Barcode;
	CString filename;
	CString filename2;
	CString BarcodeInp;	
	unsigned int PanelIndex=0;
	unsigned int BoardIndex=0;
	CAOIPanel *PanelPtr = NULL;
	CAOIBoard *BoardPtr = NULL;		
	std::vector<CString> BarcodeList;
	const LANE_ID LaneID = ProjectPtr->GetProjectActLaneID();
	const size_t PanelCount = ProjectPtr->GetProjectPanelCount();
	const size_t BoardCount = ProjectPtr->GetProjectBoardCount();
	if ( AOIDataCollect.GetOfflineMode() == true ) { return true; }
	if ( AOIDataCollect.GetProjectBarcodeFilename(LaneID, false, filename2) == false )
	{
		if ( TASK_INSPECT_PROJECT == TaskMode )
		{
			SetErrorString(AOIDataCollect.GetErrorString());
			return false;
		}
		return true;
	}
	if ( ReadDelayTime > 0 )
	{	::Sleep(ReadDelayTime); }

	filename.Format(_T("%s\\%s.TMP"), AOIDataCollect.GetAOITempDirectory(), _T("ProjectBarcodeRead"));

	if ( filename.CompareNoCase(filename2) != 0 )
	{
		if ( ::CopyFile(filename2, filename, FALSE) == FALSE )
		{
			if ( TASK_INSPECT_PROJECT == TaskMode )
			{
				CString str;
				JetAPI::GetSystemLastError(str);
				m_ErrorString.Format(_T("Error, %s"), str);
				return false;
			}
			return true;
		}
	}	

	//[General]//通用定義
    //Separate=#//定義後面文字解法的分隔符號
    //Barcode Count=4//解析出來的條碼數量
    //[Barcode]//條碼資料
    //Barcode_0001=CodeText#1#1//第1個條碼的內容=條碼內容#單板編號#整板編號
    //Barcode_0002=CodeText#2#1//第2個條碼的內容=條碼內容#單板編號#整板編號
    //Barcode_0003=CodeText#3#1//第3個條碼的內容=條碼內容#單板編號#整板編號
    //Barcode_0004=CodeText#4#1//第4個條碼的內容=條碼內容#單板編號#整板編號

	CString str;
	CString Key;
	CString Err;
	CString Default;
	CString Section;	
	CString strSeparate="#";
	const bool bChkLen = false;
	const size_t szBuffer = 1024;
	TCHAR   String[szBuffer] = _T("");	

	Section = _T("General");
	Key = _T("Separate");
	Default = strSeparate;
	if ( LoadINIData(Section, Key, Default, String, szBuffer, filename, bChkLen, Err) == false )
	{
		SetErrorString(Err);
		return false;
	}
	strSeparate = String;

	Key = _T("Barcode Count");
	Default.Format(_T("%d"), BarcodeCount);
	if ( LoadINIData(Section, Key, Default, String, szBuffer, filename, bChkLen, Err) == false )
	{
		SetErrorString(Err);
		return false;
	}
	nValue = ::_ttoi(String);
	if ( nValue < 0 ) 
	{	nValue = 0; }	
	BarcodeCount = nValue;

	Section = _T("Barcode");
	for ( i=0; i<BarcodeCount; i++ )
	{
		Key.Format(_T("Barcode_%04d"), i+1);
		Default = _T("");
		if ( LoadINIData(Section, Key, Default, String, szBuffer, filename, bChkLen, Err) == false )
		{
			SetErrorString(Err);
			return false;
		}
		BarcodeInp = String;
		if ( BarcodeInp.GetLength() == 0 ) { continue; }
		BarcodeList.push_back(BarcodeInp);
	}	

	int PanelID=0;
	int BoardID=0;
	TBarcodeInfo BarcodeInfo;
	CBarcode_Handheld Barcode_Handheld;	
	
	std::wstring wStr;
	rapidjson::WDocument Doc;
	rapidjson::CJsonCtrl JSonCtrl;
	const bool bCheckBarcodeForJSON=true;

	BarcodeCount = BarcodeList.size();
	Barcode_Handheld.SetProjectPtr(this);
	for ( i=0; i<BarcodeCount; i++ )
	{		
		if ( DecodeProjectBarcodeText(BarcodeList[i], strSeparate, PanelID, BoardID, Barcode) == false )
		{	continue;	}

		PanelPtr = NULL;
		BoardPtr = NULL;
		PanelIndex = -1;	
		BoardIndex = -1;
		if ( PanelID > 0  )		
		{
			PanelIndex = PanelID-1;
			PanelPtr = ProjectPtr->GetProjectPanelPtr(PanelIndex, true);
			if ( NULL == PanelPtr ) 
			{	continue; }
			if ( BoardID > 0  )
			{	
				BoardIndex = BoardID-1;	
				BoardPtr = PanelPtr->GetPanelBoardPtr(BoardIndex, true);
				if ( NULL == BoardPtr ) 
				{	continue; }
				BoardIndex = BoardPtr->GetBoardIndex_Project();
			}
		}
		if ( true == bCheckBarcodeForJSON )
		{
			str.Format(_T("{\"Barcode\":\"%s\"}"), Barcode);
			JetAPI::TCHAR2wstring(str, wStr);
			if ( JSonCtrl.SetBuffer(wStr, Doc) == false )
			{
				m_ErrorString.Format(_T("Error, Barcode Exception[%s]"), Barcode);
				return false;
			}
		}
		BarcodeInfo.pPanel = PanelPtr;
		BarcodeInfo.pBoard = BoardPtr;
		BarcodeInfo.nPanelIndex = PanelIndex;
		BarcodeInfo.nBoardIndex = BoardIndex;
		JetAPI::TCHAR2wstring(Barcode, BarcodeInfo.wsBarcode);
		Barcode_Handheld.AddBarcodeInfo(BarcodeInfo);
	}

	const size_t BarcodeInfoCount = Barcode_Handheld.GetBarcodeInfoCount();
	if ( 0 == BarcodeInfoCount )
	{ 
		if ( TASK_INSPECT_PROJECT == TaskMode )
		{
			m_ErrorString.Format(_T("Error, Load Project Barcode Fault [%s]"), _T("Barcode Count is Zero"));
			return false; 
		}
		return true;
	}

	if ( AssignProjectBarcodeHandHeldCode_Fn(&Barcode_Handheld) == false )
	{
		if ( TASK_INSPECT_PROJECT == TaskMode )
		{	return false;  }
		return true;
	}
	
	if ( TASK_INSPECT_PROJECT == TaskMode )
	{	DeleteFile(filename2); }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::DecodeProjectBarcodeText(LPCTSTR Text, LPCTSTR Gap, int &PanelID, int &BoardID, CString &Barcode)
{
	if ( NULL == Gap ) 
	{
		SetErrorString(_T("Error, No Separate Text"));
		return false; 
	}
	if ( NULL == Text ) 
	{ 
		SetErrorString(_T("Error, No Barcode Input Text"));
		return false; 
	}

	size_t EndI=0;
	size_t i=0, j=0;	
	size_t PanelEnd=-1;
	size_t BoardEnd=-1;
	size_t BarcodeEnd=-1;
	const size_t GapLen = ::_tcslen(Gap);
	const size_t TextLen = ::_tcslen(Text);
	if ( GapLen >= TextLen )
	{
		SetErrorString(_T("Error, Barcode Input Text Fault"));
		return false; 
	}

	for ( i=0; i<TextLen-GapLen; i++ )
	{
		for ( j=0; j<GapLen; j++ )
		{
			if ( Text[j+i] != Gap[j] )
			{	break; }
		}
		if ( j != GapLen )
		{	continue;	}
		if ( -1 == BarcodeEnd )
		{	BarcodeEnd = i; }
		else if ( -1 == BoardEnd )
		{	BoardEnd = i; }
		else if ( -1 == PanelEnd )
		{	PanelEnd = i; }
	}	
	if ( -1==BarcodeEnd || -1==BoardEnd )
	{	
		SetErrorString(_T("Error, Barcode Text Extarct Fault"));
		return false; 
	}
	if ( -1 == PanelEnd )
	{	PanelEnd = TextLen;	}

	CString strPanel;
	CString strBoard;
	CString str = Text;	
	Barcode=str.Left(BarcodeEnd);	
	strPanel=str.Mid(BoardEnd+1, PanelEnd-BoardEnd-1);
	strBoard=str.Mid(BarcodeEnd+1, BoardEnd-BarcodeEnd-1);
	PanelID = ::_ttoi(strPanel);
	BoardID = ::_ttoi(strBoard);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CheckProjectBarcodeDeviceIDList()//確認專案的條碼裝置列表
{
	BARCODE_INPUT_TYPE BarcodeInputType = m_ProjectParameter.m_BarcodeInputType;//條碼輸入樣式
	if ( BARCODE_INPUT_DEVICE != BarcodeInputType ) { return true; }

	bool            IsOK=true;
	size_t          i=0;
	int             BarcodeDeviceID=0;
	unsigned int    BarcodeDeviceIndex=0;	
	CString         strPanel, strBoard, strIndex, strBarcodeDevice;
	CString         strError, strError2, strError3;
	CAOIPanel      *PanelPtr=NULL;
	CAOIBoard      *BoardPtr=NULL;
	CBarcode_Basic *BarcodeDevicePtr=NULL;
	const unsigned int BarcodeDeviceIndex_NoUse=-1;
	const size_t MaxDeviceCount = MAX_BARCODE_DEVICE_COUNT;
	const size_t PanelCount = GetProjectPanelCount();
	const size_t BoardCount = GetProjectBoardCount();	

	strIndex = AOIDataDefine.GetIndexText();
	strPanel = AOIDataDefine.GetPanelText();
	strPanel = AOIDataDefine.GetBoardText();	
	strBarcodeDevice = AOIDataDefine.GetBarcodeDeviceText();
	IsOK=true;		
	for ( i=0; i<MaxDeviceCount; i++ )
	{	m_ProjectBarcodeDeviceUsedList[i] = false;	}	

	BarcodeDeviceIndex = GetProjectBarcodeDeviceIndex();			
	if ( BarcodeDeviceIndex_NoUse != BarcodeDeviceIndex )
	{
		if ( BarcodeDeviceIndex < MaxDeviceCount )
		{	m_ProjectBarcodeDeviceUsedList[BarcodeDeviceIndex] = true; }		
	}

	//確認專案內的條碼機設定引數正常
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		BarcodeDeviceIndex = PanelPtr->GetPanelBarcodeDeviceIndex();
		if ( BarcodeDeviceIndex_NoUse == BarcodeDeviceIndex ) { continue; }//不使用
		if ( BarcodeDeviceIndex >= MaxDeviceCount )
		{
			strError2.Format(_T("%s[%d] %s %s=%d/%d"), strPanel, i+1, strBarcodeDevice, strIndex, BarcodeDeviceIndex+1, MaxDeviceCount);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
		}
		else
		{	m_ProjectBarcodeDeviceUsedList[BarcodeDeviceIndex] = true;	}
	}

	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
		BarcodeDeviceIndex = BoardPtr->GetBoardBarcodeDeviceIndex();
		if ( BarcodeDeviceIndex_NoUse == BarcodeDeviceIndex ) { continue; }//不使用
		if ( BarcodeDeviceIndex >= MaxDeviceCount )
		{
			strError2.Format(_T("%s[%d] %s %s=%d/%d"), strBoard, i+1, strBarcodeDevice, strIndex, BarcodeDeviceIndex+1, MaxDeviceCount);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
		}
		else
		{	m_ProjectBarcodeDeviceUsedList[BarcodeDeviceIndex] = true;	}
	}

	//確認軌道的條碼機	
	LANE_WORK_MODE LaneWorkMode_LA = AOIDataCollect.GetLaneWorkMode_LA();
	if ( LANE_WORK_RUN==LaneWorkMode_LA && true==GetProjectLaneEnable_LA() )
	{
		if ( AOIDataCollect.CheckBarcodeDeviceIDList_LA(m_ProjectBarcodeDeviceUsedList) == false )
		{
			strError2 = AOIDataCollect.GetErrorString();
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
		}
	}

	LANE_WORK_MODE LaneWorkMode_LB = AOIDataCollect.GetLaneWorkMode_LB();
	if ( LANE_WORK_RUN==LaneWorkMode_LB && true==GetProjectLaneEnable_LB() )
	{
		if ( AOIDataCollect.CheckBarcodeDeviceIDList_LB(m_ProjectBarcodeDeviceUsedList) == false )
		{
			strError2 = AOIDataCollect.GetErrorString();
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
		}
	}
	
	if ( false == IsOK )
	{	
		strError2 = AOIDataDefine.GetErrorText();
		strError3.Format(_T("%s, %s"), strError2, strError);
		strError = strError3;		
		SetErrorString(strError);	
	}
	return IsOK;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CloneProjectBarcodeDeviceUsedList(bool UsedList[])//複製專案的條碼裝置使用列表
{
	size_t       i=0;
	const size_t MaxBarcodeDeviceCount = MAX_BARCODE_DEVICE_COUNT;
	for ( i=0; i<MaxBarcodeDeviceCount; i++ )
	{	UsedList[i] = m_ProjectBarcodeDeviceUsedList[i]; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AssignProjectBarcodeDeviceCode(LANE_ID LaneID)//分派專案條碼裝置內容
{
	CAOIProject   *ProjectPtr = this;
	BARCODE_INPUT_TYPE BarcodeInputType = m_ProjectParameter.m_BarcodeInputType;//條碼輸入樣式
	if ( BARCODE_INPUT_DEVICE != BarcodeInputType ) { return true; }

	size_t       i=0, j=0;
	bool         IsOK=true;	
	int          BarcodeDeviceID=0;		
	unsigned int BarcodeDeviceIndex=0;
	unsigned int BarcodeDeviceCodeIndex=0;	
	size_t       BarcodeCodeLen=0;
	size_t       BarcodeDeviceCount=0;
	CString      strLane;	
	CString      strError, strError2, strError3;	
	CString      strCode = AOIDataDefine.GetBarcodeText();
	CString      strDevice = AOIDataDefine.GetBarcodeDeviceText();
	CAOIPanel      *PanelPtr=NULL;
	CAOIBoard      *BoardPtr=NULL;	
	CBarcode_Basic *BarcodeDevicePtr=NULL;
	int   LaneBarcodeIDList[MAX_BARCODE_DEVICE_COUNT];	
	const size_t PanelCount = ProjectPtr->GetProjectPanelCount();
	const size_t BoardCount = ProjectPtr->GetProjectBoardCount();	
	const size_t MaxBarcodeDeviceCount = MAX_BARCODE_DEVICE_COUNT;

	IsOK=true;	
	if ( LANE_ID_B == LaneID )
	{	AOIDataCollect.CloneBarcodeDeviceIDList_LB(LaneBarcodeIDList);	}
	else
	{	AOIDataCollect.CloneBarcodeDeviceIDList_LA(LaneBarcodeIDList); }
	
	std::pair<int, int> BadCode;
	std::vector<std::pair<int, int>> BadCodeList;

	//專案條碼
	std::string ResultBarcode;//過濾後的條碼
	BarcodeDeviceIndex = ProjectPtr->GetProjectBarcodeDeviceIndex();
	BarcodeDeviceCodeIndex = ProjectPtr->GetProjectBarcodeDeviceCodeIndex();
	if ( BarcodeDeviceIndex>=0 && BarcodeDeviceIndex<MaxBarcodeDeviceCount )
	{
		BarcodeDeviceID = LaneBarcodeIDList[BarcodeDeviceIndex];		
		BarcodeDevicePtr = AOIDataCollect.GetBarcodeDevicePtr(BarcodeDeviceID);
		if ( NULL != BarcodeDevicePtr )
		{
			//取備份的條碼, 因為可能條碼機已經準備讀取下一筆
			//const char *ResultPtr = BarcodeDevicePtr->GetResultSubBuffer(BarcodeDeviceCodeIndex);
			const char *ResultPtr = BarcodeDevicePtr->GetResultSubBackup(BarcodeDeviceCodeIndex);
			if ( NULL != ResultPtr )
			{
				BarcodeCodeLen = ::strlen(ResultPtr);
				if ( 0 != BarcodeCodeLen )
				{
					ResultBarcode=RemoveProjectBarcodeCharCount(ResultPtr);
					ProjectPtr->SetProjectIsGetBarcode(true);
					ProjectPtr->SetProjectBarcode(ResultBarcode.c_str());
					ProjectPtr->SetProjectBarcodeBelongMode(BARCODE_BELONG_PROJECT);
				}
				else
				{
					BadCode.first = BarcodeDeviceIndex;
					BadCode.second = BarcodeDeviceCodeIndex;
					BadCodeList.push_back(BadCode);
				}
			}
		}
	}

	//整板條碼	
	for ( i=0; i<PanelCount; i++ )
	{
		PanelPtr = ProjectPtr->GetProjectPanelPtr(i, false);
		if ( NULL == PanelPtr ) { continue; }
		if ( PanelPtr->GetPanelBypassed() == true ) { continue; }
		if ( PanelPtr->GetPanelBarcodeEnabled() == false ) { continue; }
		BarcodeDeviceIndex = PanelPtr->GetPanelBarcodeDeviceIndex();
		BarcodeDeviceCodeIndex = PanelPtr->GetPanelBarcodeDeviceCodeIndex();
		if ( BarcodeDeviceIndex<0 || BarcodeDeviceIndex >= MaxBarcodeDeviceCount ) { continue; }
		BarcodeDeviceID = LaneBarcodeIDList[BarcodeDeviceIndex];		
		BarcodeDevicePtr = AOIDataCollect.GetBarcodeDevicePtr(BarcodeDeviceID);
		if ( NULL == BarcodeDevicePtr ) { continue; }		
		//取備份的條碼, 因為可能條碼機已經準備讀取下一筆
		//const char *ResultPtr = BarcodeDevicePtr->GetResultSubBuffer(BarcodeDeviceCodeIndex);
		const char *ResultPtr = BarcodeDevicePtr->GetResultSubBackup(BarcodeDeviceCodeIndex);
		if ( NULL == ResultPtr ) { continue; }
		BarcodeCodeLen = ::strlen(ResultPtr);
		if ( 0 == BarcodeCodeLen )
		{
			BadCode.first = BarcodeDeviceIndex;
			BadCode.second = BarcodeDeviceCodeIndex;
			BadCodeList.push_back(BadCode);
			continue; 
		}
		ResultBarcode=RemoveProjectBarcodeCharCount(ResultPtr);
		PanelPtr->SetPanelIsGetBarcode(true);
		PanelPtr->SetPanelBarcode(ResultBarcode.c_str());
		PanelPtr->SetPanelBarcodeBelongMode(BARCODE_BELONG_PANEL);
	}

	//單板條碼
	for ( i=0; i<BoardCount; i++ )
	{
		BoardPtr = ProjectPtr->GetProjectBoardPtr(i, false);
		if ( NULL == BoardPtr ) { continue; }
		if ( BoardPtr->GetBoardBypassed() == true ) { continue; }
		if ( BoardPtr->GetBoardBarcodeEnabled() == false ) { continue; }
		BarcodeDeviceIndex = BoardPtr->GetBoardBarcodeDeviceIndex();
		BarcodeDeviceCodeIndex = BoardPtr->GetBoardBarcodeDeviceCodeIndex();
		if ( BarcodeDeviceIndex<0 || BarcodeDeviceIndex >= MaxBarcodeDeviceCount ) { continue; }
		BarcodeDeviceID = LaneBarcodeIDList[BarcodeDeviceIndex];		
		BarcodeDevicePtr = AOIDataCollect.GetBarcodeDevicePtr(BarcodeDeviceID);
		if ( NULL == BarcodeDevicePtr ) { continue; }
		//取備份的條碼, 因為可能條碼機已經準備讀取下一筆
		//const char *ResultPtr = BarcodeDevicePtr->GetResultSubBuffer(BarcodeDeviceCodeIndex);
		const char *ResultPtr = BarcodeDevicePtr->GetResultSubBackup(BarcodeDeviceCodeIndex);
		if ( NULL == ResultPtr ) { continue; }
		BarcodeCodeLen = ::strlen(ResultPtr);
		if ( 0 == BarcodeCodeLen ) 
		{
			BadCode.first = BarcodeDeviceIndex;
			BadCode.second = BarcodeDeviceCodeIndex;
			BadCodeList.push_back(BadCode);
			continue; 
		}
		ResultBarcode=RemoveProjectBarcodeCharCount(ResultPtr);
		BoardPtr->SetBoardIsGetBarcode(true);
		BoardPtr->SetBoardBarcode(ResultBarcode.c_str());		
		BoardPtr->SetBoardBarcodeBelongMode(BARCODE_BELONG_BOARD);
	}

	const size_t BadCodeCount=BadCodeList.size();
	BARCODE_NG_HANDLE_MODE BarcodeNGHandleMode = m_ProjectParameter.m_BarcodeNGHandleMode;//條碼失敗處理模式
	if ( BARCODE_NG_HANDLE_PASS != BarcodeNGHandleMode )
	{
		if ( BadCodeCount > 0 )
		{
			for ( i=0; i<BadCodeCount; i++ )
			{
				strError.Format(_T("%s:%d, %s:%d"), strDevice, BadCodeList[i].first+1, strCode, BadCodeList[i].second+1);
				if ( i == 0 )
				{	strError2 = strError;	}
				else
				{
					strError3 = strError2;
					strError2.Format(_T("%s\n%s"), strError3, strError);
				}
			}		
			strError = _T("Error, Analysis Barcode Device Content Fault");
			strError = LoadMultiLanguageString(strError, strError);
			m_ErrorString.Format(_T("%s\n%s"), strError, strError2);
			return false;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AssignProjectBarcodeHandHeldCode(LANE_ID LaneID)//分派專案手持條碼機內容
{
	CAOIProject   *ProjectPtr = this;
	BARCODE_INPUT_TYPE BarcodeInputType = m_ProjectParameter.m_BarcodeInputType;//條碼輸入樣式
	if ( BARCODE_INPUT_HANDHELD != BarcodeInputType ) { return true; }
	CBarcode_Handheld* BarcodeHandHeldPtr = AOIDataCollect.GetBarcodeHandHeldPtr(LaneID);
	if ( NULL == BarcodeHandHeldPtr )
	{	return false;	}
	if ( AssignProjectBarcodeHandHeldCode_Fn(BarcodeHandHeldPtr) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AssignProjectBarcodeHandHeldCode_Fn(CBarcode_Handheld *BarcodeHandHeldPtr)//分派專案手持條碼機內容	
{
	CAOIProject   *ProjectPtr = this;
	//CBarcode_Handheld* BarcodeHandHeldPtr = AOIDataCollect.GetBarcodeHandHeldPtr(LaneID);
	if ( NULL == BarcodeHandHeldPtr )
	{	return false;	}

	size_t        i=0, j=0;
	size_t        PanelBoardCount=0;
	bool          IsGetProjectBarcode=false;
	std::wstring  wsBarcode=L"";
	std::wstring  ResultBarcode=L"";
	CAOIPanel    *PanelPtr = NULL;
	CAOIBoard    *BoardPtr = NULL;
	TBarcodeInfo *BarcodeInfoPtr=NULL;	
	const size_t  PanelCount = ProjectPtr->GetProjectPanelCount();
	const size_t  BoardCount = ProjectPtr->GetProjectBoardCount();
	const size_t  BarcodeInfoCount = BarcodeHandHeldPtr->GetBarcodeInfoCount();

	//尋找專案條碼
	IsGetProjectBarcode = false;
	for ( i=0; i<BarcodeInfoCount; i++ )
	{
		BarcodeInfoPtr = BarcodeHandHeldPtr->GetBarcodeInfoPtr(i, false);
		if ( NULL == BarcodeInfoPtr ) { continue; }
		if ( NULL != BarcodeInfoPtr->pPanel ) { continue; }
		if ( NULL != BarcodeInfoPtr->pBoard ) { continue; }
		if ( INVALID_INDEX != BarcodeInfoPtr->nPanelIndex ) { continue; }
		if ( INVALID_INDEX != BarcodeInfoPtr->nBoardIndex ) { continue; }		
		wsBarcode = BarcodeInfoPtr->wsBarcode;	
		ResultBarcode=RemoveProjectBarcodeCharCount(wsBarcode.c_str());
		ProjectPtr->SetProjectIsGetBarcode(true);
		ProjectPtr->SetProjectBarcode(ResultBarcode.c_str());
		ProjectPtr->SetProjectBarcodeBelongMode(BARCODE_BELONG_PROJECT);
		break;
	}	
	//尋找整板條碼
	for ( i=0; i<BarcodeInfoCount; i++ )
	{
		BarcodeInfoPtr = BarcodeHandHeldPtr->GetBarcodeInfoPtr(i, false);
		if ( NULL == BarcodeInfoPtr ) { continue; }
		if ( NULL == BarcodeInfoPtr->pPanel ) { continue; }
		if ( NULL != BarcodeInfoPtr->pBoard ) { continue; }
		if ( INVALID_INDEX == BarcodeInfoPtr->nPanelIndex ) { continue; }
		if ( INVALID_INDEX != BarcodeInfoPtr->nBoardIndex ) { continue; }
		
		PanelPtr = (CAOIPanel*)(BarcodeInfoPtr->pPanel);
		if ( NULL == PanelPtr ) { continue; }
		if ( PanelPtr->GetPanelBarcodeEnabled() == false ) { continue; }
		wsBarcode = BarcodeInfoPtr->wsBarcode;
		ResultBarcode=RemoveProjectBarcodeCharCount(wsBarcode.c_str());
		PanelPtr->SetPanelIsGetBarcode(true);
		PanelPtr->SetPanelBarcode(ResultBarcode.c_str());
		PanelPtr->SetPanelBarcodeBelongMode(BARCODE_BELONG_PANEL);
	}

	//尋找單板條碼
	for ( i=0; i<BarcodeInfoCount; i++ )
	{
		BarcodeInfoPtr = BarcodeHandHeldPtr->GetBarcodeInfoPtr(i, false);
		if ( NULL == BarcodeInfoPtr ) { continue; }		
		if ( NULL == BarcodeInfoPtr->pBoard ) { continue; }		
		if ( INVALID_INDEX == BarcodeInfoPtr->nBoardIndex ) { continue; }
		
		BoardPtr = (CAOIBoard*)(BarcodeInfoPtr->pBoard);
		if ( NULL == BoardPtr ) { continue; }
		if ( BoardPtr->GetBoardBarcodeEnabled() == false ) { continue; }
		wsBarcode = BarcodeInfoPtr->wsBarcode;
		ResultBarcode=RemoveProjectBarcodeCharCount(wsBarcode.c_str());
		BoardPtr->SetBoardIsGetBarcode(true);
		BoardPtr->SetBoardBarcode(ResultBarcode.c_str());		
		BoardPtr->SetBoardBarcodeBelongMode(BARCODE_BELONG_BOARD);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ModifyProjectBarcodeHandHeldCode(CBarcode_Handheld &BarcodeHandHeld)//修改專案手持條碼機內容
{
	CAOIProject *ProjectPtr = this;

	size_t        i=0;
	unsigned int  PanelIndex=0;
	unsigned int  BoardIndex=0;
	CAOIPanel    *PanelPtr = NULL;
	CAOIBoard    *BoardPtr = NULL;
	TBarcodeInfo *BarcodeInfoPtr = NULL;
	const size_t BarcodeInfoCount = BarcodeHandHeld.GetBarcodeInfoCount();

	//依照引數重新定義專案, 整板, 單板指標
	BarcodeHandHeld.SetProjectPtr(ProjectPtr);
	for ( i=0; i<BarcodeInfoCount; i++ )
	{
		BarcodeInfoPtr = BarcodeHandHeld.GetBarcodeInfoPtr(i, false);
		if ( NULL != BarcodeInfoPtr->pPanel )
		{
			PanelIndex = BarcodeInfoPtr->nPanelIndex;
			PanelPtr = ProjectPtr->GetProjectPanelPtr(PanelIndex, true);
			if ( NULL == PanelPtr )
			{
				m_ErrorString.Format(_T("Error, ModifyProjectBarcodeHandHeldCode Fault (Panel ID[%d])"), PanelIndex+1);
				return false;
			}
			BarcodeInfoPtr->pPanel = PanelPtr;
		}

		if ( NULL != BarcodeInfoPtr->pBoard )
		{
			BoardIndex = BarcodeInfoPtr->nBoardIndex;
			BoardPtr = ProjectPtr->GetProjectBoardPtr(BoardIndex, true);
			if ( NULL == BoardPtr )
			{
				m_ErrorString.Format(_T("Error, ModifyProjectBarcodeHandHeldCode Fault (BoardPtr ID[%d])"), BoardIndex+1);
				return false;
			}
			BarcodeInfoPtr->pBoard = BoardPtr;
		}
	}
	return true;
}
