//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectServerModelLockListToFile(LPCTSTR filename)//儲存專案伺服器模組鎖住列表至檔案
{
	if ( SaveProjectServerModelLockListToFileFn(filename) == false )
	{
		SetProjectExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectServerModelLockListToFileFn(LPCTSTR filename)//儲存專案伺服器模組鎖住列表至檔案
{
	if (NULL == filename)
	{	return false; }
	
	TCHAR   TMode[32] = _T("");
	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	FILE *pfile = ::_tfopen(filename, TMode);
	if (NULL == pfile)
	{
		m_ErrorString.Format(_T("Error, Open TXT File to Save Fault (%s)"), filename);
		return false;
	}	
	
	size_t       i=0;
	const size_t ModelLockCount=m_ProjectServerModelLockList.size();	
	::_ftprintf(pfile, _T("Locked Model List\n"), _T(""));
	for ( i=0; i<ModelLockCount; i++ )
	{	::_ftprintf(pfile, _T("%s\n"), m_ProjectServerModelLockList[i]);	}

	::fclose(pfile);
	pfile = NULL;
	return true;
}
