{
	if ( LoadProjectServerLibraryFn(ServerFolder) == false )
	{
		SetProjectExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectServerLibraryFn(LPCTSTR ServerFolder)//載入專案伺服器資料庫
{
	CString str;
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }		

	bool    bLockFile = true;	
	if ( ProjectPtr->CreateProjectServerLockFile(bLockFile) == false )
	{	return false;	}
	if ( true == bLockFile )
	{	return false; }	

	CString ModelExtName = _T("MDL");	
	if ( JetAPI::IsFolderExist(ServerFolder) == false )
	{	
		ProjectPtr->DeleteProjectServerLockFile();
		str = _T("Error, The Server Folder does not exist");
		str = LoadMultiLanguageString(str, str);
		m_ErrorString.Format(_T("%s [%s]"), str, ServerFolder);
		return false;
	}

	std::vector<WIN32_FIND_DATA> ServerModelFileList;
	if ( JetAPI::ListFilesInFolder(ServerFolder, ModelExtName, ServerModelFileList) == false )
	{	
		ProjectPtr->DeleteProjectServerLockFile();
		str = _T("Error, List Server Folder File Fault");
		str = ProjectPtr->LoadMultiLanguageString(str, str);
		m_ErrorString.Format(_T("%s [%s]"), str, ServerFolder);
		return false;
	}

	size_t       i=0, j=0;	
	unsigned int ModelIndex=0;
	CString      ModelName;	
	CString      ModelFileName;
	CString      ModelFolderSrc;
	CString      ModelFolderDst;
	CAOIModel   *ModelPtr = NULL;	
	CAOIModel   *ModelPtr2 = NULL;	
	bool        bModelCreated=false;
	const bool  bClearDest = true;
	const bool  bDeleteSrc = false;	
	const size_t ServerModelFileCount = ServerModelFileList.size();
	CString      ProjectLibraryFolder = ProjectPtr->GetProjectLibraryFolder();		

	unsigned int   DefaultFrameIndex=0;
	unsigned int   DefaultFrameUniqueID = 0;	
	std::vector<CColorGroup>  ColorGroupList;
	std::vector<unsigned int> FrameIndexMapList;
	ProjectPtr->CloneProjectColorGroupList(ColorGroupList);
	ProjectPtr->BuildProjectFrameIndexMapParam(FrameIndexMapList, DefaultFrameIndex, DefaultFrameUniqueID);			

	::CreateDirectory(ProjectLibraryFolder, NULL);		
	for ( i=0; i<ServerModelFileCount; i++ )
	{	
		JetAPI::ExtractMainFileName(ServerModelFileList[i].cFileName, ModelName);
		ModelFileName.Format(_T("%s\\%s"), ServerFolder, ServerModelFileList[i].cFileName);		
		ModelPtr = AOIObjManager.CreateModelObj(); 		
		if ( NULL == ModelPtr )
		{	
			m_ErrorString = AOIObjManager.GetErrorString();
			ProjectPtr->DeleteProjectServerLockFile();
			return false;
		}
		if ( ModelPtr->LoadModelParamFile(ModelFileName) == false )
		{
			AOIObjManager.DestroyModelObj(ModelPtr);
			ModelPtr = NULL;			
			continue;
		}		
		ModelFolderSrc.Format(_T("%s\\%s"), ServerFolder, ModelName);
		ModelFolderDst.Format(_T("%s\\%s"), ProjectLibraryFolder, ModelName);
		if ( JetAPI::CopyFolderAToFolderB(ModelFolderSrc, ModelFolderDst, bDeleteSrc, bClearDest, _T(""), -1, -1) == false )
		{	
			AOIObjManager.DestroyModelObj(ModelPtr);
			ModelPtr = NULL;			
			continue; 
		}		
		ModelPtr->SetModelName(ModelName);//不應該設定
		ModelPtr->SetModelFolderModel(ModelFolderDst);
		ModelPtr->AssignModelFolder();
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);
		ModelPtr->UpdateModelFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);

		ModelPtr2 = ProjectPtr->GetProjectModelPtrByModelName(ModelName);
		if ( NULL == ModelPtr2 )
		{	ProjectPtr->AddProjectModelPtr(ModelPtr, false); }
		else
		{
			ModelIndex = ModelPtr2->GetModelIndex();
			ModelPtr->SetModelIndex(ModelIndex);			
			(*ModelPtr2) = (*ModelPtr);
			AOIObjManager.DestroyModelObj(ModelPtr);
			ModelPtr = NULL;		
		}
	}	
	ProjectPtr->DeleteProjectServerLockFile();
	return true;
}
