bool CAOIProject::CreateProjectServerLibraryFolder()
{
	CString ServerLibraryFolder;
	TProjectParameter &ProParam = GetProjectParameter();	
	CString ServerFolder = AOIDataCollect.GetAOIServerFolder();
	CString GroupName = ProParam.m_ProjectServerLibraryGroup.c_str();
	if ( 0 == GroupName.GetLength() )
	{	GroupName = _T("Library"); }

	ServerLibraryFolder.Format(_T("%s\\%s"), ServerFolder, GroupName);
	::CreateDirectory(ServerLibraryFolder, NULL);
	SetProjectServerLibraryFolder(ServerLibraryFolder);
	return true;
}
