//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectLibryToServerLibraryFn(LPCTSTR ServerLibraryFolder, LPCTSTR ServerProjectLibraryFolder)//儲存專案資料庫至伺服器資料庫
{
	CString  str;
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }

	int     ModelTempInt=0;	
	CString ExtName=_T("MDL");	
	std::vector<CString> ModelLogList;
	std::vector<WIN32_FIND_DATA> ServerModelFileList;
	CString TempFolder = AOIDataCollect.GetAOITempDirectory();		
	if ( JetAPI::ListFilesInFolder(ServerLibraryFolder, ExtName, ServerModelFileList) == false )
	{
		str = _T("Error, List Server Folder File Fault");
		str = ProjectPtr->LoadMultiLanguageString(str, str);
		m_ErrorString.Format(_T("%s [%s]"), str, ServerLibraryFolder);
		return false;
	}

	size_t       i=0, j=0;		
	CString      ModelName;
	CString      ModelFileName;		
	CAOIModel   *ModelPtr = NULL;
	FILETIME     ftLastWriteTime;
	time_t       ModelSaveDateTime=0;
	time_t       ModelModifyDateTime=0;
	std::vector<CAOIModel*> ModelModifiedList;	
	const size_t ServerModelFileCount = ServerModelFileList.size();
	const size_t ModelCount = ProjectPtr->GetProjectModelCount();	

	const int    ModelAdded    = SERVER_MODEL_ADD;
	const int    ModelModified = SERVER_MODEL_MODIFY;
	const int    ModelDeleted  = SERVER_MODEL_DELETE;	
	const int    ModelNoChanged  = SERVER_MODEL_UNCHANGE;	

	for ( i=0; i<ModelCount; i++ )
	{
		ModelPtr = ProjectPtr->GetProjectModelPtr(i, false);
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->SetModelTempInt(ModelAdded);
	}

	for ( i=0; i<ServerModelFileCount; i++ )
	{
		ModelFileName = ServerModelFileList[i].cFileName;		
		JetAPI::ExtractMainFileName(ModelFileName, ModelName);
		ModelPtr = ProjectPtr->GetProjectModelPtrByModelName(ModelName);
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->SetModelTempInt(ModelModified);
		ftLastWriteTime = ServerModelFileList[i].ftLastWriteTime;
		ModelModifyDateTime = ModelPtr->GetModelModifiedDateTime();
		JetAPI::FileTimeToTimet(ftLastWriteTime, ModelSaveDateTime);		
		if ( ModelSaveDateTime >= ModelModifyDateTime )//確認存檔日期是否大於修改日期
		{
			ModelPtr->SetModelTempInt(ModelNoChanged);
			continue; 
		}
		ModelModifiedList.push_back(ModelPtr);
	}
	
	bool         IsOK=true;		
	CString      FolderSrc;	
	CString      FolderDst;	
	CString      ModelFileNameTmp;	
	CString      ModelFileNameDst;		
	CString      ModelFileNameSrc;		
	const size_t ModelModifiedCount = ModelModifiedList.size();	
	COPY_HUGE_FILES_MODE CopyHugeFilesMode = ProjectPtr->GetProjectCopyServerHugeFileMode();
	for ( i=0; i<ModelCount; i++ )
	{
		ModelPtr = ProjectPtr->GetProjectModelPtr(i, false);
		if ( NULL == ModelPtr ) { continue; }
		ModelTempInt = ModelPtr->GetModelTempInt();
		if ( ModelNoChanged == ModelTempInt )
		{	continue; }	

		ModelName = ModelPtr->GetModelName();		
		ModelFileNameDst.Format(_T("%s\\%s"), ServerLibraryFolder, ModelName);
		ModelFileNameSrc.Format(_T("%s\\%s"), ServerProjectLibraryFolder, ModelName);
		
		FolderDst = ModelFileNameDst;
		FolderSrc = ModelFileNameSrc;
		//複製要貼上的模組	
		IsOK = JetAPI::HugeCopyFolderAToFolderB(CopyHugeFilesMode, FolderSrc, FolderDst, false, false, _T(""), -1, -1);				
		if ( false == IsOK ) 
		{	
			str = _T("Error, Copy Model Folder Fault");
			str = ProjectPtr->LoadMultiLanguageString(str, str);
			m_ErrorString.Format(_T("%s \n[%s]\nto\n[%s]"), str, FolderSrc, FolderDst);
			return false; 
		}
		//改成直接複製比較快
		ModelFileNameDst.Format(_T("%s\\%s.%s"), ServerLibraryFolder, ModelName, ExtName);
		ModelFileNameSrc.Format(_T("%s\\%s.%s"), ServerProjectLibraryFolder, ModelName, ExtName);
		::CopyFile(ModelFileNameSrc, ModelFileNameDst, FALSE);

		switch ( ModelTempInt )
		{
		case ModelModified:	str.Format(_T("[%s] %s"), ModelName, _T("Modified"));	break;
		default:
		case ModelAdded:	str.Format(_T("[%s] %s"), ModelName, _T("Added"));	break;
		}		
		ModelLogList.push_back(str);
	}

	CString strTime;
	CTime   cTime = CTime::GetCurrentTime();
	strTime.Format(_T("%04d%02d%02d"), cTime.GetYear(), cTime.GetMonth(), cTime.GetDay());		
	str.Format(_T("%s\\%s_Log.TXT"), ServerLibraryFolder, strTime);
	ProjectPtr->SaveProjectServerLogFile(str, ModelLogList);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectLibryFromServerLibrary(LPCTSTR ServerFolder, bool bIncNewModel, bool bLoadAll)//載入專案資料庫從伺服器資料庫
{
	if ( LoadProjectLibryFromServerLibraryFn(ServerFolder, bIncNewModel, bLoadAll) == false )
	{
		SetProjectExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectLibryFromServerLibraryFn(LPCTSTR ServerFolder, bool bIncNewModel, bool bLoadAll)//載入專案資料庫從伺服器資料庫
{
	CString  str;
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }

	ClearProjectServerModelLockList();
	if ( JetAPI::IsFolderExist(ServerFolder) == false )
	{
		m_ErrorString.Format(_T("Error, The Server Folder does not exist [%s]"), ServerFolder);
		return false;
	}
	CString ExtName=_T("MDL");	
	CString TempFolder = AOIDataCollect.GetAOITempDirectory();	
	CString ProjectServerShareFileName = ProjectPtr->GetProjectServerShareFilename();
	std::vector<WIN32_FIND_DATA> ServerModelFileList;
	
	time_t ProjectSaveDateTimeSrc = 0;//Modified Time
	time_t ProjectSaveDateTimeDst = 0;
	time_t ProjectCheckDelayTime  = 10;
	//更新伺服器專案檔案的修改日期
	if ( JetAPI::GetFileModifedTime(ProjectServerShareFileName, ProjectSaveDateTimeSrc) == true )	
	{	ProjectPtr->SetProjectServerSavedDateTime(ProjectSaveDateTimeSrc);	}	
	if ( JetAPI::ListFilesInFolder(ServerFolder, ExtName, ServerModelFileList) == false )
	{
		str = _T("Error, List Server Folder File Fault");
		str = ProjectPtr->LoadMultiLanguageString(str, str);
		m_ErrorString.Format(_T("%s [%s]"), str, ServerFolder);
		return false;
	}

	size_t       i=0, j=0;		
	CString      ModelName;
	CString      ModelFolder;
	CString      ModelFileName;		
	CAOIModel   *ModelPtr = NULL;
	FILETIME     ftLastWriteTime;
	time_t       DelayTime=10;//消除存檔時間差距, 單位為秒
	time_t       ModelSaveDateTime=0;
	time_t       ModelModifyDateTime=0;
	std::vector<CAOIModel*> ModelModifiedList;
	const size_t ServerModelFileCount = ServerModelFileList.size();
	const size_t ModelCount = ProjectPtr->GetProjectModelCount();	
	CString      ProjectLibraryFolder = ProjectPtr->GetProjectLibraryFolder();

	const int    ModelAdded    = SERVER_MODEL_ADD;
	const int    ModelModified = SERVER_MODEL_MODIFY;
	const int    ModelDeleted  = SERVER_MODEL_DELETE;	
	const int    ModelNoChanged  = SERVER_MODEL_UNCHANGE;	

	unsigned int   DefaultFrameIndex=0;
	unsigned int   DefaultFrameUniqueID = 0;	
	std::vector<CColorGroup>  ColorGroupList;
	std::vector<unsigned int> FrameIndexMapList;
	ProjectPtr->CloneProjectColorGroupList(ColorGroupList);
	ProjectPtr->BuildProjectFrameIndexMapParam(FrameIndexMapList, DefaultFrameIndex, DefaultFrameUniqueID);	

	for ( i=0; i<ModelCount; i++ )
	{
		ModelPtr = ProjectPtr->GetProjectModelPtr(i, false);
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->SetModelTempInt(ModelNoChanged);
	}	
	for ( i=0; i<ServerModelFileCount; i++ )
	{
		ModelFileName = ServerModelFileList[i].cFileName;		
		JetAPI::ExtractMainFileName(ModelFileName, ModelName);
		ModelPtr = ProjectPtr->GetProjectModelPtrByModelName(ModelName);
		if ( NULL == ModelPtr ) 
		{
			//是否自動建立未建立過的模組
			if ( false == bIncNewModel ) { continue; }
			CAOIComponent *ComponentPtr=GetProjectComponentPtrByModelName(ModelName);
			if ( NULL == ComponentPtr ) { continue; }
			ModelPtr = AOIObjManager.CreateModelObj();
			if ( NULL == ModelPtr ) { continue; }
			
			ModelPtr->SetModelName(ModelName);//不應該設定			
			ModelFolder.Format(_T("%s\\%s"), ProjectLibraryFolder, ModelName);			
			ModelPtr->SetModelFolderModel(ModelFolder);
			ModelPtr->AssignModelFolder();
			ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);
			ModelPtr->UpdateModelFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);

			ProjectPtr->AddProjectModelPtr(ModelPtr, false);
			ModelModifiedList.push_back(ModelPtr);		
			ModelPtr->SetModelTempInt(ModelModified);
			continue; 			
		}
		ftLastWriteTime = ServerModelFileList[i].ftLastWriteTime;
		ModelModifyDateTime = ModelPtr->GetModelModifiedDateTime();
		JetAPI::FileTimeToTimet(ftLastWriteTime, ModelSaveDateTime);	
		if ( false == bLoadAll )//沒有全載入
		{
			if ( ModelSaveDateTime <= (ModelModifyDateTime+DelayTime) )//確認存檔日期是否小於修改日期
			{	continue;	}
		}
		ModelModifiedList.push_back(ModelPtr);		
		ModelPtr->SetModelTempInt(ModelModified);
	}
	
	bool         IsOK=true;	
	size_t       UpdateCount=0;	
	CString      FolderSrc;	
	CString      FolderDst;		
	CString      ModelFileNameSrc;
	CString      ModelFileNameDst;	
	CString      ModelFileNameTmp;
	const size_t ModelModifiedCount = ModelModifiedList.size();
	COPY_HUGE_FILES_MODE CopyHugeFilesMode = ProjectPtr->GetProjectCopyServerHugeFileMode();

	//載入伺服器的資料
	UpdateCount=0;
	for ( i=0; i<ModelModifiedCount; i++ )
	{		
		ModelPtr = ModelModifiedList[i];
		if ( NULL == ModelPtr )	{	continue; }
		ModelName = ModelPtr->GetModelName();
		ModelFileNameSrc.Format(_T("%s\\%s"), ServerFolder, ModelName);
		
		FolderSrc = ModelFileNameSrc;
		FolderDst = ModelPtr->GetModelFolderModel();
		//複製要貼上的模組	
		IsOK = JetAPI::HugeCopyFolderAToFolderB(CopyHugeFilesMode, FolderSrc, FolderDst, false, false, _T(""), -1, -1);		
		if ( false == IsOK ) 
		{	
			str = _T("Error, Copy Model Folder Fault");
			str = ProjectPtr->LoadMultiLanguageString(str, str);
			m_ErrorString.Format(_T("%s \n[%s]\nto\n[%s]"), str, FolderSrc, FolderDst);
			return false; 
		}
		ModelFileNameTmp.Format(_T("%s\\%s.%s"), TempFolder, ModelName, ExtName);		
		ModelFileNameSrc.Format(_T("%s\\%s.%s"), ServerFolder, ModelName, ExtName);
		::CopyFile(ModelFileNameSrc, ModelFileNameTmp, FALSE);
		ModelPtr->LoadModelParamFile(ModelFileNameTmp);

		ModelPtr->SetModelFolderModel(FolderDst);
		ModelPtr->AssignModelFolder();
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);
		ModelPtr->UpdateModelFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);

		UpdateCount ++;		
		::DeleteFile(ModelFileNameTmp);
	}
	

	MODEL_TYPE  ModelType;
	const size_t ModelCount2 = ProjectPtr->GetProjectModelCount();
	for ( i=0; i<ModelCount2; i++ )
	{
		ModelPtr = ProjectPtr->GetProjectModelPtr(i, false);
		if ( NULL == ModelPtr ) { continue; }
		if ( ModelNoChanged == ModelPtr->GetModelTempInt() ) { continue; }
		ModelType = ModelPtr->GetModelType();
		//if ( MODEL_TYPE_NULL == ModelType ) { continue; }
		if ( CAOIModel::CheckModelTypeEnabled(ModelType) == false )
		{	continue; }

		ModelName = ModelPtr->GetModelName();
		ModelName.MakeUpper();
		SelectProjectAllComponents(false);
		SelectProjectComponentsByModelName(ModelName, false);
		ApplyProjectModelToComponentsSelected(ModelPtr);		
	}

	//寫入暫存專案檔案內
	CString ProjectName = ProjectPtr->GetProjectFileName();		
	if ( ProjectPtr->SaveProjectFile(ProjectName) == false )
	{	return false; }
	//更新至原始專案的資料夾
	bool bUpdateToProject=true;	
	if ( true == bUpdateToProject )
	{
		CString LibraryFolder;
		CString ProjectFolder;
		CString ProjectFileNameSrc;
		CString ProjectFileNameDst;
		CString ProjectFileNameShow = ProjectPtr->GetProjectShowName();		

		ProjectFileNameSrc = ProjectName;
		ProjectFileNameDst = ProjectFileNameShow;
		JetAPI::ExtractMainFileName(ProjectFileNameShow, ProjectFolder);
		LibraryFolder = AOIDataDefine.GetProjectLibraryFolderName(ProjectFolder);		
		if ( ::CopyFile(ProjectFileNameSrc, ProjectFileNameDst, FALSE) == FALSE )
		{	
			str = _T("Error, Copy Project File Fault");
			str = ProjectPtr->LoadMultiLanguageString(str, str);
			m_ErrorString.Format(_T("%s \n[%s]\nTo\n[%s]"), str, ProjectFileNameSrc, ProjectFileNameDst);
			return false;		
		}
		
		UpdateCount=0;
		for ( i=0; i<ModelModifiedCount; i++ )
		{		
			ModelPtr = ModelModifiedList[i];
			if ( NULL == ModelPtr )	{	continue; }
			ModelName = ModelPtr->GetModelName();
			ModelFileNameSrc.Format(_T("%s\\%s"), ServerFolder, ModelName);
			ModelFileNameDst.Format(_T("%s\\%s"), LibraryFolder, ModelName);
		
			FolderSrc = ModelFileNameSrc;
			FolderDst = ModelFileNameDst;
			//複製要貼上的模組	
			IsOK = JetAPI::HugeCopyFolderAToFolderB(CopyHugeFilesMode, FolderSrc, FolderDst, false, false, _T(""), -1, -1);		
			if ( false == IsOK ) 
			{	
				str = _T("Error, Copy Model Folder Fault");
				str = ProjectPtr->LoadMultiLanguageString(str, str);
				m_ErrorString.Format(_T("%s \n[%s]\nto\n[%s]"), str, FolderSrc, FolderDst);
				return false; 
			}			
			UpdateCount ++;		
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectLibryFromServerProjectLibrary(LPCTSTR LibraryFolderSrc, LPCTSTR LibraryFolderDst, std::vector<TModelInfo> &BefList, std::vector<TModelInfo> &AftList, std::vector<TModelInfo> &NewList, std::vector<TModelInfo> &DelList, std::vector<TModelInfo> &RepList, std::vector<CString> &CopyList)//載入專案資料庫從伺服器專案資料庫
{
	if ( LoadProjectLibryFromServerProjectLibraryFn(LibraryFolderSrc, LibraryFolderDst, BefList, AftList, NewList, DelList, RepList, CopyList) == false )
	{
		SetProjectExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectLibryFromServerProjectLibraryFn(LPCTSTR LibraryFolderSrc, LPCTSTR LibraryFolderDst, std::vector<TModelInfo> &BefList, std::vector<TModelInfo> &AftList, std::vector<TModelInfo> &NewList, std::vector<TModelInfo> &DelList, std::vector<TModelInfo> &RepList, std::vector<CString> &CopyList)//載入專案資料庫從伺服器專案資料庫	
{
	CString  str;
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }
	size_t       i=0, j=0;	
	std::vector<CString>    &CopyModelList=CopyList;	
	std::vector<TModelInfo> &ModelList_Bef=BefList;//載檔前
	std::vector<TModelInfo> &ModelList_Aft=AftList;//載檔後
	std::vector<TModelInfo> &ModelList_New=NewList;//新的
	std::vector<TModelInfo> &ModelList_Rep=RepList;//重複
	std::vector<TModelInfo> &ModelList_Del=DelList;//刪除
	
	CString      ServerFolder=LibraryFolderSrc;
	CString      LibraryFolder=LibraryFolderDst;	
	
	bool         IsOK=true;
	CString      FolderSrc;
	CString      FolderDst;
	CString      ModelName;		
	CString      ModelFolder;		
	CString      ModelFileNameSrc;		
	CString      ModelFileNameDst;		
	CString      ModelExtName=_T("MDL");
	const size_t ModelCount_Bef=ModelList_Bef.size();
	const size_t ModelCount_Aft=ModelList_Aft.size();	
	for ( i=0; i<ModelCount_Bef; i++ )
	{	ModelList_Bef[i].sTempInt = -1; }
	for ( i=0; i<ModelCount_Aft; i++ )
	{	ModelList_Aft[i].sTempInt = -1; }
	//比較新舊的模組列表
	for ( i=0; i<ModelCount_Bef; i++ )
	{
		for ( j=0; j<ModelCount_Aft; j++ )
		{
			if ( -1 != ModelList_Aft[j].sTempInt ) { continue; }
			if ( ModelList_Bef[i].sModelName.CompareNoCase(ModelList_Aft[j].sModelName) != 0 )
			{	continue; }
			ModelList_Bef[i].sTempInt = (int)(j);
			ModelList_Aft[j].sTempInt = (int)(i);
			ModelList_Bef[i].sModelPtr = ModelList_Aft[j].sModelPtr;
			ModelList_Rep.push_back(ModelList_Bef[i]);
			break;
		}
		if ( j != ModelCount_Aft )
		{	continue; }
		ModelList_Del.push_back(ModelList_Bef[i]);		
	}

	for ( i=0; i<ModelCount_Aft; i++ )
	{	
		if ( -1 != ModelList_Aft[i].sTempInt ) { continue; } 
		ModelList_New.push_back(ModelList_Aft[i]);
	}

	const int    ModelAdded    = SERVER_MODEL_ADD;
	const int    ModelModified = SERVER_MODEL_MODIFY;
	const int    ModelDeleted  = SERVER_MODEL_DELETE;	
	const int    ModelNoChanged  = SERVER_MODEL_UNCHANGE;	

	const size_t ModelCount_New = ModelList_New.size();
	const size_t ModelCount_Rep = ModelList_Rep.size();
	const size_t ModelCount_Del = ModelList_Del.size();

	//刪除不要的模組-專案資料庫
	for ( i=0; i<ModelCount_Del; i++ )
	{
		ModelFolder.Format(_T("%s\\%s"), LibraryFolder, ModelList_Del[i].sModelName);
		JetAPI::RemoveFolder(ModelFolder);
	}

	//複製新的模組-伺服器資料庫
	for ( i=0; i<ModelCount_New; i++ )
	{	CopyModelList.push_back(ModelList_New[i].sModelName); }

	std::vector<WIN32_FIND_DATA> ServerModelFileList;
	if ( JetAPI::ListFilesInFolder(ServerFolder, ModelExtName, ServerModelFileList) == false )
	{	
		str = _T("Error, List Server Folder File Fault");
		str = ProjectPtr->LoadMultiLanguageString(str, str);
		m_ErrorString.Format(_T("%s [%s]"), str, ServerFolder);
		return false;
	}

	//更新日期不同的	
	FILETIME ftLastWriteTime;	
	time_t   ModelSaveDateTime=0;
	time_t   ModelModifyDateTime=0;
	time_t   ModelCheckDelayTime=10;
	const size_t ServerModelFileCount = ServerModelFileList.size();
	for ( i=0; i<ModelCount_Rep; i++ )
	{			
		ModelList_Rep[i].sTempInt = ModelModified; 
		ModelName.Format(_T("%s.%s"), ModelList_Rep[i].sModelName, ModelExtName);;
		for ( j=0; j<ServerModelFileCount; j++ )
		{
			if ( ModelName.CompareNoCase(ServerModelFileList[j].cFileName) != 0)
			{	continue; }
			break;
		}
		if ( ServerModelFileCount == j )
		{
			ModelList_Rep[i].sTempInt = ModelNoChanged; 
			continue;
		}

		ftLastWriteTime = ServerModelFileList[j].ftLastWriteTime;
		ModelModifyDateTime = ModelList_Rep[i].sModifiedTime;
		JetAPI::FileTimeToTimet(ftLastWriteTime, ModelSaveDateTime);	
		if ( ModelSaveDateTime <= (ModelModifyDateTime+ModelCheckDelayTime) )//確認存檔日期是否小於修改日期
		{
			ModelList_Rep[i].sTempInt = ModelNoChanged; 
			continue; 
		}
		if ( NULL != ModelList_Rep[i].sModelPtr )
		{
			ModelList_Rep[i].sModelPtr->SetModelNeedSaveFiles(true);
			ModelList_Rep[i].sModelPtr->SetModelModifiedDateTime(ModelSaveDateTime);	
		}
		CopyModelList.push_back(ModelList_Rep[i].sModelName);
	}	

	const size_t CopyModelCount = CopyModelList.size();
	COPY_HUGE_FILES_MODE CopyHugeFilesMode = ProjectPtr->GetProjectCopyServerHugeFileMode();
	for ( i=0; i<CopyModelCount; i++ )
	{
		ModelName = CopyModelList[i];
		ModelFileNameDst.Format(_T("%s\\%s"), LibraryFolder, ModelName);
		ModelFileNameSrc.Format(_T("%s\\%s"), ServerFolder, ModelName);
		
		FolderSrc = ModelFileNameSrc;
		FolderDst = ModelFileNameDst;
		//複製要貼上的模組			
		IsOK = JetAPI::HugeCopyFolderAToFolderB(CopyHugeFilesMode, FolderSrc, FolderDst, false, false, _T(""), -1, -1);
		if ( false == IsOK ) 
		{	
			str = _T("Error, Copy Model Folder Fault");
			str = ProjectPtr->LoadMultiLanguageString(str, str);
			m_ErrorString.Format(_T("%s \n[%s]\nTo\n[%s]"), str, FolderSrc, FolderDst);
			return false; 
		}
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectLibryToServerLibrary_Backup(LPCTSTR ServerFolder)//儲存專案資料庫至伺服器資料庫
{
	CString  str;
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }

	ClearProjectServerModelLockList();
	if ( JetAPI::IsFolderExist(ServerFolder) == false )
	{
		m_ErrorString.Format(_T("Error, The Server Folder does not exist [%s]"), ServerFolder);
		return false;
	}

	CString LockFileName;	
	CString LockFileNameTmp;		
	CString ExtName=_T("MDL");
	CString ExtNameLock=_T("TMP");
	CString MainFilename = GetProjectFileMainName();
	CString TempFolder = AOIDataCollect.GetAOITempDirectory();	

	LockFileNameTmp.Format(_T("%s\\%s.%s"), TempFolder, _T("LockFile"), ExtNameLock);
	if ( JetAPI::CreateTempFile(LockFileNameTmp, MainFilename) == false )
	{
		m_ErrorString.Format(_T("Error, Create Lock File Fault [%s]"), LockFileNameTmp);
		return false;	
	}
	
	std::vector<WIN32_FIND_DATA> ServerModelFileList;
	if ( JetAPI::ListFilesInFolder(ServerFolder, ExtName, ServerModelFileList) == false )
	{
		::DeleteFile(LockFileNameTmp);
		m_ErrorString.Format(_T("Error, List Server Folder File Fault [%s]"), ServerFolder);
		return false;
	}

	size_t       i=0, j=0;		
	CString      ModelName;
	CString      ModelFileName;		
	CAOIModel   *ModelPtr = NULL;
	FILETIME     ftLastWriteTime;
	time_t       ModelSaveDateTime=0;
	time_t       ModelModifyDateTime=0;
	std::vector<CString> ModelFileList;	
	const size_t ServerModelFileCount = ServerModelFileList.size();
	const size_t ModelCount = ProjectPtr->GetProjectModelCount();	

	for ( i=0; i<ModelCount; i++ )
	{
		ModelPtr = ProjectPtr->GetProjectModelPtr(i, false);
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->SetModelTempInt(FN_ENABLE);
	}

	for ( i=0; i<ServerModelFileCount; i++ )
	{
		ModelFileName = ServerModelFileList[i].cFileName;		
		JetAPI::ExtractMainFileName(ModelFileName, ModelName);
		ModelPtr = ProjectPtr->GetProjectModelPtrByModelName(ModelName);
		if ( NULL == ModelPtr ) { continue; }
		ftLastWriteTime = ServerModelFileList[i].ftLastWriteTime;
		ModelModifyDateTime = ModelPtr->GetModelModifiedDateTime();
		JetAPI::FileTimeToTimet(ftLastWriteTime, ModelSaveDateTime);		
		if ( ModelSaveDateTime >= ModelModifyDateTime )//確認存檔日期是否大於修改日期
		{
			ModelPtr->SetModelTempInt(FN_DISABLE);
			continue; 
		}
		ModelFileList.push_back(ModelName);
	}
	
	bool         IsOK=true;		
	CString      FolderSrc;	
	CString      FolderDst;	
	CString      ModelFileNameTmp;	
	CString      ModelFileNameDst;		
	const size_t ModelFileCount = ModelFileList.size();		
	std::vector<CString> &ModelLockList=m_ProjectServerModelLockList;

	//刪除舊有的資料
	for ( i=0; i<ModelFileCount; i++ )
	{
		ModelName = ModelFileList[i];
		LockFileName.Format(_T("%s\\%s.%s"), ServerFolder, ModelName, ExtNameLock);
		if ( JetAPI::IsFileExist(LockFileName) == true )//確認是否鎖住
		{	
			ModelPtr = ProjectPtr->GetProjectModelPtrByModelName(ModelName);
			if ( NULL != ModelPtr )
			{	ModelPtr->SetModelTempInt(FN_DISABLE); }
			ModelLockList.push_back(ModelName);
			continue;
		}
		//複製鎖住檔案時, 如果錯誤視為別人正在操作
		if ( ::CopyFile(LockFileNameTmp, LockFileName, TRUE) == FALSE )
		{	
			ModelPtr = ProjectPtr->GetProjectModelPtrByModelName(ModelName);
			if ( NULL != ModelPtr )
			{	ModelPtr->SetModelTempInt(FN_DISABLE); }
			ModelLockList.push_back(ModelName);
			continue;	
		}

		FolderDst.Format(_T("%s\\%s"), ServerFolder, ModelName);		
		JetAPI::RemoveFolder(FolderDst);
		ModelFileNameDst.Format(_T("%s\\%s.%s"), ServerFolder, ModelName, ExtName);
		::DeleteFile(ModelFileNameDst);
		::DeleteFile(LockFileName);
	}
	
	COPY_HUGE_FILES_MODE CopyHugeFilesMode = ProjectPtr->GetProjectCopyServerHugeFileMode();
	for ( i=0; i<ModelCount; i++ )
	{
		ModelPtr = ProjectPtr->GetProjectModelPtr(i, false);
		if ( FN_DISABLE == ModelPtr->GetModelTempInt() )
		{	continue; }	

		ModelName = ModelPtr->GetModelName();		
		LockFileName.Format(_T("%s\\%s.%s"), ServerFolder, ModelName, ExtNameLock);
		if ( JetAPI::IsFileExist(LockFileName) == true )
		{			
			ModelLockList.push_back(ModelName);
			ModelPtr->SetModelTempInt(FN_DISABLE);
			continue;	
		}		
		if ( ::CopyFile(LockFileNameTmp, LockFileName, TRUE) == FALSE )
		{
			ModelLockList.push_back(ModelName);
			ModelPtr->SetModelTempInt(FN_DISABLE);
			continue;	
		}
		ModelFileNameDst.Format(_T("%s\\%s"), ServerFolder, ModelName);
		
		FolderDst = ModelFileNameDst;
		FolderSrc = ModelPtr->GetModelFolderModel();
		//複製要貼上的模組	
		IsOK = JetAPI::HugeCopyFolderAToFolderB(CopyHugeFilesMode, FolderSrc, FolderDst, false, false, _T(""), -1, -1);				
		if ( false == IsOK ) 
		{	
			::DeleteFile(LockFileName);
			::DeleteFile(LockFileNameTmp);
			m_ErrorString.Format(_T("Error, Copy Model Folder Fault \n[%s]\nto\n[%s]"), FolderSrc, FolderDst);
			return false; 
		}
		ModelPtr->SetupkModelModifiedDateTime();//盡量讓模組修改日期與存檔日期相同		
		ModelFileNameTmp.Format(_T("%s\\%s.%s"), TempFolder, ModelName, ExtName);
		if ( ModelPtr->SaveModelParamFile(ModelFileNameTmp) == false ) 
		{
			::DeleteFile(LockFileName);
			continue; 
		}		
		ModelFileNameDst.Format(_T("%s\\%s.%s"), ServerFolder, ModelName, ExtName);
		::CopyFile(ModelFileNameTmp, ModelFileNameDst, FALSE);				
		::DeleteFile(LockFileName);
		::DeleteFile(ModelFileNameTmp);
	}
	::DeleteFile(LockFileNameTmp);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LoadProjectLibryFromServerLibrary_Backup(LPCTSTR ServerFolder)//載入專案資料庫從伺服器資料庫
{
	CString  str;
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }

	ClearProjectServerModelLockList();
	if ( JetAPI::IsFolderExist(ServerFolder) == false )
	{
		m_ErrorString.Format(_T("Error, The Server Folder does not exist [%s]"), ServerFolder);
		return false;
	}

	CString LockFileName;	
	CString LockFileNameTmp;	
	CString ExtName=_T("MDL");
	CString ExtNameLock=_T("TMP");
	CString MainFilename = GetProjectFileMainName();
	CString TempFolder = AOIDataCollect.GetAOITempDirectory();	

	LockFileNameTmp.Format(_T("%s\\%s.%s"), TempFolder, _T("LockFile"), ExtNameLock);
	if ( JetAPI::CreateTempFile(LockFileNameTmp, MainFilename) == false )
	{
		m_ErrorString.Format(_T("Error, Create Lock File Fault [%s]"), LockFileNameTmp);
		return false;	
	}
	
	std::vector<WIN32_FIND_DATA> ServerModelFileList;
	if ( JetAPI::ListFilesInFolder(ServerFolder, ExtName, ServerModelFileList) == false )
	{
		::DeleteFile(LockFileNameTmp);
		m_ErrorString.Format(_T("Error, List Server Folder File Fault [%s]"), ServerFolder);
		return false;
	}

	size_t       i=0, j=0;		
	CString      ModelName;
	CString      ModelFileName;		
	CAOIModel   *ModelPtr = NULL;
	FILETIME     ftLastWriteTime;
	time_t       DelayTime=10;//消除存檔時間差距, 單位為秒
	time_t       ModelSaveDateTime=0;
	time_t       ModelModifyDateTime=0;
	std::vector<CString> ModelFileList;
	const size_t ServerModelFileCount = ServerModelFileList.size();
	const size_t ModelCount = ProjectPtr->GetProjectModelCount();	

	for ( i=0; i<ModelCount; i++ )
	{
		ModelPtr = ProjectPtr->GetProjectModelPtr(i, false);
		if ( NULL == ModelPtr ) { continue; }
		ModelPtr->SetModelTempInt(FN_DISABLE);
	}	
	for ( i=0; i<ServerModelFileCount; i++ )
	{
		ModelFileName = ServerModelFileList[i].cFileName;		
		JetAPI::ExtractMainFileName(ModelFileName, ModelName);
		ModelPtr = ProjectPtr->GetProjectModelPtrByModelName(ModelName);
		if ( NULL == ModelPtr ) { continue; }
		ftLastWriteTime = ServerModelFileList[i].ftLastWriteTime;
		ModelModifyDateTime = ModelPtr->GetModelModifiedDateTime();
		JetAPI::FileTimeToTimet(ftLastWriteTime, ModelSaveDateTime);	
		if ( ModelSaveDateTime <= (ModelModifyDateTime+DelayTime) )//確認存檔日期是否小於修改日期
		{	continue;	}
		ModelFileList.push_back(ModelName);
		ModelPtr->SetModelTempInt(FN_ENABLE);
	}
	
	bool         IsOK=true;	
	size_t       UpdateCount=0;	
	CString      FolderSrc;	
	CString      FolderDst;		
	CString      ModelFileNameSrc;	
	CString      ModelFileNameTmp;		
	const size_t ModelFileCount = ModelFileList.size();		
	std::vector<CString> &ModelLockList=m_ProjectServerModelLockList;
	COPY_HUGE_FILES_MODE CopyHugeFilesMode = ProjectPtr->GetProjectCopyServerHugeFileMode();

	unsigned int   DefaultFrameIndex=0;
	unsigned int   DefaultFrameUniqueID = 0;	
	std::vector<CColorGroup>  ColorGroupList;
	std::vector<unsigned int> FrameIndexMapList;
	ProjectPtr->CloneProjectColorGroupList(ColorGroupList);
	ProjectPtr->BuildProjectFrameIndexMapParam(FrameIndexMapList, DefaultFrameIndex, DefaultFrameUniqueID);	

	//載入伺服器的資料
	UpdateCount=0;
	for ( i=0; i<ModelFileCount; i++ )
	{
		ModelName = ModelFileList[i];
		LockFileName.Format(_T("%s\\%s.%s"), ServerFolder, ModelName, ExtNameLock);
		ModelPtr = ProjectPtr->GetProjectModelPtrByModelName(ModelName);
		if ( NULL == ModelPtr )	{	continue; }
		if ( JetAPI::IsFileExist(LockFileName) == true )//確認是否鎖住
		{	
			ModelPtr = ProjectPtr->GetProjectModelPtrByModelName(ModelName);
			if ( NULL != ModelPtr )
			{	ModelPtr->SetModelTempInt(FN_DISABLE); }
			ModelLockList.push_back(ModelName);
			continue;
		}
		//複製鎖住檔案時, 如果錯誤視為別人正在操作
		if ( ::CopyFile(LockFileNameTmp, LockFileName, TRUE) == FALSE )
		{	
			ModelPtr = ProjectPtr->GetProjectModelPtrByModelName(ModelName);
			if ( NULL != ModelPtr )
			{	ModelPtr->SetModelTempInt(FN_DISABLE); }
			ModelLockList.push_back(ModelName);
			continue;	
		}

		ModelFileNameSrc.Format(_T("%s\\%s"), ServerFolder, ModelName);
		
		FolderSrc = ModelFileNameSrc;
		FolderDst = ModelPtr->GetModelFolderModel();
		//複製要貼上的模組	
		IsOK = JetAPI::HugeCopyFolderAToFolderB(CopyHugeFilesMode, FolderSrc, FolderDst, false, false, _T(""), -1, -1);		
		if ( false == IsOK ) 
		{	
			::DeleteFile(LockFileName);
			::DeleteFile(LockFileNameTmp);
			m_ErrorString.Format(_T("Error, Copy Model Folder Fault \n[%s]\nto\n[%s]"), FolderSrc, FolderDst);
			return false; 
		}
		ModelFileNameTmp.Format(_T("%s\\%s.%s"), TempFolder, ModelName, ExtName);		
		ModelFileNameSrc.Format(_T("%s\\%s.%s"), ServerFolder, ModelName, ExtName);
		::CopyFile(ModelFileNameSrc, ModelFileNameTmp, FALSE);
		ModelPtr->LoadModelParamFile(ModelFileNameTmp);
		ModelPtr->UpdateModelColorGroupLinkIndex(ColorGroupList);
		ModelPtr->UpdateModelFrameIndex(DefaultFrameIndex, DefaultFrameUniqueID, FrameIndexMapList);

		UpdateCount ++;
		::DeleteFile(LockFileName);
		::DeleteFile(ModelFileNameTmp);
	}
	::DeleteFile(LockFileNameTmp);

	MODEL_TYPE  ModelType;
	for ( i=0; i<ModelCount; i++ )
	{
		ModelPtr = ProjectPtr->GetProjectModelPtr(i, false);
		if ( NULL == ModelPtr ) { continue; }
		if ( FN_DISABLE == ModelPtr->GetModelTempInt() ) { continue; }
		ModelType = ModelPtr->GetModelType();
		//if ( MODEL_TYPE_NULL == ModelType ) { continue; }
		if ( CAOIModel::CheckModelTypeEnabled(ModelType) == false )
		{	continue; }

		ModelName = ModelPtr->GetModelName();
		ModelName.MakeUpper();
		SelectProjectAllComponents(false);
		SelectProjectComponentsByModelName(ModelName, false);
		ApplyProjectModelToComponentsSelected(ModelPtr);		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectServerLogFile(LPCTSTR filename, std::vector<CString> &LogList)
{
	if ( SaveProjectServerLogFileFn(filename, LogList) == false )
	{
		SetProjectExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectServerLogFileFn(LPCTSTR filename, std::vector<CString> &LogList)
{
	if ( NULL == filename ) { return false; }
	const size_t StringCount=LogList.size();
	if ( 0 == StringCount ) { return true; }

	size_t       i=0;
	CString sDateTime;	
	TCHAR TMode[32] = _T("");
	_tcscpy(TMode, _T("a+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	FILE *pfile = ::_tfopen(filename, TMode);
	if ( NULL == pfile ) 
	{
		m_ErrorString.Format(_T("Error, Save File Fault [%s]"), filename);
		return false; 
	}	

	JetAPI::FormatTime(FORMAT_TIME_01, CTime::GetCurrentTime(), sDateTime);
	for ( i=0; i<StringCount; i++ )
	{	::_ftprintf(pfile, _T("%s %s\n"), sDateTime, LogList[i]);	}	
	::fclose(pfile); pfile=NULL;	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ResetProjectVersionCodeList()//復歸專案版本號列表	
{
	size_t       i=0;	
	std::vector<TVersionCode> &VersionCodeList=m_ProjectVersionCodeList;
	const size_t CodeCount=VersionCodeList.size();;
	for ( i=0; i<CodeCount; i++ )
	{	VersionCodeList[i] = TVersionCode();	}

	std::wstring wsDefault;
	CString      strDefault = AOIDataDefine.GetDefaultText();
	JetAPI::TCHAR2wstring(strDefault, wsDefault);
	VersionCodeList[0].bEnabled = true;
	VersionCodeList[0].wsCodeName = wsDefault;	
	return true;
}
//-------------------------------------------------------------------------------------//
size_t CAOIProject::GetProjectVersionCodeCount() const//取得專案版本號數量
{
	return m_ProjectVersionCodeList.size();
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CopyProjectVersionCode(size_t idx, LPCTSTR Name)//複製專案版本號
{
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }
	if ( CheckProjectVersionCodeIndex(idx) == false ) { return false; }	
	std::wstring wsCodeName;
	TProjectParameter &ProParam=GetProjectParameter();	
	const size_t NewIdx = GetProjectVersionCodeNewIndex();
	if ( -1 == NewIdx )
	{
		m_ErrorString = _T("Error, No empty version code");
		return false;
	}
	if ( JetAPI::TCHAR2wstring(Name, wsCodeName) == false )
	{	
		m_ErrorString = _T("Error, Can not convert Code Name");
		return false; 
	}
	m_ProjectVersionCodeList[NewIdx] = m_ProjectVersionCodeList[idx];
	m_ProjectVersionCodeList[NewIdx].wsCodeName = wsCodeName;

	size_t        i=0;
	CAOIComponent *ComponentPtr = NULL;
	const size_t ComponentCount = ProjectPtr->GetProjectComponentCount();

	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->CopyComponentVersionParam(idx, NewIdx);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::DeleteProjectVersionCode(size_t idx)//刪除專案版本號	
{
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }
	if ( CheckProjectVersionCodeIndex(idx) == false ) { return false; }	
	if ( PROJECT_VERSION_CODE_BASE_INDEX == idx )
	{
		m_ErrorString = _T("Error, Can not delete default Version Code");
		return false; 
	}
	m_ProjectVersionCodeList[idx] = TVersionCode();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AddProjectVersionCode(LPCTSTR Name)//新增加專案版本號
{
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }

	const size_t NewIdx=ProjectPtr->GetProjectVersionCodeNewIndex();
	if ( -1 == NewIdx )
	{
		m_ErrorString = _T("Error, can not add new version code");
		return false;	
	}
	if ( CheckProjectVersionCodeIndex(NewIdx) == false ) { return true; }

	if ( JetAPI::TCHAR2wstring(Name, m_ProjectVersionCodeList[NewIdx].wsCodeName) == false )
	{	return false; }
	m_ProjectVersionCodeList[NewIdx].bEnabled = true;

	size_t        i=0;
	CAOIComponent *ComponentPtr = NULL;
	const size_t ComponentCount = ProjectPtr->GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->UpdateToComponentVersionParam(NewIdx);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
size_t CAOIProject::GetProjectVersionCodeNewIndex() const//取得新的版本號引數	
{
	size_t i=0;	
	size_t len=0;
	const size_t CodeCount=GetProjectVersionCodeCount();	
	for ( i=0; i<CodeCount; i++ )
	{		
		if ( true == m_ProjectVersionCodeList[i].bEnabled ) { continue; }		
		return i;
	}
	return -1;
}
//-------------------------------------------------------------------------------------//
TVersionCode* CAOIProject::GetProjectVersionCodeActivePtr()//取得目前專案版本號
{
	return GetProjectVersionCodePtr(m_ProjectParameter.m_VersionCodeActiveIndex, true);
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::UpdateToProjectVersionCode()//將狀態更新至目前專案版本號碼
{
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }

	TProjectParameter &ProParam=GetProjectParameter();	
	const size_t idx = ProParam.m_VersionCodeActiveIndex;
	if ( CheckProjectVersionCodeIndex(idx) == false ) { return true; }	

	size_t        i=0;
	CAOIComponent *ComponentPtr = NULL;
	const size_t ComponentCount = ProjectPtr->GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->UpdateToComponentVersionParam(idx);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::LayoutProjectVersionCodeList()//整理專案版本號列表
{
	CAOIProject *ProjectPtr = this;
	const size_t ComponentCount=GetProjectComponentCount();
	const size_t VersionCodeListCount=m_ProjectVersionCodeList.size();
	const size_t VersionCodeListCountBackup=m_ProjectVersionCodeListBackup.size();	
	for ( size_t j=0; j<VersionCodeListCount; j++ )
	{
		const TVersionCode &VersionCode=m_ProjectVersionCodeList[j];		
		if ( true == VersionCode.bEnabled ) { continue; }
		if ( VersionCodeListCount == VersionCodeListCountBackup )
		{
			const TVersionCode &VersionCodeBackup=m_ProjectVersionCodeListBackup[j];
			if ( false == VersionCodeBackup.bEnabled ) { continue; }		
		}
		const size_t VersionCodeIndex = j;			
		for ( size_t i=0; i<ComponentCount; i++ )
		{
			CAOIComponent *ComponentPtr = GetProjectComponentPtr(i, false);
			if ( NULL == ComponentPtr ) { continue; }				
			ComponentPtr->ResetComponentVersionParam(VersionCodeIndex);
		}
	}				
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ChangeProjectVersionCode(size_t idx)//切換專案版本號碼引數
{
	CAOIProject *ProjectPtr = this;
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }
	if ( CheckProjectVersionCodeIndex(idx) == false ) { return false; }	

	TProjectParameter &ProParam=GetProjectParameter();	
	ProParam.m_VersionCodeActiveIndex = idx;


	size_t        i=0;
	bool          ModelChanged = false;
	CAOIComponent *ComponentPtr = NULL;
	std::vector<CAOIComponent*> ChangeModelList;
	const size_t ComponentCount = ProjectPtr->GetProjectComponentCount();
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->ChangeComponentVersionParam(idx, ModelChanged);
		if ( true == ModelChanged )
		{	ChangeModelList.push_back(ComponentPtr); }
	}
	if ( ChangeModelList.size() > 0 )
	{
		SelectProjectAllComponents(false);
		SelectProjectComponentList(ChangeModelList, true);
		ApplyProjectLibraryToComponentsSelected();
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::CheckProjectVersionCodeIndex(size_t index)//確認專案版本號碼引數
{
	const size_t CodeCount=GetProjectVersionCodeCount();
	if ( index >= CodeCount ) 
	{ 
		m_ErrorString.Format(_T("Error, Project Version Code Index out of range (%d//%d)"), index, CodeCount);
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
TVersionCode* CAOIProject::GetProjectVersionCodePtr(size_t idx, bool bCheck)//取得專案版本號
{
	if ( true == bCheck )
	{
		if ( CheckProjectVersionCodeIndex(idx) == false )
		{	return false; }		
	}
	return &m_ProjectVersionCodeList[idx];
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SetProjectVersionCodeList(const std::vector<TVersionCode> &VersionList)//設定專案版本號列表	
{
	size_t i=0;	
	const size_t VersionCount=VersionList.size();
	const size_t CodeCount=GetProjectVersionCodeCount();
	const size_t UsedCnt=MIN(VersionCount, CodeCount);
	ResetProjectVersionCodeList();
	for ( i=0; i<UsedCnt; i++ )
	{	m_ProjectVersionCodeList[i] = VersionList[i];	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ReadProjectAIModelComponentLabelFile(LPCTSTR Filename)
{
	const bool bUnicode = false;
	//--------------------------------------------------------------------//	
	FILE *pfile = JetAPI::OpenReadFile(Filename, bUnicode);;	
	if ( pfile == NULL )
	{		
		this->m_ErrorString.Format(_T("Open File Fault (%s)"), Filename);
		return false;
	}
	//--------------------------------------------------------------------//
	size_t Pos=0;
	bool   bReadSucc=true;
	const int StartLine = 1;
	const size_t textlinesize = 1024;
	//--------------------------------------------------------------------//
	char Textline[textlinesize] = "";
	std::string trimChar=" ";
	std::string StringLine, SubString, Str;
	std::vector<std::string> NgStringList;
	std::vector<std::string> SubStringList;
	
	wchar_t wTextline[textlinesize] = L"";
	std::wstring wtrimChar=L" ";
	std::wstring wStringLine, wSubString, wStr;	
	std::vector<std::wstring> wNgStringList;
	std::vector<std::wstring> wSubStringList;	
	//--------------------------------------------------------------------//	
	size_t NgCount=0;
	size_t textlen=0;
	size_t DataLine=0;	
	size_t SubStringCount=0;
	double MapResX=0, MapResY=0;
	//--------------------------------------------------------------------//
	int          GroupNum;	
	RECT         PartRect;
	MODEL_TYPE   ModelType;
	unsigned int Index=0;
	unsigned int PanelIndex=0;
	unsigned int BoardIndex=0;	
	double       AveSizeX=0;
	double       AveSizeY=0;
	double       AveSizeX2=0;
	double       AveSizeY2=0;
	double       BodySizeX=0;
	double       BodySizeY=0;
	double       PartAngle=0;	
	double       Confidence=0;	
	TPOINT2D     PartPos;
	size_t       NewModelIdx=0;
	CString      GroupName;
	CString      PartNumber;
	CString      ComponentName;
	CAOIModel      NewModel;
	CAOIModel     *ModelPtr=NULL;
	CAOIComponent *ComponentPtr=NULL;		
	std::vector<CAOIModel> NewModelList;
	const size_t ComponentCount=GetProjectComponentCount();
	//--------------------------------------------------------------------//	
	GetProjectMapResolution(MapResX, MapResY);
	for ( size_t i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if ( NULL == ComponentPtr ) { continue; }
		ComponentPtr->SetComponentTempIndex(-1);
	}
	//--------------------------------------------------------------------//
	//index, PanelID, BoardID, Component, PartNumber, PosX, PosY, Angle, Left, Top, Right, Bottom, Width_avg, Height_avg, Group, Confidence
	while(!feof(pfile) )
	{ 
		DataLine++;
		
		if ( false == bUnicode )
		{
			if( fgets(Textline,textlinesize,pfile) ==NULL ) 
			{	continue;	}
			StringLine = Textline;
		}
		else
		{
			if( fgetws(wTextline,textlinesize,pfile) ==NULL ) 
			{	continue;	}			
			wStringLine = wTextline;
		}
		//未達到使用者要求的開始列數
		if ( DataLine <= StartLine ) { continue; }

		if ( false == bUnicode )
		{	textlen=StringLine.length(); }
		else
		{	textlen=wStringLine.length(); }
		if ( textlen == 0 ) //enter鍵
		{	
			DataLine ++;			
			continue;	
		}
		
		Pos=0;		
		SubStringList.clear();
		wSubStringList.clear();
		if ( false == bUnicode )
		{	bReadSucc = JetAPI::ListSubString(StringLine, ',', SubStringList);	}
		else
		{	bReadSucc = JetAPI::ListSubString(wStringLine, ',', wSubStringList);	}
		if ( false == bReadSucc )
		{
			::fclose(pfile); pfile=NULL;
			return false;
		}				
		
		if ( false == bUnicode )
		{	SubStringCount = SubStringList.size();	}
		else
		{	SubStringCount = wSubStringList.size();	}
		
		if ( 0 == SubStringCount ) { continue; }

		Index=-1;		
		GroupNum=INT_MAX;
		PanelIndex=-1;
		BoardIndex=-1;
		AveSizeX = 0;
		AveSizeY = 0;
		PartAngle = 0;
		Confidence = 0;
		PartPos=TPOINT2D();
		GroupName = _T("");
		PartNumber = _T("");
		ComponentName = _T("");
		PartRect.left=PartRect.right=0;
		PartRect.top=PartRect.bottom=0;
		//if ( 16 != SubStringCount ) { continue; }

		for ( size_t j=0; j<SubStringCount; j++ )
		{
			if ( false == bUnicode )
			{	
				Str = SubStringList[j];	
				Str = JetAPI::Trim(Str, trimChar);
			}
			else
			{	
				wStr = wSubStringList[j];	
				wStr = JetAPI::Trim(wStr, wtrimChar);
			}
			switch ( j )
			{
			case 0://Index
				if ( false == bUnicode )
				{	Index = ::atoi(Str.c_str()); }
				else
				{	Index = ::_wtoi(wStr.c_str()); }
				break;
			case 1://PanelID
				if ( false == bUnicode )
				{	PanelIndex = ::atoi(Str.c_str()); }
				else
				{	PanelIndex = ::_wtoi(wStr.c_str()); }
				break;
			case 2://BoardID
				if ( false == bUnicode )
				{	BoardIndex = ::atoi(Str.c_str()); }
				else
				{	BoardIndex = ::_wtoi(wStr.c_str()); }
				break;
			case 3://Component
				if ( false == bUnicode )
				{	ComponentName = CString(Str.c_str()); }
				else
				{	ComponentName = CString(wStr.c_str()); }
				break;
			case 4://PartNumber
				if ( false == bUnicode )
				{	PartNumber = CString(Str.c_str()); }
				else
				{	PartNumber = CString(wStr.c_str()); }				
				break;
			case 5://PosX
				if ( false == bUnicode )
				{	PartPos.x = ::atof(Str.c_str()); }
				else
				{	PartPos.x = ::_wtof(wStr.c_str()); }
				break;
			case 6://PosY
				if ( false == bUnicode )
				{	PartPos.y = ::atof(Str.c_str()); }
				else
				{	PartPos.y = ::_wtof(wStr.c_str()); }
				break;
			case 7://Angle
				if ( false == bUnicode )
				{	PartAngle = ::atof(Str.c_str()); }
				else
				{	PartAngle = ::_wtof(wStr.c_str()); }				
				break;
			case 8://Left
				if ( false == bUnicode )
				{	PartRect.left = ::atoi(Str.c_str()); }
				else
				{	PartRect.left = ::_wtoi(wStr.c_str()); }
				break;
			case 9://Top
				if ( false == bUnicode )
				{	PartRect.top = ::atoi(Str.c_str()); }
				else
				{	PartRect.top = ::_wtoi(wStr.c_str()); }
				break;
			case 10://Right
				if ( false == bUnicode )
				{	PartRect.right = ::atoi(Str.c_str()); }
				else
				{	PartRect.right = ::_wtoi(wStr.c_str()); }
				break;
			case 11://Bottom
				if ( false == bUnicode )
				{	PartRect.bottom = ::atoi(Str.c_str()); }
				else
				{	PartRect.bottom = ::_wtoi(wStr.c_str()); }
				break;
			case 12://Confidence
				if ( false == bUnicode )
				{	Confidence = ::atof(Str.c_str()); }
				else
				{	Confidence = ::_wtof(wStr.c_str()); }
				break;
			case 13://Width_avg
				if ( false == bUnicode )
				{	AveSizeX = ::atof(Str.c_str()); }
				else
				{	AveSizeX = ::_wtof(wStr.c_str()); }				
				break;
			case 14://Height_avg
				if ( false == bUnicode )
				{	AveSizeY = ::atof(Str.c_str()); }
				else
				{	AveSizeY = ::_wtof(wStr.c_str()); }
				break;
			case 15://Group
				if ( false == bUnicode )
				{	
					GroupNum = ::atoi(Str.c_str());
					GroupName = CString(Str.c_str()); 					
				}
				else
				{
					GroupNum = ::_wtoi(wStr.c_str());
					GroupName = CString(wStr.c_str()); 
				}				
				break;			
			default:
				break;
			}
		}
		if ( GroupNum < 0 )//無法分類的
		{	continue; }

		AveSizeX2 = AveSizeX*MapResX;
		AveSizeY2 = AveSizeY*MapResY;


		PanelIndex = PanelIndex-1;
		BoardIndex = BoardIndex-1;
		ComponentPtr = GetProjectComponentPtrByComponentFullName(PanelIndex, BoardIndex, ComponentName);
		if ( NULL == ComponentPtr ) 
		{ 
			if ( false == bUnicode )
			{	NgStringList.push_back(StringLine); }
			else
			{	wNgStringList.push_back(wStringLine); }			
			continue; 
		}
		ModelPtr = ComponentPtr->GetComponentModelPtr();
		if ( NULL == ModelPtr ) { continue; }
		
		bool IsExceptionAngle = JetAPI::CheckIsExceptionAngle(PartAngle);		
		
		ModelType = ModelPtr->GetModelType();
		CAOIBox &BodyBoxRef=ModelPtr->GetModelBodyBox();
		BodySizeX = ComponentPtr->GetComponentBodySizeW();
		BodySizeY = ComponentPtr->GetComponentBodySizeH();

		NewModelIdx = -1;
		const size_t NewModelCount=NewModelList.size();
		for ( size_t j=0; j<NewModelCount; j++ )
		{
			const CAOIModel &ModelRef=NewModelList[j];
			CString ModelName=CString(ModelRef.GetModelName());
			if ( GroupName.CompareNoCase(ModelName) == 0 )
			{	
				NewModelIdx = j;
				break; 
			}
		}
		if ( -1 == NewModelIdx )
		{
			bool bAddNewModel=false;
			if ( GroupNum < 99 )//Chip-C
			{
				bAddNewModel = true;			
				NewModel.SetModelType(MODEL_TYPE_CHIP_C);
			}
			else if ( GroupNum < 199 )//Chip-R
			{
				bAddNewModel = true;			
				NewModel.SetModelType(MODEL_TYPE_CHIP_R);
			}
			if ( true == bAddNewModel )
			{
				CAOIBox &BodyBox=NewModel.GetModelBodyBox();
				BodyBox.SetBoxSize(AveSizeX2, AveSizeY2);

				NewModelIdx = NewModelCount;				
				NewModel.SetModelName(GroupName);
				NewModel.SetModelTempInt(GroupNum);
				NewModel.SetModelGroupName(GroupName);
				NewModelList.push_back(NewModel);				
			}
		}

		if ( false == IsExceptionAngle )
		{
			int nAngleLabel=JetAPI::GetAngleLabel(PartAngle);
			switch ( nAngleLabel )
			{
			case 0:
			case 180:
				BodyBoxRef.SetBoxSize(AveSizeX2, AveSizeY2);
				break;
			case 90:
			case 270:
				BodyBoxRef.SetBoxSize(AveSizeY2, AveSizeX2);				
				break;
			}
		}
		else
		{
			BodyBoxRef.RotateBox(-PartAngle, 0, 0);
			BodyBoxRef.SetBoxSize(AveSizeX2, AveSizeY2);
			BodyBoxRef.RotateBox(PartAngle, 0, 0);
		}		
		ComponentPtr->SetComponentRoiSizeW(AveSizeX2);
		ComponentPtr->SetComponentRoiSizeH(AveSizeY2);
		ComponentPtr->SetComponentBodySizeW(AveSizeX2);
		ComponentPtr->SetComponentBodySizeH(AveSizeY2);
		ComponentPtr->SetComponentTempIndex(NewModelIdx);
		ComponentPtr->CalcComponentCadCornerPos();
		ComponentPtr->LayoutComponentStageCornerPos();
		ComponentPtr->SetComponentTempInt(GroupNum);

		ModelPtr = NULL;
	};
	::fclose(pfile); pfile=NULL;

	CString strDate;
	CString strTime;
	CString DateTime;
	CString PackName;
	CString ChipSize;
	TREGION4D BodyRgn;	
	JetAPI::GetTime(DateTime, CTime::GetCurrentTime());
	JetAPI::GetDateTime(DateTime, strDate, strTime);	
	CHIP_SIZE_MODE ChipSizeMode=CHIP_SIZE_NONE;
	const size_t NewModelCount=NewModelList.size();	
	for ( size_t j=0; j<NewModelCount; j++ )
	{		
		CAOIModel &ModelRef=NewModelList[j];
		CAOIBox   &BodyBox=ModelRef.GetModelBodyBox();

		BodyBox.GetBoxRegion(BodyRgn);
		BodySizeX = BodyRgn.GetSizeX();
		BodySizeY = BodyRgn.GetSizeY();
		if ( BodySizeY > BodySizeX )
		{	JetAPI::RotateRegion(90, 0, 0, BodyRgn, BodyRgn);	}

		PackName = _T("");
		ModelType = ModelRef.GetModelType();
		GroupName = ModelRef.GetModelGroupName();
		GroupNum = ModelRef.GetModelTempInt();		
		switch ( ModelType )
		{
		case MODEL_TYPE_CHIP_C:	PackName.Format(_T("C_%03d#%s"), GroupNum, strTime);	break;
		case MODEL_TYPE_CHIP_R:	PackName.Format(_T("R_%03d#%s"), GroupNum, strTime);	break;				
		case MODEL_TYPE_CHIP_L:	PackName.Format(_T("L_%03d#%s"), GroupNum, strTime);	break;				
		default:
			PackName.Format(_T("Oterh_%03d"), GroupNum);
			break;
		}		
		ChipSizeMode = ModelRef.FindModelChipSizeMode(ModelType, BodyRgn);		
		if ( CHIP_SIZE_OTHERS != ChipSizeMode )
		{			
			ChipSize=ModelRef.GetModelChipSizeModeText(ChipSizeMode);
			switch ( ModelType )
			{
			case MODEL_TYPE_CHIP_C:	GroupName.Format(_T("C%s"), ChipSize);	break;
			case MODEL_TYPE_CHIP_R:	GroupName.Format(_T("R%s"), ChipSize);	break;				
			case MODEL_TYPE_CHIP_L:	GroupName.Format(_T("L%s"), ChipSize);	break;				
			}
			ModelRef.SetModelGroupName(GroupName);
		}
		if ( PackName.GetLength() == 0 )
		{	PackName = ModelRef.GetModelGroupName();	}

		ModelRef.SetModelName(PackName);
		ModelRef.SetModelGroupName(GroupName);
		for ( size_t i=0; i<ComponentCount; i++ )
		{
			ComponentPtr = GetProjectComponentPtr(i, false);
			if ( NULL == ComponentPtr ) { continue; }
			NewModelIdx = ComponentPtr->GetComponentTempIndex();
			if ( NewModelIdx != j ) { continue; }
			ModelPtr = ComponentPtr->GetComponentModelPtr();
			if ( NULL == ModelPtr ) { continue; }
			ModelPtr->SetModelName(PackName);
			ModelPtr->SetModelGroupName(GroupName);
			ComponentPtr->SetComponentModelName(PackName);
		}
	}	


	//Save for Debug
	if ( NewModelCount > 0 )
	{
		CString DebugFile;
		DebugFile.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("AILabelResult.TXT"));
		pfile = ::_tfopen(DebugFile, _T("w+"));
		if ( pfile != NULL )
		{
			for ( size_t j=0; j<NewModelCount; j++ )
			{		
				const CAOIModel &ModelRef=NewModelList[j];
				PackName = ModelRef.GetModelName();
				::_ftprintf(pfile, _T("%d, %s\n"), j+1, PackName);
			}
			::fclose(pfile); pfile = NULL;		
			::Sleep(0);
			::ShellExecute(NULL, _T("open"), DebugFile, NULL, NULL, SW_SHOW);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::ReadProjectAIModelComponentLabel_JSON(LPCTSTR Filename)
{
	bool bVal=true;
	bool bRet=false;
	bool bSucc=true;
	int  nVal=1;
	float fVal=1.f;	
	double dVal=1.0;	
	RECT   rcVal;	
	float aiConfidence=0;
	CString aiResultText;
	std::wstring wsVal;	
	std::wstring wsSender;
	std::wstring wsVersion;	
	std::wstring strfilename;

	rapidjson::CGMItr itr;	
	rapidjson::WDocument Doc;
	rapidjson::CJsonCtrl JSonCtrl;		
	const int AiExceptionCode = -1;

	JetAPI::TCHAR2wstring(Filename, strfilename);
	//initial
	Doc.SetObject();
	JSonCtrl.Set(&Doc);	
	if ( JSonCtrl.OpenFile(strfilename.c_str(), Doc) == false )
	{	return false; }

	if ( JSonCtrl.ReadDocItr(Doc, L"HeaderData", itr) == false )		
	{	return false;	}
	if ( JSonCtrl.ReadObjString(itr, L"Version_s", wsVersion) == false )
	{	return false; }
	if ( JSonCtrl.ReadObjString(itr, L"Sender_s", wsSender) == false )
	{	return false; }

	if ( JSonCtrl.ReadDocItr(Doc, L"AIResultW", itr) == false )		
	{	return false;	}	
	auto pName = itr->name.GetString();	
	auto arrayV = itr->value.GetArray();
	for (auto m = arrayV.Begin(); arrayV.End() != m; ++m)
	{	
		if ( m->IsObject() == false )
		{	continue; }
		bSucc = false;
		rapidjson::CGMItr itrLv2;
		if ( JSonCtrl.ReadValInt(*m, L"WindowID", nVal) == false )//"WindowID": -1,
		{	continue;	}
		if ( AiExceptionCode != nVal )
		{	return false; }
		if ( JSonCtrl.ReadValInt(*m, L"IsOK", nVal) == true )//"IsOK": 1,
		{
			switch ( nVal )
			{
			case AI_RESULT_ID_NONE:
			case AI_RESULT_ID_OK:			
			case AI_RESULT_ID_BYPASS:
				bSucc = true;
				break;
			default:
			case AI_RESULT_ID_NG:
			case AI_RESULT_ID_EXCEPTION:
				bSucc = false;
				break;
			}			
		}

		if ( JSonCtrl.ReadValString(*m, L"ErrorMessage", wsVal) == true )//"ErrorMessage": "None",
		{	
			aiResultText = CString(wsVal.c_str());	
			if ( false == bSucc )
			{	m_ErrorString.Format(_T("Error, AI ErrorMessage[%s]"), aiResultText);	}
		}
		if ( JSonCtrl.ReadValFloat(*m, L"AIConfidenceW", fVal) == true )//"AIConfidenceW": 0.9999,
		{	aiConfidence = fVal;	}
		bRet = bRet;
	}
	bRet = bRet;		
	return bSucc;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::WriteProjectAIModelComponentLabel_JSON(LPCTSTR Filename, LPCTSTR ImgName1, LPCTSTR ImgName2)
{		
	CString        strText;
	CString        ExtName=_T("JPG");
	double         MapResX=0, MapResY=0;
	IMAGE_PTR      MapPtr=NULL;
	IMAGE_SIZE     MapW=0, MapH=0, MapStep=0, BitCount=0;
	CString        MainName=GetProjectFileMainName();
	const size_t   szBuffer = 256;
	wchar_t        strTag[szBuffer] = L"";
	wchar_t        strBuffer[szBuffer] = L"";		
	const double   MinClusterDistanceUm=AOIDataCollect.GetSystemParameter().m_AIModelLabelMinClusterDistance;

	GetProjectMapResolution(MapResX, MapResY);
	if ( GetProjectMapPtr(0, MapW, MapH, MapStep, BitCount, MapPtr) == false )
	{	return false; }
	if ( NULL == MapPtr ) 
	{	return false; }
	const double   MapRes = (MapResX+MapResY)*0.5;
	const double   MinClusterDistance = MinClusterDistanceUm/MapRes;	

	FILE *pfile = ::_tfopen(Filename, _T("w+"));
	if ( NULL == pfile )
	{	return false;	}

	::fwprintf(pfile, L"{\n");

	::fwprintf(pfile, L"  \"HeaderData\":\n");//Header_cs
	::fwprintf(pfile, L"  {\n");//Header_cs Begin
	//"Version_s": "1.0.2",
	::wcscpy(strTag, L"Version_s");	
	::wcscpy(strBuffer, AI_MODEL_VERSION);	
	::fwprintf(pfile, L"    \"%s\": \"%s\",\n", strTag, strBuffer);

	::wcscpy(strTag, L"Sender_s");	
	::wcscpy(strBuffer, AOI3D_APP_NAME_W);//L"JET8000"	
	::fwprintf(pfile, L"    \"%s\": \"%s\"\n", strTag, strBuffer);
	::fwprintf(pfile, L"  },\n");//Header_cs End

	::fwprintf(pfile, L"  \"%s\":\n", L"AIInferenceDataW");//AIInferenceDataW
	::fwprintf(pfile, L"  [\n");//AIInferenceDataW Begin
	{
		::fwprintf(pfile, L"    {\n");//Wnd Begin
		
		//"ComponentImageFileName": "ProjectMainName#1.jpg"				
		::wcscpy(strTag, L"ComponentImageFileName");
		strText.Format(_T("%s"), ImgName1);
		//strText.Format(_T("%s#%d.%s"), MainName, 1, ExtName);		
		JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
		::fwprintf(pfile, L"      \"%s\": \"%s\",\n", strTag, strBuffer);

		//"ComponentImageFileName2": "ProjectMainName#1.jpg"//3D
		::wcscpy(strTag, L"ComponentImageFileName2");
		strText.Format(_T("%s"), ImgName2);
		//strText.Format(_T("%s#%d.%s"), MainName, 1, ExtName);		
		JetAPI::TCHAR2wchar(strText, strBuffer, szBuffer);
		::fwprintf(pfile, L"      \"%s\": \"%s\",\n", strTag, strBuffer);

		//"ROI":
		::fwprintf(pfile, L"      \"%s\":\n", L"Rect");
		::fwprintf(pfile, L"      [\n");//Rect Begin
		//"Map Image rect": [0,0,342,282],		
		::fwprintf(pfile, L"        [%d, %d, %d, %d],\n", 0, 0, MapW, MapH);

		//"Dummy rect": [0,0,342,282],		
		::fwprintf(pfile, L"        [%d, %d, %d, %d]\n", 0, 0, 0, 0);
		::fwprintf(pfile, L"      ],\n");//Rect End

		//"AImodelID": 3001
		::wcscpy(strTag, L"AImodelID");
		::fwprintf(pfile, L"      \"%s\": %d,\n", strTag, ALG_AI_MODEL_AUTO_LABEL);

		//"WindowDirection": 1,
		::wcscpy(strTag, L"WindowDirection");
		::fwprintf(pfile, L"      \"%s\": %d,\n", strTag, 1);

		//"ConfidenceThreshold": 1,
		::wcscpy(strTag, L"ConfidenceThreshold");
		::fwprintf(pfile, L"      \"%s\": %.2f,\n", strTag, 0.00);

		//"OCRImageRotateAngle": 0,
		::wcscpy(strTag, L"OCRImageRotateAngle");		
		::fwprintf(pfile, L"      \"%s\": %d,\n", strTag, 0);
		
		std::vector<RECT> CharRectList;
		std::vector<std::wstring> OcrTextList;		
		const size_t OcrTextCount=OcrTextList.size();
		//"OCRGroundTruthStr": []
		::wcscpy(strTag, L"OCRGroundTruthStr");
		::fwprintf(pfile, L"      \"%s\":\n", strTag);
		::fwprintf(pfile, L"      [\n");//OCRGroundTruthStr Begin
		for ( size_t j=0; j<OcrTextCount; j++ )
		{
			if ( 0 != j )
			{	::fwprintf(pfile, L",\n");	}
			::fwprintf(pfile, L"        \"%s\"", OcrTextList[j].c_str());				
		}
		::fwprintf(pfile, L"\n");		
		::fwprintf(pfile, L"      ],\n");//OCRGroundTruthStr End

		const size_t CharRectCount=CharRectList.size();;		
		::wcscpy(strTag, L"OCRGroundTruthBox");//"OCRGroundTruthBox": []
		::fwprintf(pfile, L"      \"%s\":\n", strTag);
		::fwprintf(pfile, L"      [\n");//OCRGroundTruthBox Begin
		for ( size_t j=0; j<CharRectCount; j++ )
		{
			if ( 0 != j )
			{	::fwprintf(pfile, L",\n");	}
			const RECT &rc=CharRectList[j];
			::fwprintf(pfile, L"        [%d, %d, %d, %d]", rc.left, rc.top, rc.right, rc.bottom);
		}
		::fwprintf(pfile, L"\n");		
		::fwprintf(pfile, L"      ],\n");//OCRGroundTruthBox End		

		//"ExpandRange": 2,
		::wcscpy(strTag, L"ExpandRange");
		::fwprintf(pfile, L"      \"%s\": %.2f,\n", strTag, 0.0);

		//"MinClusterDistance": 4,
		::wcscpy(strTag, L"MinClusterDistance");
		::fwprintf(pfile, L"      \"%s\": %.2f,\n", strTag, MinClusterDistance);

		//"WindowID": 0,
		::wcscpy(strTag, L"WindowID");
		::fwprintf(pfile, L"      \"%s\": %d\n", strTag, -1);		

		::fwprintf(pfile, L"    }");//Wnd End
	}
	::fwprintf(pfile, L"\n");
	::fwprintf(pfile, L"  ]\n");//AIInferenceDataW End		
	
	::fwprintf(pfile, L"}\n");
	::fclose(pfile); pfile = NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::AutoLabelProjectComponentModelGroupByAI()//自動分類專案零件模組群組-AI
{
	if ( AOIDataCollect.CheckAIServerIsReady() == false )
	{
		SetErrorString(AOIDataCollect.GetErrorString());		
		return false;
	}
	
	size_t  i=0;
	BOOL    bOK=false;
	CString strMapNameTmp;
	CString str, Filename, SyncName;
	CString strMapName1, strMapName2;
	CString strMapNameSrc, strMapNameDst;
	std::vector<CString> InFileList;
	std::vector<CString> OutFileList;
	std::vector<CString> TmpFileList;
	unsigned int FrameUniqueIID=0;
	unsigned int UsdUniqueIndex_1=-1;
	unsigned int UsdUniqueIndex_2=-1;	
	const unsigned int UsdUniqueID_1=FRAME_UNIQUE_ID_TOP;
	const unsigned int UsdUniqueID_2=FRAME_UNIQUE_ID_DLP;
	std::vector<unsigned int> FrameUniqueIDList;	
	CString ProjectMainName = GetProjectFileMainName();	
	CString strFolderSend = CAOIModel::GetAIServerFolderSend();
	CString strFolderRecv = CAOIModel::GetAIServerFolderRecv();	
	CString strFolderTemp = AOIDataCollect.GetAOITempDirectory();
	GetProjectFrameUniqueIDList(FrameUniqueIDList);
	const size_t FrameUniqueIDCount=FrameUniqueIDList.size();
	strFolderTemp.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("AILabel"));
	
	::CreateDirectory(strFolderRecv, NULL);
	::CreateDirectory(strFolderSend, NULL);
	::CreateDirectory(strFolderTemp, NULL);
	::Sleep(0);		
	JetAPI::ClearFolder(strFolderRecv);
	JetAPI::ClearFolder(strFolderSend);
	JetAPI::ClearFolder(strFolderTemp);

	//取得底圖編號
	for ( i=0; i<FrameUniqueIDCount; i++ )
	{
		FrameUniqueIID = FrameUniqueIDList[i];
		if ( UsdUniqueID_1 == FrameUniqueIID  )
		{	UsdUniqueIndex_1 = i;	}
		if ( UsdUniqueID_2 == FrameUniqueIID  )
		{	UsdUniqueIndex_2 = i;	}
	}	
	if ( -1 == UsdUniqueIndex_1 )
	{
		str = _T("TOP");
		TFrameParam *FrameParamPtr=AOIDataCollect.GetSystemFrameParamPtrByUniqueID(UsdUniqueID_1);
		if ( NULL != FrameParamPtr )
		{	str = FrameParamPtr->FrameName;	}
		m_ErrorString.Format(_T("Error, No [%s] Map"), str);
		return false;
	}
	if ( -1 == UsdUniqueIndex_2 )
	{
		str = _T("3D");
		TFrameParam *FrameParamPtr=AOIDataCollect.GetSystemFrameParamPtrByUniqueID(UsdUniqueID_2);
		if ( NULL != FrameParamPtr )
		{	str = FrameParamPtr->FrameName;	}
		m_ErrorString.Format(_T("Error, No [%s] Map"), str);
		return false;
	}
	strMapName1 = AOIDataDefine.GetProjectMapImageName(NULL, ProjectMainName, UsdUniqueIndex_1);
	strMapName2 = AOIDataDefine.GetProjectMapImageName(NULL, ProjectMainName, UsdUniqueIndex_2);

	//存底圖檔過去		
	strMapNameSrc = m_ProjectMapFilename[UsdUniqueIndex_1];	
	strMapNameDst = AOIDataDefine.GetProjectMapImageName(strFolderSend, ProjectMainName, UsdUniqueIndex_1);
	if ( FALSE == ::CopyFile(strMapNameSrc, strMapNameDst, FALSE) )
	{
		m_ErrorString.Format(_T("Error, Copy Project Map Fault\n[%s] -> [%s]"), strMapNameSrc, strMapNameDst);
		return false;
	}
	OutFileList.push_back(strMapNameDst);
	strMapNameTmp = AOIDataDefine.GetProjectMapImageName(strFolderTemp, UsdUniqueIndex_1, false);
	::CopyFile(strMapNameDst, strMapNameTmp, FALSE);	
	TmpFileList.push_back(strMapNameTmp);
	
	strMapNameSrc = m_ProjectMapFilename[UsdUniqueIndex_2];	
	strMapNameDst = AOIDataDefine.GetProjectMapImageName(strFolderSend, ProjectMainName, UsdUniqueIndex_2);
	if ( FALSE == ::CopyFile(strMapNameSrc, strMapNameDst, FALSE) )
	{
		m_ErrorString.Format(_T("Error, Copy Project Map Fault\n[%s] -> [%s]"), strMapNameSrc, strMapNameDst);
		return false;
	}
	OutFileList.push_back(strMapNameDst);
	strMapNameTmp = AOIDataDefine.GetProjectMapImageName(strFolderTemp, UsdUniqueIndex_2, false);
	::CopyFile(strMapNameDst, strMapNameTmp, FALSE);	
	TmpFileList.push_back(strMapNameTmp);

	//存零件座標過去
	Filename.Format(_T("%s\\%s#CAD.TXT"), strFolderSend, ProjectMainName);
	if ( SaveProjectComponentMapLocation(Filename, true) == false )	
	{	return false;	}
	OutFileList.push_back(Filename);
	strMapNameTmp.Format(_T("%s\\%s#CAD.TXT"), strFolderTemp, _T("Project"));
	::CopyFile(Filename, strMapNameTmp, FALSE);
	TmpFileList.push_back(strMapNameTmp);

	//存AI-Json檔案
	Filename.Format(_T("%s\\%s.JSON"), strFolderSend, ProjectMainName);
	if ( WriteProjectAIModelComponentLabel_JSON(Filename, strMapName1, strMapName2) == false )
	{	return false; }
	strMapNameTmp.Format(_T("%s\\%s.JSON"), strFolderTemp, _T("Project"));
	::CopyFile(Filename, strMapNameTmp, FALSE);
	TmpFileList.push_back(strMapNameTmp);
	
	JetAPI::GetSyncFilename(Filename, SyncName);	
	JetAPI::CreateSyncFile(SyncName);
	::Sleep(0);	

	const size_t Timeout=CAOIModel::GetAIServerTimeout();
	const size_t MaxWaitCount=(100, Timeout/10);

	Filename.Format(_T("%s\\%s.JSON"), strFolderRecv, ProjectMainName);
	JetAPI::GetSyncFilename(Filename, SyncName);	
	for ( i=0; i<MaxWaitCount; i++ )
	{
		if ( JetAPI::IsFileExist(SyncName) == true )
		{	break;	}
		::Sleep(10);
	}
	if ( MaxWaitCount == i )
	{	
		m_ErrorString.Format(_T("Error, Waito for AI Sync File too long[%s]"), SyncName);
		return false;
	}
	InFileList.push_back(SyncName);	
	InFileList.push_back(Filename);
	if ( ReadProjectAIModelComponentLabel_JSON(Filename) == false )
	{	return false;	}	
	
	Filename.Format(_T("%s\\%s#CAD.TXT"), strFolderRecv, ProjectMainName);
	strMapNameDst.Format(_T("%s\\%s#CAD.TXT"), AOIDataCollect.GetAOITempDirectory(), _T("AILabel"));
	::CopyFile(Filename, strMapNameDst, FALSE);
	InFileList.push_back(Filename);
	if ( ReadProjectAIModelComponentLabelFile(Filename) == false )
	{	return false; }	

	JetAPI::DeleteFileList(InFileList);		
	JetAPI::DeleteFileList(TmpFileList);
	//JetAPI::DeleteFileList(OutFileList);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectMappingCadXYFile(LPCTSTR filename)
{
	const bool bPanelFdOnlye = true;
	DISTRICT_ID DistrictID = GetProjectActDistrictID();
	size_t  FdCount = GetProjectFdCount(DistrictID, bPanelFdOnlye);
	LANE_ID     LaneID = AOIDataCollect.GetActiveLaneID();
	const bool  IsNeedGrabFiducial = AOIDataCollect.GetIsNeedGrabFiducial(LaneID);
	if (true == IsNeedGrabFiducial && FdCount>0)
	{
		m_ErrorString = _T("Align board first, please");
		m_ErrorString = LoadMultiLanguageString(m_ErrorString, m_ErrorString);
		//JetAPI::ShowMessageBox(str);
		return false;
	}
	if (SaveProjectMappingCadXYFileFn(filename) == false)
	{
		SetProjectExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIProject::SaveProjectMappingCadXYFileFn(LPCTSTR filename)
{
	FILE *pfile = NULL;
	TCHAR TMode[32] = _T("");
	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	pfile = _tfopen(filename, TMode);
	if (NULL == pfile)
	{
		m_ErrorString.Format(_T("Error, Open file to save Fault[%s]"), filename);
		return false;
	}

	CString        str;
	int            nHeights = 0;
	int            WndCount = 0;
	int            i = 0, j = 0, k = 0;
	int            PanelBoardCount = 0;
	unsigned int   Index = 0;
	CString        strNozzle;
	CString        strPartNumber;
	CString        strComponentName;
	double         CadX = 0, CadY = 0, Angle = 0;
	double         StageX = 0, StageY = 0;
	double         StageResX = 0, StageResY = 0;
	double         OffsetX = 0, OffsetY = 0, Skew = 0;
	double         RelOffsetX = 0, RelOffsetY = 0;
	CAOIModel     *ModelPtr = NULL;
	CAOIComponent *ComponentPtr = NULL;
	CAOIFd        *FdPtr = NULL;
	const int      ComponentCount = (int)(GetProjectComponentCount());
	const int      FdCount = (int)(GetProjectFdCount());
	::_ftprintf(pfile, _T("FdIndex, CadX(mm), CadY(mm), StageX(mm), StageY(mm), StageResX(mm), StageResY(mm), OffsetX(mm), OffsetY(mm)\n"));
	for (i = 0; i < FdCount; i++) {
		FdPtr = GetProjectFdPtr(i, false);
		if (FdPtr == NULL) { continue; }
		Index = FdPtr->GetFdIndex_Project();
		CadX = FdPtr->GetFdCadPosX();
		CadY = FdPtr->GetFdCadPosY();
		CadX = JetAPI::Unit_UmtoMM(CadX);//um to mm
		CadY = JetAPI::Unit_UmtoMM(CadY);//um to mm

		StageX = FdPtr->GetFdTeachStagePosX();
		StageY = FdPtr->GetFdTeachStagePosY();
		StageResX = FdPtr->GetFdStagePosX();
		StageResY = FdPtr->GetFdStagePosY();
		OffsetX = StageResX - StageX;
		OffsetY = StageResY - StageY;
		StageX = JetAPI::Unit_UmtoMM(StageX);//um to mm
		StageY = JetAPI::Unit_UmtoMM(StageY);//um to mm
		StageResX = JetAPI::Unit_UmtoMM(StageResX);//um to mm
		StageResY = JetAPI::Unit_UmtoMM(StageResY);//um to mm
		OffsetX = JetAPI::Unit_UmtoMM(OffsetX);//um to mm
		OffsetY = JetAPI::Unit_UmtoMM(OffsetY);//um to mm
		::_ftprintf(pfile, _T("%d, %.16f, %.16f, %.16f,%.16f,%.16f,%.16f,%.16f, %.16f\n"), Index, CadX, CadY, StageX, StageY, StageResX, StageResY, OffsetX, OffsetY);
	}
	//About Component
	::_ftprintf(pfile, _T("-------------------------------------------------------------------"));
	::_ftprintf(pfile, _T("Component, CadX(mm), CadY(mm), OffsetX(mm), OffsetY(mm)\n"));
	for (i = 0; i<ComponentCount; i++)
	{
		ComponentPtr = GetProjectComponentPtr(i, false);
		if (NULL == ComponentPtr) { continue; }
		//if (ComponentPtr->GetComponentDeleted() == true) { continue; }
		//if (ComponentPtr->GetComponentSelected() == false) { continue; }
		strComponentName = ComponentPtr->GetComponentName();
		CadX = ComponentPtr->GetComponentCadPosX();
		CadY = ComponentPtr->GetComponentCadPosY();
		CadX = JetAPI::Unit_UmtoMM(CadX) ;//um to mm
		CadY = JetAPI::Unit_UmtoMM(CadY);//um to mm
		StageX = ComponentPtr->GetComponentStagePosX();
		StageY = ComponentPtr->GetComponentStagePosY();
		StageResX = ComponentPtr->GetComponentStageResultX();
		StageResY = ComponentPtr->GetComponentStageResultY();
		OffsetX = StageResX - StageX;
		OffsetY = StageResY - StageY;
		StageX = JetAPI::Unit_UmtoMM(StageX);//um to mm
		StageY = JetAPI::Unit_UmtoMM(StageY);//um to mm
		StageResX = JetAPI::Unit_UmtoMM(StageResX);//um to mm
		StageResY = JetAPI::Unit_UmtoMM(StageResY);//um to mm
		OffsetX = JetAPI::Unit_UmtoMM(OffsetX);//um to mm
		OffsetY = JetAPI::Unit_UmtoMM(OffsetY);//um to mm
		::_ftprintf(pfile, _T("%s, %.16f, %.16f, %.16f,%.16f,%.16f,%.16f,%.16f, %.16f\n"), (LPCTSTR)strComponentName, CadX, CadY, StageX, StageY, StageResX, StageResY, OffsetX, OffsetY);
	}
	::fclose(pfile);
	pfile = NULL;
	return true;
}
